def provision_live_workspace(ws: Path) -> None:
    (ws / "config").mkdir(parents=True, exist_ok=True)
    (ws / ".config.local").mkdir(parents=True, exist_ok=True)
    (ws / "spaces" / "source").mkdir(parents=True, exist_ok=True)
    (ws / "spaces" / "docs").mkdir(parents=True, exist_ok=True)
    (ws / "spaces" / "ignored_logs").mkdir(parents=True, exist_ok=True)
    (ws / "sub_dir").mkdir(parents=True, exist_ok=True)
    (ws / "sub_dir" / "sample.py").write_text("def hello() -> int:\n    return 42\n", encoding="utf-8")
    atomic_write_json(HostPath(ws / "yscb.config.json"), {"workspace_version": 2})
    atomic_write_json(HostPath(ws / "config" / "gdrive.json"), {"auto_sync": False, "interval_sec": 0.10, "work_ms": 0})
    _provision_core_tier0_modules(ws)
    _provision_tier1_modules(ws)


# Subprocess Entrypoints for Real Daemon & Real CLI Worker Processes


@dataclass(frozen=True, slots=True)
class WorkspaceDispatcherRig:
    dispatcher: RuntimeDispatcher
    config_view: FileConfigView
    echo_ledger: FileEchoLedger
    provider: ManifestModuleProvider


def build_dispatcher_for_workspace(
    ws: HostPath,
    venv_python: HostPath,
    *,
    is_daemon_host: bool = False,
    sandbox_restricted: bool = False,
    ttl_sec: float = 8.0,
    persistent_session: Optional[PersistentRpcSession] = None,
) -> WorkspaceDispatcherRig:
    cache_dir = ws.join(".cache")
    cfg_view = FileConfigView(ws)
    echo_ledger = FileEchoLedger(cache_dir)
    ded_env = os.environ.get("YSCB_TEST_DEDICATED_VENV_PY", "")
    ded_venv = HostPath(ded_env) if ded_env else venv_python
    provider = ManifestModuleProvider(ws, venv_python, dedicated_venv_python=ded_venv)
    spawner = SingleFlightDaemonSpawner(
        cache_dir,
        lambda root: [
            sys.executable,
            "-W",
            "error::ResourceWarning",
            str(Path(__file__).resolve()),
            "--daemon-entry",
            str(root),
            str(venv_python),
            str(ttl_sec),
        ],
        sandbox_restricted=sandbox_restricted,
    )

    def _child_factory(child_ws: HostPath) -> RuntimeDispatcher:
        c_cache = child_ws.join(".cache")
        c_prov = ManifestModuleProvider(child_ws, venv_python, dedicated_venv_python=ded_venv)
        c_opts = DispatcherHostOptions(
            config_view=FileConfigView(child_ws),
            daemon_spawner=None,
            connection_config=DaemonConnectionConfig(enabled=not sandbox_restricted, auto_spawn=False),
            is_daemon_host=False,
            child_dispatcher_factory=_child_factory,
        )
        return RuntimeDispatcher(workspace_root=child_ws, cache_dir=c_cache, module_provider=c_prov, options=c_opts)

    opts = DispatcherHostOptions(
        config_view=cfg_view,
        daemon_spawner=None if is_daemon_host else spawner,
        connection_config=DaemonConnectionConfig(enabled=not sandbox_restricted, auto_spawn=not sandbox_restricted),
        is_daemon_host=is_daemon_host,
        persistent_rpc_session=persistent_session,
        child_dispatcher_factory=_child_factory,
    )
    disp = RuntimeDispatcher(workspace_root=ws, cache_dir=cache_dir, module_provider=provider, options=opts)
    return WorkspaceDispatcherRig(disp, cfg_view, echo_ledger, provider)


def _record_daemon_spawn_counter(ws: HostPath) -> None:
    cnt_lock = FileLock(ws.join(".cache", "locks", "spawn_counter.lock"))
    cnt_lock.acquire(blocking=True, timeout_sec=5.0)
    try:
        cnt_f = ws.join(".cache", "daemon_spawn_count.json")
        cur = read_json_dict(cnt_f)
        prev_pids = cur.get("pids") if isinstance(cur, Mapping) else None
        pids = [int(x) for x in prev_pids if isinstance(x, int) and not isinstance(x, bool)] if isinstance(prev_pids, list) else []
        me = os.getpid()
        if me not in pids:
            pids.append(me)
        atomic_write_json(cnt_f, {"spawns": _jint(cur, "spawns", 0) + 1, "pids": pids})
    finally:
        cnt_lock.release()


def _daemon_process_main(ws_str: str, venv_py_str: str, ttl_str: str) -> int:
    ws = HostPath(ws_str)
    venv_py = HostPath(venv_py_str)
    ttl = float(ttl_str)
    _record_daemon_spawn_counter(ws)
    rig = build_dispatcher_for_workspace(ws, venv_py, is_daemon_host=True, ttl_sec=ttl)
    disp, cfg_view, echo_ledger = rig.dispatcher, rig.config_view, rig.echo_ledger
    watch_cfg = DaemonWatcherConfig(
        echo_guard=echo_ledger,
        space_watch_roots=(ws.join("spaces"),),
        config_watch_roots=(ws.join("config"), ws.join("yscb.config.json"), ws.join(".config.local")),
        on_space_changed_task=TaskId("space.scan"),
        on_config_changed_task=None,
        watcher_debounce_sec=0.08,
    )
    daemon = WorkspaceDaemon(
        workspace_root=ws,
        cache_dir=ws.join(".cache"),
        dispatcher=disp,
        config_view=cfg_view,
        watch_config=watch_cfg,
        self_restart_argv=[
            sys.executable,
            "-W",
            "error::ResourceWarning",
            str(Path(__file__).resolve()),
            "--daemon-entry",
            ws_str,
            venv_py_str,
            ttl_str,
        ],
    )
    return daemon.run_forever(ttl_override_sec=ttl)


def _scan_static_route_manifest(rfile: Path, known_ids: list[str], cli_cmds: list[str]) -> None:
    meta = read_json_dict(HostPath(rfile)) or {}
    t_list = meta.get("tasks")
    for item in (t_list if isinstance(t_list, list) else []):
        if isinstance(item, dict) and isinstance(item.get("task_id"), str):
            known_ids.append(str(item["task_id"]))
            if isinstance(item.get("cli_path"), list):
                cli_cmds.append(" ".join(str(x) for x in item["cli_path"]))


def _handle_static_cli_meta(ws: HostPath, task_str: str) -> Optional[int]:
    if task_str != "--help" and not task_str.startswith("unknown."):
        return None
    cli_cmds: list[str] = []
    known_ids: list[str] = []
    mods_dir = ws.path / ".modules"
    for rfile in (sorted(mods_dir.glob("*/routes.json")) if mods_dir.is_dir() else []):
        _scan_static_route_manifest(rfile, known_ids, cli_cmds)
    if task_str == "--help":
        sys.stdout.write(json.dumps({"ok": True, "cli_commands": cli_cmds}) + "\n")
        return 0
    hints = difflib.get_close_matches(task_str, known_ids, n=2, cutoff=0.3)
    sys.stdout.write(json.dumps({"ok": False, "error": "task_not_found", "suggestions": hints}) + "\n")
    return 2


def _cli_oneshot_main(
    ws_str: str,
    venv_py_str: str,
    cwd_str: str,
    task_str: str,
    payload_json: str,
    policy_str: str,
) -> int:
    ws = HostPath(ws_str)
    static_rc = _handle_static_cli_meta(ws, task_str)
    if static_rc is not None:
        return static_rc
    venv_py = HostPath(venv_py_str)
    disp = build_dispatcher_for_workspace(ws, venv_py, is_daemon_host=False).dispatcher
    try:
        raw_obj = json.loads(payload_json)
        if not isinstance(raw_obj, dict):
            raise ValueError("CLI payload must be a JSON object")
        out = disp.invoke(
            InvokeRequest(
                task_id=TaskId(task_str),
                raw_input=raw_obj,
                workspace_root=ws,
                caller_cwd=HostPath(cwd_str),
                caller_surface=CallerSurface.CLI,
                routing_policy=ClientRoutingPolicy(policy_str),
            )
        )
        is_sigint = bool(out.error and "SIGINT" in out.error.message)
        sys.stdout.write(
            json.dumps(
                {
                    "ok": out.ok,
                    "value": out.value,
                    "executed_hot": out.executed_hot,
                    "coalesced": out.coalesced,
                    "error": out.error.code.value if out.error else None,
                    "teardown_count": len(out.teardown_diagnostics),
                }
            )
            + "\n"
        )
        return 0 if out.ok else (130 if is_sigint else 1)
    finally:
        disp.shutdown(grace_ms=300)


# Gate 0: Strict AST, Symtable, Nesting Depth, Type-Hint & Self-Audit Gate

_CF_AST_NODES = (ast.If, ast.For, ast.AsyncFor, ast.While, ast.With, ast.AsyncWith, ast.Try, ast.TryStar, ast.Match)
_MUTABLE_GLOBAL_CONSTRUCTORS: Final[frozenset[str]] = frozenset(
    {
        "dict",
        "list",
        "set",
        "bytearray",
        "defaultdict",
        "OrderedDict",
        "deque",
        "WeakValueDictionary",
        "WeakKeyDictionary",
        "WeakSet",
        "getLogger",
    }
)


def _is_mutable_global_expr(expr: Optional[ast.expr]) -> bool:
    if isinstance(expr, (ast.Dict, ast.List, ast.Set, ast.DictComp, ast.ListComp, ast.SetComp)):
        return True
    if isinstance(expr, ast.Call):
        fn = expr.func
        callee = fn.id if isinstance(fn, ast.Name) else (fn.attr if isinstance(fn, ast.Attribute) else "")
        return callee in _MUTABLE_GLOBAL_CONSTRUCTORS
    return False


def _function_body_loc(node: ast.FunctionDef | ast.AsyncFunctionDef) -> int:
    stmts = list(node.body)
    if stmts and isinstance(stmts[0], ast.Expr) and isinstance(stmts[0].value, ast.Constant) and isinstance(stmts[0].value.value, str):
        stmts = stmts[1:]
    if not stmts:
        return 1
    return (node.end_lineno or stmts[-1].lineno) - stmts[0].lineno + 1


def _max_control_flow_depth(node: ast.AST, cur: int = 0) -> int:
    best = cur
    for child in ast.iter_child_nodes(node):
        if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            continue
        is_elif = isinstance(node, ast.If) and isinstance(child, ast.If) and node.orelse == [child] and child.col_offset == node.col_offset
        nxt = cur if is_elif else (cur + 1 if isinstance(child, _CF_AST_NODES) else cur)
        best = max(best, _max_control_flow_depth(child, nxt))
    return best


def _collect_descendant_free_names(table: symtable.SymbolTable) -> set[str]:
    names: set[str] = set()
    for ch in table.get_children():
        for s in ch.get_symbols():
            if s.is_free() or s.is_referenced():
                names.add(s.get_name())
        names.update(_collect_descendant_free_names(ch))
    return names


def _verify_symtable_clean(src: str, rel_name: str) -> None:
    builtin_names = {k for k, _ in inspect.getmembers_static(builtins)} | {
        "__annotations__", "__file__", "__name__", "__package__", "__doc__",
        "__spec__", "__path__", "__cached__", "__builtins__", "__class__",
    }
    st = symtable.symtable(src, rel_name, "exec")

    def _walk(table: symtable.SymbolTable, enclosing: set[str]) -> None:
        defined = {
            s.get_name()
            for s in table.get_symbols()
            if s.is_assigned() or s.is_imported() or s.is_parameter() or s.is_namespace()
        }
        visible = enclosing | defined
        child_enc = enclosing if table.get_type() == "class" else visible
        desc_used = _collect_descendant_free_names(table) if table.get_type() == "function" else set()
        for sym in table.get_symbols():
            name = sym.get_name()
            if sym.is_referenced() and not (
                sym.is_assigned() or sym.is_imported() or sym.is_parameter() or sym.is_namespace()
            ):
                _check(name in visible or name in builtin_names, lambda: f"Undefined symbol '{name}' in {rel_name}")
            if (
                table.get_type() == "function"
                and sym.is_local()
                and sym.is_assigned()
                and not (sym.is_parameter() or sym.is_imported() or sym.is_namespace() or sym.is_referenced())
                and not name.startswith("_")
            ):
                _check(name in desc_used, lambda: f"Unused local variable '{name}' in {rel_name}:{table.get_name()}")
        for child in table.get_children():
            _walk(child, child_enc)

    _walk(st, set())



def _resolve_except_expr_obj(
    expr: ast.expr,
    ns: Mapping[str, object],
    bi_ns: Mapping[str, object],
) -> object:
    if isinstance(expr, ast.Name):
        return ns.get(expr.id, bi_ns.get(expr.id))
    if isinstance(expr, ast.Attribute) and isinstance(expr.value, ast.Name):
        base = ns.get(expr.value.id, bi_ns.get(expr.value.id))
        if isinstance(base, types.ModuleType):
            return dict(inspect.getmembers(base)).get(expr.attr)
    return None


def _assert_valid_except_handlers(tree: ast.AST, mod_name: str, label: str) -> None:
    canon_mod = mod_name[:-9] if mod_name.endswith(".__init__") else mod_name
    mod_obj = sys.modules[canon_mod]
    ns = dict(inspect.getmembers(mod_obj))
    bi_ns = dict(inspect.getmembers(builtins))
    for node in ast.walk(tree):
        if not isinstance(node, ast.ExceptHandler) or node.type is None:
            continue
        items = list(node.type.elts) if isinstance(node.type, ast.Tuple) else [node.type]
        for item in items:
            resolved = _resolve_except_expr_obj(item, ns, bi_ns)
            _check(
                isinstance(resolved, type) and issubclass(resolved, BaseException),
                lambda: f"Non-BaseException in except handler at {label}:{node.lineno}: {ast.unparse(item)}",
            )


def _audit_single_kernel_ast(
    py_f: Path,
    rel_posix: str,
    rel_mod: str,
    forbidden_by_prefix: Sequence[tuple[str, tuple[str, ...]]],
) -> None:
    noise_re = re.compile(
        r"\b(?:FR-\d+|EC-\d+|DR-\d+|P[0-3](?:-\d+)?|D[1-5]|S[1-6]|RC-\d+|N-\d+|F-\d+|M-\d+|"
        r"REV-[A-Z0-9]+|R[1-9]\d*|AUD-\d+|TASK-\d+|OPT-\d+|TODO|FIXME|HACK|XXX)\b|#\s*Step\s+\d+"
    )
    src = py_f.read_text(encoding="utf-8")
    m_noise = noise_re.search(src)
    _check(m_noise is None, lambda: f"Forbidden audit/ticket tag '{m_noise.group(0)}' in {rel_posix}")
    _check(("# type" + ": ignore") not in src, lambda: f"Forbidden type-ignore comment in {rel_posix}")
    _verify_symtable_clean(src, rel_posix)
    tree = ast.parse(src, filename=rel_posix)
    _assert_no_unused_top_imports(tree, rel_posix)
    _assert_no_duplicate_defs(tree, rel_posix)
    _assert_valid_except_handlers(tree, rel_mod, rel_posix)
    _assert_no_stateless_private_methods(tree, rel_posix)
    _assert_no_cross_collaborator_private_calls(tree, rel_posix)

    for stmt in tree.body:
        if isinstance(stmt, (ast.Assign, ast.AnnAssign)) and _is_mutable_global_expr(stmt.value):
            raise AssertionError(f"Mutable module-level global forbidden in {rel_posix}:{stmt.lineno}")

    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and node.id == "Any":
            raise AssertionError(f"Type erasure 'Any' forbidden in {rel_posix}:{node.lineno}")
        if isinstance(node, ast.Attribute) and node.attr in {"Any", "getattr", "setattr", "hasattr", "delattr", "eval", "exec"}:
            raise AssertionError(f"Forbidden attribute '{node.attr}' in {rel_posix}:{node.lineno}")
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            _check(node.func.id != "print", lambda: f"Bare print() forbidden in {rel_posix}:{node.lineno}")
            _check(node.func.id not in {"getattr", "setattr", "hasattr", "delattr", "__import__", "vars", "dir", "eval", "exec"}, lambda: f"Dynamic {node.func.id} forbidden in {rel_posix}:{node.lineno}")
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            _check(not (isinstance(node.func.value, ast.Name) and node.func.value.id == "os" and node.func.attr == "getcwd"), lambda: f"os.getcwd() forbidden in {rel_posix}:{node.lineno}")
            _check(node.func.attr not in {"abspath", "cwd"}, lambda: f"Implicit cwd call .{node.func.attr}() forbidden in {rel_posix}:{node.lineno}")
        if isinstance(node, ast.Attribute) and node.attr in {"__dict__", "import_module"}:
            _assert_allowed_kernel_reflection(tree, rel_posix, node)
        if isinstance(node, ast.Assert):
            raise AssertionError(f"Bare assert forbidden in kernel {rel_posix}:{node.lineno}")
        if isinstance(node, ast.Lambda) and isinstance(node.body, ast.Tuple) and len(node.body.elts) >= 3:
            raise AssertionError(f"Wide 3+ tuple lambda forbidden in {rel_posix}:{node.lineno}")
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            _assert_no_local_imports(node, rel_posix)
            all_args = [*node.args.posonlyargs, *node.args.args, *node.args.kwonlyargs]
            p_cnt = len(all_args) - (1 if all_args and all_args[0].arg in {"self", "cls"} else 0)
            p_cnt += (1 if node.args.vararg else 0) + (1 if node.args.kwarg else 0)
            _check(p_cnt <= 6, lambda: f"Function {rel_posix}:{node.name} has {p_cnt} parameters (> 6)")
            loc = _function_body_loc(node)
            span = (node.end_lineno or node.lineno) - node.lineno + 1
            _check(loc <= 75 and span <= 75, lambda: f"Function {rel_posix}:{node.name} exceeds 75 lines (span={span})")
            depth = _max_control_flow_depth(node, 0)
            _check(depth <= 3, lambda: f"Function {rel_posix}:{node.name} has nesting depth {depth} (> 3)")
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            _assert_no_wide_tuple_params(node, rel_posix)
            _assert_no_unused_function_params(node, rel_posix)
        _check_dag_imports(node, rel_mod, forbidden_by_prefix)


_ALLOWED_KERNEL_REFLECTION_FUNCS: Final[dict[str, frozenset[str]]] = {
    "core/foundation/codec.py": frozenset(
        {
            "_populate_module_and_outer_classes",
            "_populate_single_mro_base",
            "_build_mro_tv_maps",
            "_resolve_single_class_hints",
            "_compile_mro_base_metadata",
            "_needs_localns_for_forward_ref",
            "_resolve_forward_ref",
            "_compile_plan_uncached",
        }
    ),
    "core/execution/runtime/module_slot.py": frozenset(
        {"_make_scoped_builtins", "exec_module", "_ensure_finder", "_deactivate_finder_if_empty_locked", "load_module_artifact"}
    ),
}


def _assert_allowed_kernel_reflection(tree: ast.AST, rel_posix: str, attr_node: ast.Attribute) -> None:
    allowed_fns = _ALLOWED_KERNEL_REFLECTION_FUNCS.get(rel_posix, frozenset())
    _check(allowed_fns, lambda: f"Reflection {attr_node.attr} forbidden in {rel_posix}:{attr_node.lineno}")
    if attr_node.attr == "import_module":
        _check(rel_posix == "core/execution/runtime/module_slot.py", lambda: f"import_module forbidden in {rel_posix}:{attr_node.lineno}")
    enclosing = [
        fn.name
        for fn in ast.walk(tree)
        if isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef))
        and fn.lineno <= attr_node.lineno <= (fn.end_lineno or fn.lineno)
        and any(sub is attr_node for sub in ast.walk(fn))
    ]
    _check(any(nm in allowed_fns for nm in enclosing), lambda: f"Reflection {attr_node.attr} outside allowlisted functions in {rel_posix}:{attr_node.lineno}")


def _is_wide_tuple_subscript(node: ast.AST) -> bool:
    return (
        isinstance(node, ast.Subscript)
        and isinstance(node.value, ast.Name)
        and node.value.id in {"tuple", "Tuple"}
        and isinstance(node.slice, ast.Tuple)
        and len(node.slice.elts) >= 3
    )


_TUPLE_RETURN_COMPAT_NAMES: Final[frozenset[str]] = frozenset(
    {"tuple", "Tuple", "Sequence", "Iterable", "object", "JsonValue", "JsonArray", "ScopedHop"}
)


def _iter_direct_fn_returns(stmts: Sequence[ast.stmt]) -> list[ast.Return]:
    found: list[ast.Return] = []
    for st in stmts:
        if isinstance(st, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            continue
        if isinstance(st, ast.Return):
            found.append(st)
        for ch in ast.iter_child_nodes(st):
            if isinstance(ch, ast.stmt):
                found.extend(_iter_direct_fn_returns((ch,)))
    return found


def _assert_no_wide_tuple_params(fn_node: ast.FunctionDef | ast.AsyncFunctionDef, label: str) -> None:
    for arg in (*fn_node.args.posonlyargs, *fn_node.args.args, *fn_node.args.kwonlyargs):
        if arg.annotation is not None and any(_is_wide_tuple_subscript(s) for s in ast.walk(arg.annotation)):
            raise AssertionError(f"Anonymous 3+-tuple parameter '{arg.arg}' forbidden in {label}:{fn_node.name}")
    if fn_node.returns is not None and any(_is_wide_tuple_subscript(s) for s in ast.walk(fn_node.returns)):
        raise AssertionError(f"Anonymous 3+-tuple return annotation forbidden in {label}:{fn_node.name}")
    allows_tuple = fn_node.returns is None or any(
        isinstance(n, ast.Name) and n.id in _TUPLE_RETURN_COMPAT_NAMES for n in ast.walk(fn_node.returns)
    )
    is_homog_seq = isinstance(fn_node.returns, ast.Subscript) and (
        (isinstance(fn_node.returns.value, ast.Name) and fn_node.returns.value.id == "Sequence")
        or (
            isinstance(fn_node.returns.value, ast.Name)
            and fn_node.returns.value.id in {"tuple", "Tuple"}
            and isinstance(fn_node.returns.slice, ast.Tuple)
            and len(fn_node.returns.slice.elts) == 2
            and isinstance(fn_node.returns.slice.elts[1], ast.Constant)
            and fn_node.returns.slice.elts[1].value is Ellipsis
        )
    )
    for ret in _iter_direct_fn_returns(fn_node.body):
        if isinstance(ret.value, ast.Tuple):
            if not is_homog_seq and not any(isinstance(e, ast.Starred) for e in ret.value.elts) and len(ret.value.elts) >= 3:
                raise AssertionError(f"Anonymous 3+-tuple return literal forbidden in {label}:{fn_node.name}:{ret.lineno}")
            if not allows_tuple:
                raise AssertionError(f"Tuple return literal mismatches annotation in {label}:{fn_node.name}:{ret.lineno}")


def _resolve_import_from_base(node: ast.ImportFrom, rel_mod: str) -> str:
    pkg_parts = rel_mod.split(".")[:-1]
    if node.level > 0:
        keep = max(0, len(pkg_parts) - (node.level - 1))
        base = ".".join(pkg_parts[:keep])
        if node.module:
            return f"{base}.{node.module}" if base else node.module
        return base
    return node.module or ""


def _assert_rpc_readonly_fs_import(node: ast.AST, bound_targets: Sequence[str], rel_mod: str) -> None:
    if isinstance(node, ast.Import):
        for imp in bound_targets:
            if imp == "core" or imp.startswith("core.filesystem"):
                raise AssertionError(f"Forbidden bare filesystem/core import in {rel_mod}: {imp}")
        return
    for imp in bound_targets:
        if imp.startswith("core.filesystem") and imp != "core.filesystem.fs.read_json_dict":
            raise AssertionError(f"Non-readonly filesystem import in {rel_mod}: {imp}")


def _check_dag_imports(
    node: ast.AST,
    rel_mod: str,
    forbidden_by_prefix: Sequence[tuple[str, tuple[str, ...]]],
) -> None:
    bound_targets: list[str] = []
    all_targets: list[str] = []
    if isinstance(node, ast.Import):
        bound_targets = [alias.name for alias in node.names]
        all_targets = list(bound_targets)
    elif isinstance(node, ast.ImportFrom):
        base = _resolve_import_from_base(node, rel_mod)
        bound_targets = [f"{base}.{a.name}" if base else a.name for a in node.names]
        all_targets = ([base, *bound_targets] if base else list(bound_targets))
    if not all_targets:
        return
    if rel_mod.startswith("core.execution.rpc"):
        _assert_rpc_readonly_fs_import(node, bound_targets, rel_mod)
    applicable_bad = [bad for mod_p, bads in forbidden_by_prefix if rel_mod.startswith(mod_p) for bad in bads]
    for imp in all_targets:
        if any(imp.startswith(bad) for bad in applicable_bad):
            raise AssertionError(f"Illegal reverse import in {rel_mod}: {imp}")
    if (
        isinstance(node, ast.ImportFrom)
        and base == "core.foundation"
        and any(bad.startswith("core.foundation.") for bad in applicable_bad)
    ):
        raise AssertionError(f"Illegal barrel import from core.foundation in {rel_mod}")
    for b_imp in bound_targets:
        if any(bad.startswith(f"{b_imp}.") for bad in applicable_bad):
            raise AssertionError(f"Illegal parent-package umbrella import in {rel_mod}: {b_imp}")


def _assert_no_local_imports(fn_node: ast.FunctionDef | ast.AsyncFunctionDef, label: str) -> None:
    for sub in ast.walk(fn_node):
        if isinstance(sub, (ast.Import, ast.ImportFrom)):
            raise AssertionError(f"Function-local import forbidden in {label}:{fn_node.name}:{sub.lineno}")


def _collect_ast_and_str_ann_loads(tree: ast.AST) -> set[str]:
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
    for n in ast.walk(tree):
        if isinstance(n, ast.AnnAssign) and isinstance(n.annotation, ast.Constant) and isinstance(n.annotation.value, str):
            try:
                ann_t = ast.parse(n.annotation.value, mode="eval")
                used.update(sn.id for sn in ast.walk(ann_t) if isinstance(sn, ast.Name))
            except SyntaxError:
                pass
    return used


def _assert_all_ann_assign_symbols_resolve(tree: ast.AST, label: str) -> None:
    if not isinstance(tree, ast.Module):
        return
    known = {k for k, _ in inspect.getmembers_static(builtins)}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            known.update(al.asname or al.name.split(".")[0] for al in node.names)
        elif isinstance(node, ast.ImportFrom):
            known.update(al.asname or al.name for al in node.names)
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            known.add(node.name)
        elif isinstance(node, ast.arg):
            known.add(node.arg)
        elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            known.add(node.id)
    ann_nodes = [n for n in ast.walk(tree) if isinstance(n, ast.AnnAssign) and n.annotation is not None]
    for node in ann_nodes:
        for sub in ast.walk(node.annotation):
            if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Load):
                _check(
                    sub.id in known,
                    lambda s=sub.id, ln=node.lineno: f"Unimported annotation symbol {s!r} in {label}:{ln}",
                )


def _assert_no_unused_top_imports(tree: ast.AST, label: str) -> None:
    _assert_all_ann_assign_symbols_resolve(tree, label)
    if not isinstance(tree, ast.Module):
        return
    seen_bound: set[str] = set()
    for stmt in tree.body:
        if isinstance(stmt, ast.Import):
            for al in stmt.names:
                nm = al.asname or al.name.split(".")[0]
                _check(nm not in seen_bound, lambda: f"Duplicate top-level import '{nm}' in {label}:{stmt.lineno}")
                seen_bound.add(nm)
        elif isinstance(stmt, ast.ImportFrom) and stmt.module != "__future__":
            for al in stmt.names:
                nm = al.asname or al.name
                _check(nm not in seen_bound, lambda: f"Duplicate top-level import '{nm}' in {label}:{stmt.lineno}")
                seen_bound.add(nm)
    if label.endswith("__init__.py"):
        return
    used = _collect_ast_and_str_ann_loads(tree)
    for nm in seen_bound:
        _check(nm in used, lambda: f"Unused import '{nm}' in {label}")


def _assert_no_stateless_private_methods(tree: ast.AST, label: str) -> None:
    for cls_node in ast.walk(tree):
        if not isinstance(cls_node, ast.ClassDef) or cls_node.bases:
            continue
        for ch in cls_node.body:
            if not isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            if not ch.name.startswith("_") or ch.name.startswith("__") or _is_stub_ellipsis_fn(ch):
                continue
            decs = {
                d.id if isinstance(d, ast.Name) else (d.attr if isinstance(d, ast.Attribute) else "")
                for d in ch.decorator_list
            }
            if decs & {"staticmethod", "classmethod", "abstractmethod", "overload"}:
                continue
            pos_args = [*ch.args.posonlyargs, *ch.args.args]
            if not pos_args or pos_args[0].arg != "self":
                continue
            used = {
                sub.id
                for st in ch.body
                for sub in ast.walk(st)
                if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Load)
            }
            _check("self" in used, lambda: f"Stateless private method '{cls_node.name}.{ch.name}' in {label}:{ch.lineno}")


def _assert_no_cross_collaborator_private_calls(tree: ast.AST, label: str) -> None:
    for node in ast.walk(tree):
        if (
            isinstance(node, ast.Attribute)
            and node.attr.startswith("_")
            and not node.attr.startswith("__")
            and isinstance(node.value, ast.Attribute)
            and isinstance(node.value.value, ast.Name)
            and node.value.value.id == "self"
            and node.value.attr in {
                "_gates",
                "_tier1_pool",
                "_coordinator",
                "_routes",
                "_sessions",
                "_step_host",
                "_container",
                "_tier0_slots",
                "_cold_locks",
                "channel",
            }
        ):
            raise AssertionError(
                f"Cross-collaborator private access 'self.{node.value.attr}.{node.attr}' forbidden in {label}:{node.lineno}"
            )


def _assert_no_duplicate_defs(tree: ast.AST, label: str) -> None:
    for scope in ast.walk(tree):
        if not isinstance(scope, (ast.Module, ast.ClassDef)):
            continue
        seen_names: set[str] = set()
        for ch in scope.body:
            if not isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            is_ov = any(
                (isinstance(d, ast.Name) and d.id == "overload")
                or (isinstance(d, ast.Attribute) and d.attr == "overload")
                for d in ch.decorator_list
            )
            if is_ov:
                continue
            _check(ch.name not in seen_names, lambda: f"Duplicate function/method {ch.name} in {label}:{ch.lineno}")
            seen_names.add(ch.name)


def _is_stub_ellipsis_fn(node: ast.FunctionDef | ast.AsyncFunctionDef) -> bool:
    if any(
        (isinstance(d, ast.Name) and d.id in {"overload", "abstractmethod"})
        or (isinstance(d, ast.Attribute) and d.attr in {"overload", "abstractmethod"})
        for d in node.decorator_list
    ):
        return True
    stmts = node.body
    if len(stmts) == 1 and isinstance(stmts[0], ast.Expr) and isinstance(stmts[0].value, ast.Constant):
        return stmts[0].value.value is Ellipsis
    if (
        len(stmts) == 2
        and isinstance(stmts[0], ast.Expr)
        and isinstance(stmts[0].value, ast.Constant)
        and isinstance(stmts[0].value.value, str)
        and isinstance(stmts[1], ast.Expr)
        and isinstance(stmts[1].value, ast.Constant)
    ):
        return stmts[1].value.value is Ellipsis
    return False


def _assert_no_unused_function_params(node: ast.FunctionDef | ast.AsyncFunctionDef, label: str) -> None:
    if _is_stub_ellipsis_fn(node):
        return
    if (label.startswith("embedded:") or label.startswith("inline_py_")) and node.name in {"run", "on_start", "on_init"}:
        return
    used = {
        sub.id
        for stmt in node.body
        for sub in ast.walk(stmt)
        if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Load)
    }
    all_args = [*node.args.posonlyargs, *node.args.args, *node.args.kwonlyargs]
    if node.args.vararg is not None:
        all_args.append(node.args.vararg)
    if node.args.kwarg is not None:
        all_args.append(node.args.kwarg)
    for idx, arg in enumerate(all_args):
        if (idx == 0 and arg.arg in {"self", "cls"}) or arg.arg.startswith("_"):
            continue
        if arg.arg not in used:
            raise AssertionError(f"Unused parameter '{arg.arg}' in {label}:{node.name} (line {node.lineno})")


_ROUND_SYM_RE: Final[re.Pattern[str]] = re.compile(
    r"(?:^|_)(?:round\d+|rig_\d+|r[1-9]\d*(?!c\d))(?:_|[A-Z]|$)", re.IGNORECASE
)
_LOCAL_RIG_NUM_RE: Final[re.Pattern[str]] = re.compile(r"^_?rig_\d+$", re.IGNORECASE)


def _assert_zero_round_symbol_names(tree: ast.AST, label: str) -> None:
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and _ROUND_SYM_RE.search(node.name):
            raise AssertionError(f"Round-numbered symbol '{node.name}' forbidden in {label}:{node.lineno}")
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            if _LOCAL_RIG_NUM_RE.match(node.id) or (len(node.id) >= 4 and _ROUND_SYM_RE.search(node.id)):
                raise AssertionError(f"Round/lineno-numbered variable '{node.id}' forbidden in {label}:{node.lineno}")


def _audit_ast_tree_metrics(tree: ast.AST, label: str, *, allow_import_module: bool = False) -> None:
    _assert_no_unused_top_imports(tree, label)
    _assert_no_duplicate_defs(tree, label)
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and node.id == "Any":
            raise AssertionError(f"Any forbidden in {label}:{node.lineno}")
        if isinstance(node, ast.Attribute) and node.attr in {"Any", "getattr", "setattr", "hasattr", "delattr"}:
            raise AssertionError(f"Forbidden attribute '{node.attr}' in {label}:{node.lineno}")
        if isinstance(node, ast.Attribute):
            _check(node.attr != "__dict__", lambda: f"Direct .__dict__ reflection forbidden in {label}:{node.lineno}")
            if not allow_import_module:
                _check(node.attr != "import_module", lambda: f"Runtime import_module forbidden in {label}:{node.lineno}")
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            _check(node.func.id != "print", lambda: f"Bare print() forbidden in {label}:{node.lineno}")
            _check(node.func.id not in {"getattr", "setattr", "hasattr", "delattr", "__import__", "vars", "dir"}, lambda: f"Dynamic {node.func.id} forbidden in {label}")
        if isinstance(node, ast.Assert):
            raise AssertionError(f"Bare assert forbidden under -O in {label}:{node.lineno}")
        if isinstance(node, ast.Lambda) and isinstance(node.body, ast.Tuple) and len(node.body.elts) >= 3:
            raise AssertionError(f"Wide 3+ tuple lambda forbidden in {label}:{node.lineno}")
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            _assert_no_local_imports(node, label)
            _assert_no_wide_tuple_params(node, label)
            _assert_no_unused_function_params(node, label)
            all_args = [*node.args.posonlyargs, *node.args.args, *node.args.kwonlyargs]
            p_cnt = len(all_args) - (1 if all_args and all_args[0].arg in {"self", "cls"} else 0)
            p_cnt += (1 if node.args.vararg else 0) + (1 if node.args.kwarg else 0)
            _check(p_cnt <= 6, lambda: f"Function {label}:{node.name} has {p_cnt} parameters (> 6)")
            loc = _function_body_loc(node)
            span = (node.end_lineno or node.lineno) - node.lineno + 1
            _check(loc <= 75 and span <= 75, lambda: f"Function {label}:{node.name} exceeds 75 lines (span={span})")
            depth = _max_control_flow_depth(node, 0)
            _check(depth <= 3, lambda: f"Function {label}:{node.name} has nesting depth {depth} (> 3)")


def _assert_zero_comment_noise_bytes(raw_bytes: bytes, label: str) -> None:
    comment_noise_re = re.compile(
        r"\b(?:FR-\d+|DR-\d+|EC-\d+|AUD-[A-Z0-9_-]+|P[0-3](?:-\d+)?|D[1-5]|S[1-6]|RC-\d+|N-\d+|"
        r"R[1-9]\d*(?:-[A-Z0-9]+)?|Issue-\d+|TODO|FIXME)\b|#\s*Step\s+\d+|#\s*Sub-path\s+\d+|\bProbe\s+[A-Z0-9]|^#\s*[-=]{3,}",
        re.IGNORECASE,
    )
    lines = raw_bytes.splitlines(keepends=True)
    it = iter(lines)
    for tok in tokenize.tokenize(lambda: next(it, b"")):
        if tok.type == tokenize.COMMENT:
            m = comment_noise_re.search(tok.string)
            _check(m is None, lambda: f"Forbidden comment noise '{m.group(0)}' in {label}:{tok.start[0]}")


def _assert_zero_comment_noise(py_path: Path) -> None:
    _assert_zero_comment_noise_bytes(py_path.read_bytes(), py_path.name)


_ROUND_STR_NOISE_RE: Final[re.Pattern[str]] = re.compile(
    r"(?:blind[-_ ]?review|\bround[-_ ]?\d+\b|(?:_|-)r[1-9]\d*(?:$|[/_-]))",
    re.IGNORECASE,
)


def _assert_zero_round_string_literals(tree: ast.AST, label: str) -> None:
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            m = _ROUND_STR_NOISE_RE.search(node.value)
            _check(m is None, lambda: f"Forbidden round/review string noise {m.group(0)!r} in {label}:{node.lineno}")


def _audit_self_test_ast() -> None:
    self_path = Path(__file__).resolve()
    src = self_path.read_text(encoding="utf-8")
    _check(("# type" + ": ignore") not in src, "Test suite must not suppress static type checks")
    _assert_zero_comment_noise(self_path)
    _verify_symtable_clean(src, self_path.name)
    self_tree = ast.parse(src, filename=self_path.name)
    _assert_zero_round_symbol_names(self_tree, self_path.name)
    _assert_zero_round_string_literals(self_tree, self_path.name)
    _audit_ast_tree_metrics(self_tree, self_path.name)
    _verify_module_runtime_type_hints(__name__)
    for tpl_name, tpl_src in (
        ("space", _SPACE_MODULE_SRC),
        ("broken_opt", _BROKEN_OPT_MODULE_SRC),
        ("vsc", _VSC_MODULE_SRC),
        ("dev", _DEV_MODULE_SRC),
        ("ast", _AST_MODULE_SRC),
        ("kdb", _KDB_MODULE_SRC),
        ("gdrive", _GDRIVE_MODULE_SRC),
        ("cprobe", _COORD_PROBE_MOD_SRC),
        ("mhop", _MHOP_MODULE_SRC),
        ("ofm", _ORPHAN_FOLD_MOD_SRC),
        ("fob", _FOLD_ORPHAN_BRIDGE_SRC),
        ("tcm", _TRANS_CANCEL_MOD_SRC),
        ("mbl", _MB_LINEAGE_MOD_SRC),
        ("ocg", _ORPHAN_CG_AND_STRICT_IMM_SRC),
        ("pfm", _PRIVATE_FATAL_MOD_SRC),
        ("opb", _ORPHAN_PUB_BASE_MOD_SRC),
        ("xg1", _XGRP_OUTER_SRC),
        ("xg2", _XGRP_INNER_SRC),
        ("lhc", _LPC_HOST_CYCLE_ORPHAN_SRC),
    ):
        label = f"embedded:{tpl_name}"
        _verify_symtable_clean(tpl_src, label)
        tpl_tree = ast.parse(tpl_src, filename=label)
        _assert_zero_round_symbol_names(tpl_tree, label)
        _audit_ast_tree_metrics(tpl_tree, label)
    _audit_inline_module_entry_literals(self_tree)


def _walk_runtime_type_hints(container: object, mod_name: str, seen: set[int]) -> None:
    oid = id(container)
    if oid in seen:
        return
    seen.add(oid)
    for attr_name, val in inspect.getmembers_static(container):
        if attr_name.startswith("__") and attr_name not in {"__init__", "__call__"}:
            continue
        if isinstance(val, property):
            if val.fget is not None and val.fget.__module__ == mod_name:
                typing.get_type_hints(val.fget, include_extras=True)
            continue
        if isinstance(val, (staticmethod, classmethod)):
            fn = val.__func__
            if fn.__module__ == mod_name:
                typing.get_type_hints(fn, include_extras=True)
            continue
        if inspect.isclass(val) and val.__module__ == mod_name:
            typing.get_type_hints(val, include_extras=True)
            _walk_runtime_type_hints(val, mod_name, seen)
        elif inspect.isfunction(val) and val.__module__ == mod_name:
            typing.get_type_hints(val, include_extras=True)


def _assert_module_class_self_attrs(mod: object, mod_name: str) -> None:
    src_file = inspect.getsourcefile(mod) if inspect.ismodule(mod) else None
    if src_file is None:
        return
    tree = ast.parse(Path(src_file).read_text(encoding="utf-8"), filename=mod_name)
    cls_map = {k: v for k, v in inspect.getmembers_static(mod) if inspect.isclass(v) and v.__module__ == mod_name}
    ast_cls_map = {n.name: n for n in tree.body if isinstance(n, ast.ClassDef)}
    for node in tree.body:
        if not isinstance(node, ast.ClassDef) or node.name not in cls_map:
            continue
        defined = {k for k, _ in inspect.getmembers_static(cls_map[node.name])}
        for base_c in cls_map[node.name].__mro__:
            defined.update(k for k, _ in inspect.getmembers_static(base_c))
            base_ast = ast_cls_map.get(base_c.__name__)
            if base_ast is not None:
                defined.update(
                    sub.attr
                    for sub in ast.walk(base_ast)
                    if isinstance(sub, ast.Attribute) and isinstance(sub.value, ast.Name) and sub.value.id == "self" and isinstance(sub.ctx, ast.Store)
                )
        for sub in ast.walk(node):
            if isinstance(sub, ast.Attribute) and isinstance(sub.value, ast.Name) and sub.value.id == "self" and isinstance(sub.ctx, ast.Load):
                _check(sub.attr in defined, lambda: f"Undefined self.{sub.attr} in {mod_name}.{node.name}:{sub.lineno}")
            if (
                isinstance(sub, ast.Call)
                and isinstance(sub.func, ast.Attribute)
                and isinstance(sub.func.value, ast.Name)
                and sub.func.value.id == "self"
            ):
                _assert_self_method_call_arity(cls_map[node.name], sub, f"{mod_name}.{node.name}")


def _assert_self_method_call_arity(cls_obj: type[object], call_node: ast.Call, label: str) -> None:
    _check(isinstance(call_node.func, ast.Attribute))
    m_name = call_node.func.attr
    raw_member = dict(inspect.getmembers_static(cls_obj)).get(m_name)
    if raw_member is None:
        return
    if isinstance(raw_member, property):
        raise AssertionError(f"Property self.{m_name} called as method in {label}:{call_node.lineno}")
    target_fn = raw_member.__func__ if isinstance(raw_member, (staticmethod, classmethod)) else raw_member
    if not inspect.isfunction(target_fn):
        return
    if any(isinstance(a, ast.Starred) for a in call_node.args) or any(k.arg is None for k in call_node.keywords):
        return
    sig = inspect.signature(target_fn)
    params = list(sig.parameters.values())
    if not isinstance(raw_member, staticmethod) and params:
        params = params[1:]
    bound_sig = sig.replace(parameters=params)
    dummy_pos = [None] * len(call_node.args)
    dummy_kw = {k.arg: None for k in call_node.keywords if k.arg is not None}
    try:
        bound_sig.bind(*dummy_pos, **dummy_kw)
    except TypeError as exc:
        raise AssertionError(f"Arity/kw mismatch calling self.{m_name} in {label}:{call_node.lineno}: {exc}") from exc


def _verify_module_runtime_type_hints(mod_name: str) -> None:
    mod = sys.modules[mod_name]
    _walk_runtime_type_hints(mod, mod_name, set())
    _assert_module_class_self_attrs(mod, mod_name)
    src_file = inspect.getsourcefile(mod) if inspect.ismodule(mod) else None
    if src_file is None:
        return
    tree = ast.parse(Path(src_file).read_text(encoding="utf-8"), filename=mod_name)
    ns_classes = {k: v for k, v in inspect.getmembers_static(mod) if inspect.isclass(v)}
    for sub in ast.walk(tree):
        if isinstance(sub, ast.Attribute) and isinstance(sub.value, ast.Name) and isinstance(sub.ctx, ast.Load):
            target_cls = ns_classes.get(sub.value.id)
            if target_cls is None:
                continue
            valid = {k for base_c in target_cls.__mro__ for k, _ in inspect.getmembers_static(base_c)}
            _check(sub.attr in valid, lambda: f"Undefined {sub.value.id}.{sub.attr} in {mod_name}:{sub.lineno}")


def _is_overload_decorated(fn_node: ast.FunctionDef | ast.AsyncFunctionDef) -> bool:
    return any(
        (isinstance(d, ast.Name) and d.id == "overload") or (isinstance(d, ast.Attribute) and d.attr == "overload")
        for d in fn_node.decorator_list
    )


def _is_property_decorated(fn_node: ast.FunctionDef | ast.AsyncFunctionDef) -> bool:
    return any(isinstance(d, ast.Name) and d.id == "property" for d in fn_node.decorator_list)


def _method_decorator_tags(fn_node: ast.FunctionDef | ast.AsyncFunctionDef) -> set[str]:
    tags: set[str] = set()
    for dec in fn_node.decorator_list:
        nm = dec.id if isinstance(dec, ast.Name) else (dec.attr if isinstance(dec, ast.Attribute) else "")
        if nm in {"property", "staticmethod", "classmethod", "contextmanager"}:
            tags.add(nm)
    return tags


def _strip_ann_quotes(expr: ast.expr) -> ast.expr:
    if isinstance(expr, ast.Constant) and isinstance(expr.value, str):
        try:
            return _strip_ann_quotes(ast.parse(expr.value, mode="eval").body)
        except SyntaxError:
            return expr
    if isinstance(expr, ast.Subscript):
        if isinstance(expr.value, ast.Name) and expr.value.id == "Literal":
            return expr
        return ast.Subscript(value=_strip_ann_quotes(expr.value), slice=_strip_ann_quotes(expr.slice), ctx=expr.ctx)
    if isinstance(expr, ast.Tuple):
        return ast.Tuple(elts=[_strip_ann_quotes(e) for e in expr.elts], ctx=expr.ctx)
    if isinstance(expr, ast.List):
        return ast.List(elts=[_strip_ann_quotes(e) for e in expr.elts], ctx=expr.ctx)
    if isinstance(expr, ast.BinOp) and isinstance(expr.op, ast.BitOr):
        return ast.BinOp(left=_strip_ann_quotes(expr.left), op=expr.op, right=_strip_ann_quotes(expr.right))
    if isinstance(expr, ast.Attribute) and isinstance(expr.value, ast.Name) and expr.value.id in {"typing", "cabc"}:
        return ast.Name(id=expr.attr, ctx=ast.Load())
    return expr


def _norm_ann_ast(node: Optional[ast.expr], alias_map: Mapping[str, str] = {}) -> str:
    if node is None:
        return "<missing>"
    cleaned = _strip_ann_quotes(node)
    if (
        isinstance(cleaned, ast.Subscript)
        and isinstance(cleaned.value, ast.Name)
        and cleaned.value.id == "Optional"
    ):
        inner = _norm_ann_ast(cleaned.slice, alias_map)
        return f"Optional[{inner}]"
    if isinstance(cleaned, ast.BinOp) and isinstance(cleaned.op, ast.BitOr):
        left_s = _norm_ann_ast(cleaned.left, alias_map)
        right_s = _norm_ann_ast(cleaned.right, alias_map)
        if right_s == "None":
            return f"Optional[{left_s}]"
    txt = ast.unparse(cleaned)
    for k, v in alias_map.items():
        if txt == k:
            return v
    return txt


def _norm_dflt_ast(node: Optional[ast.expr]) -> Optional[str]:
    if node is None:
        return None
    if isinstance(node, ast.Constant) and node.value is Ellipsis:
        return "<has_default>"
    return ast.unparse(node)


@dataclass(frozen=True, slots=True)
class _AstParamSig:
    name: str
    kind: str
    ann: str
    default: Optional[str]


def _ast_full_param_sig(
    fn_node: ast.FunctionDef | ast.AsyncFunctionDef,
    *,
    drop_self: bool,
    alias_map: Mapping[str, str] = {},
) -> list[_AstParamSig]:
    posonly = [(a, "posonly") for a in fn_node.args.posonlyargs]
    reg_pos = [(a, "pos") for a in fn_node.args.args]
    combined = [*posonly, *reg_pos]
    pad = len(combined) - len(fn_node.args.defaults)
    pos_dflts: list[Optional[ast.expr]] = [None] * pad + list(fn_node.args.defaults)
    out: list[_AstParamSig] = []
    for idx, ((arg, kind), dflt) in enumerate(zip(combined, pos_dflts)):
        if drop_self and idx == 0 and arg.arg in {"self", "cls"}:
            continue
        out.append(_AstParamSig(arg.arg, kind, _norm_ann_ast(arg.annotation, alias_map), _norm_dflt_ast(dflt)))
    if fn_node.args.vararg is not None:
        va = fn_node.args.vararg
        out.append(_AstParamSig(va.arg, "vararg", _norm_ann_ast(va.annotation, alias_map), None))
    for kw_arg, kw_dflt in zip(fn_node.args.kwonlyargs, fn_node.args.kw_defaults):
        out.append(_AstParamSig(kw_arg.arg, "kw", _norm_ann_ast(kw_arg.annotation, alias_map), _norm_dflt_ast(kw_dflt)))
    if fn_node.args.kwarg is not None:
        ka = fn_node.args.kwarg
        out.append(_AstParamSig(ka.arg, "kwarg", _norm_ann_ast(ka.annotation, alias_map), None))
    return out


def _resolve_ast_expr_value(node: ast.expr, ns: Mapping[str, object]) -> object:
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Tuple):
        return tuple(_resolve_ast_expr_value(e, ns) for e in node.elts)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub) and isinstance(node.operand, ast.Constant):
        val = node.operand.value
        _check(isinstance(val, (int, float)))
        return -val
    if isinstance(node, ast.Name):
        if node.id == "frozenset":
            return frozenset
        _check(node.id in ns, lambda: f"Unresolved default symbol {node.id!r}")
        return ns[node.id]
    if isinstance(node, ast.Attribute):
        base = _resolve_ast_expr_value(node.value, ns)
        return dict(inspect.getmembers_static(base))[node.attr]
    if isinstance(node, ast.Call) and not node.args and not node.keywords:
        fn = _resolve_ast_expr_value(node.func, ns)
        _check(callable(fn))
        return fn()
    raise AssertionError(f"Unsupported spec default AST expression: {ast.unparse(node)}")


def _assert_default_matches_runtime(
    label: str,
    dflt_node: Optional[ast.expr],
    rt_default: object,
    ns: Mapping[str, object],
) -> None:
    if dflt_node is None:
        _check(rt_default is inspect.Parameter.empty, lambda: f"Unexpected runtime default on {label}: {rt_default!r}")
        return
    _check(rt_default is not inspect.Parameter.empty, lambda: f"Missing runtime default on {label}")
    if isinstance(dflt_node, ast.Constant) and dflt_node.value is Ellipsis:
        return
    exp_val = _resolve_ast_expr_value(dflt_node, ns)
    _check(type(exp_val) is type(rt_default) and exp_val == rt_default, lambda: f"Default value drift on {label}: spec={exp_val!r} vs runtime={rt_default!r}")


def _assert_fn_ast_and_runtime_parity(
    label: str,
    spec_fn: ast.FunctionDef | ast.AsyncFunctionDef,
    impl_fn: ast.FunctionDef | ast.AsyncFunctionDef,
    rt_member: object,
    ctx_maps: tuple[Mapping[str, object], Mapping[str, str]],
    *,
    is_method: bool,
) -> None:
    ns, alias_map = ctx_maps
    if _is_property_decorated(spec_fn):
        _check(isinstance(rt_member, property) and _is_property_decorated(impl_fn), lambda: f"{label} @property drift")
        _check(_norm_ann_ast(spec_fn.returns, alias_map) == _norm_ann_ast(impl_fn.returns, alias_map), lambda: f"Property return type drift on {label}: {ast.unparse(spec_fn.returns or ast.Constant(None))} vs {ast.unparse(impl_fn.returns or ast.Constant(None))}")
        return
    is_static = isinstance(rt_member, staticmethod)
    drop_s = is_method and not is_static
    s_sig = _ast_full_param_sig(spec_fn, drop_self=drop_s, alias_map=alias_map)
    i_sig = _ast_full_param_sig(impl_fn, drop_self=drop_s, alias_map=alias_map)
    _check(len(s_sig) == len(i_sig), lambda: f"Param count drift on {label}: {s_sig} vs {i_sig}")
    for sp_p, im_p in zip(s_sig, i_sig):
        _check((sp_p.name, sp_p.kind) == (im_p.name, im_p.kind) and sp_p.ann == im_p.ann, lambda: f"Param type/kind drift on {label}: spec={sp_p} vs impl={im_p}")
        if sp_p.default != "<has_default>":
            _check(sp_p.default == im_p.default, lambda: f"Param AST default drift on {label}.{sp_p.name}: spec={sp_p.default} vs impl={im_p.default}")
    s_ret = _norm_ann_ast(spec_fn.returns, alias_map)
    i_ret = _norm_ann_ast(impl_fn.returns, alias_map)
    _check(s_ret == i_ret, lambda: f"Return type drift on {label}: spec={s_ret} vs impl={i_ret}")
    raw_fn = rt_member.__func__ if isinstance(rt_member, (staticmethod, classmethod)) else rt_member
    _check(callable(raw_fn))
    rt_params = list(inspect.signature(raw_fn).parameters.values())
    if drop_s and rt_params and rt_params[0].name in {"self", "cls"}:
        rt_params = rt_params[1:]
    spec_dflts = _collect_spec_param_dflt_nodes(spec_fn, drop_self=drop_s)
    for (p_name, d_node), r_p in zip(spec_dflts, rt_params):
        _assert_default_matches_runtime(f"{label}.{p_name}", d_node, r_p.default, ns)


def _collect_spec_param_dflt_nodes(
    fn_node: ast.FunctionDef | ast.AsyncFunctionDef,
    *,
    drop_self: bool,
) -> list[tuple[str, Optional[ast.expr]]]:
    comb = [*fn_node.args.posonlyargs, *fn_node.args.args]
    pos_d: list[Optional[ast.expr]] = [None] * (len(comb) - len(fn_node.args.defaults)) + list(fn_node.args.defaults)
    out: list[tuple[str, Optional[ast.expr]]] = []
    for idx, (a, d) in enumerate(zip(comb, pos_d)):
        if drop_self and idx == 0 and a.arg in {"self", "cls"}:
            continue
        out.append((a.arg, d))
    if fn_node.args.vararg is not None:
        out.append((fn_node.args.vararg.arg, None))
    for ka, kd in zip(fn_node.args.kwonlyargs, fn_node.args.kw_defaults):
        out.append((ka.arg, kd))
    if fn_node.args.kwarg is not None:
        out.append((fn_node.args.kwarg.arg, None))
    return out


@dataclass(slots=True)
class _ParsedModuleAstIndex:
    classes: dict[str, ast.ClassDef] = field(default_factory=dict)
    functions: dict[str, ast.FunctionDef | ast.AsyncFunctionDef] = field(default_factory=dict)
    overloads: dict[str, list[ast.FunctionDef | ast.AsyncFunctionDef]] = field(default_factory=dict)
    cls_methods: dict[str, dict[str, ast.FunctionDef | ast.AsyncFunctionDef]] = field(default_factory=dict)
    cls_overloads: dict[str, dict[str, list[ast.FunctionDef | ast.AsyncFunctionDef]]] = field(default_factory=dict)
    aliases: dict[str, str] = field(default_factory=dict)
    exported_syms: set[str] = field(default_factory=set)
    value_exprs: dict[str, ast.expr] = field(default_factory=dict)


def _index_single_class_ast(stmt: ast.ClassDef, idx: _ParsedModuleAstIndex) -> None:
    idx.exported_syms.add(stmt.name)
    idx.classes[stmt.name] = stmt
    m_map = idx.cls_methods.setdefault(stmt.name, {})
    ov_map = idx.cls_overloads.setdefault(stmt.name, {})
    for ch in stmt.body:
        if not isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        if _is_overload_decorated(ch):
            ov_map.setdefault(ch.name, []).append(ch)
        elif not ch.name.startswith("_") or ch.name == "__init__":
            m_map[ch.name] = ch


def _index_single_assign_ast(stmt: ast.Assign, idx: _ParsedModuleAstIndex, ignored: frozenset[str]) -> None:
    if isinstance(stmt.value, ast.Call) and isinstance(stmt.value.func, ast.Name) and stmt.value.func.id == "TypeVar":
        return
    is_type_expr = isinstance(stmt.value, (ast.Name, ast.Subscript, ast.BinOp))
    for t in stmt.targets:
        if isinstance(t, ast.Name) and t.id not in ignored:
            idx.exported_syms.add(t.id)
            idx.value_exprs[t.id] = stmt.value
            if is_type_expr:
                idx.aliases[t.id] = _norm_ann_ast(stmt.value)


def _index_single_func_ast(
    stmt: ast.FunctionDef | ast.AsyncFunctionDef,
    idx: _ParsedModuleAstIndex,
    *,
    reject_collisions: bool,
) -> None:
    idx.exported_syms.add(stmt.name)
    if _is_overload_decorated(stmt):
        idx.overloads.setdefault(stmt.name, []).append(stmt)
        return
    if reject_collisions and not stmt.name.startswith("_"):
        _check(stmt.name not in idx.functions, lambda: f"Duplicate kernel public function '{stmt.name}'")
    idx.functions[stmt.name] = stmt


def _index_ast_statements(
    stmts: Sequence[ast.stmt],
    idx: _ParsedModuleAstIndex,
    *,
    ignored: frozenset[str] = frozenset(),
    reject_collisions: bool = False,
) -> None:
    for stmt in stmts:
        if isinstance(stmt, ast.ClassDef):
            _check(not reject_collisions or stmt.name not in idx.classes, lambda: f"Duplicate kernel class '{stmt.name}'")
            _index_single_class_ast(stmt, idx)
        elif isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
            _index_single_func_ast(stmt, idx, reject_collisions=reject_collisions)
        elif isinstance(stmt, ast.Assign):
            _index_single_assign_ast(stmt, idx, ignored)
        elif isinstance(stmt, ast.AnnAssign) and isinstance(stmt.target, ast.Name) and stmt.target.id not in ignored:
            idx.exported_syms.add(stmt.target.id)
            if stmt.value is not None:
                idx.value_exprs[stmt.target.id] = stmt.value


def _build_kernel_ast_index() -> _ParsedModuleAstIndex:
    idx = _ParsedModuleAstIndex()
    py_all = sorted((CORE_SRC_ROOT / "core").rglob("*.py"))
    for py_f in py_all:
        if py_f.name != "__init__.py":
            tree = ast.parse(py_f.read_text(encoding="utf-8"), filename=py_f.name)
            _index_ast_statements(tree.body, idx, reject_collisions=True)
    for py_f in py_all:
        if py_f.name == "__init__.py":
            tree = ast.parse(py_f.read_text(encoding="utf-8"), filename=py_f.name)
            _index_ast_statements(tree.body, idx)
    return idx


def _build_spec_ast_index(md_path: Path) -> _ParsedModuleAstIndex:
    blocks = re.findall(r"```python\n(.*?)```", md_path.read_text(encoding="utf-8"), flags=re.DOTALL)
    _check(blocks, lambda: f"No python contract block found in {md_path.name}")
    ignored = frozenset({"TIn", "TOut", "TOut_co", "TPayload", "TReq", "TReqContra"})
    idx = _ParsedModuleAstIndex()
    for blk in blocks:
        _index_ast_statements(ast.parse(blk, filename=md_path.name).body, idx, ignored=ignored)
    return idx


def _lookup_mro_static_member(cls_obj: type[object], attr: str) -> object:
    for base in cls_obj.__mro__:
        for k, v in inspect.getmembers_static(base):
            if k == attr:
                return v
    raise AssertionError(f"Missing {cls_obj.__name__}.{attr}")


def _lookup_mro_method_ast(
    cls_obj: type[object],
    attr: str,
    kernel_idx: _ParsedModuleAstIndex,
) -> ast.FunctionDef | ast.AsyncFunctionDef:
    for base in cls_obj.__mro__:
        m_ast = kernel_idx.cls_methods.get(base.__name__, {}).get(attr)
        if m_ast is not None:
            return m_ast
    raise AssertionError(f"Missing kernel AST for {cls_obj.__name__}.{attr}")


def _dc_field_default_tag(val_node: Optional[ast.expr]) -> Optional[str]:
    if val_node is None:
        return None
    return _norm_dflt_ast(_strip_ann_quotes(val_node))


@dataclass(frozen=True, slots=True)
class _DcFieldSig:
    name: str
    ann: str
    default_tag: Optional[str]


def _extract_dc_field_sigs(
    cls_node: ast.ClassDef,
    alias_map: Mapping[str, str],
) -> list[_DcFieldSig]:
    out: list[_DcFieldSig] = []
    for ch in cls_node.body:
        if isinstance(ch, ast.AnnAssign) and isinstance(ch.target, ast.Name) and not ch.target.id.startswith("_"):
            out.append(_DcFieldSig(ch.target.id, _norm_ann_ast(ch.annotation, alias_map), _dc_field_default_tag(ch.value)))
    return out


def _assert_dc_fields_parity(
    label: str,
    spec_cls: ast.ClassDef,
    impl_cls: ast.ClassDef,
    alias_map: Mapping[str, str],
) -> None:
    s_dc = _extract_dc_field_sigs(spec_cls, alias_map)
    i_dc = _extract_dc_field_sigs(impl_cls, alias_map)
    if not s_dc:
        return
    _check(len(s_dc) == len(i_dc), lambda: f"Dataclass field count drift on {label}: {s_dc} vs {i_dc}")
    for sf, imf in zip(s_dc, i_dc):
        _check((sf.name, sf.ann) == (imf.name, imf.ann), lambda: f"Dataclass field type drift on {label}.{sf.name}: spec={sf.ann} vs impl={imf.ann}")
        if sf.default_tag not in {"<has_default>", "<field_factory>"} and imf.default_tag != "<field_factory>":
            _check(sf.default_tag == imf.default_tag, lambda: f"Dataclass default drift on {label}.{sf.name}: spec={sf.default_tag} vs impl={imf.default_tag}")
        else:
            _check((sf.default_tag is not None) == (imf.default_tag is not None), lambda: f"Dataclass default presence drift on {label}.{sf.name}")


def _extract_spec_dc_flags(spec_cls: ast.ClassDef) -> tuple[bool, bool]:
    for dec in spec_cls.decorator_list:
        if isinstance(dec, ast.Name) and dec.id == "dataclass":
            return (False, False)
        if isinstance(dec, ast.Call) and isinstance(dec.func, ast.Name) and dec.func.id == "dataclass":
            kw = {k.arg: bool(ast.literal_eval(k.value)) for k in dec.keywords if k.arg in {"frozen", "slots"}}
            return (kw.get("frozen", False), kw.get("slots", False))
    return (False, False)


def _assert_dc_decorator_flags_parity(label: str, cls_obj: type[object], spec_cls: ast.ClassDef) -> None:
    exp_frozen, exp_slots = _extract_spec_dc_flags(spec_cls)
    dc_params = dict(inspect.getmembers_static(cls_obj)).get("__dataclass_params__")
    rt_frozen = bool(dc_params is not None and dc_params.frozen is True)
    rt_slots = "__slots__" in dict(inspect.getmembers_static(cls_obj))
    _check((rt_frozen, rt_slots) == (exp_frozen, exp_slots), lambda: f"Dataclass flags drift on {label}: impl=(frozen={rt_frozen}, slots={rt_slots}) vs spec=({exp_frozen}, {exp_slots})")


def _assert_class_bases_and_abstract_parity(label: str, cls_obj: type[object], spec_cls: ast.ClassDef) -> None:
    s_bases: list[str] = []
    for b in spec_cls.bases:
        nm = b.value.id if isinstance(b, ast.Subscript) and isinstance(b.value, ast.Name) else (b.id if isinstance(b, ast.Name) else "")
        if nm and nm != "Generic":
            s_bases.append(nm)
    rt_bases = [b.__name__ for b in cls_obj.__bases__ if b.__name__ not in {"object", "Generic"}]
    _check(s_bases == rt_bases, lambda: f"Base class drift on {label}: spec={s_bases} vs impl={rt_bases}")
    s_abs = {
        ch.name
        for ch in spec_cls.body
        if isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef))
        and any(
            (isinstance(d, ast.Name) and d.id == "abstractmethod")
            or (isinstance(d, ast.Attribute) and d.attr == "abstractmethod")
            for d in ch.decorator_list
        )
    }
    rt_abs = set(dict(inspect.getmembers_static(cls_obj)).get("__abstractmethods__", ()))
    _check(s_abs == rt_abs, lambda: f"Abstract methods drift on {label}: spec={sorted(s_abs)} vs impl={sorted(rt_abs)}")


def _assert_spec_constants_parity(fname: str, spec_idx: _ParsedModuleAstIndex, kernel_idx: _ParsedModuleAstIndex, ns_map: Mapping[str, object]) -> None:
    for sym, s_expr in spec_idx.value_exprs.items():
        _check(sym in ns_map, lambda: f"Missing constant/alias {fname}:{sym}")
        k_expr = kernel_idx.value_exprs.get(sym)
        _check(k_expr is not None, lambda: f"Missing kernel assignment AST for {fname}:{sym}")
        _check(_norm_ann_ast(s_expr) == _norm_ann_ast(k_expr), lambda: f"Constant/alias definition drift on {fname}:{sym}: spec={ast.unparse(s_expr)} vs impl={ast.unparse(k_expr)}")


def _assert_class_full_parity(
    label: str,
    cls_obj: type[object],
    spec_cls: ast.ClassDef,
    impl_cls: ast.ClassDef,
    spec_idx: _ParsedModuleAstIndex,
    kernel_idx: _ParsedModuleAstIndex,
) -> None:
    alias_map = {**kernel_idx.aliases, **spec_idx.aliases}
    if typing.Protocol not in cls_obj.__mro__ and not issubclass(cls_obj, Enum):
        init_priv = [p for p in inspect.signature(cls_obj).parameters if p.startswith("_")]
        _check(not init_priv, lambda: f"Spec class {label} leaks private __init__ params: {init_priv}")
    _assert_class_bases_and_abstract_parity(label, cls_obj, spec_cls)
    if dataclasses.is_dataclass(cls_obj):
        _assert_dc_decorator_flags_parity(label, cls_obj, spec_cls)
    if not issubclass(cls_obj, Enum):
        _assert_dc_fields_parity(label, spec_cls, impl_cls, alias_map)
    if issubclass(cls_obj, Enum):
        s_enum = {
            ch.targets[0].id: ast.literal_eval(ch.value)
            for ch in spec_cls.body
            if isinstance(ch, ast.Assign) and len(ch.targets) == 1 and isinstance(ch.targets[0], ast.Name)
        }
        if s_enum:
            _check({m.name: m.value for m in cls_obj} == s_enum, lambda: f"Enum drift on {label}")
    spec_pub_m = {
        mn
        for base_c in cls_obj.__mro__
        for mn in spec_idx.cls_methods.get(base_c.__name__, {}).keys()
        if not mn.startswith("_")
    }
    impl_pub_m = {
        mn
        for base_c in cls_obj.__mro__
        for mn in kernel_idx.cls_methods.get(base_c.__name__, {}).keys()
        if not mn.startswith("_")
    }
    _check(impl_pub_m == spec_pub_m, lambda: f"Public method surface drift on {label}: impl={sorted(impl_pub_m)} vs spec={sorted(spec_pub_m)}")
    for pub_m in spec_pub_m:
        s_m_ast = _lookup_mro_method_ast(cls_obj, pub_m, spec_idx)
        i_m_ast = _lookup_mro_method_ast(cls_obj, pub_m, kernel_idx)
        _check(
            _method_decorator_tags(s_m_ast) == _method_decorator_tags(i_m_ast),
            lambda: f"Method decorator drift on {label}.{pub_m}: spec={sorted(_method_decorator_tags(s_m_ast))} vs impl={sorted(_method_decorator_tags(i_m_ast))}",
        )
    for m_name, s_ovs in spec_idx.cls_overloads.get(spec_cls.name, {}).items():
        i_ovs = kernel_idx.cls_overloads.get(impl_cls.name, {}).get(m_name, [])
        _check(len(s_ovs) == len(i_ovs), lambda: f"Overload count drift on {label}.{m_name}: {len(s_ovs)} vs {len(i_ovs)}")
        for ov_i, (s_ov, i_ov) in enumerate(zip(s_ovs, i_ovs)):
            _check(_ast_full_param_sig(s_ov, drop_self=True, alias_map=alias_map) == _ast_full_param_sig(
                i_ov, drop_self=True, alias_map=alias_map
            ), lambda: f"Overload #{ov_i} param drift on {label}.{m_name}")
            _check(_norm_ann_ast(s_ov.returns, alias_map) == _norm_ann_ast(i_ov.returns, alias_map), lambda: f"Overload #{ov_i} return drift on {label}.{m_name}")


def _build_spec_eval_ns(kernel_mods: Sequence[object]) -> dict[str, object]:
    merged: dict[str, object] = {}
    for mod in (
        core.foundation.primitives,
        core.foundation.errors,
        core.foundation.observability,
        core.execution.event,
        core.execution.lifecycle,
        rpc_pkg,
        core.execution.runtime,
        core.execution.daemon,
        *kernel_mods,
    ):
        merged.update(dict(inspect.getmembers_static(mod)))
    return merged


def _verify_execution_living_specs_parity() -> None:
    spec_dir = Path(__file__).resolve().parent / "sub_module_design" / "execution"
    kernel_idx = _build_kernel_ast_index()
    pairs: tuple[tuple[str, object], ...] = (
        ("event.md", core.execution.event),
        ("lifecycle.md", core.execution.lifecycle),
        ("rpc.md", rpc_pkg),
        ("runtime.md", core.execution.runtime),
        ("daemon.md", core.execution.daemon),
    )
    eval_ns = _build_spec_eval_ns([m for _, m in pairs])
    for fname, mod in pairs:
        spec_idx = _build_spec_ast_index(spec_dir / fname)
        alias_map = {**kernel_idx.aliases, **spec_idx.aliases}
        ns_map = dict(inspect.getmembers_static(mod))
        all_tuple = ns_map.get("__all__")
        _check(isinstance(all_tuple, tuple))
        _check(spec_idx.exported_syms == set(all_tuple), lambda: f"Spec drift in {fname}: diff={sorted(spec_idx.exported_syms ^ set(all_tuple))}")
        _assert_spec_constants_parity(fname, spec_idx, kernel_idx, ns_map)
        for fn_name, s_fn in spec_idx.functions.items():
            _assert_fn_ast_and_runtime_parity(
                f"{fname}:{fn_name}", s_fn, kernel_idx.functions[fn_name], ns_map[fn_name], (eval_ns, alias_map), is_method=False
            )
        for cname, m_dict in spec_idx.cls_methods.items():
            cls_obj = ns_map[cname]
            if not isinstance(cls_obj, type):
                continue
            impl_cls = kernel_idx.classes[cls_obj.__name__]
            _assert_class_full_parity(f"{fname}:{cname}", cls_obj, spec_idx.classes[cname], impl_cls, spec_idx, kernel_idx)
            for m_name, s_m in m_dict.items():
                rt_m = _lookup_mro_static_member(cls_obj, m_name)
                i_m = _lookup_mro_method_ast(cls_obj, m_name, kernel_idx)
                _assert_fn_ast_and_runtime_parity(
                    f"{fname}:{cname}.{m_name}", s_m, i_m, rt_m, (eval_ns, alias_map), is_method=True
                )


def _verify_dag_guard_rejects_violations(
    forbidden_by_prefix: Sequence[tuple[str, tuple[str, ...]]],
) -> None:
    cases = (
        ("core.execution.runtime.dispatcher", "from core.execution import daemon"),
        ("core.execution.runtime.dispatcher", "from .. import daemon"),
        ("core.execution.event.engine", "from core.filesystem.fs import FileLock"),
        ("core.execution.rpc.channel", "from core.foundation.codec import DataclassCodec"),
        ("core.execution.rpc.channel", "from core.filesystem.fs import FileLock"),
        ("core.execution.rpc.channel", "import core.filesystem.fs as fs"),
        ("core.execution.runtime.dispatcher", "import core.execution as ex"),
        ("core.execution.event.engine", "from core import execution"),
        ("core.execution.event.engine", "from core.foundation import CancellationToken"),
        ("core.execution.rpc.channel", "from core.foundation import DataclassCodec"),
    )
    for mod_name, bad_stmt in cases:
        stmt_node = ast.parse(bad_stmt).body[0]
        caught = False
        try:
            _check_dag_imports(stmt_node, mod_name, forbidden_by_prefix)
        except AssertionError:
            caught = True
        if not caught:
            raise AssertionError(f"DAG guard failed to catch '{bad_stmt}' in {mod_name}")


def verify_gate0_ast_architecture() -> None:
    core_pkg = CORE_SRC_ROOT / "core"
    forbidden_by_prefix: tuple[tuple[str, tuple[str, ...]], ...] = (
        ("core.foundation", ("core.filesystem", "core.metadata", "core.packaging", "core.execution", "core.surface")),
        ("core.filesystem", ("core.metadata", "core.packaging", "core.execution", "core.surface")),
        ("core.execution.event", ("core.filesystem", "core.foundation.observability", "core.foundation.proc", "core.execution.lifecycle", "core.execution.rpc", "core.execution.runtime", "core.execution.daemon", "core.surface")),
        ("core.execution.rpc", ("core.foundation.codec", "core.execution.event", "core.execution.lifecycle", "core.execution.runtime", "core.execution.daemon", "core.surface")),
        ("core.execution.lifecycle", ("core.execution.rpc", "core.execution.runtime", "core.execution.daemon", "core.surface")),
        ("core.execution.runtime", ("core.execution.daemon", "core.surface")),
        ("core.execution.daemon", ("core.metadata", "core.packaging", "core.execution.event", "core.surface", "core.execution.runtime.contracts", "core.execution.runtime.coordinator", "core.execution.runtime.dispatcher", "core.execution.runtime.gates", "core.execution.runtime.lineage_join", "core.execution.runtime.module_slot", "core.execution.runtime.route_index", "core.execution.runtime.step_host", "core.execution.runtime.turn_session", "core.execution.runtime.wire", "core.execution.runtime.worker_entry", "core.execution.runtime.worker_pool")),
    )
    py_files = sorted(core_pkg.rglob("*.py"))
    _check(len(py_files) >= 27)
    for py_f in py_files:
        rel_posix = py_f.relative_to(CORE_SRC_ROOT).as_posix()
        rel_mod = "core." + ".".join(py_f.relative_to(core_pkg).with_suffix("").parts)
        _audit_single_kernel_ast(py_f, rel_posix, rel_mod, forbidden_by_prefix)

    _check(worker_entry_pkg.__name__.endswith("worker_entry"))
    for _, mod_name, _ in pkgutil.walk_packages(core.__path__, core.__name__ + "."):
        _verify_module_runtime_type_hints(mod_name)
    _verify_dag_guard_rejects_violations(forbidden_by_prefix)
    _verify_execution_living_specs_parity()
    _audit_self_test_ast()


def wait_for_daemon_online(ws: HostPath, timeout_sec: float = 6.0) -> JsonObject:
    deadline = time.monotonic() + timeout_sec
    while time.monotonic() < deadline:
        res = query_daemon_control(ws.join(".cache"), ws, FrameKind.CONTROL_STATUS)
        if res and res.get("ok") and isinstance(res.get("status"), Mapping) and res["status"].get("state") == "ready":
            return res["status"]
        time.sleep(0.04)
    raise AssertionError(f"Daemon did not come online within {timeout_sec}s at {ws}")


def _recorded_daemon_pids(cache_dir: HostPath) -> tuple[int, ...]:
    pids: list[int] = []
    for fname in ("daemon.json", "spawn_lease.json"):
        doc = read_json_dict(cache_dir.join("daemon", fname))
        if doc is not None:
            pv = _jint(doc, "pid", 0)
            if pv > 0 and pv not in pids:
                pids.append(pv)
    cnt_doc = read_json_dict(cache_dir.join("daemon_spawn_count.json"))
    raw_list = cnt_doc.get("pids") if isinstance(cnt_doc, Mapping) else None
    if isinstance(raw_list, list):
        for item in raw_list:
            if isinstance(item, int) and not isinstance(item, bool) and item > 0 and item not in pids:
                pids.append(item)
    return tuple(pids)


def _has_pending_daemon_lease(cache_dir: HostPath) -> bool:
    if read_json_dict(cache_dir.join("daemon", "handoff_lease.json")) is not None:
        return True
    return any(is_process_alive(p) for p in _recorded_daemon_pids(cache_dir))


def _codec_has_form_plan(tp: object) -> bool:
    cache = DataclassCodec._CACHE
    with cache.lock:
        return _dehydrate_type(tp) in cache.form_plans


def _codec_live_form_plan_types() -> tuple[object, ...]:
    cache = DataclassCodec._CACHE
    with cache.lock:
        pairs = [_rehydrate_type(k) for k in cache.form_plans.keys()]
    return tuple(v for ok, v in pairs if ok)


def _wait_until(pred: Callable[[], bool], timeout_sec: float = 4.0, step_sec: float = 0.015) -> None:
    deadline = time.monotonic() + timeout_sec
    while time.monotonic() < deadline:
        if pred():
            return
        time.sleep(step_sec)
    _check(pred(), "Timed out waiting for asynchronous condition to converge.")


def _drain_teardown_until(
    disp: RuntimeDispatcher,
    pred: Callable[[ErrorDetail], bool],
    timeout_sec: float = 3.5,
) -> tuple[ErrorDetail, ...]:
    collected: list[ErrorDetail] = []
    deadline = time.monotonic() + timeout_sec
    while time.monotonic() < deadline:
        collected.extend(disp.drain_teardown_diagnostics())
        if any(pred(d) for d in collected):
            return tuple(collected)
        time.sleep(0.015)
    collected.extend(disp.drain_teardown_diagnostics())
    return tuple(collected)


def _wait_daemon_lock_released(cache_dir: HostPath) -> None:
    dlock_p = cache_dir.join("daemon", "daemon.lock")
    if not dlock_p.path.exists():
        return
    lk = FileLock(dlock_p)
    if lk.acquire(shared=False, blocking=True, timeout_sec=4.0):
        lk.release()


def stop_daemon_cleanly(ws: HostPath) -> None:
    cache_dir = ws.join(".cache")
    known_pids: set[int] = set(_recorded_daemon_pids(cache_dir))
    outer_dl = time.monotonic() + 7.0
    while time.monotonic() < outer_dl:
        known_pids.update(_recorded_daemon_pids(cache_dir))
        ep = probe_daemon_endpoint(cache_dir, ws)
        if ep is not None:
            known_pids.add(ep.pid)
            query_daemon_control(cache_dir, ws, FrameKind.CONTROL_STOP)
            inner_dl = time.monotonic() + 4.0
            while time.monotonic() < inner_dl and is_process_alive(ep.pid):
                time.sleep(0.02)
            continue
        if _has_pending_daemon_lease(cache_dir) or any(is_process_alive(p) for p in known_pids):
            time.sleep(0.02)
            continue
        _wait_daemon_lock_released(cache_dir)
        known_pids.update(_recorded_daemon_pids(cache_dir))
        if probe_daemon_endpoint(cache_dir, ws) is None and not _has_pending_daemon_lease(cache_dir) and not any(
            is_process_alive(p) for p in known_pids
        ):
            return
    alive_pids = sorted(p for p in known_pids if is_process_alive(p))
    for pid in alive_pids:
        try:
            os.kill(pid, int(signal.SIGKILL) if os.name != "nt" else int(signal.SIGTERM))
        except OSError:
            pass
    _check(not alive_pids, lambda: f"Daemon failed to stop cleanly within 7.0s at {ws}: {alive_pids}")


def _run_cli_subproc(ws: HostPath, venv_py: Path, cwd: str, task_id: str, payload: JsonObject, policy: ClientRoutingPolicy) -> MutableJsonObject:
    cp = subprocess.run(
        [
            sys.executable, "-B", "-W", "error::ResourceWarning", str(Path(__file__).resolve()),
            "--cli-oneshot", str(ws), str(venv_py), cwd, task_id, json.dumps(dict(payload)), policy.value,
        ],
        capture_output=True, text=True, timeout=45.0, check=False,
    )
    parsed = json.loads(cp.stdout.strip())
    _check(isinstance(parsed, dict))
    return parsed


# Live Execution Verification Scenarios (Decomposed <= 75 LOC Each)


def verify_rc01_cold_storm_and_sandbox(tmp_root: Path, venv_py: Path) -> None:
    _log("[RC-01] Testing static help, AUTO_NO_SPAWN, 10-proc storm (spawn_count==1), stale JSON & sandbox...")
    ws1_path = tmp_root / "ws_rc01"
    provision_live_workspace(ws1_path)
    ws1 = HostPath(ws1_path)
    stale_json = ws1.join(".cache", "daemon", "daemon.json")
    atomic_write_json(stale_json, {"pid": 999999, "host": "127.0.0.1", "port": 65431, "boot_id": "s", "auth_token": "s", "workspace_root": str(ws1)})
    _check(query_daemon_control(ws1.join(".cache"), ws1, FrameKind.CONTROL_STATUS) is None)
    _check(stale_json.path.is_file())

    # Static --help short-circuit: 0 module loads, 0 daemon spawns!
    help_r = _run_cli_subproc(ws1, venv_py, str(ws1), "--help", {}, ClientRoutingPolicy.AUTO_SPAWN)
    _check(help_r["ok"] is True and not ws1.join(".cache", "ast_lazy_inited.json").path.exists())
    _check(_jint(read_json_dict(ws1.join(".cache", "daemon_spawn_count.json")), "spawns", 0) == 0)

    # Normal workspace AUTO_NO_SPAWN while offline runs cold and spawns 0 Daemons!
    sub_cwd = str(ws1_path / "sub_dir")
    nospawn_cold = _run_cli_subproc(ws1, venv_py, sub_cwd, "ast.outline", {"rel_file": "./sample.py"}, ClientRoutingPolicy.AUTO_NO_SPAWN)
    _check(nospawn_cold["ok"] is True and nospawn_cold["executed_hot"] is False)
    _check(_jint(read_json_dict(ws1.join(".cache", "daemon_spawn_count.json")), "spawns", 0) == 0)

    # 10-process concurrent AUTO_SPAWN storm -> exactly 1 Daemon spawned!
    with concurrent.futures.ThreadPoolExecutor(max_workers=10) as pool:
        storm_results = list(
            pool.map(lambda _i: _run_cli_subproc(ws1, venv_py, sub_cwd, "ast.outline", {"rel_file": "./sample.py"}, ClientRoutingPolicy.AUTO_SPAWN), range(10))
        )
    for r in storm_results:
        val = r["value"]
        _check(r["ok"] is True and isinstance(val, dict) and val["exists"] is True and val["lazy_ready"] is True)
        _check(Path(str(val["resolved_path"])) == (ws1_path / "sub_dir" / "sample.py").resolve())

    st1 = wait_for_daemon_online(ws1)
    _check(st1["state"] == "ready")
    _check(_jint(read_json_dict(ws1.join(".cache", "daemon_spawn_count.json")), "spawns", 0) == 1)
    # Verify --help while online does NOT reset Daemon idle_ttl_remaining_sec + typo suggestions work!
    time.sleep(0.15)
    ttl_before = _jfloat(wait_for_daemon_online(ws1), "idle_ttl_remaining_sec", 99.0)
    _check(_run_cli_subproc(ws1, venv_py, str(ws1), "--help", {}, ClientRoutingPolicy.AUTO_SPAWN)["ok"] is True)
    ttl_after = _jfloat(wait_for_daemon_online(ws1), "idle_ttl_remaining_sec", 99.0)
    _check(ttl_after <= ttl_before + 0.02)
    typo_r = _run_cli_subproc(ws1, venv_py, str(ws1), "unknown.outline", {}, ClientRoutingPolicy.AUTO_SPAWN)
    _check(typo_r["ok"] is False and isinstance(typo_r.get("suggestions"), list) and len(typo_r["suggestions"]) >= 1)
    nospawn_hot = _run_cli_subproc(ws1, venv_py, sub_cwd, "ast.outline", {"rel_file": "./sample.py"}, ClientRoutingPolicy.AUTO_NO_SPAWN)
    _check(nospawn_hot["ok"] is True and nospawn_hot["executed_hot"] is True)
    stop_daemon_cleanly(ws1)
    _verify_rc01_booting_warming_queue(tmp_root, venv_py)
    _verify_rc01_restricted_sandbox(tmp_root, venv_py)
    _log("  -> PASS: RC-01 verified.")


def _poll_warming_state(ws_w: HostPath, warming_ev: threading.Event, stop_ev: threading.Event) -> None:
    deadline = time.monotonic() + 8.0
    while time.monotonic() < deadline and not stop_ev.is_set():
        st_raw = query_daemon_control(ws_w.join(".cache"), ws_w, FrameKind.CONTROL_STATUS)
        if st_raw and isinstance(st_raw.get("status"), Mapping) and st_raw["status"].get("state") == "warming":
            warming_ev.set()
            return
        time.sleep(0.015)


def _verify_rc01_booting_warming_queue(tmp_root: Path, venv_py: Path) -> None:
    ws_w_path = tmp_root / "ws_rc01_warming"
    provision_live_workspace(ws_w_path)
    ws_w = HostPath(ws_w_path)
    atomic_write_json(ws_w.join("config", "kdb.json"), {"warmup_delay_ms": 650})
    disp_w = build_dispatcher_for_workspace(ws_w, HostPath(venv_py), ttl_sec=8.0).dispatcher
    warming_ev = threading.Event()
    stop_poll = threading.Event()
    poller = threading.Thread(target=_poll_warming_state, args=(ws_w, warming_ev, stop_poll), daemon=True)
    poller.start()
    try:
        disp_w.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="trigger_spawn"))
        _check(warming_ev.wait(timeout=5.0), "Expected observable DaemonRunState.WARMING window!")
        queued_hot = disp_w.invoke_typed(
            AST_OUTLINE_META,
            OutlineInDto(rel_file="./sample.py"),
            caller_cwd=HostPath(ws_w_path / "sub_dir"),
            routing_policy=ClientRoutingPolicy.STRICT_HOT,
        )
        _check(queued_hot.ok and queued_hot.executed_hot is True)
    finally:
        stop_poll.set()
        poller.join(timeout=1.0)
        stop_daemon_cleanly(ws_w)
        disp_w.shutdown()


def _verify_rc01_restricted_sandbox(tmp_root: Path, venv_py: Path) -> None:
    ws_sb_path = tmp_root / "ws_rc01_sb"
    provision_live_workspace(ws_sb_path)
    disp_sb = build_dispatcher_for_workspace(HostPath(ws_sb_path), HostPath(venv_py), sandbox_restricted=True).dispatcher
    try:
        # DAEMON_ONLY in OS_SANDBOX_RESTRICTED rejected deterministically at Stage 1!
        d_only = disp_sb.invoke(InvokeRequest(task_id=TaskId("space.daemon_metrics"), raw_input={}, workspace_root=HostPath(ws_sb_path), caller_cwd=HostPath(ws_sb_path)))
        _check(not d_only.ok and d_only.error is not None and d_only.error.code == ErrorCode.DAEMON_UNAVAILABLE)

        sb_out = disp_sb.invoke_typed(
            AST_OUTLINE_META,
            OutlineInDto(rel_file="./sample.py", call_tier0=True),
            caller_cwd=HostPath(ws_sb_path / "sub_dir"),
            routing_policy=ClientRoutingPolicy.AUTO_NO_SPAWN,
        )
        _check(sb_out.ok and sb_out.value is not None and sb_out.value.lazy_ready is True)
        _check(sb_out.value.tier0_echo == "tier0:v1:SPACE_H:from_oneshot_tier1")
        _check((ws_sb_path / ".cache" / "tier1_imm_seen.json").is_file())
        sb_strict_fail = disp_sb.invoke_typed(
            AST_OUTLINE_META,
            OutlineInDto(rel_file="./sample.py", call_tier0=True, fail_imm_strict=True),
            caller_cwd=HostPath(ws_sb_path / "sub_dir"),
            routing_policy=ClientRoutingPolicy.AUTO_NO_SPAWN,
        )
        _check(not sb_strict_fail.ok and sb_strict_fail.error is not None)
        _check(not (ws_sb_path / ".cache" / "daemon" / "daemon.json").exists())
    finally:
        disp_sb.shutdown()


@dataclass(frozen=True, slots=True)
class _Rc02StageRig:
    ws: HostPath
    ws_path: Path
    dispatcher: RuntimeDispatcher


def verify_rc02_warmup_events_and_preempt(tmp_root: Path, venv_py: Path) -> _Rc02StageRig:
    _log("[RC-02] Testing co-located Tier 1 warmup fault isolation, lazy/stateless zero-boot, Tier 0 filter & PREEMPT proof...")
    ws2_path = tmp_root / "ws_rc02"
    provision_live_workspace(ws2_path)
    ws2 = HostPath(ws2_path)
    disp2 = build_dispatcher_for_workspace(ws2, HostPath(venv_py), ttl_sec=20.0).dispatcher
    _check(disp2.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot")).ok)
    st2 = wait_for_daemon_online(ws2)

    # Only idx_group (containing eager_warmup kdb + broken_opt) spawned; gdrive ('mod_gdrive') has 0 workers & ast not inited yet!
    _check("broken_opt" in _jlist(st2, "degraded_modules"))
    workers_boot = _jlist(st2, "active_tier1_workers")
    _check(len(workers_boot) == 1 and isinstance(workers_boot[0], dict) and workers_boot[0].get("group") == "idx_group")

    # Wait for startup_catchup scan on empty source/docs (count=0): DYNAMIC_WORKER_MAPPER_DROP returns None WITHOUT calling ast.on_init!
    time.sleep(0.22)
    _check(not ws2.join(".cache", "ast_state.json").path.exists())
    _check(not ws2.join(".cache", "ast_lazy_inited.json").path.exists())

    deg_out = disp2.invoke(InvokeRequest(task_id=TaskId("broken_opt.ping"), raw_input={}, workspace_root=ws2, caller_cwd=ws2))
    _check(not deg_out.ok and deg_out.error is not None and deg_out.error.code == ErrorCode.MODULE_DEGRADED)
    exp_denied = disp2.invoke(InvokeRequest(task_id=TaskId("space.scan"), raw_input={}, workspace_root=ws2, caller_cwd=ws2))
    _check(not exp_denied.ok and exp_denied.error is not None and exp_denied.error.code == ErrorCode.EXPOSURE_DENIED)

    _verify_rc02_preempt_and_static_filter(ws2, ws2_path, disp2)
    _log("  -> PASS: RC-02 verified.")
    return _Rc02StageRig(ws2, ws2_path, disp2)


def _verify_rc02_preempt_and_static_filter(ws2: HostPath, ws2_path: Path, disp2: RuntimeDispatcher) -> None:
    # Isolated static filter check FIRST: write ONLY to 'ignored_logs', wait past debounce, verify 0 ast.sync & 0 ast.on_init!
    (ws2_path / "spaces" / "ignored_logs" / "noise.log").write_text("isolated_noise\n", encoding="utf-8")
    time.sleep(0.24)
    _check(not ws2.join(".cache", "ast_state.json").path.exists())
    _check(not ws2.join(".cache", "ast_lazy_inited.json").path.exists())

    atomic_write_json(ws2.join("config", "kdb.json"), {"bg_wave1_ms": 1800})
    # Wave 1: write to BOTH 'source' and 'docs' -> folded into 1 ast.sync run -> starts slow 450ms kdb.bg_preempt_index(gen=1)
    (ws2_path / "spaces" / "source" / "a.py").write_text("x = 1\n", encoding="utf-8")
    (ws2_path / "spaces" / "docs" / "b.md").write_text("# doc\n", encoding="utf-8")
    deadline_in = time.monotonic() + 4.0
    while time.monotonic() < deadline_in:
        if _jint(read_json_dict(ws2.join(".cache", "kdb_bg_inflight.json")), "in_flight_gen", 0) >= 1:
            break
        time.sleep(0.02)
    _check(_jint(read_json_dict(ws2.join(".cache", "kdb_bg_inflight.json")), "in_flight_gen", 0) == 1)
    # Write to 'ignored_logs' WHILE gen=1 is actively running -> must NOT preempt gen=1!
    (ws2_path / "spaces" / "ignored_logs" / "inflight_noise.log").write_text("no_preempt\n", encoding="utf-8")
    time.sleep(0.14)
    _check(_jint(read_json_dict(ws2.join(".cache", "kdb_preempt_stats.json")), "preempted_count", 0) == 0)

    # Wave 2: write to 'source' while gen=1 is STILL mid-flight -> deterministically triggers PREEMPT!
    (ws2_path / "spaces" / "source" / "a.py").write_text("x = 2\n", encoding="utf-8")

    deadline = time.monotonic() + 5.0
    while time.monotonic() < deadline:
        bg_st = read_json_dict(ws2.join(".cache", "kdb_bg_state.json"))
        ast_st = read_json_dict(ws2.join(".cache", "ast_state.json"))
        if bg_st and ast_st and _jint(ast_st, "ast_gen") >= 2 and _jint(bg_st, "acked_ast_gen") == _jint(ast_st, "ast_gen"):
            break
        time.sleep(0.04)
    bg_st = read_json_dict(ws2.join(".cache", "kdb_bg_state.json"))
    ast_st = read_json_dict(ws2.join(".cache", "ast_state.json"))
    p_stats = read_json_dict(ws2.join(".cache", "kdb_preempt_stats.json"))
    _check(_jint(ast_st, "ast_gen") >= 2 and _jint(bg_st, "acked_ast_gen") == _jint(ast_st, "ast_gen"))
    _check(_jint(p_stats, "preempted_count") >= 1, lambda: f"Expected real PREEMPT abort proof, got {p_stats}")

    # Verify VSC echo-suppressed write into spaces/docs/_auto_schema.json does NOT loop!
    _check(disp2.invoke(InvokeRequest(task_id=TaskId("vsc.sync"), raw_input={}, workspace_root=ws2, caller_cwd=ws2)).ok)
    runs_after_vsc = _jint(read_json_dict(ws2.join(".cache", "ast_state.json")), "runs")
    time.sleep(0.25)
    _check(_jint(read_json_dict(ws2.join(".cache", "ast_state.json")), "runs") == runs_after_vsc)


def verify_rc03_coalesce_priority_and_nested_group(ws2: HostPath, ws2_path: Path, disp2: RuntimeDispatcher) -> None:
    _log("[RC-03] Testing snapshot read, priority inheritance, normalized/custom COALESCE, leader-cancel & subscriber fault isolation...")
    progress_seen: list[JsonObject] = []
    follower_progress: list[JsonObject] = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
        f_bg = pool.submit(
            disp2.invoke,
            InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"sleep_ms": 240}, workspace_root=ws2, caller_cwd=ws2, priority=ExecutionPriority.BACKGROUND),
            output_type=IndexOutDto,
        )
        time.sleep(0.04)
        f_fg_eq = pool.submit(
            disp2.invoke,
            InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"force": False, "export_path": "", "sleep_ms": 240}, workspace_root=ws2, caller_cwd=ws2),
            output_type=IndexOutDto,
            on_progress=follower_progress.append,
        )
        f_fg_diff = pool.submit(
            disp2.invoke,
            InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"force": True, "export_path": "./exported_bundle.json", "sleep_ms": 60}, workspace_root=ws2, caller_cwd=HostPath(ws2_path / "sub_dir")),
            output_type=IndexOutDto,
            on_progress=progress_seen.append,
        )
        time.sleep(0.03)
        read_out = disp2.invoke_typed(KDB_SEARCH_META, SearchInDto(query="fast", sync=False))
        _check(not f_bg.done(), "Lock-free read should finish while slow kdb.index still holds kdb lock!")
        r_bg, r_fg_eq, r_fg_diff = f_bg.result(timeout=10), f_fg_eq.result(timeout=10), f_fg_diff.result(timeout=10)

    _check(read_out.ok and read_out.value is not None and read_out.value.warm_model_ready is True)
    _check(r_bg.ok and r_bg.value is not None and r_bg.value.observed_priority == "foreground")
    _check(r_fg_eq.ok and r_fg_eq.coalesced is True and len(follower_progress) >= 1)
    _check(r_fg_diff.ok and r_fg_diff.coalesced is False and (ws2_path / "sub_dir" / "exported_bundle.json").is_file())
    _check(len(progress_seen) >= 2 and progress_seen[0].get("phase") == "indexing")

    _verify_rc03_custom_equiv_cancel_and_step5(ws2, ws2_path, disp2)
    _verify_rc03_cross_layer_and_step5_fatal_coalesce(ws2, disp2)
    _log("  -> PASS: RC-03 verified.")


def _verify_rc03_custom_equiv_cancel_and_step5(ws2: HostPath, ws2_path: Path, disp2: RuntimeDispatcher) -> None:
    # Custom equivalence_fn + Leader-cancel isolation synchronized on Follower live flight progress!
    leader_tok = CancellationToken()
    fl_in = threading.Event()
    ff_joined = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fl = pool.submit(
            disp2.invoke,
            InvokeRequest(task_id=TaskId("vsc.sync"), raw_input={"trace_note": "alpha", "sleep_ms": 360}, workspace_root=ws2, caller_cwd=ws2),
            cancel_token=leader_tok,
            on_progress=lambda _p: fl_in.set(),
        )
        _check(fl_in.wait(timeout=5.0))
        ff = pool.submit(
            disp2.invoke,
            InvokeRequest(task_id=TaskId("vsc.sync"), raw_input={"trace_note": "beta", "sleep_ms": 360}, workspace_root=ws2, caller_cwd=ws2),
            on_progress=lambda _p: ff_joined.set(),
        )
        _check(ff_joined.wait(timeout=5.0))
        leader_tok.cancel()
        out_l, out_f = fl.result(timeout=10), ff.result(timeout=10)
    _check(not out_l.ok and out_l.error is not None and out_l.error.code == ErrorCode.TASK_CANCELLED)
    _check(out_f.ok and out_f.coalesced is True)

    # Shared venv_group nested chain + nested progress streaming!
    nested_prog: list[JsonObject] = []
    ast_probe = disp2.invoke_typed(AST_OUTLINE_META, OutlineInDto(rel_file="./sample.py"), caller_cwd=HostPath(ws2_path / "sub_dir"))
    synced = disp2.invoke(
        InvokeRequest(task_id=TaskId("kdb.search"), raw_input={"query": "aligned", "sync": True}, workspace_root=ws2, caller_cwd=ws2),
        output_type=SearchOutDto,
        on_progress=nested_prog.append,
    )
    _check(ast_probe.ok and ast_probe.value is not None and synced.ok and synced.value is not None)
    _check(ast_probe.value.worker_pid == synced.value.worker_pid and len(nested_prog) >= 1)

    # Deferred event partial subscriber failure isolation synchronized on progress!
    sub_fault_in = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        f1 = pool.submit(disp2.invoke, InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"sleep_ms": 260, "trigger_step5_error": True}, workspace_root=ws2, caller_cwd=ws2), on_progress=lambda _p: sub_fault_in.set())
        _check(sub_fault_in.wait(timeout=5.0))
        f2 = pool.submit(disp2.invoke, InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"sleep_ms": 260, "trigger_step5_error": True}, workspace_root=ws2, caller_cwd=ws2))
        o1, o2 = f1.result(timeout=10), f2.result(timeout=10)
    _check(o1.ok and o2.ok and o2.coalesced is True)
    _check(len(o1.event_diagnostics) == 1 and len(o2.event_diagnostics) == 1)
    _check(ws2.join(".cache", "sibling_sub_ok.json").path.is_file())
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fb1 = pool.submit(disp2.emit_background_event, EventId("kdb.trigger_step5_fail"), {"query": "x"})
        fb2 = pool.submit(disp2.emit_background_event, EventId("kdb.trigger_step5_fail"), {"query": "x"})
        rb1, rb2 = fb1.result(timeout=10), fb2.result(timeout=10)
    _check(len(rb1.event_diagnostics) == 1 and len(rb2.event_diagnostics) == 1)

    # COALESCE primary crash propagation synchronized on progress!
    fc1_in = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fc1 = pool.submit(disp2.invoke, InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"sleep_ms": 260, "fail_primary": True}, workspace_root=ws2, caller_cwd=ws2), on_progress=lambda _p: fc1_in.set())
        _check(fc1_in.wait(timeout=5.0))
        fc2 = pool.submit(disp2.invoke, InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"sleep_ms": 260, "fail_primary": True}, workspace_root=ws2, caller_cwd=ws2))
        oc1, oc2 = fc1.result(timeout=10), fc2.result(timeout=10)
    _check(not oc1.ok and oc1.error is not None and oc1.error.code == ErrorCode.BUSINESS_FAILURE)
    _check(not oc2.ok and oc2.coalesced is True and oc2.error is not None and oc2.error.code == ErrorCode.BUSINESS_FAILURE)


def _verify_rc03_cross_layer_and_step5_fatal_coalesce(ws2: HostPath, disp2: RuntimeDispatcher) -> None:
    # 1) Forward cross-layer COALESCE (Top-first, Nested-second) synchronized on leader progress!
    gen_before = _jint(read_json_dict(ws2.join(".cache", "kdb_state.json")), "kdb_gen", 0)
    entered_1 = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        ft = pool.submit(
            disp2.invoke,
            InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"force": False, "sleep_ms": 260}, workspace_root=ws2, caller_cwd=ws2),
            on_progress=lambda _p: entered_1.set(),
        )
        _check(entered_1.wait(timeout=5.0))
        fn = pool.submit(disp2.invoke_typed, KDB_SEARCH_META, SearchInDto(query="cross_layer_must_coalesce", sync=True))
        _check(ft.result(timeout=10).ok and fn.result(timeout=10).ok)
    _check(_jint(read_json_dict(ws2.join(".cache", "kdb_state.json")), "kdb_gen", 0) == gen_before + 1)

    # 2) Forward cross-layer COALESCE where Top-level cancels mid-flight synchronized on search_sync_entered!
    ws2.join(".cache", "sibling_sub_ok.json").path.unlink(missing_ok=True)
    sync_m = ws2.path / ".cache" / "search_sync_entered.json"
    sync_m.unlink(missing_ok=True)
    tok_top_c = CancellationToken()
    entered_2 = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        ftc = pool.submit(
            disp2.invoke,
            InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"force": False, "sleep_ms": 260, "trigger_step5_error": True}, workspace_root=ws2, caller_cwd=ws2),
            cancel_token=tok_top_c,
            on_progress=lambda _p: entered_2.set(),
        )
        _check(entered_2.wait(timeout=5.0))
        fnc = pool.submit(disp2.invoke_typed, KDB_SEARCH_META, SearchInDto(query="ev_err", sync=True))
        _wait_file_marker(sync_m, timeout_sec=5.0)
        time.sleep(0.04)
        tok_top_c.cancel()
        rtc, rnc = ftc.result(timeout=10), fnc.result(timeout=10)
    _check(not rtc.ok and rtc.error is not None and rtc.error.code == ErrorCode.TASK_CANCELLED)
    _check(rnc.ok and ws2.join(".cache", "sibling_sub_ok.json").path.is_file())

    # 3) Same-layer & Reverse cross-layer Step 5 EVENT_CYCLE_DETECTED synchronized on progress!
    fe1_in = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fe1 = pool.submit(disp2.invoke, InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"sleep_ms": 260, "trigger_ev_cycle": True}, workspace_root=ws2, caller_cwd=ws2), on_progress=lambda _p: fe1_in.set())
        _check(fe1_in.wait(timeout=5.0))
        fe2 = pool.submit(disp2.invoke, InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"sleep_ms": 260, "trigger_ev_cycle": True}, workspace_root=ws2, caller_cwd=ws2))
        oe1, oe2 = fe1.result(timeout=10), fe2.result(timeout=10)
    _check(not oe1.ok and oe1.error is not None and oe1.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
    _check(not oe2.ok and oe2.coalesced is True and oe2.error is not None and oe2.error.code == ErrorCode.EVENT_CYCLE_DETECTED)

    sync_m.unlink(missing_ok=True)
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fn_first = pool.submit(disp2.invoke_typed, KDB_SEARCH_META, SearchInDto(query="ev_cyc", sync=True))
        _wait_file_marker(sync_m, timeout_sec=5.0)
        time.sleep(0.04)
        ft_second = pool.submit(disp2.invoke, InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"force": False, "sleep_ms": 260, "trigger_ev_cycle": True}, workspace_root=ws2, caller_cwd=ws2))
        r_nf, r_ts = fn_first.result(timeout=10), ft_second.result(timeout=10)
    _check(not r_nf.ok and r_nf.error is not None and r_nf.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
    _check(not r_ts.ok and r_ts.coalesced is True and r_ts.error is not None and r_ts.error.code == ErrorCode.EVENT_CYCLE_DETECTED)


def verify_rc04_multiplex_cancel_and_ttl(tmp_root: Path, venv_py: Path) -> None:
    _log("[RC-04] Testing multiplexed streams, P2/P3 CANCEL, Idle TTL, hot session reconnect & graceful DRAINING...")
    ws4_path = tmp_root / "ws_rc04"
    provision_live_workspace(ws4_path)
    ws4 = HostPath(ws4_path)
    sess4 = PersistentRpcSession(ws4.join(".cache"), ws4)
    disp4 = build_dispatcher_for_workspace(ws4, HostPath(venv_py), ttl_sec=1.10, persistent_session=sess4).dispatcher
    try:
        disp4.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="init"))
        old_boot_id = wait_for_daemon_online(ws4)["boot_id"]
        _check(disp4.invoke(InvokeRequest(task_id=TaskId("space.daemon_metrics"), raw_input={}, workspace_root=ws4, caller_cwd=ws4, routing_policy=ClientRoutingPolicy.STRICT_HOT)).ok)
        _verify_rc04_streams_and_cancels(ws4, disp4)

        # Idle socket does NOT block Idle TTL; external BACKGROUND RPC also does NOT extend Idle TTL!
        time.sleep(0.32)
        bg_ext = disp4.invoke(InvokeRequest(task_id=TaskId("space.echo_tier0"), raw_input={"tag": "bg"}, workspace_root=ws4, caller_cwd=ws4, priority=ExecutionPriority.BACKGROUND))
        _check(bg_ext.ok)
        _ = query_daemon_control(ws4.join(".cache"), ws4, FrameKind.CONTROL_STATUS)
        _wait_until(lambda: probe_daemon_endpoint(ws4.join(".cache"), ws4) is None, timeout_sec=4.0)

        strict_fail = disp4.invoke(InvokeRequest(task_id=TaskId("space.daemon_metrics"), raw_input={}, workspace_root=ws4, caller_cwd=ws4, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        _check(not strict_fail.ok and strict_fail.error is not None and strict_fail.error.code == ErrorCode.DAEMON_UNAVAILABLE)
        daemon_cold = disp4.invoke(InvokeRequest(task_id=TaskId("space.daemon_metrics"), raw_input={}, workspace_root=ws4, caller_cwd=ws4, routing_policy=ClientRoutingPolicy.FORCE_COLD))
        _check(not daemon_cold.ok and daemon_cold.error is not None and daemon_cold.error.code == ErrorCode.COLD_DISPATCH_FORBIDDEN)

        _verify_rc04_hot_reconnect_and_draining(ws4, venv_py, disp4, str(old_boot_id))
    finally:
        sess4.close()
        stop_daemon_cleanly(ws4)
        disp4.shutdown()
    _log("  -> PASS: RC-04 verified.")


def _verify_rc04_streams_and_cancels(ws4: HostPath, disp4: RuntimeDispatcher) -> None:
    finish_order: list[str] = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fs = pool.submit(lambda: (disp4.invoke_typed(KDB_SEARCH_META, SearchInDto(query="slow", sleep_ms=220)), finish_order.append("slow"))[0])
        time.sleep(0.03)
        ff = pool.submit(
            lambda: (
                disp4.invoke(InvokeRequest(task_id=TaskId("space.daemon_metrics"), raw_input={}, workspace_root=ws4, caller_cwd=ws4, routing_policy=ClientRoutingPolicy.STRICT_HOT)),
                finish_order.append("fast"),
            )[0]
        )
        _check(ff.result(timeout=5).ok and fs.result(timeout=5).ok)
    _check(finish_order == ["fast", "slow"])

    p2_cancel = CancellationToken()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fh = pool.submit(disp4.invoke, InvokeRequest(task_id=TaskId("space.hold_lock_ms"), raw_input={"hold_ms": 260}, workspace_root=ws4, caller_cwd=ws4))
        time.sleep(0.04)
        with _scoped_timer(0.04, p2_cancel.cancel):
            p2_out = disp4.invoke(InvokeRequest(task_id=TaskId("space.hold_lock_ms"), raw_input={"hold_ms": 80}, workspace_root=ws4, caller_cwd=ws4), cancel_token=p2_cancel)
        _check(fh.result(timeout=5).ok)
    _check(not p2_out.ok and p2_out.error is not None and p2_out.error.code == ErrorCode.TASK_CANCELLED)

    p3_cancel = CancellationToken()
    with _scoped_timer(0.05, p3_cancel.cancel):
        p3_out = disp4.invoke_typed(KDB_SEARCH_META, SearchInDto(query="cancel_me", sleep_ms=600), cancel_token=p3_cancel)
    _check(not p3_out.ok and p3_out.error is not None and p3_out.error.code == ErrorCode.TASK_CANCELLED)


def _verify_rc04_hot_reconnect_and_draining(
    ws4: HostPath,
    venv_py: Path,
    disp4: RuntimeDispatcher,
    old_boot_id: str,
) -> None:
    # Boot replacement Daemon via separate CLI client while sess4 still holds stale closed state,
    # then verify a SINGLE STRICT_HOT call on disp4/sess4 transparently reconnects on attempt 1!
    _run_cli_subproc(ws4, venv_py, str(ws4), "space.echo_tier0", {"tag": "boot2"}, ClientRoutingPolicy.AUTO_SPAWN)
    st_b2 = wait_for_daemon_online(ws4)
    _check(st_b2["boot_id"] != old_boot_id)
    # Now trigger core handoff while sess4 has an active open socket to boot_id #2, wait for boot_id #3, and call STRICT_HOT!
    hot_b2 = disp4.invoke(InvokeRequest(task_id=TaskId("space.daemon_metrics"), raw_input={}, workspace_root=ws4, caller_cwd=ws4, routing_policy=ClientRoutingPolicy.STRICT_HOT))
    _check(hot_b2.ok and hot_b2.executed_hot)
    query_daemon_control(ws4.join(".cache"), ws4, FrameKind.CONTROL_RELOAD, {"modules": ["core"]})
    deadline = time.monotonic() + 6.0
    while time.monotonic() < deadline:
        st_cand = query_daemon_control(ws4.join(".cache"), ws4, FrameKind.CONTROL_STATUS)
        if st_cand and st_cand.get("ok") and isinstance(st_cand.get("status"), Mapping) and st_cand["status"].get("boot_id") != st_b2["boot_id"]:
            break
        time.sleep(0.05)
    hot_b3 = disp4.invoke(InvokeRequest(task_id=TaskId("space.daemon_metrics"), raw_input={}, workspace_root=ws4, caller_cwd=ws4, routing_policy=ClientRoutingPolicy.STRICT_HOT))
    _check(hot_b3.ok and hot_b3.executed_hot)

    # Graceful DRAINING: in-flight succeeds, STRICT_HOT returns DAEMON_UNAVAILABLE, HYBRID falls back cold seamlessly!
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        inflight_f = pool.submit(disp4.invoke, InvokeRequest(task_id=TaskId("space.hold_lock_ms"), raw_input={"hold_ms": 260}, workspace_root=ws4, caller_cwd=ws4))
        time.sleep(0.05)
        stop_f = pool.submit(query_daemon_control, ws4.join(".cache"), ws4, FrameKind.CONTROL_STOP, {"force": False})
        time.sleep(0.03)
        drain_strict = disp4.invoke(InvokeRequest(task_id=TaskId("space.daemon_metrics"), raw_input={}, workspace_root=ws4, caller_cwd=ws4, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        drain_hybrid = disp4.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="during_drain"), routing_policy=ClientRoutingPolicy.AUTO_NO_SPAWN)
        _check(not drain_strict.ok and drain_strict.error is not None and drain_strict.error.code == ErrorCode.DAEMON_UNAVAILABLE)
        _check(drain_hybrid.ok and drain_hybrid.executed_hot is False)
        _check(inflight_f.result(timeout=5).ok)
        stop_rep = stop_f.result(timeout=5)
        _check(isinstance(stop_rep, Mapping) and stop_rep.get("ok") is True)


def _reap_popen_quietly(proc: subprocess.Popen[str] | subprocess.Popen[bytes]) -> None:
    if proc.poll() is None:
        try:
            proc.kill()
        except OSError:
            pass
    for stream in (proc.stdin, proc.stdout, proc.stderr):
        if stream is not None:
            try:
                stream.close()
            except OSError:
                pass
    try:
        proc.wait(timeout=3.0)
    except subprocess.TimeoutExpired:
        pass


def _verify_real_pty_tty_auth(ws5: HostPath, venv_py: Path) -> None:
    if os.name == "nt":
        return

    master_fd, slave_fd = pty.openpty()
    proc = subprocess.Popen(
        [
            sys.executable, "-W", "error::ResourceWarning", str(Path(__file__).resolve()),
            "--cli-oneshot", str(ws5), str(venv_py), str(ws5),
            "gdrive.auth", json.dumps({"code": ""}), ClientRoutingPolicy.AUTO_SPAWN.value,
        ],
        stdin=slave_fd, stdout=slave_fd, stderr=slave_fd, close_fds=True,
    )
    os.close(slave_fd)
    try:
        buf = b""
        deadline = time.monotonic() + 8.0
        while time.monotonic() < deadline and b"OAUTH_PROMPT>" not in buf:
            chunk = os.read(master_fd, 256)
            if not chunk:
                break
            buf += chunk
        _check(b"OAUTH_PROMPT>" in buf, lambda: f"Tier 1 interactive PTY prompt missing: {buf!r}")
        os.write(master_fd, b"PTY_SECRET_999\n")
        _check(proc.wait(timeout=10.0) == 0)
    finally:
        os.close(master_fd)
        _reap_popen_quietly(proc)
    tok = read_json_dict(ws5.join(".cache", "oauth_token.json"))
    _check(tok is not None and tok.get("token") == "tok_PTY_SECRET_999" and tok.get("tty") is True)


def verify_rc05_tty_periodic_and_worker_crashes(tmp_root: Path, venv_py: Path) -> None:
    _log("[RC-05] Testing real PTY Tier 1 auth, periodic fixed-delay/TTL/drain safety, env allowlist & P0/P3 crashes...")
    ws5_path = tmp_root / "ws_rc05"
    provision_live_workspace(ws5_path)
    ws5 = HostPath(ws5_path)
    _verify_real_pty_tty_auth(ws5, venv_py)
    _check(probe_daemon_endpoint(ws5.join(".cache"), ws5) is None)

    disp5 = build_dispatcher_for_workspace(ws5, HostPath(venv_py), ttl_sec=1.35).dispatcher
    try:
        auth_bad = disp5.invoke(InvokeRequest(task_id=TaskId("gdrive.auth"), raw_input={"code": "x"}, workspace_root=ws5, caller_cwd=ws5, propagation=CallPropagationContext(is_nested_call=True)))
        _check(not auth_bad.ok and auth_bad.error is not None and auth_bad.error.code == ErrorCode.TTY_REQUIRED)

        # Boot daemon with short 0.75s TTL, enable slow fixed-delay periodic (work_ms=160, interval=0.06):
        # Verify: (a) max_conc == 1 (fixed-delay non-overlap), (b) gdrive.put serializes safely alongside periodic,
        # (c) in-flight periodic is NOT mid-flight killed by TTL (phase=='completed'), and (d) periodic doesn't block TTL exit!
        disp5.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot"))
        wait_for_daemon_online(ws5)
        atomic_write_json(ws5.join("config", "gdrive.json"), {"auto_sync": True, "interval_sec": 0.06, "work_ms": 140})
        deadline = time.monotonic() + 4.0
        while time.monotonic() < deadline and _jint(read_json_dict(ws5.join(".cache", "gdrive_periodic.json")), "ticks") < 2:
            time.sleep(0.04)
        _check(_jint(read_json_dict(ws5.join(".cache", "gdrive_periodic.json")), "ticks") >= 2)
        put_co = disp5.invoke(
            InvokeRequest(
                task_id=TaskId("gdrive.put"),
                raw_input={"local_rel": "./sample.py"},
                workspace_root=ws5,
                caller_cwd=HostPath(ws5_path / "sub_dir"),
                caller_env={"HTTPS_PROXY": "http://corp-proxy:3128", "AWS_SECRET_ACCESS_KEY": "TOP_SECRET"},
            ),
            output_type=GdriveOutDto,
        )
        kdb_w = disp5.invoke_typed(KDB_SEARCH_META, SearchInDto(query="pid_check"))
        _check(put_co.ok and put_co.value is not None and kdb_w.ok and kdb_w.value is not None)
        _check(put_co.value.worker_pid != kdb_w.value.worker_pid)
        ded_env_p = os.environ.get("YSCB_TEST_DEDICATED_VENV_PY", "")
        _check(bool(ded_env_p) and Path(put_co.value.venv_prefix).resolve() == Path(ded_env_p).parent.parent.resolve())
        _check(put_co.value.proxy_seen == "http://corp-proxy:3128" and put_co.value.leaked_secret_seen == "")

        # Let foreground stay idle past 0.75s TTL while periodic is enabled -> Daemon drains in-flight tick cleanly & exits!
        deadline_ttl = time.monotonic() + 3.0
        while time.monotonic() < deadline_ttl and (
            probe_daemon_endpoint(ws5.join(".cache"), ws5) is not None
            or read_daemon_endpoint_file(ws5.join(".cache"), ws5) is not None
        ):
            time.sleep(0.05)
        _check(probe_daemon_endpoint(ws5.join(".cache"), ws5) is None)
        per_final = read_json_dict(ws5.join(".cache", "gdrive_periodic.json")) or {}
        _check(per_final.get("max_conc") == 1 and per_final.get("phase") == "completed")

        _verify_rc05_worker_p0_p3_and_timeout(tmp_root, venv_py)
    finally:
        stop_daemon_cleanly(ws5)
        disp5.shutdown()
    _log("  -> PASS: RC-05 verified.")


def _verify_rc05_worker_p0_p3_and_timeout(tmp_root: Path, venv_py: Path) -> None:
    ws5b_path = tmp_root / "ws_rc05_crash"
    provision_live_workspace(ws5b_path)
    ws5b = HostPath(ws5b_path)
    disp5b = build_dispatcher_for_workspace(ws5b, HostPath(venv_py), ttl_sec=15.0).dispatcher
    try:
        disp5b.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot"))
        wait_for_daemon_online(ws5b)
        put_init = disp5b.invoke(
            InvokeRequest(task_id=TaskId("gdrive.put"), raw_input={"local_rel": "./sample.py"}, workspace_root=ws5b, caller_cwd=HostPath(ws5b_path / "sub_dir")),
            output_type=GdriveOutDto,
        )
        _check(put_init.ok and put_init.executed_hot and put_init.value is not None)
        warm_pid = put_init.value.worker_pid

        # P0_PRE_ACCEPT SIGKILL while idle -> transparent respawn, attempts += 1
        att0 = _jint(read_json_dict(ws5b.join(".cache", "gdrive_put_runs.json")), "attempts")
        os.kill(warm_pid, signal.SIGTERM if sys.platform == "win32" else signal.SIGKILL)
        while is_process_alive(warm_pid):
            time.sleep(0.02)
        put_p0 = disp5b.invoke(
            InvokeRequest(task_id=TaskId("gdrive.put"), raw_input={"local_rel": "./sample.py"}, workspace_root=ws5b, caller_cwd=HostPath(ws5b_path / "sub_dir")),
            output_type=GdriveOutDto,
        )
        _check(put_p0.ok and put_p0.value is not None and put_p0.value.worker_pid != warm_pid)
        _check(_jint(read_json_dict(ws5b.join(".cache", "gdrive_put_runs.json")), "attempts") == att0 + 1)

        # P3_PRIMARY_IN_FLIGHT SIGKILL -> TRANSPORT_LOST, attempts += 1 (zero automatic retry!)
        att1 = _jint(read_json_dict(ws5b.join(".cache", "gdrive_put_runs.json")), "attempts")
        put_p3 = disp5b.invoke(InvokeRequest(task_id=TaskId("gdrive.put"), raw_input={"local_rel": "./sample.py", "crash_after_accept": True}, workspace_root=ws5b, caller_cwd=HostPath(ws5b_path / "sub_dir")))
        _check(not put_p3.ok and put_p3.error is not None and put_p3.error.code == ErrorCode.TRANSPORT_LOST)
        _check(_jint(read_json_dict(ws5b.join(".cache", "gdrive_put_runs.json")), "attempts") == att1 + 1)

        # Timeout kills hung worker PID & pool self-heals on next call
        put_pre_to = disp5b.invoke(
            InvokeRequest(task_id=TaskId("gdrive.put"), raw_input={"local_rel": "./sample.py"}, workspace_root=ws5b, caller_cwd=HostPath(ws5b_path / "sub_dir")),
            output_type=GdriveOutDto,
        )
        _check(put_pre_to.ok and put_pre_to.value is not None)
        hung_pid = put_pre_to.value.worker_pid
        put_to = disp5b.invoke(InvokeRequest(task_id=TaskId("gdrive.put"), raw_input={"local_rel": "./sample.py", "hang_ms": 1500}, workspace_root=ws5b, caller_cwd=HostPath(ws5b_path / "sub_dir")))
        _check(not put_to.ok and put_to.error is not None and put_to.error.code == ErrorCode.TASK_TIMEOUT)
        _check(not is_process_alive(hung_pid))
        _check(disp5b.invoke(InvokeRequest(task_id=TaskId("gdrive.put"), raw_input={"local_rel": "./sample.py"}, workspace_root=ws5b, caller_cwd=HostPath(ws5b_path / "sub_dir"))).ok)
    finally:
        stop_daemon_cleanly(ws5b)
        disp5b.shutdown()


def verify_rc06_quiesce_hot_reload_and_core_mutation(tmp_root: Path, venv_py: Path) -> None:
    _log("[RC-06] Testing QUIESCED reload guard, ORDERED_FIFO, emit_imm inline order, .modules reload & MUTATES_CORE...")
    ws6_path = tmp_root / "ws_rc06"
    provision_live_workspace(ws6_path)
    ws6 = HostPath(ws6_path)
    disp6 = build_dispatcher_for_workspace(ws6, HostPath(venv_py), ttl_sec=15.0).dispatcher
    try:
        disp6.invoke_typed(AST_OUTLINE_META, OutlineInDto(rel_file="./sample.py"), caller_cwd=HostPath(ws6_path / "sub_dir"))
        st6_before = wait_for_daemon_online(ws6)
        _verify_rc06_quiesce_and_ordered_events(ws6, ws6_path, venv_py, disp6)
        st6_after = _verify_rc06_live_reload_and_core_handoff(ws6, ws6_path, disp6, st6_before)
        _verify_rc06_empty_quiesce_fast_core_handoff(ws6, ws6_path, disp6, st6_after)
    finally:
        stop_daemon_cleanly(ws6)
        disp6.shutdown()
    _log("  -> PASS: RC-06 verified.")


def _verify_rc06_quiesce_and_ordered_events(
    ws6: HostPath,
    ws6_path: Path,
    venv_py: Path,
    disp6: RuntimeDispatcher,
) -> None:
    q_ack = query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_QUIESCE, {"modules": ["ast", "kdb"], "lease_sec": 5.0})
    _check(q_ack and q_ack.get("state") == "quiesced")

    # Sending CONTROL_RELOAD while QUIESCED must defer and never spawn Tier 1 workers!
    rel_during_q = query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_RELOAD, {"modules": ["kdb"]})
    _check(rel_during_q and rel_during_q.get("deferred") is True)
    st_q = query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_STATUS)
    _check(st_q and isinstance(st_q.get("status"), Mapping) and _jlist(st_q["status"], "active_tier1_workers") == [])

    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        queued_fut = pool.submit(disp6.invoke_typed, AST_OUTLINE_META, OutlineInDto(rel_file="./sample.py"), caller_cwd=HostPath(ws6_path / "sub_dir"))
        time.sleep(0.10)
        _check(not queued_fut.done())
        cold_fut = pool.submit(
            lambda: (time.sleep(0.04), _run_cli_subproc(ws6, venv_py, str(ws6), "space.echo_tier0", {"tag": "record_cold_enter"}, ClientRoutingPolicy.FORCE_COLD))[1]
        )
        mut_out = disp6.invoke(
            InvokeRequest(
                task_id=TaskId("space.remove_and_install"),
                raw_input={"target_module": "vsc", "hold_ms": 200},
                workspace_root=ws6, caller_cwd=ws6,
                approval_scope=frozenset({TaskId("space.remove_and_install")}),
            )
        )
        _check(mut_out.ok and cold_fut.result(timeout=10)["ok"] is True)

        sp_entry = ws6_path / ".modules" / "space" / "module_entry.py"
        atomic_write_bytes(HostPath(sp_entry), sp_entry.read_text(encoding="utf-8").replace('MODULE_VER = "v1"', 'MODULE_VER = "v2"').encode("utf-8"))
        # Zero artificial sleep before CONTROL_RESUME: watcher baseline resync must prevent duplicate reloads!
        _check(query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_RESUME, {}) is not None)
        _check(queued_fut.result(timeout=5.0).executed_hot is True)
        vsc_starts_after_resume = _jint(read_json_dict(ws6.join(".cache", "vsc_tier0_warm.json")), "starts", 0)
        time.sleep(0.35)
        _check(_jint(read_json_dict(ws6.join(".cache", "vsc_tier0_warm.json")), "starts", 0) == vsc_starts_after_resume)

    # Verify installer_exit_ts <= cold_reader_enter_ts, inline emit_imm proof, and DoubleBufferedEventQueue ORDERED_FIFO!
    inst_exit = _jfloat(read_json_dict(ws6.join(".cache", "installer_exit_ts.json")), "exit")
    cold_enter = _jfloat(read_json_dict(ws6.join(".cache", "cold_reader_ts.json")), "enter")
    _check(inst_exit > 0 and cold_enter >= inst_exit - 0.002, lambda: f"Cold reader entered before installer released lock: {inst_exit} vs {cold_enter}")
    imm_proof = read_json_dict(ws6.join(".cache", "imm_inline_proof.json")) or {}
    _check(imm_proof.get("imm_seen_inline") == [1, 2] and imm_proof.get("deferred_flushed_early") is False)
    fifo_log = read_json_dict(ws6.join(".cache", "deferred_fifo.json")) or {}
    _check(fifo_log.get("seqs") == [1, 2, 3] and fifo_log.get("batch_sizes") == [1, 1, 1])
    _check(_jint(read_json_dict(ws6.join(".cache", "diamond_merged.json")), "runs") == 1)
    # Test strict=True immediate failure aborting caller!
    strict_imm = disp6.invoke(InvokeRequest(task_id=TaskId("space.remove_and_install"), raw_input={"target_module": "fail_strict", "strict_imm_fail": True}, workspace_root=ws6, caller_cwd=ws6, approval_scope=frozenset({TaskId("space.remove_and_install")})))
    _check(not strict_imm.ok)


def _verify_rc06_live_reload_and_core_handoff(
    ws6: HostPath,
    ws6_path: Path,
    disp6: RuntimeDispatcher,
    st6_before: JsonObject,
) -> JsonObject:
    v2_echo = disp6.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="hot"), routing_policy=ClientRoutingPolicy.STRICT_HOT)
    _check(v2_echo.ok and v2_echo.value is not None and v2_echo.value.ok_msg == "tier0:v2:SPACE_H:hot")

    # Live Tier 1 ast_v1 -> ast_v2 reload while co-located kdb warm_model_ready stays True!
    # Start in-flight sibling kdb.search(sleep_ms=300) on shared idx_group while triggering CONTROL_RELOAD(ast)!
    ast_entry = ws6_path / ".modules" / "ast" / "module_entry.py"
    ast_entry.write_text(ast_entry.read_text(encoding="utf-8").replace('AST_MOD_VER = "ast_v1"', 'AST_MOD_VER = "ast_v2"'), encoding="utf-8")
    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as rel_pool:
        sib_fut = rel_pool.submit(disp6.invoke_typed, KDB_SEARCH_META, SearchInDto(query="survive_reload", sleep_ms=260), routing_policy=ClientRoutingPolicy.STRICT_HOT)
        time.sleep(0.04)
        _check(query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_RELOAD, {"modules": ["ast"]}) is not None)
        _check(sib_fut.result(timeout=5.0).ok)
    deadline_rel = time.monotonic() + 4.0
    saw_v2 = False
    while time.monotonic() < deadline_rel:
        p_ast = disp6.invoke_typed(AST_OUTLINE_META, OutlineInDto(rel_file="./sample.py"), caller_cwd=HostPath(ws6_path / "sub_dir"), routing_policy=ClientRoutingPolicy.STRICT_HOT)
        if p_ast.ok and p_ast.value is not None and p_ast.value.module_ver == "ast_v2":
            saw_v2 = True
            break
        time.sleep(0.08)
    _check(saw_v2)
    kdb_after_ast_reload = disp6.invoke_typed(KDB_SEARCH_META, SearchInDto(query="still_warm"), routing_policy=ClientRoutingPolicy.STRICT_HOT)
    _check(kdb_after_ast_reload.ok and kdb_after_ast_reload.value is not None and kdb_after_ast_reload.value.warm_model_ready is True)

    # Lease auto-recovery + MUTATES_CORE handoff while an in-flight foreground request drains cleanly!
    query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_QUIESCE, {"modules": ["ast"], "lease_sec": 0.22})
    time.sleep(0.38)
    _check(wait_for_daemon_online(ws6)["state"] == "ready")

    # Verify live disk config edit -> core.config_changed event -> config_reloaded_marker.json + cold fingerprint reload!
    atomic_write_json(ws6.join("config", "gdrive.json"), {"auto_sync": False, "interval_sec": 0.25, "work_ms": 0})
    deadline_cfg = time.monotonic() + 3.0
    while time.monotonic() < deadline_cfg and not ws6.join(".cache", "config_reloaded_marker.json").path.exists():
        time.sleep(0.04)
    _check(ws6.join(".cache", "config_reloaded_marker.json").path.is_file())

    bad_mod_hot = disp6.invoke(InvokeRequest(task_id=TaskId("space.bad_hot_mutate"), raw_input={}, workspace_root=ws6, caller_cwd=ws6, approval_scope=frozenset({TaskId("space.remove_and_install")})), output_type=SimpleOutDto)
    _check(bad_mod_hot.ok and bad_mod_hot.value is not None and bad_mod_hot.value.ok_msg == ErrorCode.HOT_MUTATION_FORBIDDEN.value)
    bad_core_hot = disp6.invoke(InvokeRequest(task_id=TaskId("space.bad_hot_core_mutate"), raw_input={}, workspace_root=ws6, caller_cwd=ws6, approval_scope=frozenset({TaskId("space.upgrade_core")})), output_type=SimpleOutDto)
    _check(bad_core_hot.ok and bad_core_hot.value is not None and bad_core_hot.value.ok_msg == ErrorCode.HOT_MUTATION_FORBIDDEN.value)
    cold_strict_err = disp6.invoke(InvokeRequest(task_id=TaskId("dev.run_sandbox"), raw_input={"child_workspace": str(ws6)}, workspace_root=ws6, caller_cwd=ws6, routing_policy=ClientRoutingPolicy.STRICT_HOT))
    _check(not cold_strict_err.ok and cold_strict_err.error is not None and cold_strict_err.error.code == ErrorCode.COLD_DISPATCH_FORBIDDEN)

    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
        draining_fg = pool.submit(disp6.invoke, InvokeRequest(task_id=TaskId("space.hold_lock_ms"), raw_input={"hold_ms": 180}, workspace_root=ws6, caller_cwd=ws6))
        time.sleep(0.04)
        upg_out = disp6.invoke(InvokeRequest(task_id=TaskId("space.upgrade_core"), raw_input={"version_tag": "2.1.0"}, workspace_root=ws6, caller_cwd=ws6, approval_scope=frozenset({TaskId("space.upgrade_core")})), output_type=SimpleOutDto)
        _check(upg_out.ok and upg_out.value is not None and "handoff=True" in upg_out.value.ok_msg)
        _check(draining_fg.result(timeout=5.0).ok)
    _check(read_json_dict(ws6.join(".cache", "core_upgraded.json")) == {"version": "2.1.0"})

    deadline = time.monotonic() + 6.0
    st6_after: Optional[JsonObject] = None
    while time.monotonic() < deadline:
        cand = query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_STATUS)
        if cand and cand.get("ok") and isinstance(cand.get("status"), Mapping) and cand["status"].get("boot_id") != st6_before["boot_id"]:
            st6_after = cand["status"]
            break
        time.sleep(0.06)
    _check(st6_after is not None and st6_after["pid"] != st6_before["pid"])
    return st6_after or {}


def _verify_rc06_empty_quiesce_fast_core_handoff(
    ws6: HostPath,
    ws6_path: Path,
    disp6: RuntimeDispatcher,
    st_prev: JsonObject,
) -> None:
    core_mod_dir = ws6_path / ".modules" / "core"
    core_mod_dir.mkdir(parents=True, exist_ok=True)
    atomic_write_bytes(HostPath(core_mod_dir / "fast_patch.py"), b"PATCH_REV = 1\n")
    # Also test hot Tier 1 emit_imm synchronous callback & strict=True propagation before core handoff!
    hot_imm = disp6.invoke_typed(AST_OUTLINE_META, OutlineInDto(rel_file="./sample.py", call_tier0=True), caller_cwd=HostPath(ws6_path / "sub_dir"), routing_policy=ClientRoutingPolicy.STRICT_HOT)
    _check(hot_imm.ok and (ws6_path / ".cache" / "tier1_imm_seen.json").is_file())
    hot_imm_err = disp6.invoke_typed(AST_OUTLINE_META, OutlineInDto(rel_file="./sample.py", call_tier0=True, fail_imm_strict=True), caller_cwd=HostPath(ws6_path / "sub_dir"), routing_policy=ClientRoutingPolicy.STRICT_HOT)
    _check(not hot_imm_err.ok)
    # Reboot fresh baseline so .modules/core/fast_patch.py (14 bytes) is in boot snapshot, then overwrite with EQUAL-SIZE bytes!
    stop_daemon_cleanly(ws6)
    disp6.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="re_boot_same_size"))
    st_prev = wait_for_daemon_online(ws6)
    q_ack = query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_QUIESCE, {})
    _check(q_ack is not None and q_ack.get("ok") is True)
    atomic_write_bytes(HostPath(core_mod_dir / "fast_patch.py"), b"PATCH_REV = 2\n")
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as h_pool:
        queued_strict = h_pool.submit(
            disp6.invoke,
            InvokeRequest(
                task_id=TaskId("space.daemon_metrics"),
                raw_input={},
                workspace_root=ws6,
                caller_cwd=ws6,
                routing_policy=ClientRoutingPolicy.STRICT_HOT,
            ),
            output_type=SimpleOutDto,
        )
        time.sleep(0.05)
        r_ack = query_daemon_control(ws6.join(".cache"), ws6, FrameKind.CONTROL_RESUME, {})
        _check(r_ack is not None and r_ack.get("handoff") is True)
        q_res = queued_strict.result(timeout=10.0)
    _check(q_res.ok and q_res.executed_hot is True)
    st_post = wait_for_daemon_online(ws6)
    _check(st_post["boot_id"] != st_prev["boot_id"])


def _verify_rc07_real_sigint_tree_and_lifo(ws7_host: Path, venv_py: Path) -> None:
    (ws7_host / ".cache").mkdir(parents=True, exist_ok=True)
    (ws7_host / ".cache" / "inject_teardown_error.flag").write_text("1", encoding="utf-8")
    gp_path = HostPath(ws7_host / ".cache" / "grandchild_pid.json")
    cli_proc = subprocess.Popen(
        [
            sys.executable, "-W", "error::ResourceWarning", str(Path(__file__).resolve()),
            "--cli-oneshot", str(ws7_host), str(venv_py), str(ws7_host),
            "dev.run_sandbox", json.dumps({"child_workspace": str(ws7_host), "spawn_sleep_child": True}),
            ClientRoutingPolicy.FORCE_COLD.value,
        ],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
    )
    try:
        deadline = time.monotonic() + 6.0
        while time.monotonic() < deadline and read_json_dict(gp_path) is None:
            time.sleep(0.03)
        gp_info = read_json_dict(gp_path)
        _check(gp_info is not None)
        sig_int = signal.CTRL_C_EVENT if sys.platform == "win32" else signal.SIGINT
        cli_proc.send_signal(sig_int)
        out_str, _err_str = cli_proc.communicate(timeout=10.0)
    finally:
        _reap_popen_quietly(cli_proc)
    _check(cli_proc.returncode == 130)
    parsed = json.loads(out_str.strip())
    _check(parsed["ok"] is False and parsed["error"] == ErrorCode.TASK_CANCELLED.value and parsed["teardown_count"] == 1)
    lifo_ord = read_json_dict(HostPath(ws7_host / ".cache" / "lifo_teardown_order.json")) or {}
    _check(lifo_ord.get("order") == ["space_threw_first_in_lifo", "dev_closed_after_space_threw"])
    time.sleep(0.08)
    _check(not is_process_alive(_jint(gp_info, "child_pid")) and not is_process_alive(_jint(gp_info, "grandchild_pid")))
    probe_l = FileLock(HostPath(ws7_host / ".cache" / "locks" / "installer.lock"))
    _check(probe_l.acquire(shared=False, blocking=False))
    probe_l.release()
    (ws7_host / ".cache" / "inject_teardown_error.flag").unlink(missing_ok=True)


def verify_rc07_child_sandbox_and_lifo_teardown(tmp_root: Path, venv_py: Path) -> None:
    _log("[RC-07] Testing multi-child sandbox, cross-ws RPC cycle, real SIGINT (130) & 2-item LIFO order...")
    ws7_host = tmp_root / "ws_rc07_host"
    ws7_child_a = tmp_root / "ws_rc07_child_a"
    ws7_child_b = tmp_root / "ws_rc07_child_b"
    for w in (ws7_host, ws7_child_a, ws7_child_b):
        provision_live_workspace(w)

    rig = build_dispatcher_for_workspace(HostPath(ws7_host), HostPath(venv_py), sandbox_restricted=True)
    disp7_cold, cfg7 = rig.dispatcher, rig.config_view
    try:
        # Cold config fingerprint reload check + cold host -> child workspace + cold->mutating chain!
        atomic_write_json(HostPath(ws7_host / "yscb.config.json"), {"workspace_version": 3})
        sb_chain = disp7_cold.invoke(
            InvokeRequest(
                task_id=TaskId("dev.run_sandbox"),
                raw_input={"child_workspace": str(ws7_child_a), "spawn_sleep_child": False, "sync_host_install": True},
                workspace_root=HostPath(ws7_host), caller_cwd=HostPath(ws7_host),
                approval_scope=frozenset({TaskId("space.remove_and_install")}),
            ),
            output_type=SandboxOutDto,
        )
        _check(sb_chain.ok and sb_chain.value is not None and sb_chain.value.child_ok is True)
        _check(cfg7.get_module_value(ModuleId("root"), "workspace_version") == 3)
        _check(not (ws7_child_a / ".cache" / "daemon" / "daemon.json").exists())
        # OneShotVenvHost cancel must deterministically run ast.on_init LIFO close()!
        (ws7_host / ".cache" / "ast_lazy_inited.json").unlink(missing_ok=True)
        (ws7_host / ".cache" / "ast_lazy_closed.json").unlink(missing_ok=True)
        os_cancel = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as c_pool:
            os_fut = c_pool.submit(
                disp7_cold.invoke_typed,
                AST_OUTLINE_META,
                OutlineInDto(rel_file="./sample.py", coop_sleep_ms=500),
                caller_cwd=HostPath(ws7_host / "sub_dir"),
                cancel_token=os_cancel,
            )
            dl_init = time.monotonic() + 4.0
            while time.monotonic() < dl_init and not (ws7_host / ".cache" / "ast_lazy_inited.json").is_file():
                time.sleep(0.02)
            _check((ws7_host / ".cache" / "ast_lazy_inited.json").is_file())
            os_cancel.cancel()
            os_res = os_fut.result(timeout=5.0)
        _check(not os_res.ok and os_res.error is not None and os_res.error.code == ErrorCode.TASK_CANCELLED)
        _check((ws7_host / ".cache" / "ast_lazy_closed.json").is_file())
    finally:
        disp7_cold.shutdown()

    _verify_rc07_real_sigint_tree_and_lifo(ws7_host, venv_py)
    _verify_rc07_hot_multi_child_and_cross_ws_cycle(ws7_host, ws7_child_a, ws7_child_b, venv_py)
    _log("  -> PASS: RC-07 verified.")


def _verify_rc07_hot_multi_child_and_cross_ws_cycle(
    ws7_host: Path,
    ws7_child_a: Path,
    ws7_child_b: Path,
    venv_py: Path,
) -> None:
    disp7_hot = build_dispatcher_for_workspace(HostPath(ws7_host), HostPath(venv_py), ttl_sec=10.0).dispatcher
    disp7_peer = build_dispatcher_for_workspace(HostPath(ws7_child_b), HostPath(venv_py), ttl_sec=10.0).dispatcher
    try:
        disp7_hot.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot_h"))
        wait_for_daemon_online(HostPath(ws7_host))
        hot_multi = disp7_hot.invoke(
            InvokeRequest(
                task_id=TaskId("space.orchestrate_child_ws"),
                raw_input={"child_ws": str(ws7_child_a), "second_child_ws": str(ws7_child_b)},
                workspace_root=HostPath(ws7_host), caller_cwd=HostPath(ws7_host), routing_policy=ClientRoutingPolicy.STRICT_HOT,
            ),
            output_type=SimpleOutDto,
        )
        _check(hot_multi.ok and hot_multi.executed_hot and hot_multi.value is not None and hot_multi.value.ok_msg == "child_ok")
        _check(not (ws7_child_b / ".cache" / "daemon" / "daemon.json").exists())

        # Boot peer daemon on ws7_child_b & verify REAL 2-Daemon 3-hop TCP RPC cycle ws_host -> ws_child_b -> ws_host!
        disp7_peer.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot_p"))
        peer_st_before = wait_for_daemon_online(HostPath(ws7_child_b))
        cyc_cross = disp7_hot.invoke(
            InvokeRequest(
                task_id=TaskId("space.orchestrate_child_ws"),
                raw_input={"child_ws": str(ws7_child_b), "bounce_back_ws": str(ws7_host)},
                workspace_root=HostPath(ws7_host), caller_cwd=HostPath(ws7_host),
                routing_policy=ClientRoutingPolicy.STRICT_HOT,
            )
        )
        peer_st_after = wait_for_daemon_online(HostPath(ws7_child_b))
        _check(not cyc_cross.ok and cyc_cross.executed_hot is True)
        _check(cyc_cross.error is not None and cyc_cross.error.code == ErrorCode.CALL_CYCLE_DETECTED)
        _check(_jint(peer_st_after, "tasks_handled") > _jint(peer_st_before, "tasks_handled"))
        _check(query_daemon_control(HostPath(ws7_child_b).join(".cache"), HostPath(ws7_child_b), FrameKind.CONTROL_STOP, {"force": True}) is not None)
    finally:
        stop_daemon_cleanly(HostPath(ws7_child_b))
        stop_daemon_cleanly(HostPath(ws7_host))
        disp7_peer.shutdown()
        disp7_hot.shutdown()


def verify_rc08_cross_proc_locks_and_guards(tmp_root: Path, venv_py: Path) -> None:
    _log("[RC-08] Testing cold-first & hot-first FileLock, security/exposure/frame/cycle gates & hot-daemon guards...")
    ws8_path = tmp_root / "ws_rc08"
    provision_live_workspace(ws8_path)
    ws8 = HostPath(ws8_path)
    disp8 = build_dispatcher_for_workspace(ws8, HostPath(venv_py), ttl_sec=90.0).dispatcher
    try:
        disp8.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot"))
        wait_for_daemon_online(ws8)
        _verify_rc08_both_lock_orders(ws8, venv_py, disp8)
        _verify_rc08_security_and_topology_gates(ws8, venv_py, disp8)
        _verify_rc08_frame_and_kernel_unit_regressions(ws8, disp8)
        _verify_fd_and_poisoned_pool_regressions(ws8, disp8)
        _verify_cold_isolation_and_queued_coalesce(ws8, disp8)
        _verify_retiring_reentrant_and_shutdown_edges(ws8, disp8)
        _verify_codec_partial_and_endpoint_probe(ws8, disp8)
        _verify_retiring_lock_yield_and_empty_reload(ws8, disp8)
        _verify_codec_nan_union_key_and_lease_bounds(ws8, disp8)
        _verify_daemon_hygiene_and_local_union(ws8)
    finally:
        stop_daemon_cleanly(ws8)
        disp8.shutdown()
    _log("  -> PASS: RC-08 cross-process locks & security gates verified.")


def _verify_rc08_both_lock_orders(ws8: HostPath, venv_py: Path, disp8: RuntimeDispatcher) -> None:
    # Cold-first external OS FileLock contention while warm Daemon queues behind it:
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fc = pool.submit(_run_cli_subproc, ws8, venv_py, str(ws8), "dev.hold_shared_lock", {"hold_ms": 180, "actor": "cold_1"}, ClientRoutingPolicy.FORCE_COLD)
        time.sleep(0.05)
        fh = pool.submit(disp8.invoke, InvokeRequest(task_id=TaskId("dev.hold_shared_lock"), raw_input={"hold_ms": 80, "actor": "hot_1"}, workspace_root=ws8, caller_cwd=ws8))
        _check(fc.result(timeout=10)["executed_hot"] is False and fh.result(timeout=10).ok)
    # Hot-first warm Daemon holding OS FileLock while external --cold waits:
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fh2 = pool.submit(disp8.invoke, InvokeRequest(task_id=TaskId("dev.hold_shared_lock"), raw_input={"hold_ms": 180, "actor": "hot_2"}, workspace_root=ws8, caller_cwd=ws8))
        time.sleep(0.04)
        fc2 = pool.submit(_run_cli_subproc, ws8, venv_py, str(ws8), "dev.hold_shared_lock", {"hold_ms": 80, "actor": "cold_2"}, ClientRoutingPolicy.FORCE_COLD)
        _check(fh2.result(timeout=10).ok and fc2.result(timeout=10)["executed_hot"] is False)

    spans_raw = _jlist(read_json_dict(ws8.join(".cache", "cross_lock_timeline.json")), "spans")
    _check(len(spans_raw) == 4)
    spans = sorted((s for s in spans_raw if isinstance(s, Mapping)), key=lambda s: _jfloat(s, "enter"))
    for idx in range(len(spans) - 1):
        _check(_jfloat(spans[idx], "exit") <= _jfloat(spans[idx + 1], "enter") + 0.005)


def _verify_rc08_security_and_topology_gates(ws8: HostPath, venv_py: Path, disp8: RuntimeDispatcher) -> None:
    # SDK_ONLY rejected from CLI surface!
    cli_sdk_only = _run_cli_subproc(ws8, venv_py, str(ws8), "space.daemon_metrics", {}, ClientRoutingPolicy.STRICT_HOT)
    _check(cli_sdk_only["ok"] is False and cli_sdk_only["error"] == ErrorCode.EXPOSURE_DENIED.value)

    # CONDITIONAL blocked when allow_conditional=False, allowed by default; GATED hot authorized vs nested/event blocked!
    cond_deny = disp8.invoke(InvokeRequest(task_id=TaskId("gdrive.put"), raw_input={"local_rel": "./sample.py"}, workspace_root=ws8, caller_cwd=ws8, allow_conditional=False))
    _check(not cond_deny.ok and cond_deny.error is not None and cond_deny.error.code == ErrorCode.SECURITY_GATED)
    gated_ok = disp8.invoke(InvokeRequest(task_id=TaskId("vsc.gated_clean"), raw_input={}, workspace_root=ws8, caller_cwd=ws8, approval_scope=frozenset({TaskId("vsc.gated_clean")})))
    _check(gated_ok.ok and gated_ok.executed_hot is True)
    esc = disp8.invoke(InvokeRequest(task_id=TaskId("space.bad_escalate"), raw_input={}, workspace_root=ws8, caller_cwd=ws8), output_type=SimpleOutDto)
    _check(esc.ok and esc.value is not None and esc.value.ok_msg == "blocked:security_gated")
    ev_gated = disp8.invoke(InvokeRequest(task_id=TaskId("space.remove_and_install"), raw_input={"target_module": "vsc"}, workspace_root=ws8, caller_cwd=ws8, approval_scope=frozenset({TaskId("space.remove_and_install")}), propagation=CallPropagationContext(in_event_chain=True)))
    _check(not ev_gated.ok and ev_gated.error is not None and ev_gated.error.code == ErrorCode.SECURITY_GATED)

    # Self-reentrant PREEMPT & COALESCE both fatal-abort with ILLEGAL_LOCK_REENTRANCY!
    self_pre = disp8.invoke(InvokeRequest(task_id=TaskId("space.bad_self_preempt"), raw_input={}, workspace_root=ws8, caller_cwd=ws8))
    _check(not self_pre.ok and self_pre.error is not None and self_pre.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
    self_coa = disp8.invoke(InvokeRequest(task_id=TaskId("space.bad_self_coalesce"), raw_input={}, workspace_root=ws8, caller_cwd=ws8))
    _check(not self_coa.ok and self_coa.error is not None and self_coa.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)

    # Pure CallStack cycle, pure Event cycle, AND mixed Event -> invoke_task -> Event cycle!
    call_cyc = disp8.invoke(InvokeRequest(task_id=TaskId("space.cycle_a"), raw_input={}, workspace_root=ws8, caller_cwd=ws8), output_type=SimpleOutDto)
    _check(not call_cyc.ok and call_cyc.error is not None and call_cyc.error.code == ErrorCode.CALL_CYCLE_DETECTED)
    ev_cyc = disp8.invoke(InvokeRequest(task_id=TaskId("space.ev_cycle_start"), raw_input={}, workspace_root=ws8, caller_cwd=ws8))
    _check(not ev_cyc.ok and ev_cyc.error is not None and ev_cyc.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
    mix_cyc = disp8.invoke(InvokeRequest(task_id=TaskId("space.mix_cycle_emit"), raw_input={}, workspace_root=ws8, caller_cwd=ws8))
    _check(not mix_cyc.ok and mix_cyc.error is not None and mix_cyc.error.code == ErrorCode.EVENT_CYCLE_DETECTED)

    # Tier 0 cooperative & uncooperative timeout_ms -> prompt TASK_TIMEOUT + lingering FileLock held until thread exits!
    t0_to1 = disp8.invoke(InvokeRequest(task_id=TaskId("space.tier0_timeout"), raw_input={"hold_ms": 200, "ignore_cancel": False}, workspace_root=ws8, caller_cwd=ws8))
    t_start_uncoop = time.monotonic()
    t0_to2 = disp8.invoke(InvokeRequest(task_id=TaskId("space.tier0_timeout"), raw_input={"hold_ms": 260, "ignore_cancel": True}, workspace_root=ws8, caller_cwd=ws8))
    elapsed_uncoop = time.monotonic() - t_start_uncoop
    t0_after = disp8.invoke(InvokeRequest(task_id=TaskId("space.hold_lock_ms"), raw_input={"hold_ms": 5, "ignore_cancel": False}, workspace_root=ws8, caller_cwd=ws8))
    _check(not t0_to1.ok and t0_to1.error is not None and t0_to1.error.code == ErrorCode.TASK_TIMEOUT)
    _check(not t0_to2.ok and t0_to2.error is not None and t0_to2.error.code == ErrorCode.TASK_TIMEOUT and elapsed_uncoop < 0.35)
    _check(t0_after.ok)
    ling_exit = _jfloat(read_json_dict(ws8.join(".cache", "t0_lingering_exit.json")), "exit")
    next_enter = _jfloat(read_json_dict(ws8.join(".cache", "t0_guard_probe_enter.json")), "enter")
    _check(ling_exit > 0.0 and next_enter >= ling_exit - 0.005)
    nf_out = disp8.invoke(InvokeRequest(task_id=TaskId("space.nonexistent_xyz"), raw_input={}, workspace_root=ws8, caller_cwd=ws8))
    _check(not nf_out.ok and nf_out.error is not None and nf_out.error.code == ErrorCode.TASK_NOT_FOUND)

    # Parent failure discards parent's staged outbox while preserving committed child task events!
    runs_b = _jint(read_json_dict(ws8.join(".cache", "diamond_merged.json")), "runs")
    p_fail = disp8.invoke(InvokeRequest(task_id=TaskId("space.partial_commit_parent"), raw_input={}, workspace_root=ws8, caller_cwd=ws8))
    _check(not p_fail.ok and _jint(read_json_dict(ws8.join(".cache", "diamond_merged.json")), "runs") == runs_b + 1)
    _check(not ws8.join(".cache", "deferred_fifo.json").path.exists())


def _verify_rc08_frame_and_kernel_unit_regressions(ws8: HostPath, disp8: RuntimeDispatcher) -> None:
    # Outbound >64MiB, Server-side >64MiB CALL_RESULT, and malicious 80MiB inbound header guard!
    giant_str = "x" * (65 * 1024 * 1024)
    out_big = disp8.invoke(InvokeRequest(task_id=TaskId("space.echo_tier0"), raw_input={"tag": giant_str}, workspace_root=ws8, caller_cwd=ws8))
    srv_big = disp8.invoke(InvokeRequest(task_id=TaskId("space.giant_reply"), raw_input={}, workspace_root=ws8, caller_cwd=ws8, routing_policy=ClientRoutingPolicy.STRICT_HOT))
    _check(not out_big.ok and out_big.error is not None and out_big.error.code == ErrorCode.PAYLOAD_TOO_LARGE)
    _check(not srv_big.ok and srv_big.error is not None and srv_big.error.code == ErrorCode.PAYLOAD_TOO_LARGE)

    ep = read_daemon_endpoint_file(ws8.join(".cache"), ws8)
    _check(ep is not None)
    with socket.create_connection((ep.host, ep.port), timeout=1.0) as raw_sock:
        raw_sock.sendall(struct.pack(">I", 80 * 1024 * 1024))
        _check(raw_sock.recv(16) == b"")
    _check(disp8.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="tiny")).ok)

    # Helper local_util.py isolation across space ('SPACE_H') and vsc ('VSC_H')!
    vsc_res = disp8.invoke(InvokeRequest(task_id=TaskId("vsc.sync"), raw_input={}, workspace_root=ws8, caller_cwd=ws8))
    _check(vsc_res.ok and isinstance(vsc_res.value, Mapping) and vsc_res.value.get("helper_who") == "VSC_H")

    _check(ws8.join(".cache", "vsc_tier0_warm.json").path.is_file())


def _verify_fd_and_poisoned_pool_regressions(ws8: HostPath, disp8: RuntimeDispatcher) -> None:
    # FileLock timeout must close its temporary FD exactly once without touching sibling FDs!
    lock_target = ws8.join(".cache", "locks", "fd_safety_probe.lock")
    holder = FileLock(lock_target)
    _check(holder.acquire(shared=False, blocking=False))
    canary_a = (ws8.path / ".cache" / "canary_a.txt")
    canary_b = (ws8.path / ".cache" / "canary_b.txt")
    canary_a.write_text("ok_a", encoding="utf-8")
    canary_b.write_text("ok_b", encoding="utf-8")
    with canary_a.open("r", encoding="utf-8") as fa:
        contender = FileLock(lock_target)
        _check(contender.acquire(shared=False, blocking=False) is False)
        try:
            contender.acquire(shared=False, blocking=True, timeout_sec=0.04)
            raise AssertionError("Expected YscbError(TASK_TIMEOUT) on FileLock timeout")
        except YscbError as exc_lk:
            _check(exc_lk.detail.code == ErrorCode.TASK_TIMEOUT)
        with canary_b.open("r", encoding="utf-8") as fb:
            contender.release()
            _check(fa.read() == "ok_a" and fb.read() == "ok_b")
    holder.release()

    # Co-located venv_group (idx_group: ast + kdb) poisoned-worker drain:
    # uncooperative cancelled ast.outline must NOT kill healthy sibling kdb.search mid-flight,
    # yet MUST deterministically terminate the poisoned worker once sibling completes!
    warm_kdb = disp8.invoke_typed(KDB_SEARCH_META, SearchInDto(query="pre_poison"), routing_policy=ClientRoutingPolicy.STRICT_HOT)
    _check(warm_kdb.ok and warm_kdb.value is not None)
    poisoned_pid = warm_kdb.value.worker_pid
    (ws8.path / ".cache" / "ast_uncoop_in.json").unlink(missing_ok=True)
    (ws8.path / ".cache" / "kdb_search_in.json").unlink(missing_ok=True)
    uncoop_cancel = CancellationToken()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fut_sibling = pool.submit(
            disp8.invoke_typed,
            KDB_SEARCH_META,
            SearchInDto(query="healthy_sibling", sleep_ms=900),
            routing_policy=ClientRoutingPolicy.STRICT_HOT,
        )
        _wait_file_marker(ws8.path / ".cache" / "kdb_search_in.json")
        fut_uncoop = pool.submit(
            disp8.invoke_typed,
            AST_OUTLINE_META,
            OutlineInDto(rel_file="./sample.py", uncoop_hang_ms=5000),
            caller_cwd=ws8,
            routing_policy=ClientRoutingPolicy.STRICT_HOT,
            cancel_token=uncoop_cancel,
        )
        _wait_file_marker(ws8.path / ".cache" / "ast_uncoop_in.json")
        uncoop_cancel.cancel()
        res_uncoop = fut_uncoop.result(timeout=5.0)
        res_sibling = fut_sibling.result(timeout=5.0)
    _check(not res_uncoop.ok and res_uncoop.error is not None and res_uncoop.error.code == ErrorCode.TASK_CANCELLED)
    _check(res_sibling.ok and res_sibling.value is not None and res_sibling.value.worker_pid == poisoned_pid)
    kill_deadline = time.monotonic() + 1.2
    while time.monotonic() < kill_deadline and is_process_alive(poisoned_pid):
        time.sleep(0.03)
    _check(not is_process_alive(poisoned_pid), "Poisoned shared worker was not terminated promptly after sibling drained!")
    healed_kdb = disp8.invoke_typed(KDB_SEARCH_META, SearchInDto(query="post_poison"), routing_policy=ClientRoutingPolicy.STRICT_HOT)
    _check(healed_kdb.ok and healed_kdb.value is not None)
    _check(healed_kdb.value.worker_pid != poisoned_pid and healed_kdb.value.warm_model_ready is True)


def _verify_cold_isolation_and_queued_coalesce(ws8: HostPath, disp8: RuntimeDispatcher) -> None:
    # 1) FORCE_COLD parent calling nested DAEMON_ONLY while warm Daemon is ONLINE must block cold escape!
    fc_sb = disp8.invoke(
        InvokeRequest(
            task_id=TaskId("dev.run_sandbox"),
            raw_input={"child_workspace": str(ws8), "spawn_sleep_child": False, "sync_host_install": True},
            workspace_root=ws8,
            caller_cwd=ws8,
            routing_policy=ClientRoutingPolicy.FORCE_COLD,
            approval_scope=frozenset({TaskId("space.remove_and_install")}),
        ),
        output_type=SandboxOutDto,
    )
    _check(fc_sb.ok and fc_sb.value is not None and fc_sb.value.child_ok is True)

    # 2) Concurrent ColdTurn COALESCE with distinct inputs MUST serialize and never swallow parameters!
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as cpool:
        fca = cpool.submit(
            disp8.invoke,
            InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"force": False, "sleep_ms": 60}, workspace_root=ws8, caller_cwd=ws8, routing_policy=ClientRoutingPolicy.FORCE_COLD),
            output_type=IndexOutDto,
        )
        time.sleep(0.02)
        fcb = cpool.submit(
            disp8.invoke,
            InvokeRequest(task_id=TaskId("kdb.index"), raw_input={"force": True, "sleep_ms": 20}, workspace_root=ws8, caller_cwd=ws8, routing_policy=ClientRoutingPolicy.FORCE_COLD),
            output_type=IndexOutDto,
        )
        rca, rcb = fca.result(timeout=15.0), fcb.result(timeout=15.0)
    _check(rca.ok and rcb.ok and rca.value is not None and rcb.value is not None)
    _check(rcb.coalesced is False and rcb.value.kdb_gen == rca.value.kdb_gen + 10)

    # 3) emit_background_event cleans _active_turns & queued COALESCE Leader cancel hands over cleanly!
    disp8.emit_background_event(EventId("core.config_changed"), {"changed_paths": []})
    _check(disp8.active_turn_count == 0)


def _wait_coalesce_count(coord: ResourceCoordinator | RuntimeDispatcher, resource_key: str, min_count: int, timeout_sec: float = 4.0) -> None:
    dl = time.monotonic() + timeout_sec
    while time.monotonic() < dl:
        eff_c = coord.coordinator if isinstance(coord, RuntimeDispatcher) else coord
        if eff_c.coalesce_participant_count(resource_key) >= min_count:
            return
        time.sleep(0.01)
    raise AssertionError(f"Timed out waiting for coalesce_participant_count({resource_key!r}) >= {min_count}")


def _verify_queued_coalesce_leader_cancel_unit(ws8: HostPath) -> None:
    coord = ResourceCoordinator(ws8.join(".cache", "locks_unit"))
    rel_ev = threading.Event()
    acq_ev = threading.Event()
    tok_l = CancellationToken()
    tok_f = CancellationToken()
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as qpool:
        fh = qpool.submit(
            coord.execute,
            ResourceAcquireSpec("rk", ConcurrencyMode.SERIALIZE, "h", ExecutionPriority.FOREGROUND, "t0", (), CancellationToken()),
            lambda _p, _c, _fl: (acq_ev.set(), rel_ev.wait(timeout=3.0), "h")[2],
        )
        _check(acq_ev.wait(timeout=2.0))
        fl = qpool.submit(
            coord.execute,
            ResourceAcquireSpec("rk", ConcurrencyMode.COALESCE, "eq", ExecutionPriority.FOREGROUND, "t1", (), tok_l),
            lambda _p, _c, _fl: (time.sleep(0.10), "coalesced_ok")[1],
        )
        _wait_coalesce_count(coord, "rk", 1)
        ff = qpool.submit(
            coord.execute,
            ResourceAcquireSpec("rk", ConcurrencyMode.COALESCE, "eq", ExecutionPriority.FOREGROUND, "t2", (), tok_f),
            lambda _p, _c, _fl: "unexpected",
        )
        _wait_coalesce_count(coord, "rk", 2)
        tok_l.cancel()
        rel_ev.set()
        fh.result(timeout=3.0)
        f_coord = ff.result(timeout=3.0)
        _check(f_coord.is_follower is True and f_coord.outcome == "coalesced_ok")
        caught_cancel = False
        try:
            fl.result(timeout=2.0)
        except (TaskCancelledException, YscbError) as exc_l:
            _check(exc_l.detail.code == ErrorCode.TASK_CANCELLED)
            caught_cancel = True
        _check(caught_cancel)


def _verify_cross_helper_relocation_regressions(ws8: HostPath) -> None:
    mdir = ws8.path / ".modules" / "reloc_probe"
    (mdir / "subpkg").mkdir(parents=True, exist_ok=True)
    (mdir / "subpkg" / "__init__.py").write_text("OK = 1\n", encoding="utf-8")
    (mdir / "ha.py").write_text(
        "from __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Optional\n"
        "@dataclass(frozen=True, slots=True)\nclass TopDto:\n    x: int\n"
        "def mk_cls() -> type:\n"
        "    @dataclass(frozen=True, slots=True)\n    class ClosDto:\n        d: Optional[TopDto] = None\n"
        "    return ClosDto\n",
        encoding="utf-8",
    )
    (mdir / "hb.py").write_text(
        "from __future__ import annotations\nfrom dataclasses import dataclass\nimport functools, types\n"
        "import ha\nfrom ha import TopDto\n"
        "CrossCls = ha.mk_cls()\n"
        "@dataclass(frozen=True, slots=True)\nclass WDto:\n    t: TopDto\n"
        "P_MAP = types.MappingProxyType({'w': WDto})\n"
        "P_FN = functools.partial(lambda c: c, WDto)\n"
        "def def_fn(c: object = WDto) -> object:\n    return c\n",
        encoding="utf-8",
    )
    (mdir / "module_entry.py").write_text(
        "from __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Sequence\n"
        "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.foundation.codec import DataclassCodec\nfrom core.foundation.primitives import ModuleId, TaskId\n"
        "import hb, subpkg\n"
        "@dataclass(frozen=True, slots=True)\nclass RIn:\n    v: int = 5\n"
        "@dataclass(frozen=True, slots=True)\nclass ROut:\n    pkg: str\n    cnt: int\n"
        "class CheckT(Task[RIn, ROut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[RIn, ROut]: return TaskMetadata(TaskId('reloc_probe.chk'), RIn, ROut)\n"
        "    def run(self, req: RIn, ctx: TaskContext) -> ROut:\n"
        "        cands = (hb.CrossCls, hb.P_MAP['w'], hb.P_FN.args[0], hb.def_fn())\n"
        "        ok_n = sum(1 for c in cands if isinstance(c, type) and DataclassCodec.decode(c, {'d': {'x': req.v}} if c.__name__ == 'ClosDto' else {'t': {'x': req.v}}) is not None)\n"
        "        return ROut(pkg=subpkg.__package__ or '', cnt=ok_n)\n"
        "class M(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('reloc_probe')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (CheckT(),)\n"
        "def create_module() -> YscbModule: return M()\n",
        encoding="utf-8",
    )
    art = ProtectedModuleLoader(ws8).load_module_artifact(ModuleDescriptor(ModuleId("reloc_probe"), HostPath(mdir)))
    _verify_module_runtime_type_hints(art.package_key)
    chk_task = art.instance.tasks()[0]
    noop_cb = StepContextCallbacks(lambda _e, _p, _l, _s: None, lambda _t, _r, _w, _p: TaskOutcome(ok=False), lambda _p: None)
    r_slot = LocalModuleSlotRegistry(ws8, LifoResourceStack())
    r_slot.register_descriptors([ModuleDescriptor(ModuleId("reloc_probe"), HostPath(mdir), declared_tasks=(TaskRouteSpec(task_id=chk_task.task_id),))])
    r_rep = r_slot.execute_step_locally(LocalStepExecutionSpec(chk_task.task_id, {"v": 5}, ws8, {}, CausalLineage(), CancellationToken(), PriorityHandle(ExecutionPriority.FOREGROUND), noop_cb))
    _check(r_rep.ok and isinstance(r_rep.raw_output, Mapping) and r_rep.raw_output.get("cnt") == 4)
    _check(str(r_rep.raw_output.get("pkg", "")).endswith(".subpkg"))


def _verify_dynamic_unqualified_sibling_and_watcher_bounds(ws8: HostPath) -> None:
    sib_dir = ws8.path / ".modules" / "unqual_sib"
    sib_dir.mkdir(parents=True, exist_ok=True)
    (sib_dir / "module_entry.py").write_text(
        "from __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Sequence\n"
        "from core.execution.event import EventSubscriptionSpec\n"
        "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
        "class Outer:\n"
        "    @dataclass(frozen=True, slots=True)\n    class Sib:\n        name: str\n"
        "    @dataclass(frozen=True, slots=True)\n    class Holder:\n        sib: Outer.Sib\n"
        "    @dataclass(frozen=True, slots=True)\n    class Mapper:\n"
        "        def __call__(self, items: Sequence[Outer.Sib]) -> Outer.Holder:\n"
        "            return Outer.Holder(sib=Outer.Sib(name=str(len(items))))\n"
        "class SibT(Task[Outer.Holder, Outer.Holder]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[Outer.Holder, Outer.Holder]:\n"
        "        return TaskMetadata(TaskId('unqual_sib.op'), Outer.Holder, Outer.Holder, subscriptions=(EventSubscriptionSpec(EventId('demo.unq'), Outer.Mapper()),))\n"
        "    def run(self, req: Outer.Holder, ctx: TaskContext) -> Outer.Holder: return req\n"
        "class UMod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('unqual_sib')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (SibT(),)\n"
        "def create_module() -> YscbModule: return UMod()\n",
        encoding="utf-8",
    )
    sib_art = ProtectedModuleLoader(ws8).load_module_artifact(ModuleDescriptor(ModuleId("unqual_sib"), HostPath(sib_dir)))
    _verify_module_runtime_type_hints(sib_art.package_key)
    sib_bt = sib_art.instance.tasks()[0]
    _check(sib_bt.compute_normalized_equivalence({"sib": {"name": "u_ok"}}).startswith("unqual_sib.op:"))
    skip_u, mapped_u = sib_bt.map_subscription_batch(EventId("demo.unq"), [{"name": "a"}, {"name": "b"}])
    _check(not skip_u and mapped_u == {"sib": {"name": "2"}})

    in_dir = ws8.path / "watch_in"
    out_dir = ws8.path / "watch_out"
    in_dir.mkdir(parents=True, exist_ok=True)
    out_dir.mkdir(parents=True, exist_ok=True)
    out_f = out_dir / "outside.txt"
    out_f.write_text("ext\n", encoding="utf-8")
    seen_w: list[HostPath] = []
    w_bound = PollingDirectoryWatcher((HostPath(in_dir),), lambda ps: seen_w.extend(ps), debounce_sec=0.04, poll_interval_sec=0.02)
    w_bound.resync_paths((HostPath(out_dir), HostPath(out_f)))
    _check(all(str(in_dir) in str(p) for p in w_bound.tracked_paths))


def _verify_codec_and_invariant_regressions(ws8: HostPath) -> None:
    # Frozenset decoding must reject JSON dict {'vsc.gated_clean': False}
    try:
        DataclassCodec.decode(
            DaemonRpcInvokeEnvelope,
            {"task_id": "vsc.gated_clean", "raw_input": {}, "workspace_root": str(ws8), "caller_cwd": str(ws8), "approval_scope": {"vsc.gated_clean": False}},
        )
        raise AssertionError("frozenset illegally accepted Mapping!")
    except YscbError as exc_fs:
        _check(exc_fs.detail.code == ErrorCode.CODEC_VALIDATION_FAILED)

    # decode_outcome_as(ok=True, value=None) must fail for non-Optional output_type!
    bad_none = decode_outcome_as(TaskOutcome(ok=True, value=None), SimpleOutDto)
    _check(not bad_none.ok and bad_none.error is not None and bad_none.error.code == ErrorCode.CODEC_VALIDATION_FAILED)

    # IntEnum/int map keys, nested SelfRefNode/UnqualifiedSiblingHolder & CallableMapper!
    edge = _CodecEdgeDto(modes={_SampleIntEnum.FAST: 10}, counts={7: "seven"})
    _check(DataclassCodec.decode(_CodecEdgeDto, DataclassCodec.encode(edge)) == edge)
    sr_node = DataclassCodec.decode(_NestedCodecOuter.SelfRefNode, {"label": "a", "nxt": {"label": "b"}})
    _check(sr_node.nxt is not None and sr_node.nxt.label == "b")
    sib_h = DataclassCodec.decode(_NestedCodecOuter.UnqualifiedSiblingHolder, {"sib": {"name": "inner_ok"}})
    _check(sib_h.sib.name == "inner_ok")
    cb_sub = EventSubscriptionSpec(EventId("demo.cb"), _CallableBatchMapper(scale=4))
    cb_mapped = cb_sub.decode_and_map([{"val": 2}, {"val": 3}])
    _check(isinstance(cb_mapped, _MapperLeafDto) and cb_mapped.val == 20)
    _check(_LAZY_FORWARD_SUB_SPEC.decode_and_map([{"n": 4}, {"n": 6}]) == 10)
    sib_sub = EventSubscriptionSpec(EventId("demo.sib"), _SiblingMapperScope.SibMapper())
    _check(sib_sub.decode_and_map([{"v": 7}, {"v": 8}]) == 15)
    norm_rk = TaskRouteSpec(task_id=TaskId("a.b"), concurrency_mode=ConcurrencyMode.SERIALIZE, resource_key="  kdb  ")
    _check(norm_rk.resource_key == "kdb")

    # sys.stdout restored cleanly after guard_standard_streams!
    orig_out = sys.stdout
    with guard_standard_streams() as cap:
        sys.stdout.write("captured_text")
    _check(cap.getvalue() == "captured_text" and sys.stdout is orig_out and sys.stdout.writable())

    # Strict unknown field & bool-for-IntEnum rejection!
    for bad_decode in (
        lambda: DataclassCodec.decode(EchoInDto, {"tag": "ok", "unexpected_extra": 1}),
        lambda: DataclassCodec.decode(_SampleIntEnum, True),
        lambda: DataclassCodec.decode(frozenset[JsonValue], [{"unhashable": 1}]),
    ):
        try:
            bad_decode()
            raise AssertionError("Expected YscbError(CODEC_VALIDATION_FAILED)")
        except YscbError as exc_cd:
            _check(exc_cd.detail.code == ErrorCode.CODEC_VALIDATION_FAILED)

    # _validate_route_invariants static ValueError checks (including missing resource_key on SERIALIZE/COALESCE)!
    for bad_fn in (
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), concurrency_mode=ConcurrencyMode.SERIALIZE, resource_key=None),
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), dispatch_mode=DispatchMode.COLD_ONLY, subscriptions=(SubscriptionRouteSpec(EventId("x.y")),)),
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), timeout_ms=-5),
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), concurrency_mode=ConcurrencyMode.COALESCE, resource_key="  "),
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), interactive_tty=True, dispatch_mode=DispatchMode.HYBRID),
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), mutation_scope=SelfMutationScope.MUTATES_MODULES, dispatch_mode=DispatchMode.HYBRID),
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), security_tier=SecurityTier.GATED, exposure=TaskExposure.INTERNAL_TRIGGER),
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), exposure=TaskExposure.SDK_ONLY, cli=CliBindingSpec(("a",), "s")),
        lambda: TaskRouteSpec(task_id=TaskId("a.b"), exposure=TaskExposure.INTERNAL_TRIGGER, interactive_tty=True, dispatch_mode=DispatchMode.COLD_ONLY),
        lambda: CliBindingSpec(("a",), "s", aliases=("  ",)),
        lambda: CliBindingSpec(("a",), "   "),
        lambda: CliBindingSpec(("a",), "s", aliases=("dup", "dup")),
        lambda: PeriodicScheduleSpec(1.0, enabled_config_key="  "),
    ):
        try:
            bad_fn()
            raise AssertionError("Expected ValueError from TaskRouteSpec invariant!")
        except ValueError:
            pass


@dataclass(frozen=True, slots=True)
class _ClosureCodecBundle:
    holder_cls: type
    leaf_cls: type
    sub_spec: EventSubscriptionSpec[object, int]


def _verify_mapper_and_closure_codec_edges() -> None:
    def _mk_closure_pair() -> _ClosureCodecBundle:
        @dataclass(frozen=True, slots=True)
        class ClosureLeaf:
            n: int

        @dataclass(frozen=True, slots=True)
        class ClosureHolder:
            leaf: ClosureLeaf

        def _clos_map(items: Sequence[ClosureLeaf]) -> int:
            return sum(x.n for x in items)

        return _ClosureCodecBundle(ClosureHolder, ClosureLeaf, EventSubscriptionSpec(EventId("demo.clos"), _clos_map))

    cbun = _mk_closure_pair()
    clos_holder_cls, clos_leaf_cls, clos_sub = cbun.holder_cls, cbun.leaf_cls, cbun.sub_spec
    decoded_ch = DataclassCodec.decode(clos_holder_cls, {"leaf": {"n": 42}}, localns={"ClosureLeaf": clos_leaf_cls})
    _check(DataclassCodec.encode_object(decoded_ch) == {"leaf": {"n": 42}})
    _check(clos_sub.decode_and_map([{"n": 15}, {"n": 27}]) == 42)

    def _scaled_map(factor: int, items: Sequence[_MapperLeafDto]) -> int:
        return factor * sum(i.val for i in items)

    part_sub = EventSubscriptionSpec(EventId("demo.part"), functools.partial(_scaled_map, 5))
    _check(part_sub.decode_and_map([{"val": 3}, {"val": 4}]) == 35)

    class _MethodScopeOuter:
        @dataclass(frozen=True, slots=True)
        class MethodLeaf:
            v: int

        class Holder:
            def map_items(self, items: Sequence[_MethodScopeOuter.MethodLeaf]) -> int:
                return sum(x.v for x in items) + 100

    meth_sub = EventSubscriptionSpec(EventId("demo.meth"), _MethodScopeOuter.Holder().map_items)
    _check(meth_sub.decode_and_map([{"v": 6}, {"v": 9}]) == 115)


