        "class OuterT(Task[XIn, XOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[XIn, XOut]:\n        return TaskMetadata(TaskId('bnc.outer'), XIn, XOut, resource_key='rk_bnc_outer', concurrency_mode=ConcurrencyMode.SERIALIZE)\n"
        "    def run(self, req: XIn, ctx: TaskContext) -> XOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'bnc_outer_in.json'), {'in': True})\n"
