def _verify_retiring_bounceback_and_cold_reentrancy(ws8: HostPath) -> None:
    ws_a = HostPath(ws8.path / "ws_case_ba")
    ws_b = HostPath(ws8.path / "ws_case_bb")
    provision_live_workspace(ws_a.path)
    provision_live_workspace(ws_b.path)
    venv_bin = HostPath(os.environ["YSCB_TEST_DEDICATED_VENV_PY"])
    _provision_retiring_bounce_a(ws_a)
    _provision_retiring_bounce_b(ws_b)
    disp_cold_a = build_dispatcher_for_workspace(ws_a, venv_bin, is_daemon_host=False).dispatcher
    try:
        c_ok = disp_cold_a.invoke(InvokeRequest(TaskId("bnc.outer"), {"peer": str(ws_b), "back_task": "bnc.inner"}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.FORCE_COLD))
        c_pre = disp_cold_a.invoke(InvokeRequest(TaskId("bnc.outer"), {"peer": str(ws_b), "back_task": "bnc.reenter_pre"}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.FORCE_COLD))
        _check(c_ok.ok and not c_pre.ok and c_pre.error is not None and c_pre.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
    finally:
        disp_cold_a.shutdown(grace_ms=100)

    disp_a = build_dispatcher_for_workspace(ws_a, venv_bin, ttl_sec=30.0).dispatcher
    disp_b = build_dispatcher_for_workspace(ws_b, venv_bin, ttl_sec=30.0).dispatcher
    try:
        disp_a.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="a"))
        disp_b.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="b"))
        wait_for_daemon_online(ws_a)
        wait_for_daemon_online(ws_b)
        _run_hot_bounceback_and_gates(ws_a, ws_b, disp_a)
    finally:
        stop_daemon_cleanly(ws_b)
        stop_daemon_cleanly(ws_a)
        disp_b.shutdown(grace_ms=100)
        disp_a.shutdown(grace_ms=100)


def _run_hot_bounceback_and_gates(ws_a: HostPath, ws_b: HostPath, disp_a: RuntimeDispatcher) -> None:
    (ws_a.path / ".cache" / "bnc_outer_in.json").unlink(missing_ok=True)
    (ws_a.path / ".cache" / "ast_uncoop_in.json").unlink(missing_ok=True)
    c_poison = CancellationToken()
    t0 = time.monotonic()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        f_bnc = pool.submit(disp_a.invoke, InvokeRequest(TaskId("bnc.outer"), {"peer": str(ws_b), "back_task": "bnc.inner", "wait_ms": 650}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        _wait_file_marker(ws_a.path / ".cache" / "bnc_outer_in.json")
        f_p = pool.submit(disp_a.invoke_typed, AST_OUTLINE_META, OutlineInDto(rel_file="./sample.py", uncoop_hang_ms=5200), caller_cwd=HostPath(ws_a.path / "sub_dir"), routing_policy=ClientRoutingPolicy.STRICT_HOT, cancel_token=c_poison)
        _wait_file_marker(ws_a.path / ".cache" / "ast_uncoop_in.json")
        c_poison.cancel()
        _check(not f_p.result(timeout=6.0).ok and f_bnc.result(timeout=6.0).ok)
    _check((time.monotonic() - t0) < 4.2)

    mut_r = disp_a.invoke(InvokeRequest(TaskId("bnc.outer"), {"peer": str(ws_b), "back_task": "bnc.safe_mutate"}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
    _check(not mut_r.ok and mut_r.error is not None and mut_r.error.code == ErrorCode.HOT_MUTATION_FORBIDDEN)
    tty_r = disp_a.invoke(InvokeRequest(TaskId("bnc.relay"), {"peer": str(ws_b), "back_task": "bnc.tty_only"}, ws_b, ws_b, propagation=CallPropagationContext(call_stack=((ws_a, TaskId("bnc.outer")),))))
    _check(not tty_r.ok and tty_r.error is not None and tty_r.error.code == ErrorCode.TTY_REQUIRED)
    gat_r = disp_a.invoke(InvokeRequest(TaskId("bnc.outer"), {"peer": str(ws_b), "back_task": "bnc.gated_only"}, ws_a, ws_a, approval_scope=frozenset({TaskId("bnc.gated_only")}), routing_policy=ClientRoutingPolicy.STRICT_HOT))
    _check(not gat_r.ok and gat_r.error is not None and gat_r.error.code == ErrorCode.SECURITY_GATED)


def _provision_coalesce_imm_module(ws_ci: HostPath) -> None:
    mdir = ws_ci.path / ".modules" / "cimm"
    mdir.mkdir(parents=True, exist_ok=True)
    atomic_write_json(
        HostPath(mdir / "routes.json"),
        {
            "module_id": "cimm", "tier1": False,
            "tasks": [
                {"task_id": "cimm.trig_a"},
                {"task_id": "cimm.trig_def_coal"},
                {"task_id": "cimm.wrap_coal"},
                {"task_id": "cimm.coal", "resource_key": "rk_cimm", "concurrency_mode": "coalesce", "subscriptions": [{"event_id": "cimm.ev_a"}]},
                {"task_id": "cimm.imm_sub", "exposure": "internal_trigger", "subscriptions": [{"event_id": "cimm.ev_imm"}]},
                {"task_id": "cimm.def_sub", "exposure": "internal_trigger", "subscriptions": [{"event_id": "cimm.ev_def"}]},
            ],
        },
    )
    (mdir / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport time\nfrom typing import Sequence\n"
        "from core.execution.event import EventMetadata, EventOrdering, EventSubscriptionSpec\n"
        "from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\n"
        "from core.filesystem.fs import atomic_write_json\n"
        "from core.foundation.errors import YscbError\n"
        "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass CIn:\n    cycle: bool = False\n    enter_coal: bool = False\n    emit_once: bool = True\n"
        "@dataclass(frozen=True, slots=True)\nclass COut:\n    ok: bool = True\n"
        "def _map_cin(items: Sequence[CIn]) -> CIn:\n    return items[-1]\n"
        "EV_A = EventMetadata(EventId('cimm.ev_a'), CIn, EventOrdering.UNORDERED)\n"
        "EV_IMM = EventMetadata(EventId('cimm.ev_imm'), CIn, EventOrdering.ORDERED)\n"
        "EV_DEF = EventMetadata(EventId('cimm.ev_def'), CIn, EventOrdering.UNORDERED)\n"
        "class TrigA(Task[CIn, COut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[CIn, COut]:\n        return TaskMetadata(TaskId('cimm.trig_a'), CIn, COut)\n"
        "    def run(self, req: CIn, ctx: TaskContext) -> COut:\n        ctx.emit(EV_A, req)\n        return COut()\n"
        "class TrigDefCoal(Task[CIn, COut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[CIn, COut]:\n        return TaskMetadata(TaskId('cimm.trig_def_coal'), CIn, COut)\n"
        "    def run(self, req: CIn, ctx: TaskContext) -> COut:\n        ctx.emit(EV_DEF, CIn(enter_coal=True))\n        return COut()\n"
        "class WrapCoal(Task[CIn, COut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[CIn, COut]:\n        return TaskMetadata(TaskId('cimm.wrap_coal'), CIn, COut)\n"
        "    def run(self, req: CIn, ctx: TaskContext) -> COut:\n"
        "        r = ctx.invoke_task(TaskId('cimm.coal'), {'cycle': False})\n"
        "        if not r.ok and r.error:\n            raise YscbError(r.error.code, r.error.message)\n"
        "        return COut()\n"
        "class CoalT(Task[CIn, COut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[CIn, COut]:\n"
        "        return TaskMetadata(TaskId('cimm.coal'), CIn, COut, resource_key='rk_cimm', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda _r: 'same_cimm', subscriptions=(EventSubscriptionSpec(EventId('cimm.ev_a'), _map_cin),))\n"
        "    def run(self, req: CIn, ctx: TaskContext) -> COut:\n"
        "        if not req.emit_once:\n            return COut()\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'cimm_in.json'), {'in': True})\n"
        "        time.sleep(0.28)\n"
        "        ctx.emit_imm(EV_IMM, CIn(cycle=req.cycle, emit_once=False))\n"
        "        return COut()\n"
        "class ImmSub(Task[CIn, COut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[CIn, COut]:\n"
        "        return TaskMetadata(TaskId('cimm.imm_sub'), CIn, COut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('cimm.ev_imm'), _map_cin),))\n"
        "    def run(self, req: CIn, ctx: TaskContext) -> COut:\n        ctx.emit(EV_DEF, CIn(cycle=req.cycle, emit_once=False))\n        return COut()\n"
        "class DefSub(Task[CIn, COut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[CIn, COut]:\n"
        "        return TaskMetadata(TaskId('cimm.def_sub'), CIn, COut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('cimm.ev_def'), _map_cin),))\n"
        "    def run(self, req: CIn, ctx: TaskContext) -> COut:\n"
        "        if req.enter_coal:\n"
        "            r = ctx.invoke_task(TaskId('cimm.coal'), {'cycle': False})\n"
        "            if not r.ok and r.error:\n                raise YscbError(r.error.code, r.error.message)\n"
        "            return COut()\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'cimm_def_ran.json'), {'ran': True})\n"
        "        if req.cycle:\n            ctx.emit(EV_A, CIn(cycle=False, emit_once=False))\n"
        "        return COut()\n"
        "class CMod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId:\n        return ModuleId('cimm')\n"
        "    def tasks(self) -> Sequence[BoundTask]:\n        return (TrigA(), TrigDefCoal(), WrapCoal(), CoalT(), ImmSub(), DefSub())\n"
        "def create_module() -> YscbModule:\n    return CMod()\n",
        encoding="utf-8",
    )


def _verify_coalesce_multi_follower_and_imm(ws8: HostPath) -> None:
    ws_ci = HostPath(ws8.path / "ws_case_cimm")
    provision_live_workspace(ws_ci.path)
    _provision_coalesce_imm_module(ws_ci)
    venv_bin = HostPath(os.environ["YSCB_TEST_DEDICATED_VENV_PY"])
    disp_ci = build_dispatcher_for_workspace(ws_ci, venv_bin, is_daemon_host=True).dispatcher
    try:
        disp_ci.warmup_daemon_container()
        # 1. Multi-follower pre-claim cycle check: Leader cancels, F_cyc (lineage=(ev_def,)) fails BEFORE claiming so F_good (wrap_coal, lineage=()) claims & runs DefSub!
        (ws_ci.path / ".cache" / "cimm_in.json").unlink(missing_ok=True)
        (ws_ci.path / ".cache" / "cimm_def_ran.json").unlink(missing_ok=True)
        tok_l = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fl = pool.submit(disp_ci.invoke, InvokeRequest(TaskId("cimm.coal"), {"cycle": False}, ws_ci, ws_ci), cancel_token=tok_l)
            _wait_file_marker(ws_ci.path / ".cache" / "cimm_in.json")
            f_cyc = pool.submit(disp_ci.invoke, InvokeRequest(TaskId("cimm.trig_def_coal"), {}, ws_ci, ws_ci))
            f_good = pool.submit(disp_ci.invoke, InvokeRequest(TaskId("cimm.wrap_coal"), {}, ws_ci, ws_ci))
            _wait_coalesce_count(disp_ci, "rk_cimm", 3)
            tok_l.cancel()
            rl, r_cyc, r_good = fl.result(timeout=5.0), f_cyc.result(timeout=5.0), f_good.result(timeout=5.0)
        _check(not rl.ok and not r_cyc.ok and r_cyc.error is not None and r_cyc.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
        _check(r_good.ok and (ws_ci.path / ".cache" / "cimm_def_ran.json").is_file())

        # 2. COALESCE x emit_imm -> ImmSub emits deferred EV_DEF -> cycle back to EV_A when Leader stays alive!
        _run_coalesce_imm_subcases(ws_ci, disp_ci)
    finally:
        disp_ci.shutdown(grace_ms=100)


def _run_coalesce_imm_subcases(ws_ci: HostPath, disp_ci: RuntimeDispatcher) -> None:
    (ws_ci.path / ".cache" / "cimm_in.json").unlink(missing_ok=True)
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fl2 = pool.submit(disp_ci.invoke, InvokeRequest(TaskId("cimm.coal"), {"cycle": True}, ws_ci, ws_ci))
        _wait_file_marker(ws_ci.path / ".cache" / "cimm_in.json")
        ff2 = pool.submit(disp_ci.invoke, InvokeRequest(TaskId("cimm.trig_a"), {"cycle": True}, ws_ci, ws_ci))
        _wait_coalesce_count(disp_ci, "rk_cimm", 2)
        rl2, rf2 = fl2.result(timeout=5.0), ff2.result(timeout=5.0)
    _check(rl2.ok and not rf2.ok and rf2.error is not None and rf2.error.code == ErrorCode.EVENT_CYCLE_DETECTED)


def _make_repeated_local_codec_pair(scale: int) -> tuple[tuple[type, dict[str, type]], object]:
    @dataclass(frozen=True, slots=True)
    class LocalLeaf:
        v: int

    @dataclass(frozen=True, slots=True)
    class LocalHolder:
        item: LocalLeaf

    def _map_items(items: Sequence[LocalLeaf]) -> int:
        return sum(x.v for x in items) * scale

    spec = EventSubscriptionSpec(EventId("unionmod.local_union"), _map_items)
    return ((LocalHolder, {"LocalLeaf": LocalLeaf}), spec)


def _verify_daemon_hygiene_and_local_union(ws8: HostPath) -> None:
    (h1, lns1), s1 = _make_repeated_local_codec_pair(2)
    (h2, lns2), s2 = _make_repeated_local_codec_pair(5)
    d1 = DataclassCodec.decode(h1, {"item": {"v": 7}}, localns=lns1)
    d2 = DataclassCodec.decode(h2, {"item": {"v": 9}}, localns=lns2)
    _check(type(d1) is h1 and type(d2) is h2)
    _check(isinstance(s1, EventSubscriptionSpec) and s1.decode_and_map([{"v": 3}]) == 6)
    _check(isinstance(s2, EventSubscriptionSpec) and s2.decode_and_map([{"v": 4}]) == 20)

    if os.name != "nt":
        dj_mode = (ws8.path / ".cache" / "daemon" / "daemon.json").stat().st_mode & 0o777
        _check(dj_mode == 0o600, lambda: f"Expected 0o600 on daemon.json, got {oct(dj_mode)}")

    ws_cold = HostPath(ws8.path / "ws_case_cold_hygiene")
    provision_live_workspace(ws_cold.path)
    venv_bin = HostPath(os.environ["YSCB_TEST_DEDICATED_VENV_PY"])
    before_keys = {k for k in sys.modules if k.startswith("_yscb_v2_mod_")}
    disp_c = build_dispatcher_for_workspace(ws_cold, venv_bin, is_daemon_host=False).dispatcher
    _check(disp_c.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="cold_clean"), routing_policy=ClientRoutingPolicy.FORCE_COLD).ok)
    mid_keys = {k for k in sys.modules if k.startswith("_yscb_v2_mod_")} - before_keys
    _check(mid_keys == set(), lambda: f"ColdTurn leaked dynamic modules: {mid_keys}")
    disp_c.shutdown(grace_ms=100)
    after_keys = {k for k in sys.modules if k.startswith("_yscb_v2_mod_")} - before_keys
    _check(after_keys == set(), lambda: f"Dispatcher.shutdown leaked dynamic modules: {after_keys}")



def _verify_empty_reload_resync_and_core_handoff(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_er = HostPath(ws8.path / "ws_case_empty_rel")
    provision_live_workspace(ws_er.path)
    disp_er = build_dispatcher_for_workspace(ws_er, venv_bin, ttl_sec=20.0).dispatcher
    try:
        disp_er.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot"))
        st0 = wait_for_daemon_online(ws_er)
        vsc_e = ws_er.path / ".modules" / "vsc" / "module_entry.py"
        atomic_write_bytes(HostPath(vsc_e), (vsc_e.read_text(encoding="utf-8") + "\n# touch\n").encode("utf-8"))
        _check(query_daemon_control(ws_er.join(".cache"), ws_er, FrameKind.CONTROL_RELOAD, {}) is not None)
        starts_after = _jint(read_json_dict(ws_er.join(".cache", "vsc_tier0_warm.json")), "starts", 0)
        time.sleep(0.35)
        _check(_jint(read_json_dict(ws_er.join(".cache", "vsc_tier0_warm.json")), "starts", 0) == starts_after)
        core_dir = ws_er.path / ".modules" / "core"
        core_dir.mkdir(parents=True, exist_ok=True)
        (core_dir / "ver.txt").write_text("v2\n", encoding="utf-8")
        rel_core = query_daemon_control(ws_er.join(".cache"), ws_er, FrameKind.CONTROL_RELOAD, {})
        _check(rel_core is not None and rel_core.get("handoff") is True)
        deadline = time.monotonic() + 6.0
        saw_handoff_boot = False
        while time.monotonic() < deadline:
            st_now = query_daemon_control(ws_er.join(".cache"), ws_er, FrameKind.CONTROL_STATUS)
            if st_now and isinstance(st_now.get("status"), Mapping) and st_now["status"].get("boot_id") != st0["boot_id"]:
                saw_handoff_boot = True
                break
            time.sleep(0.05)
        _check(saw_handoff_boot)
    finally:
        stop_daemon_cleanly(ws_er)
        disp_er.shutdown(grace_ms=100)




def _provision_retiring_equiv_and_map_modules(ws_a: HostPath) -> None:
    ma = ws_a.path / ".modules" / "eqm"
    ma.mkdir(parents=True, exist_ok=True)
    atomic_write_json(
        HostPath(ma / "routes.json"),
        {
            "module_id": "eqm",
            "tier1": True,
            "venv_group": "eq_grp",
            "eager_warmup": True,
            "tasks": [
                {"task_id": "eqm.outer"},
                {"task_id": "eqm.inner_coal", "resource_key": "rk_eqm", "concurrency_mode": "coalesce"},
                {"task_id": "eqm.ev_sub", "exposure": "internal_trigger", "subscriptions": [{"event_id": "eqm.ev_done"}]},
                {"task_id": "eqm.uncoop_hold", "timeout_ms": 2000},
                {"task_id": "eqm.fast_nested"},
            ],
        },
    )
    (ma / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport os, time\nfrom typing import Sequence\n"
        "from core.execution.daemon import query_daemon_control\nfrom core.execution.rpc import FrameKind\n"
        "from core.execution.event import EventMetadata, EventOrdering, EventSubscriptionSpec\n"
        "from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\n"
        "from core.filesystem.fs import atomic_write_json\n"
        "from core.foundation.primitives import EventId, HostPath, ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass EIn:\n    peer_ws: str = ''\n    key_v: str = 'k'\n    hold_ms: int = 0\n"
        "@dataclass(frozen=True, slots=True)\nclass EOut:\n    pid: int = 0\n    tag: str = ''\n"
        "EV_DONE = EventMetadata(EventId('eqm.ev_done'), EIn, EventOrdering.UNORDERED)\n"
        "def _map_ev(items: Sequence[EIn]) -> EIn:\n    return EIn(key_v=items[0].key_v if items else 'm')\n"
        "class OuterT(Task[EIn, EOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[EIn, EOut]: return TaskMetadata(TaskId('eqm.outer'), EIn, EOut)\n"
        "    def run(self, req: EIn, ctx: TaskContext) -> EOut:\n"
        "        query_daemon_control(ctx.workspace_root.join('.cache'), ctx.workspace_root, FrameKind.CONTROL_RELOAD, {'modules': ['eqm']})\n"
        "        r = ctx.invoke_task(TaskId('eqb.bridge'), {'peer_ws': str(ctx.workspace_root)}, target_workspace=HostPath(req.peer_ws))\n"
        "        if not r.ok: raise RuntimeError(str(r.error))\n"
        "        return EOut(pid=os.getpid(), tag='outer_ok')\n"
        "class InnerCoal(Task[EIn, EOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[EIn, EOut]:\n"
        "        return TaskMetadata(TaskId('eqm.inner_coal'), EIn, EOut, resource_key='rk_eqm', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda x: f'eq:{x.key_v}')\n"
        "    def run(self, req: EIn, ctx: TaskContext) -> EOut:\n"
        "        ctx.emit(EV_DONE, EIn(key_v='mapped_ok'))\n"
        "        return EOut(pid=os.getpid(), tag='coal_ok')\n"
        "class EvSub(Task[EIn, EOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[EIn, EOut]:\n"
        "        return TaskMetadata(TaskId('eqm.ev_sub'), EIn, EOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('eqm.ev_done'), _map_ev, payload_type=EIn),))\n"
        "    def run(self, req: EIn, ctx: TaskContext) -> EOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'eqm_ev_sub.json'), {'pid': os.getpid(), 'k': req.key_v})\n"
        "        return EOut(pid=os.getpid(), tag=req.key_v)\n"
        "class UncoopHold(Task[EIn, EOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[EIn, EOut]: return TaskMetadata(TaskId('eqm.uncoop_hold'), EIn, EOut, timeout_ms=2000)\n"
        "    def run(self, req: EIn, ctx: TaskContext) -> EOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'eqm_poison_pid.json'), {'pid': os.getpid()})\n"
        "        time.sleep(max(0.45, req.hold_ms / 1000.0))\n"
        "        return EOut(pid=os.getpid(), tag='held')\n"
        "class FastNested(Task[EIn, EOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[EIn, EOut]: return TaskMetadata(TaskId('eqm.fast_nested'), EIn, EOut)\n"
        "    def run(self, req: EIn, ctx: TaskContext) -> EOut: return EOut(pid=os.getpid(), tag='fast_ok')\n"
        "class EqMod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('eqm')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (OuterT(), InnerCoal(), EvSub(), UncoopHold(), FastNested())\n"
        "def create_module() -> YscbModule: return EqMod()\n",
        encoding="utf-8",
    )


