def _verify_cross_ws_retiring_equiv_and_poison_isolation(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_a = HostPath(ws8.path / "ws_ret_equiv_a")
    ws_b = HostPath(ws8.path / "ws_ret_equiv_b")
    provision_live_workspace(ws_a.path)
    provision_live_workspace(ws_b.path)
    _provision_retiring_equiv_and_map_modules(ws_a)
    _provision_retiring_bridge_module(ws_b)
    disp_a = build_dispatcher_for_workspace(ws_a, venv_bin, ttl_sec=25.0).dispatcher
    disp_b = build_dispatcher_for_workspace(ws_b, venv_bin, ttl_sec=25.0).dispatcher
    try:
        disp_a.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot_a"))
        disp_b.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot_b"))
        wait_for_daemon_online(ws_a)
        wait_for_daemon_online(ws_b)
        bounce_res = disp_a.invoke(
            InvokeRequest(TaskId("eqm.outer"), {"peer_ws": str(ws_b)}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(bounce_res.ok and isinstance(bounce_res.value, Mapping))
        orig_pid = _jint(bounce_res.value, "pid", -1)
        ev_doc = read_json_dict(ws_a.join(".cache", "eqm_ev_sub.json"))
        _check(ev_doc is not None and _jint(ev_doc, "pid", -2) == orig_pid and ev_doc.get("k") == "mapped_ok")

        tok_p = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            fp = pool.submit(
                disp_a.invoke,
                InvokeRequest(TaskId("eqm.uncoop_hold"), {"hold_ms": 600}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT),
                cancel_token=tok_p,
            )
            _wait_file_marker(ws_a.path / ".cache" / "eqm_poison_pid.json")
            poison_pid = _jint(read_json_dict(ws_a.join(".cache", "eqm_poison_pid.json")), "pid", 0)
            tok_p.cancel()
            _check(not fp.result(timeout=4.0).ok)
            time.sleep(0.28)
            unrelated_nested = disp_a.invoke(
                InvokeRequest(TaskId("eqm.fast_nested"), {}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT, propagation=CallPropagationContext(is_nested_call=True, call_stack=((ws_b, TaskId("eqb.bridge")),)))
            )
            _check(unrelated_nested.ok and isinstance(unrelated_nested.value, Mapping))
            _check(_jint(unrelated_nested.value, "pid", poison_pid) != poison_pid)
    finally:
        stop_daemon_cleanly(ws_b)
        stop_daemon_cleanly(ws_a)
        disp_b.shutdown(grace_ms=100)
        disp_a.shutdown(grace_ms=100)


def _provision_cold_installer_bounce_modules(ws_a: HostPath) -> None:
    ma = ws_a.path / ".modules" / "inst_a"
    ma.mkdir(parents=True, exist_ok=True)
    atomic_write_json(
        HostPath(ma / "routes.json"),
        {
            "module_id": "inst_a",
            "tier1": False,
            "tasks": [
                {"task_id": "inst_a.mut_outer", "dispatch_mode": "cold_only", "mutation_scope": "mutates_modules"},
                {"task_id": "inst_a.read_outer", "dispatch_mode": "cold_only"},
                {"task_id": "inst_a.mut_inner", "dispatch_mode": "cold_only", "mutation_scope": "mutates_modules"},
                {"task_id": "inst_a.read_inner", "dispatch_mode": "cold_only"},
            ],
        },
    )
    (ma / "module_entry.py").write_text(
        "from dataclasses import dataclass\nfrom typing import Sequence\n"
        "from core.execution.runtime import BoundTask, ClientRoutingPolicy, DispatchMode, SelfMutationScope, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.foundation.errors import YscbError\n"
        "from core.foundation.primitives import HostPath, ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass MIn:\n    peer_ws: str = ''\n    target_inner: str = 'inst_a.mut_inner'\n"
        "@dataclass(frozen=True, slots=True)\nclass MOut:\n    tag: str = 'ok'\n"
        "class MutOuter(Task[MIn, MOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[MIn, MOut]:\n"
        "        return TaskMetadata(TaskId('inst_a.mut_outer'), MIn, MOut, dispatch_mode=DispatchMode.COLD_ONLY, mutation_scope=SelfMutationScope.MUTATES_MODULES)\n"
        "    def run(self, req: MIn, ctx: TaskContext) -> MOut:\n"
        "        r = ctx.invoke_task(TaskId('inst_b.bounce'), {'back_ws': str(ctx.workspace_root), 'target_inner': req.target_inner}, target_workspace=HostPath(req.peer_ws), routing_policy=ClientRoutingPolicy.FORCE_COLD)\n"
        "        if not r.ok and r.error: raise YscbError(r.error.code, r.error.message)\n"
        "        return MOut(tag='mut_bounce_ok')\n"
        "class ReadOuter(Task[MIn, MOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[MIn, MOut]:\n"
        "        return TaskMetadata(TaskId('inst_a.read_outer'), MIn, MOut, dispatch_mode=DispatchMode.COLD_ONLY)\n"
        "    def run(self, req: MIn, ctx: TaskContext) -> MOut:\n"
        "        r = ctx.invoke_task(TaskId('inst_b.bounce'), {'back_ws': str(ctx.workspace_root), 'target_inner': req.target_inner}, target_workspace=HostPath(req.peer_ws), routing_policy=ClientRoutingPolicy.FORCE_COLD)\n"
        "        if not r.ok and r.error: raise YscbError(r.error.code, r.error.message)\n"
        "        return MOut(tag='read_bounce_ok')\n"
        "class MutInner(Task[MIn, MOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[MIn, MOut]:\n"
        "        return TaskMetadata(TaskId('inst_a.mut_inner'), MIn, MOut, dispatch_mode=DispatchMode.COLD_ONLY, mutation_scope=SelfMutationScope.MUTATES_MODULES)\n"
        "    def run(self, req: MIn, ctx: TaskContext) -> MOut: return MOut(tag='inner_mut_done')\n"
        "class ReadInner(Task[MIn, MOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[MIn, MOut]:\n"
        "        return TaskMetadata(TaskId('inst_a.read_inner'), MIn, MOut, dispatch_mode=DispatchMode.COLD_ONLY)\n"
        "    def run(self, req: MIn, ctx: TaskContext) -> MOut: return MOut(tag='inner_read_done')\n"
        "class InstAMod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('inst_a')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (MutOuter(), ReadOuter(), MutInner(), ReadInner())\n"
        "def create_module() -> YscbModule: return InstAMod()\n",
        encoding="utf-8",
    )


