                {"task_id": "aorp.orp_leaf", "exposure": "internal_trigger", "subscriptions": [{"event_id": "aorp.ev_orp"}]},
                {"task_id": "aorp.w_ord_entry"},
                {"task_id": "aorp.w_anc_sub", "exposure": "internal_trigger", "subscriptions": [{"event_id": "aorp.ev_w_anc"}]},
                {"task_id": "aorp.b_hop_entry"},
                {"task_id": "aorp.b_hop_sub", "exposure": "internal_trigger", "subscriptions": [{"event_id": "aorp.ev_b_hop"}]},
