def _verify_adversarial_orphan_failover_topologies(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_a = HostPath(ws8.path / "ws_adv_orp")
    provision_live_workspace(ws_a.path)
    _provision_adversarial_orphan_mod(ws_a.path)
    _write_aorp_routes(ws_a.path)
    disp_a = build_dispatcher_for_workspace(ws_a, venv_bin, is_daemon_host=True).dispatcher
    try:
        disp_a.warmup_daemon_container()
        tok_s1 = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fs1 = pool.submit(disp_a.invoke, InvokeRequest(TaskId("aorp.shared_orp"), {"mode": "cc"}, ws_a, ws_a, propagation=CallPropagationContext(call_stack=((ws_a, TaskId("ext.s")),))), cancel_token=tok_s1)
            _wait_file_marker(ws_a.path / ".cache" / "aorp_in_cc.json")
            fw1 = pool.submit(disp_a.invoke, InvokeRequest(TaskId("aorp.w_priv_cc"), {}, ws_a, ws_a))
            fb1 = pool.submit(disp_a.invoke, InvokeRequest(TaskId("aorp.b_hop_entry"), {"mode": "cc"}, ws_a, ws_a))
            _wait_coalesce_count(disp_a, "rk_aorp1", 3)
            tok_s1.cancel()
            atomic_write_json(ws_a.join(".cache", "aorp_go_cc.json"), {"go": True})
            rs1, rw1, rb1 = fs1.result(timeout=5.0), fw1.result(timeout=5.0), fb1.result(timeout=5.0)
        _check(not rs1.ok and rs1.error is not None and rs1.error.code == ErrorCode.TASK_CANCELLED)
        _check(not rw1.ok and rw1.error is not None and rw1.error.code == ErrorCode.CALL_CYCLE_DETECTED)
        _check(rb1.ok and read_json_dict(ws_a.join(".cache", "aorp_orp_ran.json")) == {"seq": 99})

        tok_s2 = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fs2 = pool.submit(disp_a.invoke, InvokeRequest(TaskId("aorp.shared_orp"), {"mode": "ord"}, ws_a, ws_a, propagation=CallPropagationContext(call_stack=((ws_a, TaskId("ext.s2")),))), cancel_token=tok_s2)
            _wait_file_marker(ws_a.path / ".cache" / "aorp_in_ord.json")
            fw2 = pool.submit(disp_a.invoke, InvokeRequest(TaskId("aorp.w_ord_entry"), {}, ws_a, ws_a))
            fb2 = pool.submit(disp_a.invoke, InvokeRequest(TaskId("aorp.b_hop_entry"), {"mode": "ord"}, ws_a, ws_a))
            _wait_coalesce_count(disp_a, "rk_aorp1", 3)
            tok_s2.cancel()
            atomic_write_json(ws_a.join(".cache", "aorp_go_ord.json"), {"go": True})
            rs2, rw2, rb2 = fs2.result(timeout=5.0), fw2.result(timeout=5.0), fb2.result(timeout=5.0)
        _check(not rs2.ok and rs2.error is not None and rs2.error.code == ErrorCode.TASK_CANCELLED)
        _check(not rw2.ok and rw2.error is not None and rw2.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
        _check(rb2.ok and read_json_dict(ws_a.join(".cache", "aorp_ord_seqs.json")) == {"seqs": [1, 2]})
    finally:
        disp_a.shutdown(grace_ms=100)


def _verify_delayed_winner_cancel_orphan_takeover(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_a = HostPath(ws8.path / "ws_adv_orp_takeover")
    provision_live_workspace(ws_a.path)
    _provision_adversarial_orphan_mod(ws_a.path)
    _write_aorp_routes(ws_a.path)
    disp_d = build_dispatcher_for_workspace(ws_a, venv_bin, is_daemon_host=True).dispatcher
    w_tid_box: list[int] = []
    delay_gate = threading.Event()

    def _trace_delay_w(_frame: object, event: str, _arg: object) -> object:
        if event == "line" and w_tid_box and threading.get_ident() == w_tid_box[0]:
            if delay_gate.is_set():
                delay_gate.clear()
                time.sleep(0.32)
        return _trace_delay_w

    try:
        disp_d.warmup_daemon_container()
        tok_s3, tok_w3 = CancellationToken(), CancellationToken()

        def _run_w() -> TaskOutcome[JsonValue]:
            w_tid_box.append(threading.get_ident())
            sys.settrace(_trace_delay_w)
            try:
                return disp_d.invoke(InvokeRequest(TaskId("aorp.shared_orp"), {"mode": "dly"}, ws_a, ws_a, propagation=CallPropagationContext(call_stack=((ws_a, TaskId("ext.w3")),))), cancel_token=tok_w3)
            finally:
                sys.settrace(None)

        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fs3 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("aorp.shared_orp"), {"mode": "dly"}, ws_a, ws_a, propagation=CallPropagationContext(call_stack=((ws_a, TaskId("ext.s3")),))), cancel_token=tok_s3)
            _wait_file_marker(ws_a.path / ".cache" / "aorp_in_dly.json")
            fw3 = pool.submit(_run_w)
            fb3 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("aorp.b_hop_entry"), {"mode": "dly"}, ws_a, ws_a))
            _wait_coalesce_count(disp_d, "rk_aorp1", 3)
            delay_gate.set()
            tok_s3.cancel()
            atomic_write_json(ws_a.join(".cache", "aorp_go_dly.json"), {"go": True})
            time.sleep(0.28)
            tok_w3.cancel()
            rs3, rw3, rb3 = fs3.result(timeout=5.0), fw3.result(timeout=5.0), fb3.result(timeout=5.0)
        _check(not rs3.ok and rs3.error is not None and rs3.error.code == ErrorCode.TASK_CANCELLED)
        _check(not rw3.ok and rw3.error is not None and rw3.error.code == ErrorCode.TASK_CANCELLED)
        _check(rb3.ok and read_json_dict(ws_a.join(".cache", "aorp_orp_ran.json")) == {"seq": 99})
    finally:
        disp_d.shutdown(grace_ms=100)


def _verify_protocol_version_rejection_and_headless_stdout(ws8: HostPath) -> None:
    _check("write_handoff_lease" not in rpc_pkg.__all__ and "clear_handoff_lease" not in rpc_pkg.__all__)
    orig_stdout = sys.stdout
    try:
        sys.stdout = None
        with guard_standard_streams() as cap_outer:
            _check(sys.stdout is not None and not sys.stdout.isatty())
            with guard_standard_streams() as cap_inner:
                sys.stdout.write("inner_msg")
            _check(cap_inner.getvalue() == "inner_msg")
            sys.stdout.write("outer_msg")
            _check(cap_outer.getvalue() == "outer_msg")
        _check(sys.stdout is None)
    finally:
        sys.stdout = orig_stdout

    for bad_proto in (999, True, "2"):
        hello_obj = {"stream_id": 0, "kind": "hello", "payload": {"protocol": bad_proto, "auth_token": "t", "boot_id": "b", "workspace_root": str(ws8)}}
        raw_hello = json.dumps(hello_obj).encode("utf-8")
        a_s, b_s = socket.socketpair()
        try:
            a_s.sendall(struct.pack(">I", len(raw_hello)) + raw_hello)
            a_s.close()
            _check(accept_worker_handshake(b_s, expected_auth_token="t", boot_id="b", handler=_NoopInboundRpcHandler()) is None)
        finally:
            _close_socket_pair_quietly(a_s, b_s)


def _verify_listener_and_client_protocol_bounds(ws8: HostPath) -> None:
    listener = RpcServerListener(ws8, _NoopInboundRpcHandler())
    ep = listener.start()
    try:
        for bad_proto in (999, True):
            cli = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            try:
                cli.settimeout(2.0)
                cli.connect((ep.host, ep.port))
                msg = json.dumps({"stream_id": 0, "kind": "hello", "payload": {"protocol": bad_proto, "auth_token": ep.auth_token, "boot_id": ep.boot_id, "workspace_root": str(ws8)}}).encode("utf-8")
                cli.sendall(struct.pack(">I", len(msg)) + msg)
                hdr = cli.recv(4)
                ack = json.loads(cli.recv(struct.unpack(">I", hdr)[0]).decode("utf-8"))
                _check(ack["payload"]["ok"] is False)
            finally:
                cli.close()
    finally:
        listener.close_all()

    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.bind(("127.0.0.1", 0))
    srv.listen(2)
    port = int(srv.getsockname()[1])

    def _bad_ack_srv() -> None:
        try:
            conn, _ = srv.accept()
            try:
                _ = conn.recv(512)
                raw = json.dumps({"stream_id": 0, "kind": "hello_ack", "payload": {"ok": True, "boot_id": "b", "protocol": 999}}).encode("utf-8")
                conn.sendall(struct.pack(">I", len(raw)) + raw)
            finally:
                conn.close()
        except OSError:
            pass

    th = threading.Thread(target=_bad_ack_srv, daemon=True)
    th.start()
    try:
        bad_ep = RpcEndpointInfo(pid=os.getpid(), host="127.0.0.1", port=port, boot_id="b", auth_token="t", workspace_root=ws8)
        _check(connect_and_handshake(bad_ep, connect_timeout_sec=1.0) is None)
    finally:
        srv.close()
        th.join(timeout=2.0)


def _verify_quiesce_resume_stray_module_entries_and_owner_stack(ws8: HostPath) -> None:
    ws_q = HostPath(ws8.path / "ws_quiesce_stray")
    provision_live_workspace(ws_q.path)
    coord = ResourceCoordinator(ws_q.join(".cache"))
    tok_c = CancellationToken()
    spec_l = ResourceAcquireSpec(
        "rk_bad_own", ConcurrencyMode.SERIALIZE, "eq", ExecutionPriority.FOREGROUND, "t1", ((ws_q, TaskId("alpha.t")),), cancel_token=tok_c, call_tree_id="ct_bad"
    )
    out_s = coord.execute(spec_l, lambda _p, _c, _fl: "ok").outcome
    lock_files = [f for f in ws_q.join(".cache").path.rglob("*.lock") if "installer" not in f.name]
    _check(out_s == "ok" and len(lock_files) == 1)
    held_lock = FileLock(HostPath(lock_files[0]))
    held_lock.acquire(shared=False, blocking=True, timeout_sec=1.0)
    atomic_write_json(
        HostPath(lock_files[0].with_suffix(".owner.json")),
        {"call_tree_id": "ct_bad", "pid": os.getpid(), "mode": "serialize", "call_stack": [["", "bad..id"]]},
    )

    def _release_soon() -> None:
        time.sleep(0.05)
        held_lock.release()

    rel_th = threading.Thread(target=_release_soon, daemon=True)
    rel_th.start()
    try:
        spec_l2 = ResourceAcquireSpec(
            "rk_bad_own", ConcurrencyMode.SERIALIZE, "eq", ExecutionPriority.FOREGROUND, "t2", ((ws_q, TaskId("alpha.t")), (ws_q, TaskId("alpha.t2"))), cancel_token=tok_c, timeout_ms=800, call_tree_id="ct_bad"
        )
        out_s2 = coord.execute(spec_l2, lambda _p, _c, _fl: "ok2").outcome
        _check(out_s2 == "ok2")
    finally:
        rel_th.join(timeout=2.0)
        held_lock.release()


def _verify_daemon_stray_module_files_quiesce(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_q = HostPath(ws8.path / "ws_quiesce_stray_dmn")
    provision_live_workspace(ws_q.path)
    rig = build_dispatcher_for_workspace(ws_q, venv_bin, is_daemon_host=True)
    disp_q, cfg_q = rig.dispatcher, rig.config_view
    wcfg = DaemonWatcherConfig(watcher_debounce_sec=0.05)
    dmn = WorkspaceDaemon(workspace_root=ws_q, cache_dir=ws_q.join(".cache"), dispatcher=disp_q, config_view=cfg_q, watch_config=wcfg)
    ready_ev = threading.Event()
    th = threading.Thread(target=dmn.run_forever, kwargs={"ttl_override_sec": 20.0, "ready_callback": ready_ev.set}, daemon=True)
    try:
        th.start()
        _check(ready_ev.wait(timeout=6.0))
        bad_q = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_QUIESCE, {"modules": ["../bad"]})
        bad_r = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_RELOAD, {"modules": ["../bad"]})
        _check(bad_q is not None and bad_q.get("ok") is False and bad_r is not None and bad_r.get("ok") is False)
        q_ack = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_QUIESCE, {"modules": ["alpha"], "lease_sec": 10.0})
        _check(q_ack is not None and q_ack.get("ok") is True)
        (ws_q.path / ".modules" / ".DS_Store").write_bytes(b"stray")
        (ws_q.path / ".modules" / "manifest.json").write_text("{}", encoding="utf-8")
        time.sleep(0.18)
        r_ack = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_RESUME, {})
        _check(r_ack is not None and r_ack.get("ok") is True and r_ack.get("state") == "ready")
    finally:
        dmn.request_shutdown()
        th.join(timeout=4.0)
        disp_q.shutdown(grace_ms=100)


def _provision_dynamic_backup_and_nonfatal_mod(ws_dir: Path) -> None:
    md = ws_dir / ".modules" / "dorp"
    md.mkdir(parents=True, exist_ok=True)
    (md / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport time\nfrom typing import Optional, Sequence\n"
        "from core.execution.event import EventMetadata, EventSubscriptionSpec\n"
        "from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\n"
        "from core.filesystem.fs import atomic_write_json, read_json_dict\n"
        "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass DIn:\n    tag: str = ''\n    role: str = ''\n"
        "@dataclass(frozen=True, slots=True)\nclass DOut:\n    ok_tag: str = 'ok'\n"
        "EV_DH1 = EventMetadata(EventId('dorp.ev_dh1'), DIn)\nEV_DH2 = EventMetadata(EventId('dorp.ev_dh2'), DIn)\n"
        "EV_WC = EventMetadata(EventId('dorp.ev_wc'), DIn)\nEV_ONCE = EventMetadata(EventId('dorp.ev_once'), DIn)\n"
        "def _md(items: Sequence[DIn]) -> Optional[DIn]: return items[-1] if items else DIn()\n"
        "def _wg(ctx: TaskContext, gn: str) -> None:\n"
        "    gp = ctx.workspace_root.join('.cache', gn).path\n    dl = time.monotonic() + 5.0\n"
        "    while not gp.is_file() and time.monotonic() < dl:\n        ctx.cancel_token.raise_if_cancelled()\n        time.sleep(0.01)\n"
        "def _inc(ctx: TaskContext, fn: str) -> None:\n"
        "    p = ctx.workspace_root.join('.cache', fn)\n    prev = (read_json_dict(p) or {}).get('count', 0)\n"
        "    cnt = (prev if isinstance(prev, int) else 0) + 1\n    atomic_write_json(p, {'count': cnt})\n"
        "class CHop1T(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]:\n"
        "        return TaskMetadata(TaskId('dorp.c_hop1'), DIn, DOut, resource_key='rk_dh1', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.tag)\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'dh1_in.json'), {'ok': True})\n        _wg(ctx, 'dh1_go.json')\n"
        "        ctx.emit(EV_DH1, DIn(tag=req.tag))\n        return DOut('h1')\n"
        "class CHop2T(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]:\n"
        "        return TaskMetadata(TaskId('dorp.c_hop2'), DIn, DOut, resource_key='rk_dh2', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.tag)\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'dh2_in.json'), {'ok': True})\n        _wg(ctx, 'dh2_go.json')\n"
        "        ctx.emit(EV_DH2, DIn(tag=req.tag))\n        return DOut('h2')\n"
        "class WCycT(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]: return TaskMetadata(TaskId('dorp.w_cyc'), DIn, DOut)\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n"
        "        ctx.emit(EV_WC, DIn())\n        ctx.invoke_task(TaskId(req.role), {'tag': req.tag})\n        return DOut('wc')\n"
        "class DLoopT(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]: return TaskMetadata(TaskId('dorp.d_loop'), DIn, DOut)\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n        ctx.invoke_task(TaskId('dorp.d_loop'), {})\n        return DOut()\n"
        "class WCSubT(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]:\n"
        "        return TaskMetadata(TaskId('dorp.wc_sub'), DIn, DOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('dorp.ev_wc'), _md),))\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n        ctx.invoke_task(TaskId('dorp.d_loop'), {})\n        return DOut()\n"
        "class BParT(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]: return TaskMetadata(TaskId('dorp.b_par'), DIn, DOut)\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n"
        "        ctx.invoke_task(TaskId(req.role), {'tag': req.tag})\n"
        "        if req.tag == 'sole_biz': raise RuntimeError('sole_backup_biz_fail')\n        return DOut('bp')\n"
        "class SubDh1T(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]:\n"
        "        return TaskMetadata(TaskId('dorp.sub_dh1'), DIn, DOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('dorp.ev_dh1'), _md),))\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'sub_dh1_in.json'), {'ok': True})\n"
        "        _wg(ctx, 'dh2_ready_for_b.json')\n        ctx.invoke_task(TaskId('dorp.c_hop2'), {'tag': req.tag})\n        return DOut()\n"
        "class SubDh2T(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]:\n"
        "        return TaskMetadata(TaskId('dorp.sub_dh2'), DIn, DOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('dorp.ev_dh2'), _md),))\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n        _inc(ctx, 'dh2_count.json')\n        return DOut()\n"
        "class COnceT(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]:\n"
        "        return TaskMetadata(TaskId('dorp.c_once'), DIn, DOut, resource_key='rk_once', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.tag)\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', f'once_in_{req.tag}.json'), {'ok': True})\n"
        "        _wg(ctx, f'once_go_{req.tag}.json')\n        ctx.emit(EV_ONCE, DIn(tag=req.tag))\n        return DOut('once')\n"
        "class FOnceT(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]: return TaskMetadata(TaskId('dorp.f_once'), DIn, DOut)\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n"
        "        ctx.invoke_task(TaskId('dorp.c_once'), {'tag': req.tag})\n"
        "        if req.role == 'biz': raise RuntimeError('nonfatal_biz_after_child')\n"
        "        fp = ctx.workspace_root.join('.cache', f'first_post_{req.tag}.json')\n"
        "        if not fp.path.is_file(): atomic_write_json(fp, {'role': req.role})\n"
        "        _wg(ctx, f'post_go_{req.tag}_{req.role}.json')\n        return DOut('fo')\n"
        "class SubOnceT(Task[DIn, DOut]):\n    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]:\n"
        "        return TaskMetadata(TaskId('dorp.sub_once'), DIn, DOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('dorp.ev_once'), _md),))\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n        _inc(ctx, f'once_cnt_{req.tag}.json')\n        return DOut()\n"
        "class DMod(YscbModule):\n    @property\n    def module_id(self) -> ModuleId: return ModuleId('dorp')\n"
        "    def tasks(self) -> Sequence[BoundTask]:\n"
        "        return (CHop1T(), CHop2T(), WCycT(), DLoopT(), WCSubT(), BParT(), SubDh1T(), SubDh2T(), COnceT(), FOnceT(), SubOnceT())\n"
        "def create_module() -> YscbModule: return DMod()\n",
        encoding="utf-8",
    )


def _write_dorp_routes(ws_dir: Path) -> None:
    md = ws_dir / ".modules" / "dorp"
    atomic_write_json(
        HostPath(md / "routes.json"),
        {
            "module_id": "dorp",
            "tier1": False,
            "tasks": [
                {"task_id": "dorp.c_hop1", "resource_key": "rk_dh1", "concurrency_mode": "coalesce"},
                {"task_id": "dorp.c_hop2", "resource_key": "rk_dh2", "concurrency_mode": "coalesce"},
                {"task_id": "dorp.w_cyc"},
                {"task_id": "dorp.d_loop"},
                {"task_id": "dorp.wc_sub", "exposure": "internal_trigger", "subscriptions": [{"event_id": "dorp.ev_wc"}]},
                {"task_id": "dorp.b_par"},
                {"task_id": "dorp.sub_dh1", "exposure": "internal_trigger", "subscriptions": [{"event_id": "dorp.ev_dh1"}]},
                {"task_id": "dorp.sub_dh2", "exposure": "internal_trigger", "subscriptions": [{"event_id": "dorp.ev_dh2"}]},
                {"task_id": "dorp.c_once", "resource_key": "rk_once", "concurrency_mode": "coalesce"},
                {"task_id": "dorp.f_once"},
                {"task_id": "dorp.sub_once", "exposure": "internal_trigger", "subscriptions": [{"event_id": "dorp.ev_once"}]},
            ],
        },
    )


def _invoke_with_post_wake_delay(
    disp: RuntimeDispatcher,
    req: InvokeRequest,
    delay_gate: threading.Event,
    cancel_token: Optional[CancellationToken] = None,
) -> TaskOutcome[JsonValue]:
    tid_self = threading.get_ident()
    prev_trace = sys.gettrace()

    def _trace_delay(frame: object, event: str, arg: object) -> object:
        if event == "line" and threading.get_ident() == tid_self and delay_gate.is_set():
            delay_gate.clear()
            time.sleep(0.06)
        if prev_trace is not None:
            prev_trace(frame, event, arg)
        return _trace_delay

    sys.settrace(_trace_delay)
    try:
        return disp.invoke(req, cancel_token=cancel_token)
    finally:
        sys.settrace(prev_trace)


def _verify_multihop_dynamic_backup_and_nonfatal_winner_drain(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_d = HostPath(ws8.path / "ws_dyn_bkp")
    provision_live_workspace(ws_d.path)
    _provision_dynamic_backup_and_nonfatal_mod(ws_d.path)
    _write_dorp_routes(ws_d.path)
    disp_d = build_dispatcher_for_workspace(ws_d, venv_bin, is_daemon_host=True).dispatcher
    try:
        disp_d.warmup_daemon_container()
        _run_dynamic_two_hop_backup_case(ws_d, disp_d)
        _run_nonfatal_winner_and_sole_backup_cases(ws_d, disp_d)
        _run_sole_backup_nonfatal_parent_case(ws_d, disp_d)
    finally:
        disp_d.shutdown(grace_ms=100)


def _run_dynamic_two_hop_backup_case(ws_d: HostPath, disp_d: RuntimeDispatcher) -> None:
    tok_s1, tok_s2 = CancellationToken(), CancellationToken()
    gate_b = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
        fs1 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.c_hop1"), {"tag": "t"}, ws_d, ws_d, propagation=CallPropagationContext(call_stack=((ws_d, TaskId("ext.s1")),))), cancel_token=tok_s1)
        _wait_file_marker(ws_d.path / ".cache" / "dh1_in.json")
        fw1 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.w_cyc"), {"tag": "t", "role": "dorp.c_hop1"}, ws_d, ws_d))
        fb = pool.submit(_invoke_with_post_wake_delay, disp_d, InvokeRequest(TaskId("dorp.b_par"), {"tag": "t", "role": "dorp.c_hop1"}, ws_d, ws_d), gate_b)
        _wait_coalesce_count(disp_d, "rk_dh1", 3)
        gate_b.set()
        tok_s1.cancel()
        atomic_write_json(ws_d.join(".cache", "dh1_go.json"), {"go": True})
        _wait_file_marker(ws_d.path / ".cache" / "sub_dh1_in.json")

        fs2 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.c_hop2"), {"tag": "t"}, ws_d, ws_d, propagation=CallPropagationContext(call_stack=((ws_d, TaskId("ext.s2")),))), cancel_token=tok_s2)
        _wait_file_marker(ws_d.path / ".cache" / "dh2_in.json")
        fw2 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.w_cyc"), {"tag": "t", "role": "dorp.c_hop2"}, ws_d, ws_d))
        atomic_write_json(ws_d.join(".cache", "dh2_ready_for_b.json"), {"go": True})
        _wait_coalesce_count(disp_d, "rk_dh2", 3)
        gate_b.set()
        tok_s2.cancel()
        atomic_write_json(ws_d.join(".cache", "dh2_go.json"), {"go": True})
        rs1, rs2 = fs1.result(timeout=5.0), fs2.result(timeout=5.0)
        rw1, rw2, rb = fw1.result(timeout=5.0), fw2.result(timeout=5.0), fb.result(timeout=5.0)
    _check(not rs1.ok and rs1.error is not None and rs1.error.code == ErrorCode.TASK_CANCELLED)
    _check(not rs2.ok and rs2.error is not None and rs2.error.code == ErrorCode.TASK_CANCELLED)
    _check(not rw1.ok and not rw2.ok and rb.ok)
    _check(read_json_dict(ws_d.join(".cache", "dh2_count.json")) == {"count": 1})


def _run_nonfatal_winner_and_sole_backup_cases(ws_d: HostPath, disp_d: RuntimeDispatcher) -> None:
    tok_sb = CancellationToken()
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
        fsb = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.c_once"), {"tag": "bz"}, ws_d, ws_d, propagation=CallPropagationContext(call_stack=((ws_d, TaskId("ext.sb")),))), cancel_token=tok_sb)
        _wait_file_marker(ws_d.path / ".cache" / "once_in_bz.json")
        ff1 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.f_once"), {"tag": "bz", "role": "biz"}, ws_d, ws_d))
        ff2 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.f_once"), {"tag": "bz", "role": "biz"}, ws_d, ws_d))
        _wait_coalesce_count(disp_d, "rk_once", 3)
        tok_sb.cancel()
        atomic_write_json(ws_d.join(".cache", "once_go_bz.json"), {"go": True})
        rsb, rf1, rf2 = fsb.result(timeout=5.0), ff1.result(timeout=5.0), ff2.result(timeout=5.0)
    _check(not rsb.ok and rsb.error is not None and rsb.error.code == ErrorCode.TASK_CANCELLED)
    _check(not rf1.ok and not rf2.ok and read_json_dict(ws_d.join(".cache", "once_cnt_bz.json")) == {"count": 1})

    tok_sc, tok_c1, tok_c2 = CancellationToken(), CancellationToken(), CancellationToken()
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
        fsc = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.c_once"), {"tag": "cn"}, ws_d, ws_d, propagation=CallPropagationContext(call_stack=((ws_d, TaskId("ext.sc")),))), cancel_token=tok_sc)
        _wait_file_marker(ws_d.path / ".cache" / "once_in_cn.json")
        fc1 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.f_once"), {"tag": "cn", "role": "r1"}, ws_d, ws_d), cancel_token=tok_c1)
        fc2 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.f_once"), {"tag": "cn", "role": "r2"}, ws_d, ws_d), cancel_token=tok_c2)
        _wait_coalesce_count(disp_d, "rk_once", 3)
        tok_sc.cancel()
        atomic_write_json(ws_d.join(".cache", "once_go_cn.json"), {"go": True})
        _wait_file_marker(ws_d.path / ".cache" / "first_post_cn.json")
        first_role = str((read_json_dict(ws_d.join(".cache", "first_post_cn.json")) or {}).get("role", "r1"))
        (tok_c1 if first_role == "r1" else tok_c2).cancel()
        other_role = "r2" if first_role == "r1" else "r1"
        time.sleep(0.05)
        atomic_write_json(ws_d.join(".cache", f"post_go_cn_{other_role}.json"), {"go": True})
        rsc, rc1, rc2 = fsc.result(timeout=5.0), fc1.result(timeout=5.0), fc2.result(timeout=5.0)
    _check(not rsc.ok and rsc.error is not None and rsc.error.code == ErrorCode.TASK_CANCELLED)
    _check((rc1.ok != rc2.ok) and read_json_dict(ws_d.join(".cache", "once_cnt_cn.json")) == {"count": 1})


def _run_sole_backup_nonfatal_parent_case(ws_d: HostPath, disp_d: RuntimeDispatcher) -> None:
    tok_ss = CancellationToken()
    gate_sole = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
        fss = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.c_once"), {"tag": "sole_biz"}, ws_d, ws_d, propagation=CallPropagationContext(call_stack=((ws_d, TaskId("ext.ss")),))), cancel_token=tok_ss)
        _wait_file_marker(ws_d.path / ".cache" / "once_in_sole_biz.json")
        fws = pool.submit(disp_d.invoke, InvokeRequest(TaskId("dorp.w_cyc"), {"tag": "sole_biz", "role": "dorp.c_once"}, ws_d, ws_d))
        fbs = pool.submit(_invoke_with_post_wake_delay, disp_d, InvokeRequest(TaskId("dorp.b_par"), {"tag": "sole_biz", "role": "dorp.c_once"}, ws_d, ws_d), gate_sole)
        _wait_coalesce_count(disp_d, "rk_once", 3)
        gate_sole.set()
        tok_ss.cancel()
        atomic_write_json(ws_d.join(".cache", "once_go_sole_biz.json"), {"go": True})
        rss, rws, rbs = fss.result(timeout=5.0), fws.result(timeout=5.0), fbs.result(timeout=5.0)
    _check(not rss.ok and rss.error is not None and rss.error.code == ErrorCode.TASK_CANCELLED)
    _check(not rws.ok and rws.error is not None and rws.error.code == ErrorCode.CALL_CYCLE_DETECTED)
    _check(not rbs.ok and rbs.error is not None and rbs.error.code == ErrorCode.BUSINESS_FAILURE)
    _check(read_json_dict(ws_d.join(".cache", "once_cnt_sole_biz.json")) == {"count": 1})


def _verify_rpc_stream_parity_falsy_payload_and_finite_clamps(ws8: HostPath) -> None:
    nan_file = ws8.join(".cache_nan", "daemon", "handoff_lease.json")
    nan_file.path.parent.mkdir(parents=True, exist_ok=True)
    nan_file.path.write_text('{"old_boot_id": "b", "expires_epoch": NaN}', encoding="utf-8")
    _check(read_json_dict(nan_file) is None)

    for bad_frame in (
        b'{"stream_id":777,"kind":"hello","payload":{"protocol":2,"auth_token":"t","boot_id":"b","workspace_root":"' + str(ws8).encode("utf-8") + b'"}}',
        b'{"stream_id":0,"kind":"hello","payload":{"protocol":2,"auth_token":"t","boot_id":"SPOOF","workspace_root":"' + str(ws8).encode("utf-8") + b'"}}',
        b'{"stream_id":0,"kind":"hello","payload":{"protocol":2,"auth_token":"t","boot_id":"b","workspace_root":"/spoofed/other"}}',
        b'{"stream_id":0,"kind":"hello","payload":[]}',
        b'{"stream_id":0,"kind":"hello","payload":{"protocol":2,"auth_token":"t","boot_id":"b","workspace_root":"' + str(ws8).encode("utf-8") + b'","x":Infinity}}',
    ):
        a_s, b_s = socket.socketpair()
        try:
            a_s.sendall(struct.pack(">I", len(bad_frame)) + bad_frame)
            a_s.close()
            _check(accept_worker_handshake(
                    b_s, expected_auth_token="t", boot_id="b", handler=_NoopInboundRpcHandler(), expected_workspace_root=ws8
                )
                is None)
        finally:
            _close_socket_pair_quietly(a_s, b_s)


def _verify_listener_stream_parity_and_quiesce_inf_clamps(ws8: HostPath, venv_bin: HostPath) -> None:
    listener = RpcServerListener(ws8, _NoopInboundRpcHandler())
    ep = listener.start()
    try:
        c1 = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            c1.settimeout(1.5)
            c1.connect((ep.host, ep.port))
            bad_h = json.dumps({"stream_id": 999, "kind": "hello", "payload": {"protocol": 2, "auth_token": ep.auth_token, "boot_id": ep.boot_id, "workspace_root": str(ws8)}}).encode("utf-8")
            c1.sendall(struct.pack(">I", len(bad_h)) + bad_h)
            _check(c1.recv(16) == b"")
        finally:
            c1.close()

        c2 = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            c2.settimeout(1.5)
            c2.connect((ep.host, ep.port))
            ok_h = json.dumps({"stream_id": 0, "kind": "hello", "payload": {"protocol": 2, "auth_token": ep.auth_token, "boot_id": ep.boot_id, "workspace_root": str(ws8)}}).encode("utf-8")
            c2.sendall(struct.pack(">I", len(ok_h)) + ok_h)
            ack_len = struct.unpack(">I", c2.recv(4))[0]
            _ = c2.recv(ack_len)
            even_call = json.dumps({"stream_id": 2, "kind": "call_start", "payload": {}}).encode("utf-8")
            c2.sendall(struct.pack(">I", len(even_call)) + even_call)
            _check(c2.recv(16) == b"")
        finally:
            c2.close()
    finally:
        listener.close_all()

    ws_inf = HostPath(ws8.path / "ws_inf_clamp")
    provision_live_workspace(ws_inf.path)
    atomic_write_json(ws_inf.join("config", "alpha.json"), {"periodic_enabled": True, "periodic_interval": 1e20})
    rig = build_dispatcher_for_workspace(ws_inf, venv_bin, is_daemon_host=True)
    disp_i, cfg_i = rig.dispatcher, rig.config_view
    dmn_i = WorkspaceDaemon(workspace_root=ws_inf, cache_dir=ws_inf.join(".cache"), dispatcher=disp_i, config_view=cfg_i)
    ready_i = threading.Event()
    th_i = threading.Thread(target=dmn_i.run_forever, kwargs={"ttl_override_sec": 20.0, "ready_callback": ready_i.set}, daemon=True)
    try:
        th_i.start()
        _check(ready_i.wait(timeout=6.0))
        for bad_q in (True, -1.0, 0.0, float("nan"), float("inf")):
            caught_q = False
            try:
                _ = dmn_i.quiesce(frozenset({ModuleId("alpha")}), lease_sec=bad_q)
            except ValueError:
                caught_q = True
            _check(caught_q)
        _check(dmn_i.quiesce(frozenset({ModuleId("alpha")}), lease_sec=1e20, drain_timeout_sec=1e20))
        dmn_i.resume_from_quiesce()
    finally:
        dmn_i.request_shutdown()
        th_i.join(timeout=4.0)
        disp_i.shutdown(grace_ms=100)


def _provision_two_hop_and_bidir_mod(ws_dir: Path) -> None:
    mt = ws_dir / ".modules" / "tbp"
    mt.mkdir(parents=True, exist_ok=True)
    (mt / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport time\nfrom typing import Optional, Sequence\n"
        "from core.execution.event import EventMetadata, EventSubscriptionSpec\n"
        "from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\n"
        "from core.filesystem.fs import atomic_write_json, read_json_dict\n"
        "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass TIn:\n    tag: str = ''\n    mode: str = ''\n"
        "@dataclass(frozen=True, slots=True)\nclass TOut:\n    ok_tag: str = 'ok'\n"
        "EV_ANC = EventMetadata(EventId('tbp.ev_anc'), TIn)\nEV_H1 = EventMetadata(EventId('tbp.ev_h1'), TIn)\n"
        "EV_H2 = EventMetadata(EventId('tbp.ev_h2'), TIn)\nEV_WP = EventMetadata(EventId('tbp.ev_wp'), TIn)\n"
        "def _mt(items: Sequence[TIn]) -> Optional[TIn]: return items[-1] if items else TIn()\n"
        "def _wt(ctx: TaskContext, gn: str) -> None:\n"
        "    gp = ctx.workspace_root.join('.cache', gn).path\n    dl = time.monotonic() + 5.0\n"
        "    while not gp.is_file() and time.monotonic() < dl:\n        ctx.cancel_token.raise_if_cancelled()\n        time.sleep(0.01)\n"
        "class AEntryT(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]: return TaskMetadata(TaskId('tbp.a_entry'), TIn, TOut)\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n        ctx.emit_imm(EV_ANC, TIn(tag=req.tag, mode='start'))\n        return TOut('a')\n"
        "class SubAncT(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]:\n"
        "        return TaskMetadata(TaskId('tbp.sub_anc'), TIn, TOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('tbp.ev_anc'), _mt),))\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n"
        "        if req.mode == 'start': ctx.invoke_task(TaskId('tbp.hop1'), {'tag': req.tag, 'mode': 'fol'})\n        return TOut()\n"
        "class Hop1T(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]:\n"
        "        return TaskMetadata(TaskId('tbp.hop1'), TIn, TOut, resource_key='rk_tbp1', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.tag)\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', f'h1_in_{req.tag}.json'), {'ok': True})\n"
        "        _wt(ctx, f'h1_go_{req.tag}.json')\n        ctx.emit(EV_H1, TIn(tag=req.tag, mode=req.mode))\n        return TOut('h1')\n"
        "class SubH1T(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]:\n"
        "        return TaskMetadata(TaskId('tbp.sub_h1'), TIn, TOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('tbp.ev_h1'), _mt),))\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n"
        "        ctx.invoke_task(TaskId('tbp.hop2'), {'tag': req.tag, 'mode': req.mode})\n"
        "        if req.mode == 'b_cancel':\n            atomic_write_json(ctx.workspace_root.join('.cache', f'b_sub_done_{req.tag}.json'), {'ok': True})\n            _wt(ctx, f'b_exit_go_{req.tag}.json')\n"
        "        return TOut()\n"
        "class Hop2T(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]:\n"
        "        return TaskMetadata(TaskId('tbp.hop2'), TIn, TOut, resource_key='rk_tbp2', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.tag)\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', f'h2_in_{req.tag}.json'), {'ok': True})\n"
        "        _wt(ctx, f'h2_go_{req.tag}.json')\n        ctx.emit(EV_H2, TIn(tag=req.tag, mode=req.mode))\n        return TOut('h2')\n"
        "class WPrivT(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]: return TaskMetadata(TaskId('tbp.w_priv'), TIn, TOut)\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n        ctx.emit(EV_WP, TIn())\n        ctx.invoke_task(TaskId('tbp.hop2'), {'tag': req.tag})\n        return TOut('wp')\n"
        "class SubWpT(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]:\n"
        "        return TaskMetadata(TaskId('tbp.sub_wp'), TIn, TOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('tbp.ev_wp'), _mt),))\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n        ctx.emit(EV_WP, TIn())\n        return TOut()\n"
        "class SubH2DiagT(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]:\n"
        "        return TaskMetadata(TaskId('tbp.sub_h2_diag'), TIn, TOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('tbp.ev_h2'), _mt),))\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n"
        "        p = ctx.workspace_root.join('.cache', f'h2_cnt_{req.tag}.json')\n        prev = (read_json_dict(p) or {}).get('count', 0)\n"
        "        atomic_write_json(p, {'count': (prev if isinstance(prev, int) else 0) + 1})\n"
        "        if req.mode != 'acyc': raise RuntimeError('c_diag')\n        return TOut()\n"
        "class SubH2CycT(Task[TIn, TOut]):\n    @property\n    def metadata(self) -> TaskMetadata[TIn, TOut]:\n"
        "        return TaskMetadata(TaskId('tbp.sub_h2_cyc'), TIn, TOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('tbp.ev_h2'), _mt),))\n"
        "    def run(self, req: TIn, ctx: TaskContext) -> TOut:\n"
        "        if req.mode != 'acyc': ctx.emit(EV_ANC, TIn(tag=req.tag, mode='done'))\n        return TOut()\n"
        "class TMod(YscbModule):\n    @property\n    def module_id(self) -> ModuleId: return ModuleId('tbp')\n"
        "    def tasks(self) -> Sequence[BoundTask]:\n"
        "        return (AEntryT(), SubAncT(), Hop1T(), SubH1T(), Hop2T(), WPrivT(), SubWpT(), SubH2DiagT(), SubH2CycT())\n"
        "def create_module() -> YscbModule: return TMod()\n",
        encoding="utf-8",
    )


def _write_tbp_routes(ws_dir: Path) -> None:
    mt = ws_dir / ".modules" / "tbp"
    atomic_write_json(
        HostPath(mt / "routes.json"),
        {
            "module_id": "tbp",
            "tier1": False,
            "tasks": [
                {"task_id": "tbp.a_entry"},
                {"task_id": "tbp.sub_anc", "exposure": "internal_trigger", "subscriptions": [{"event_id": "tbp.ev_anc"}]},
                {"task_id": "tbp.hop1", "resource_key": "rk_tbp1", "concurrency_mode": "coalesce"},
                {"task_id": "tbp.sub_h1", "exposure": "internal_trigger", "subscriptions": [{"event_id": "tbp.ev_h1"}]},
                {"task_id": "tbp.hop2", "resource_key": "rk_tbp2", "concurrency_mode": "coalesce"},
                {"task_id": "tbp.w_priv"},
                {"task_id": "tbp.sub_wp", "exposure": "internal_trigger", "subscriptions": [{"event_id": "tbp.ev_wp"}]},
                {"task_id": "tbp.sub_h2_diag", "exposure": "internal_trigger", "subscriptions": [{"event_id": "tbp.ev_h2"}]},
                {"task_id": "tbp.sub_h2_cyc", "exposure": "internal_trigger", "subscriptions": [{"event_id": "tbp.ev_h2"}]},
            ],
        },
    )


def _verify_two_hop_backup_edge_expansion_and_survivor_cancel(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_t = HostPath(ws8.path / "ws_two_hop_bkp")
    provision_live_workspace(ws_t.path)
    _provision_two_hop_and_bidir_mod(ws_t.path)
    _write_tbp_routes(ws_t.path)
    disp_t = build_dispatcher_for_workspace(ws_t, venv_bin, is_daemon_host=True).dispatcher
    try:
        disp_t.warmup_daemon_container()
        for cancel_b, tag in ((True, "cb"), (False, "nb")):
            _run_single_two_hop_backup_probe(ws_t, disp_t, tag, cancel_b=cancel_b)
        _run_survivor_cancelled_host_backup_drain_probe(ws_t, disp_t)
    finally:
        disp_t.shutdown(grace_ms=100)


def _run_single_two_hop_backup_probe(
    ws_t: HostPath,
    disp_t: RuntimeDispatcher,
    tag: str,
    *,
    cancel_b: bool,
) -> None:
    tok_b, tok_s2 = CancellationToken(), CancellationToken()
    gate_c = threading.Event()
    b_mode = "b_cancel" if cancel_b else "norm"
    with concurrent.futures.ThreadPoolExecutor(max_workers=5) as pool:
        fb = pool.submit(disp_t.invoke, InvokeRequest(TaskId("tbp.hop1"), {"tag": tag, "mode": b_mode}, ws_t, ws_t), cancel_token=tok_b)
        _wait_file_marker(ws_t.path / ".cache" / f"h1_in_{tag}.json")
        fa = pool.submit(disp_t.invoke, InvokeRequest(TaskId("tbp.a_entry"), {"tag": tag}, ws_t, ws_t))
        _wait_coalesce_count(disp_t, "rk_tbp1", 2)

        fs2 = pool.submit(disp_t.invoke, InvokeRequest(TaskId("tbp.hop2"), {"tag": tag, "mode": "cyc"}, ws_t, ws_t, propagation=CallPropagationContext(call_stack=((ws_t, TaskId("ext.s2")),))), cancel_token=tok_s2)
        _wait_file_marker(ws_t.path / ".cache" / f"h2_in_{tag}.json")
        fw1 = pool.submit(disp_t.invoke, InvokeRequest(TaskId("tbp.w_priv"), {"tag": tag}, ws_t, ws_t))
        fc = pool.submit(_invoke_with_post_wake_delay, disp_t, InvokeRequest(TaskId("tbp.hop2"), {"tag": tag, "mode": "cyc"}, ws_t, ws_t, propagation=CallPropagationContext(call_stack=((ws_t, TaskId("ext.c")),))), gate_c)
        atomic_write_json(ws_t.join(".cache", f"h1_go_{tag}.json"), {"go": True})
        _wait_coalesce_count(disp_t, "rk_tbp2", 4)
        gate_c.set()
        tok_s2.cancel()
        atomic_write_json(ws_t.join(".cache", f"h2_go_{tag}.json"), {"go": True})
        if cancel_b:
            _wait_file_marker(ws_t.path / ".cache" / f"b_sub_done_{tag}.json")
            tok_b.cancel()
            atomic_write_json(ws_t.join(".cache", f"b_exit_go_{tag}.json"), {"go": True})
        rs2, rw1, rc = fs2.result(timeout=5.0), fw1.result(timeout=5.0), fc.result(timeout=5.0)
        rb, ra = fb.result(timeout=5.0), fa.result(timeout=5.0)
    _check(not rs2.ok and rs2.error is not None and rs2.error.code == ErrorCode.TASK_CANCELLED)
    _check(not rw1.ok and rw1.error is not None and rw1.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
    _check(rc.ok and len(rc.event_diagnostics) == 1)
    _check((not rb.ok and rb.error is not None and rb.error.code == ErrorCode.TASK_CANCELLED) if cancel_b else rb.ok)
    _check(not ra.ok and ra.error is not None and ra.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
    _check(len(ra.event_diagnostics) == 1)


def _run_survivor_cancelled_host_backup_drain_probe(ws_t: HostPath, disp_t: RuntimeDispatcher) -> None:
    tok_b, tok_s2 = CancellationToken(), CancellationToken()
    gate_b = threading.Event()
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
        fb = pool.submit(
            _invoke_with_post_wake_delay,
            disp_t,
            InvokeRequest(TaskId("tbp.hop1"), {"tag": "sv", "mode": "b_cancel"}, ws_t, ws_t, propagation=CallPropagationContext(call_stack=((ws_t, TaskId("ext.b_sv")),))),
            gate_b,
            tok_b,
        )
        _wait_file_marker(ws_t.path / ".cache" / "h1_in_sv.json")
        fa = pool.submit(
            disp_t.invoke,
            InvokeRequest(TaskId("tbp.hop1"), {"tag": "sv", "mode": "acyc"}, ws_t, ws_t, propagation=CallPropagationContext(call_stack=((ws_t, TaskId("ext.a_sv")),))),
        )
        _wait_coalesce_count(disp_t, "rk_tbp1", 2)

        fs2 = pool.submit(disp_t.invoke, InvokeRequest(TaskId("tbp.hop2"), {"tag": "sv", "mode": "acyc"}, ws_t, ws_t, propagation=CallPropagationContext(call_stack=((ws_t, TaskId("ext.sv2")),))), cancel_token=tok_s2)
        _wait_file_marker(ws_t.path / ".cache" / "h2_in_sv.json")
        fw1 = pool.submit(disp_t.invoke, InvokeRequest(TaskId("tbp.w_priv"), {"tag": "sv"}, ws_t, ws_t))
        atomic_write_json(ws_t.join(".cache", "h1_go_sv.json"), {"go": True})
        _wait_coalesce_count(disp_t, "rk_tbp2", 3)
        gate_b.set()
        tok_s2.cancel()
        atomic_write_json(ws_t.join(".cache", "h2_go_sv.json"), {"go": True})
        _wait_file_marker(ws_t.path / ".cache" / "b_sub_done_sv.json")
        tok_b.cancel()
        atomic_write_json(ws_t.join(".cache", "b_exit_go_sv.json"), {"go": True})
        rs2, rw1, rb, ra = fs2.result(timeout=5.0), fw1.result(timeout=5.0), fb.result(timeout=5.0), fa.result(timeout=5.0)
    _check(not rs2.ok and rs2.error is not None and rs2.error.code == ErrorCode.TASK_CANCELLED)
    _check(not rw1.ok and not rb.ok and rb.error is not None and rb.error.code == ErrorCode.TASK_CANCELLED)
    _check(ra.ok and read_json_dict(ws_t.join(".cache", "h2_cnt_sv.json")) == {"count": 1})


def _verify_bidirectional_coalesce_fixed_point_and_tier0_lazy_fault(ws8: HostPath, venv_bin: HostPath) -> None:
    e1, e2 = EventId("bi.e1"), EventId("bi.e2")
    for reverse_t1 in (False, True):
        c1 = FlightCascade()
        c2 = FlightCascade(imm_hops=(EmittedEventHop("", e2, "bi.t2"),))
        c3 = FlightCascade(imm_hops=(EmittedEventHop("", e1, "bi.t3"),))
        c4 = FlightCascade(imm_hops=(EmittedEventHop("", e1, "bi.t4"),))
        c2.add_child_join((), c3)
        c2.add_child_join((EmittedEventHop("", e2, "bi.t2"),), c4)
        c3.add_child_join((EmittedEventHop("", e1, "bi.t3"),), c2)
        first_c, second_c = (c3, c2) if reverse_t1 else (c2, c3)
        c1.add_child_join((), first_c)
        c1.add_child_join((), second_c)
        out_c2 = c2.collect_outcomes(-1, CausalLineage())
        out_c1 = c1.collect_outcomes(-1, CausalLineage())
        _check(out_c2.fatal_error is not None and out_c2.fatal_error.code == ErrorCode.EVENT_CYCLE_DETECTED)
        _check(out_c1.fatal_error is not None and out_c1.fatal_error.code == ErrorCode.EVENT_CYCLE_DETECTED)

    ws_bt0 = HostPath(ws8.path / "ws_broken_t0_lazy")
    provision_live_workspace(ws_bt0.path)
    mb = ws_bt0.path / ".modules" / "badt0"
    mb.mkdir(parents=True, exist_ok=True)
    (mb / "module_entry.py").write_text("raise RuntimeError('lazy_t0_boom')\n", encoding="utf-8")
    atomic_write_json(
        HostPath(mb / "routes.json"),
        {
            "module_id": "badt0",
            "tier1": False,
            "eager_warmup": False,
            "tasks": [
                {"task_id": "badt0.par", "concurrency_mode": "parallel"},
                {"task_id": "badt0.ser", "resource_key": "rk_bt0", "concurrency_mode": "serialize"},
                {"task_id": "badt0.coa", "resource_key": "rk_bt0c", "concurrency_mode": "coalesce"},
            ],
        },
    )
    disp_b = build_dispatcher_for_workspace(ws_bt0, venv_bin, is_daemon_host=True).dispatcher
    try:
        disp_b.warmup_daemon_container()
        for tid_s in ("badt0.par", "badt0.ser", "badt0.coa"):
            out_b = disp_b.invoke(InvokeRequest(TaskId(tid_s), {}, ws_bt0, ws_bt0))
            _check(not out_b.ok and out_b.error is not None)
    finally:
        disp_b.shutdown(grace_ms=100)


def _verify_rpc_dup_stream_monotonic_accept_and_ctrl_bounds() -> None:
    for _ in range(15):
        s_a, s_b = socket.socketpair()
        ch_srv = MultiplexedChannel(s_b, is_initiator=False, handler=_NoopInboundRpcHandler())
        try:
            raw_cs = json.dumps({"stream_id": 1, "kind": "call_start", "payload": {}}).encode("utf-8")
            pkt = struct.pack(">I", len(raw_cs)) + raw_cs
            t_close = threading.Thread(target=ch_srv.close, daemon=True)
            s_a.sendall(pkt)
            t_close.start()
            t_close.join(timeout=1.5)
            ch_srv.wait_until_closed(timeout_sec=1.5)
            _check(ch_srv.is_closed)
        finally:
            ch_srv.close()
            _close_socket_pair_quietly(s_a, s_b)


def _verify_rpc_monotonic_accept_dup_sid_and_post_hello() -> None:
    s1, s2 = socket.socketpair()
    ch_cli = MultiplexedChannel(s1, is_initiator=True)

    def _fake_srv_monotonic() -> None:
        try:
            hdr = s2.recv(4)
            _ = s2.recv(struct.unpack(">I", hdr)[0])
            f_acc = json.dumps({"stream_id": 1, "kind": "call_accepted", "payload": {}}).encode("utf-8")
            f_res = json.dumps({"stream_id": 1, "kind": "call_result", "payload": {"ok": False}, "meta": {"rejected_before_accept": True}}).encode("utf-8")
            s2.sendall(struct.pack(">I", len(f_acc)) + f_acc + struct.pack(">I", len(f_res)) + f_res)
        except OSError:
            pass

    th = threading.Thread(target=_fake_srv_monotonic, daemon=True)
    th.start()
    try:
        out_m = ch_cli.call({"cmd": "x"}, timeout_ms=2000)
        _check(out_m.was_accepted is True and out_m.rejected_before_accept is False)
    finally:
        ch_cli.close()
        _close_socket_pair_quietly(s1, s2)
        th.join(timeout=1.5)

    for bad_second in (
        {"stream_id": 0, "kind": "hello", "payload": {}},
        {"stream_id": 1, "kind": "call_start", "payload": {}},
    ):
        sa, sb = socket.socketpair()
        slow_gate = threading.Event()

        class _SlowHandler(InboundCallHandler):
            def on_call(self, stream_id: int, payload: JsonObject, ack_accepted: typing.Callable[[], bool], emit_progress: typing.Callable[[JsonObject], None], peer_cancel_token: CancellationToken) -> tuple[bool, JsonObject]:
                _ = (stream_id, payload, ack_accepted, emit_progress)
                slow_gate.wait(timeout=1.0)
                peer_cancel_token.wait(timeout=0.01)
                return (True, {"ok": True})

            def on_control(self, kind: FrameKind, payload: JsonObject) -> JsonObject:
                _ = (kind, payload)
                return {"ok": True}

        ch_s = MultiplexedChannel(sb, is_initiator=False, handler=_SlowHandler())
        try:
            c_first = json.dumps({"stream_id": 1, "kind": "call_start", "payload": {}}).encode("utf-8")
            c_sec = json.dumps(bad_second).encode("utf-8")
            sa.sendall(struct.pack(">I", len(c_first)) + c_first + struct.pack(">I", len(c_sec)) + c_sec)
            ch_s.wait_until_closed(timeout_sec=1.5)
            _check(ch_s.is_closed)
        finally:
            slow_gate.set()
            ch_s.close()
            _close_socket_pair_quietly(sa, sb)

    sc1, sc2 = socket.socketpair()
    ch_ctrl = MultiplexedChannel(sc1, is_initiator=True)
    try:
        sc2.close()
        _check(ch_ctrl.send_control(FrameKind.CONTROL_STATUS, {}, timeout_ms=10**18) is None)
        ch_ctrl.close_when_idle()
        _check(ch_ctrl.is_closed)
    finally:
        ch_ctrl.close()
        _close_socket_pair_quietly(sc1, sc2)


def _provision_failed_leader_child_and_bkp_cancel_mod(ws_dir: Path) -> None:
    mf = ws_dir / ".modules" / "flc"
    mf.mkdir(parents=True, exist_ok=True)
    (mf / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport time\nfrom typing import Optional, Sequence\n"
        "from core.execution.event import EventMetadata, EventSubscriptionSpec\n"
        "from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\n"
        "from core.filesystem.fs import atomic_write_json, read_json_dict\n"
        "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass FIn:\n    tag: str = ''\n    mode: str = ''\n"
        "@dataclass(frozen=True, slots=True)\nclass FOut:\n    ok_tag: str = 'ok'\n"
        "EV_CH = EventMetadata(EventId('flc.ev_ch'), FIn)\nEV_SLW = EventMetadata(EventId('flc.ev_slw'), FIn)\n"
        "def _mf(items: Sequence[FIn]) -> Optional[FIn]: return items[-1] if items else FIn()\n"
        "def _wf(ctx: TaskContext, gn: str, sec: float = 5.0) -> None:\n"
        "    gp = ctx.workspace_root.join('.cache', gn).path\n    dl = time.monotonic() + sec\n"
        "    while not gp.is_file() and time.monotonic() < dl:\n        ctx.cancel_token.raise_if_cancelled()\n        time.sleep(0.01)\n"
        "class ChildEmitT(Task[FIn, FOut]):\n    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]: return TaskMetadata(TaskId('flc.child_emit'), FIn, FOut)\n"
        "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n        ctx.emit(EV_CH, FIn(tag=req.tag))\n        return FOut('ce')\n"
        "class CoaFailAfterChildT(Task[FIn, FOut]):\n    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]:\n"
        "        return TaskMetadata(TaskId('flc.coa_fail'), FIn, FOut, resource_key='rk_flc', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.tag)\n"
        "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
        "        ctx.invoke_task(TaskId('flc.child_emit'), {'tag': req.tag})\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', f'flc_in_{req.tag}.json'), {'ok': True})\n"
        "        _wf(ctx, f'flc_go_{req.tag}.json')\n"
        "        if req.mode == 'ok_slw':\n            ctx.emit(EV_SLW, FIn(tag=req.tag))\n            return FOut('ok')\n"
        "        raise RuntimeError('leader_step_failed_after_child')\n"
        "class AncFolT(Task[FIn, FOut]):\n    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]: return TaskMetadata(TaskId('flc.anc_fol'), FIn, FOut)\n"
        "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n        ctx.emit_imm(EV_CH, FIn(tag=req.tag, mode='anc'))\n        return FOut('af')\n"
        "class SubChT(Task[FIn, FOut]):\n    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]:\n"
        "        return TaskMetadata(TaskId('flc.sub_ch'), FIn, FOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('flc.ev_ch'), _mf),))\n"
        "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
        "        if req.mode == 'anc':\n            ctx.invoke_task(TaskId('flc.coa_fail'), {'tag': req.tag, 'mode': 'fail'})\n            return FOut()\n"
        "        p = ctx.workspace_root.join('.cache', f'ch_cnt_{req.tag}.json')\n        prev = (read_json_dict(p) or {}).get('count', 0)\n"
        "        atomic_write_json(p, {'count': (prev if isinstance(prev, int) else 0) + 1})\n        return FOut()\n"
        "class SurvFolT(Task[FIn, FOut]):\n    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]: return TaskMetadata(TaskId('flc.surv_fol'), FIn, FOut)\n"
        "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
        "        _ = ctx.invoke_task(TaskId('flc.coa_fail'), {'tag': req.tag, 'mode': req.mode})\n        return FOut('sf')\n"
        "class LdrPostCycT(Task[FIn, FOut]):\n    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]: return TaskMetadata(TaskId('flc.ldr_post_cyc'), FIn, FOut)\n"
        "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
        "        ctx.invoke_task(TaskId('flc.coa_fail'), {'tag': req.tag, 'mode': 'ok_slw'})\n"
        "        ctx.invoke_task(TaskId('flc.ldr_post_cyc'), {'tag': req.tag})\n        return FOut()\n"
        "class SubSlwT(Task[FIn, FOut]):\n    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]:\n"
        "        return TaskMetadata(TaskId('flc.sub_slw'), FIn, FOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('flc.ev_slw'), _mf),))\n"
        "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', f'slw_in_{req.tag}.json'), {'ok': True})\n"
        "        _wf(ctx, f'slw_never_{req.tag}.json', 4.0)\n        return FOut()\n"
        "class FMod(YscbModule):\n    @property\n    def module_id(self) -> ModuleId: return ModuleId('flc')\n"
        "    def tasks(self) -> Sequence[BoundTask]:\n"
        "        return (ChildEmitT(), CoaFailAfterChildT(), AncFolT(), SubChT(), SurvFolT(), LdrPostCycT(), SubSlwT())\n"
        "def create_module() -> YscbModule: return FMod()\n",
        encoding="utf-8",
    )
    atomic_write_json(
        HostPath(mf / "routes.json"),
        {
            "module_id": "flc",
            "tier1": False,
            "tasks": [
                {"task_id": "flc.child_emit"},
                {"task_id": "flc.coa_fail", "resource_key": "rk_flc", "concurrency_mode": "coalesce"},
                {"task_id": "flc.anc_fol"},
                {"task_id": "flc.sub_ch", "exposure": "internal_trigger", "subscriptions": [{"event_id": "flc.ev_ch"}]},
                {"task_id": "flc.surv_fol"},
                {"task_id": "flc.ldr_post_cyc"},
                {"task_id": "flc.sub_slw", "exposure": "internal_trigger", "subscriptions": [{"event_id": "flc.ev_slw"}]},
            ],
        },
    )


def _verify_failed_leader_child_events_and_backup_cancel(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_f = HostPath(ws8.path / "ws_flc_bkp")
    provision_live_workspace(ws_f.path)
    _provision_failed_leader_child_and_bkp_cancel_mod(ws_f.path)
    disp_f = build_dispatcher_for_workspace(ws_f, venv_bin, is_daemon_host=True).dispatcher
    try:
        disp_f.warmup_daemon_container()
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fl1 = pool.submit(disp_f.invoke, InvokeRequest(TaskId("flc.coa_fail"), {"tag": "c1", "mode": "fail"}, ws_f, ws_f, propagation=CallPropagationContext(call_stack=((ws_f, TaskId("ext.l1")),))))
            _wait_file_marker(ws_f.path / ".cache" / "flc_in_c1.json")
            ff1 = pool.submit(disp_f.invoke, InvokeRequest(TaskId("flc.anc_fol"), {"tag": "c1"}, ws_f, ws_f))
            _wait_coalesce_count(disp_f, "rk_flc", 2)
            atomic_write_json(ws_f.join(".cache", "flc_go_c1.json"), {"go": True})
            rl1, rf1 = fl1.result(timeout=5.0), ff1.result(timeout=5.0)
        _check(not rl1.ok and not rf1.ok and rf1.error is not None and rf1.error.code == ErrorCode.EVENT_CYCLE_DETECTED)

        tok_l2 = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fl2 = pool.submit(disp_f.invoke, InvokeRequest(TaskId("flc.coa_fail"), {"tag": "c2", "mode": "fail"}, ws_f, ws_f, propagation=CallPropagationContext(call_stack=((ws_f, TaskId("ext.l2")),))), cancel_token=tok_l2)
            _wait_file_marker(ws_f.path / ".cache" / "flc_in_c2.json")
            ff2 = pool.submit(disp_f.invoke, InvokeRequest(TaskId("flc.surv_fol"), {"tag": "c2", "mode": "fail"}, ws_f, ws_f))
            _wait_coalesce_count(disp_f, "rk_flc", 2)
            tok_l2.cancel()
            atomic_write_json(ws_f.join(".cache", "flc_go_c2.json"), {"go": True})
            rl2, rf2 = fl2.result(timeout=5.0), ff2.result(timeout=5.0)
        _check(not rl2.ok and rl2.error is not None and rl2.error.code == ErrorCode.TASK_CANCELLED)
        _check(rf2.ok and read_json_dict(ws_f.join(".cache", "ch_cnt_c2.json")) == {"count": 1})

        tok_f3 = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fl3 = pool.submit(disp_f.invoke, InvokeRequest(TaskId("flc.ldr_post_cyc"), {"tag": "c3"}, ws_f, ws_f))
            _wait_file_marker(ws_f.path / ".cache" / "flc_in_c3.json")
            ff3 = pool.submit(disp_f.invoke, InvokeRequest(TaskId("flc.surv_fol"), {"tag": "c3", "mode": "ok_slw"}, ws_f, ws_f), cancel_token=tok_f3)
            _wait_coalesce_count(disp_f, "rk_flc", 2)
            atomic_write_json(ws_f.join(".cache", "flc_go_c3.json"), {"go": True})
            _wait_file_marker(ws_f.path / ".cache" / "slw_in_c3.json")
            t_cancel_start = time.monotonic()
            tok_f3.cancel()
            rl3, rf3 = fl3.result(timeout=5.0), ff3.result(timeout=5.0)
            elapsed_cancel = time.monotonic() - t_cancel_start
        _check(not rl3.ok and rl3.error is not None and rl3.error.code == ErrorCode.CALL_CYCLE_DETECTED)
        _check(not rf3.ok and rf3.error is not None and rf3.error.code == ErrorCode.TASK_CANCELLED and elapsed_cancel < 1.5)
    finally:
        disp_f.shutdown(grace_ms=100)


def _verify_warming_and_watcher_installer_lock_quiesce_yield(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_y = HostPath(ws8.path / "ws_inst_quiesce_yield")
    provision_live_workspace(ws_y.path)
    inst_lock = FileLock(ws_y.join(".cache", "locks", "installer.lock"))
    inst_lock.acquire(shared=False, blocking=True, timeout_sec=2.0)
    rig = build_dispatcher_for_workspace(ws_y, venv_bin, is_daemon_host=True)
    disp_y, cfg_y = rig.dispatcher, rig.config_view
    wcfg = DaemonWatcherConfig(config_watch_roots=(ws_y.join("config"),), watcher_debounce_sec=0.04)
    dmn_y = WorkspaceDaemon(workspace_root=ws_y, cache_dir=ws_y.join(".cache"), dispatcher=disp_y, config_view=cfg_y, watch_config=wcfg)
    ready_y = threading.Event()
    th_y = threading.Thread(target=dmn_y.run_forever, kwargs={"ttl_override_sec": 20.0, "ready_callback": ready_y.set}, daemon=True)
    try:
        th_y.start()
        dl = time.monotonic() + 4.0
        while read_daemon_endpoint_file(ws_y.join(".cache"), ws_y) is None and time.monotonic() < dl:
            time.sleep(0.02)
        time.sleep(0.05)
        t0 = time.monotonic()
        q1 = query_daemon_control(ws_y.join(".cache"), ws_y, FrameKind.CONTROL_QUIESCE, {"modules": [], "lease_sec": 8.0, "drain_timeout_sec": 1.5})
        _check(q1 is not None and q1.get("ok") is True and (time.monotonic() - t0) < 1.2)
        r1 = query_daemon_control(ws_y.join(".cache"), ws_y, FrameKind.CONTROL_RESUME, {})
        _check(r1 is not None and r1.get("ok") is True)
        inst_lock.release()
        _check(ready_y.wait(timeout=5.0))
        hot_out = disp_y.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="after_yield"))
        _check(hot_out.ok)

        inst_lock.acquire(shared=False, blocking=True, timeout_sec=2.0)
        atomic_write_json(ws_y.join("config", "alpha.json"), {"periodic_enabled": False, "seq": 2})
        time.sleep(0.12)
        t1 = time.monotonic()
        q2 = query_daemon_control(ws_y.join(".cache"), ws_y, FrameKind.CONTROL_QUIESCE, {"modules": [], "lease_sec": 8.0, "drain_timeout_sec": 2.5})
        _check(q2 is not None and q2.get("ok") is True and (time.monotonic() - t1) < 2.2)
        inst_lock.release()
        r2 = query_daemon_control(ws_y.join(".cache"), ws_y, FrameKind.CONTROL_RESUME, {})
        _check(r2 is not None and r2.get("ok") is True and r2.get("state") == "ready")
    finally:
        inst_lock.release()
        dmn_y.request_shutdown()
        th_y.join(timeout=4.0)
        disp_y.shutdown(grace_ms=100)


@dataclass(frozen=True, slots=True)
class _StrictMapDto:
    items: dict[int, str] = field(default_factory=dict)


@dataclass(frozen=True, slots=True)
class _BadBytesUnionDto:
    val: bytes | str = "x"


def _expect_yscb_code(fn: typing.Callable[[], object], expected: ErrorCode) -> None:
    try:
        fn()
    except YscbError as exc:
        _check(exc.detail.code == expected, lambda: f"Expected {expected}, got {exc.detail.code}")
        return
    raise AssertionError(f"Expected YscbError({expected}), but call succeeded")


class _PreemptEchoHandler(InboundCallHandler):
    def __init__(self) -> None:
        self.entered = threading.Event()
        self.cancelled = threading.Event()
        self.seen_preempted: bool = False
        self.seen_reason: str = ""

    def on_call(
        self,
        stream_id: int,
        payload: JsonObject,
        ack_accepted: typing.Callable[[], bool],
        emit_progress: typing.Callable[[JsonObject], None],
        peer_cancel_token: CancellationToken,
    ) -> tuple[bool, JsonObject]:
        _ = (stream_id, payload, emit_progress)
        ack_accepted()
        self.entered.set()
        dl = time.monotonic() + 3.0
        while not peer_cancel_token.is_cancelled and time.monotonic() < dl:
            time.sleep(0.01)
        self.seen_preempted = peer_cancel_token.is_preempted
        self.seen_reason = peer_cancel_token.reason or ""
        self.cancelled.set()
        raise TaskCancelledException(self.seen_reason or "cancelled", preempted=self.seen_preempted)

    def on_control(self, kind: FrameKind, payload: JsonObject) -> JsonObject:
        _ = (kind, payload)
        return {"ok": True}


def _verify_posix_upgrade_restore_codec_depth_and_rpc_ping(ws8: HostPath) -> None:
    lk_path = ws8.join(".cache", "sc_upg_shared.lock")
    rdy_f = ws8.path / ".cache" / "sc_sh_rdy.json"
    stop_f = ws8.path / ".cache" / "sc_sh_stop.json"
    child_code = (
        "import sys, time; sys.path.insert(0, sys.argv[1]); "
        "from core.filesystem.fs import FileLock, atomic_write_json; "
        "from core.foundation.primitives import HostPath; "
        "lk = FileLock(HostPath(sys.argv[2])); lk.acquire(shared=True, blocking=True, timeout_sec=3.0) or sys.exit(9); "
        "atomic_write_json(HostPath(sys.argv[3]), {'ok': True}); "
        "dl = time.monotonic() + 5.0\n"
        "while not HostPath(sys.argv[4]).path.is_file() and time.monotonic() < dl: time.sleep(0.02)\n"
        "lk.release()"
    )
    proc = subprocess.Popen([sys.executable, "-c", child_code, str(CORE_SRC_ROOT), str(lk_path), str(rdy_f), str(stop_f)])
    own_lk = FileLock(lk_path)
    try:
        _wait_file_marker(rdy_f)
        _check(own_lk.acquire(shared=True, blocking=True, timeout_sec=2.0))
        _expect_yscb_code(lambda: own_lk.upgrade_to_exclusive(timeout_sec=0.08), ErrorCode.ILLEGAL_LOCK_REENTRANCY)
        _check(own_lk.is_acquired)
        atomic_write_json(HostPath(stop_f), {"stop": True})
        proc.wait(timeout=4.0)
        probe_code = (
            "import sys; sys.path.insert(0, sys.argv[1]); "
            "from core.filesystem.fs import FileLock; from core.foundation.primitives import HostPath; "
            "p = FileLock(HostPath(sys.argv[2])); got = p.acquire(shared=False, blocking=False); "
            "p.release() if got else None; raise SystemExit(1 if got else 0)"
        )
        rc = subprocess.run([sys.executable, "-c", probe_code, str(CORE_SRC_ROOT), str(lk_path)], timeout=4.0).returncode
        _check(rc == 0)
    finally:
        atomic_write_json(HostPath(stop_f), {"stop": True})
        own_lk.release()
        if proc.poll() is None:
            proc.kill()
        proc.wait(timeout=3.0)


def _verify_strict_codec_and_rpc_channel_semantics() -> None:
    _expect_yscb_code(lambda: DataclassCodec.encode("\ud800"), ErrorCode.CODEC_VALIDATION_FAILED)
    _expect_yscb_code(lambda: DataclassCodec.canonical_hash({"bad": "\ud800"}), ErrorCode.CODEC_VALIDATION_FAILED)
    deep_obj: dict[str, object] = {"leaf": 1}
    for _ in range(135):
        deep_obj = {"n": deep_obj}
    _expect_yscb_code(lambda: DataclassCodec.encode(deep_obj), ErrorCode.CODEC_VALIDATION_FAILED)
    _expect_yscb_code(lambda: DataclassCodec.decode(_StrictMapDto, {"items": {1: "bad_int_key"}}), ErrorCode.CODEC_VALIDATION_FAILED)
    _expect_yscb_code(lambda: DataclassCodec.encode_object(_BadBytesUnionDto(val=b"abc")), ErrorCode.CODEC_VALIDATION_FAILED)
    _expect_yscb_code(lambda: DataclassCodec.decode(_BadBytesUnionDto, {"val": "YWJj"}), ErrorCode.CODEC_VALIDATION_FAILED)

    hnd = _PreemptEchoHandler()
    s_cli, s_srv = socket.socketpair()
    ch_cli = MultiplexedChannel(s_cli, is_initiator=True)
    ch_srv = MultiplexedChannel(s_srv, is_initiator=False, handler=hnd)
    try:
        _check(ch_cli.ping(timeout_ms=1500) is True)
        ctok = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as ex:
            fut = ex.submit(ch_cli.call, {"op": "hold"}, cancel_token=ctok, timeout_ms=3000)
            _check(hnd.entered.wait(timeout=2.0))
            ctok.cancel(preempted=True, reason="sc_preempt_signal")
            out = fut.result(timeout=3.0)
        _check(out.error_code == ErrorCode.TASK_PREEMPTED)
        _check(hnd.cancelled.wait(timeout=2.0) and hnd.seen_preempted is True and hnd.seen_reason == "sc_preempt_signal")
    finally:
        ch_cli.close()
        ch_srv.close()
    _check(ch_cli.ping(timeout_ms=200) is False)


