def _verify_neutral_flight_reentrancy_cycle_and_imm_cycle(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_nf = HostPath(ws8.path / "ws_case_neutral_flight")
    provision_live_workspace(ws_nf.path)
    md = ws_nf.path / ".modules" / "nf"
    md.mkdir(parents=True, exist_ok=True)
    (md / "module_entry.py").write_text(_NEUTRAL_FLIGHT_MOD_SRC, encoding="utf-8")
    atomic_write_json(HostPath(md / "routes.json"), {"module_id": "nf", "tier1": False, "tasks": []})
    disp_nf = build_dispatcher_for_workspace(ws_nf, venv_bin, is_daemon_host=True).dispatcher
    try:
        tok_f2 = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f1 = pool.submit(disp_nf.invoke, InvokeRequest(TaskId("nf.coal_bridge"), {}, ws_nf, ws_nf))
            _wait_file_marker(ws_nf.path / ".cache" / "nf_coal_in.json")
            f2 = pool.submit(disp_nf.invoke, InvokeRequest(TaskId("nf.outer_hold"), {}, ws_nf, ws_nf), cancel_token=tok_f2)
            dl = time.monotonic() + 2.0
            while disp_nf.coordinator.coalesce_participant_count("rk_nf_coal") < 2 and time.monotonic() < dl:
                time.sleep(0.01)
            atomic_write_json(ws_nf.join(".cache", "nf_both_joined.json"), {"joined": True})
            _wait_file_marker(ws_nf.path / ".cache" / "nf_in_ser.json")
            tok_f2.cancel(reason="follower_cancel_mid_reentrant_ser")
            r1, r2 = f1.result(timeout=4.0), f2.result(timeout=4.0)
        _check(r1.ok and r1.value == {"ok_tag": "True"})
        _check(not r2.ok and r2.error is not None and r2.error.code == ErrorCode.TASK_CANCELLED)
        _verify_neutral_flight_call_and_imm_cycles(ws_nf, disp_nf)
    finally:
        disp_nf.shutdown(grace_ms=100)


def _verify_neutral_flight_call_and_imm_cycles(ws_nf: HostPath, disp_nf: RuntimeDispatcher) -> None:
    single_cyc = disp_nf.invoke(InvokeRequest(TaskId("nf.cyc_caller"), {}, ws_nf, ws_nf))
    _check(not single_cyc.ok and single_cyc.error is not None and single_cyc.error.code == ErrorCode.CALL_CYCLE_DETECTED)

    (ws_nf.path / ".cache" / "nf_cc_in.json").unlink(missing_ok=True)
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        fa = pool.submit(disp_nf.invoke, InvokeRequest(TaskId("nf.acyc_caller"), {}, ws_nf, ws_nf))
        _wait_file_marker(ws_nf.path / ".cache" / "nf_cc_in.json")
        fc = pool.submit(disp_nf.invoke, InvokeRequest(TaskId("nf.cyc_caller"), {}, ws_nf, ws_nf))
        ra, rc = fa.result(timeout=4.0), fc.result(timeout=4.0)
    _check(ra.ok and ra.value == {"ok_tag": "acyc_ok"})
    _check(not rc.ok and rc.error is not None and rc.error.code == ErrorCode.CALL_CYCLE_DETECTED)

    rep_imm = disp_nf.emit_background_event(EventId("nf.ev_cyc"), {})
    _check(rep_imm.fatal_event_error is not None and rep_imm.fatal_event_error.code == ErrorCode.EVENT_CYCLE_DETECTED)
    _check(_jint(read_json_dict(ws_nf.join(".cache", "nf_imm_hits.json")), "n") == 1)


