def _verify_selective_quiesce_warming_watch_and_core_boot_handoff(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_sq = HostPath(ws8.path / "ws_case_sel_quiesce")
    provision_live_workspace(ws_sq.path)
    ma, mb = ws_sq.path / ".modules" / "wmod_a", ws_sq.path / ".modules" / "wmod_b"
    ma.mkdir(parents=True, exist_ok=True)
    mb.mkdir(parents=True, exist_ok=True)
    (ma / "module_entry.py").write_text(_WARM_COMPANION_MOD_SRC, encoding="utf-8")
    (mb / "module_entry.py").write_text(_FAST_COMPANION_MOD_SRC, encoding="utf-8")
    atomic_write_json(HostPath(ma / "routes.json"), {"module_id": "wmod_a", "tier1": False, "eager_warmup": True, "tasks": []})
    atomic_write_json(HostPath(mb / "routes.json"), {"module_id": "wmod_b", "tier1": False, "tasks": [{"task_id": "wmod_b.ping", "subscriptions": [{"event_id": "core.config_changed"}]}]})
    rig = build_dispatcher_for_workspace(ws_sq, venv_bin, is_daemon_host=True)
    disp_d, cfg_d, echo_d = rig.dispatcher, rig.config_view, rig.echo_ledger
    disp_c = build_dispatcher_for_workspace(ws_sq, venv_bin, is_daemon_host=False).dispatcher
    wcfg = DaemonWatcherConfig(echo_guard=echo_d, config_watch_roots=(ws_sq.join("config"),), watcher_debounce_sec=0.05)
    dmn = WorkspaceDaemon(workspace_root=ws_sq, cache_dir=ws_sq.join(".cache"), dispatcher=disp_d, config_view=cfg_d, watch_config=wcfg)
    th = threading.Thread(target=dmn.run_forever, kwargs={"ttl_override_sec": 20.0}, daemon=True)
    try:
        th.start()
        _wait_file_marker(ws_sq.path / ".cache" / "wmod_a_warming.json")
        atomic_write_json(ws_sq.join("config", "wmod_b.json"), {"edited_during_warming": True})
        _wait_file_marker(ws_sq.path / ".cache" / "wmod_b_cfg_seen.json", timeout_sec=5.0)
        q_sel = query_daemon_control(ws_sq.join(".cache"), ws_sq, FrameKind.CONTROL_QUIESCE, {"modules": ["wmod_a"], "lease_sec": 8.0})
        _check(q_sel is not None and q_sel.get("ok") is True and q_sel.get("state") == "quiesced")
        t0 = time.monotonic()
        b_out = disp_c.invoke(InvokeRequest(TaskId("wmod_b.ping"), {"v": 42}, ws_sq, ws_sq, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        _check(b_out.ok and b_out.executed_hot and b_out.value == {"v": 42} and (time.monotonic() - t0) < 0.8)
        r_sel = query_daemon_control(ws_sq.join(".cache"), ws_sq, FrameKind.CONTROL_RESUME, {})
        _check(r_sel is not None and r_sel.get("ok") is True and r_sel.get("state") == "ready")
    finally:
        dmn.request_shutdown()
        th.join(timeout=4.0)
        disp_c.shutdown(grace_ms=100)
        disp_d.shutdown(grace_ms=100)


def _verify_boot_lock_core_mutation_handoff(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_bh = HostPath(ws8.path / "ws_case_boot_handoff")
    provision_live_workspace(ws_bh.path)
    (ws_bh.path / "spaces" / "source" / "boot_catchup.py").write_text("X = 1\n", encoding="utf-8")
    core_dir = ws_bh.path / ".modules" / "core"
    core_dir.mkdir(parents=True, exist_ok=True)
    (core_dir / "ver.py").write_text("VER = 1\n", encoding="utf-8")
    inst_lk = FileLock(ws_bh.join(".cache", "locks", "installer.lock"))
    _check(inst_lk.acquire(shared=False, blocking=True, timeout_sec=2.0))
    rig = build_dispatcher_for_workspace(ws_bh, venv_bin, is_daemon_host=True)
    disp_bh, cfg_bh, echo_bh = rig.dispatcher, rig.config_view, rig.echo_ledger
    wcfg = DaemonWatcherConfig(
        echo_guard=echo_bh,
        space_watch_roots=(ws_bh.join("spaces"),),
        on_space_changed_task=TaskId("space.scan"),
        watcher_debounce_sec=0.06,
    )
    restart_argv = [sys.executable, "-W", "error::ResourceWarning", str(Path(__file__).resolve()), "--daemon-entry", str(ws_bh), str(venv_bin.path), "15.0"]
    dmn_bh = WorkspaceDaemon(workspace_root=ws_bh, cache_dir=ws_bh.join(".cache"), dispatcher=disp_bh, config_view=cfg_bh, watch_config=wcfg, self_restart_argv=restart_argv)
    th_bh = threading.Thread(target=dmn_bh.run_forever, kwargs={"ttl_override_sec": 15.0}, daemon=True)
    try:
        th_bh.start()
        dl = time.monotonic() + 4.0
        while read_daemon_endpoint_file(ws_bh.join(".cache"), ws_bh) is None and time.monotonic() < dl:
            time.sleep(0.02)
        ep_old = read_daemon_endpoint_file(ws_bh.join(".cache"), ws_bh)
        _check(ep_old is not None)
        q_bh = query_daemon_control(ws_bh.join(".cache"), ws_bh, FrameKind.CONTROL_QUIESCE, {"modules": [], "lease_sec": 8.0})
        _check(q_bh is not None and q_bh.get("ok") is True)
        (core_dir / "ver.py").write_text("VER = 2\n", encoding="utf-8")
        inst_lk.release()
        r_bh = query_daemon_control(ws_bh.join(".cache"), ws_bh, FrameKind.CONTROL_RESUME, {})
        _check(r_bh is not None and r_bh.get("ok") is True and r_bh.get("handoff") is True)
        th_bh.join(timeout=5.0)
        ep_new = wait_for_handoff_daemon_endpoint(
            ws_bh.join(".cache"), ws_bh, max_wait_sec=6.0, previous_boot_id=ep_old.boot_id
        )
        _check(ep_new is not None and ep_new.boot_id != ep_old.boot_id)
        _wait_file_marker(ws_bh.path / ".cache" / "ast_state.json", timeout_sec=5.0)
    finally:
        inst_lk.release()
        dmn_bh.request_shutdown()
        th_bh.join(timeout=3.0)
        stop_daemon_cleanly(ws_bh)
        disp_bh.shutdown(grace_ms=100)


_XWS_COAL_MOD_SRC: Final[str] = (
    "from dataclasses import dataclass\nfrom typing import Sequence\n"
    "from core.execution.runtime import BoundTask, ClientRoutingPolicy, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule\n"
    "from core.foundation.errors import YscbError\n"
    "from core.foundation.primitives import HostPath, ModuleId, TaskId\n"
    "@dataclass(frozen=True, slots=True)\nclass XCIn:\n    peer_ws: str = ''\n    back_ws: str = ''\n    mode: str = 'ser'\n"
    "@dataclass(frozen=True, slots=True)\nclass XCOut:\n    tag: str = ''\n"
    "class OuterSerT(Task[XCIn, XCOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[XCIn, XCOut]:\n"
    "        return TaskMetadata(TaskId('xcoal.outer_ser'), XCIn, XCOut, resource_key='rk_xc', concurrency_mode=ConcurrencyMode.SERIALIZE)\n"
    "    def run(self, req: XCIn, ctx: TaskContext) -> XCOut:\n"
    "        r = ctx.invoke_task(TaskId('xcoal.bridge_coal'), {'back_ws': str(ctx.workspace_root), 'mode': req.mode}, target_workspace=HostPath(req.peer_ws), routing_policy=ClientRoutingPolicy.STRICT_HOT)\n"
    "        if not r.ok and r.error is not None: raise YscbError(r.error.code, r.error.message, source_task=r.error.source_task)\n"
    "        return XCOut(tag='xcoal_reentered_ok')\n"
    "class BridgeCoalT(Task[XCIn, XCOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[XCIn, XCOut]:\n"
    "        return TaskMetadata(TaskId('xcoal.bridge_coal'), XCIn, XCOut, resource_key='rk_xb', concurrency_mode=ConcurrencyMode.COALESCE)\n"
    "    def run(self, req: XCIn, ctx: TaskContext) -> XCOut:\n"
    "        tid = TaskId('xcoal.inner_ser' if req.mode == 'ser' else ('xcoal.inner_pre' if req.mode == 'pre' else 'xcoal.helper_cyc'))\n"
    "        r = ctx.invoke_task(tid, {'peer_ws': str(ctx.workspace_root), 'back_ws': req.back_ws, 'mode': req.mode}, target_workspace=HostPath(req.back_ws), routing_policy=ClientRoutingPolicy.STRICT_HOT)\n"
    "        if not r.ok and r.error is not None: raise YscbError(r.error.code, r.error.message, source_task=r.error.source_task)\n"
    "        return XCOut(tag='bridge_ok')\n"
    "class HelperCycT(Task[XCIn, XCOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[XCIn, XCOut]: return TaskMetadata(TaskId('xcoal.helper_cyc'), XCIn, XCOut)\n"
    "    def run(self, req: XCIn, ctx: TaskContext) -> XCOut:\n"
    "        r = ctx.invoke_task(TaskId('xcoal.outer_ser'), {'peer_ws': req.peer_ws, 'mode': 'ser'}, routing_policy=ClientRoutingPolicy.STRICT_HOT)\n"
    "        if not r.ok and r.error is not None: raise YscbError(r.error.code, r.error.message, source_task=r.error.source_task)\n"
    "        return XCOut(tag='never')\n"
    "class InnerSerT(Task[XCIn, XCOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[XCIn, XCOut]:\n"
    "        return TaskMetadata(TaskId('xcoal.inner_ser'), XCIn, XCOut, resource_key='rk_xc', concurrency_mode=ConcurrencyMode.SERIALIZE)\n"
    "    def run(self, req: XCIn, ctx: TaskContext) -> XCOut: return XCOut(tag='inner_ok')\n"
    "class InnerPreT(Task[XCIn, XCOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[XCIn, XCOut]:\n"
    "        return TaskMetadata(TaskId('xcoal.inner_pre'), XCIn, XCOut, resource_key='rk_xc', concurrency_mode=ConcurrencyMode.PREEMPT)\n"
    "    def run(self, req: XCIn, ctx: TaskContext) -> XCOut: return XCOut(tag='pre_ok')\n"
    "class XCoalMod(YscbModule):\n"
    "    @property\n    def module_id(self) -> ModuleId: return ModuleId('xcoal')\n"
    "    def tasks(self) -> Sequence[BoundTask]: return (OuterSerT(), BridgeCoalT(), HelperCycT(), InnerSerT(), InnerPreT())\n"
    "def create_module() -> YscbModule: return XCoalMod()\n"
)


def _verify_cross_ws_coalesce_bounce_and_cycle(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_a = HostPath(ws8.path / "ws_xc_a")
    ws_b = HostPath(ws8.path / "ws_xc_b")
    provision_live_workspace(ws_a.path)
    provision_live_workspace(ws_b.path)
    for w_dir in (ws_a.path, ws_b.path):
        mdir = w_dir / ".modules" / "xcoal"
        mdir.mkdir(parents=True, exist_ok=True)
        atomic_write_json(
            HostPath(mdir / "routes.json"),
            {
                "module_id": "xcoal",
                "tier1": False,
                "tasks": [
                    {"task_id": "xcoal.outer_ser", "resource_key": "rk_xc", "concurrency_mode": "serialize"},
                    {"task_id": "xcoal.bridge_coal", "resource_key": "rk_xb", "concurrency_mode": "coalesce"},
                    {"task_id": "xcoal.helper_cyc"},
                    {"task_id": "xcoal.inner_ser", "resource_key": "rk_xc", "concurrency_mode": "serialize"},
                    {"task_id": "xcoal.inner_pre", "resource_key": "rk_xc", "concurrency_mode": "preempt"},
                ],
            },
        )
        (mdir / "module_entry.py").write_text(_XWS_COAL_MOD_SRC, encoding="utf-8")
    disp_a = build_dispatcher_for_workspace(ws_a, venv_bin, ttl_sec=25.0).dispatcher
    disp_b = build_dispatcher_for_workspace(ws_b, venv_bin, ttl_sec=25.0).dispatcher
    try:
        disp_a.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="xca"))
        disp_b.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="xcb"))
        wait_for_daemon_online(ws_a)
        wait_for_daemon_online(ws_b)
        ok_s = disp_a.invoke(InvokeRequest(TaskId("xcoal.outer_ser"), {"peer_ws": str(ws_b), "mode": "ser"}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        bad_p = disp_a.invoke(InvokeRequest(TaskId("xcoal.outer_ser"), {"peer_ws": str(ws_b), "mode": "pre"}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        bad_c = disp_a.invoke(InvokeRequest(TaskId("xcoal.outer_ser"), {"peer_ws": str(ws_b), "mode": "cyc"}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        _check(ok_s.ok and ok_s.value == {"tag": "xcoal_reentered_ok"})
        _check(not bad_p.ok and bad_p.error is not None and bad_p.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
        _check(not bad_c.ok and bad_c.error is not None and bad_c.error.code == ErrorCode.CALL_CYCLE_DETECTED)
        _check(bad_c.error.source_task == "xcoal.outer_ser")
    finally:
        stop_daemon_cleanly(ws_b)
        stop_daemon_cleanly(ws_a)
        disp_b.shutdown()
        disp_a.shutdown()


def _build_iso_dyn_mod_src(mod_id_s: str, expected_val: str) -> str:
    return (
        "from dataclasses import dataclass\nimport importlib\nimport time\nfrom typing import Sequence\n"
        "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.foundation.primitives import ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass DIn:\n    n: int = 1\n"
        "@dataclass(frozen=True, slots=True)\nclass DOut:\n    val: str = ''\n"
        "class DynT(Task[DIn, DOut]):\n"
        f"    @property\n    def metadata(self) -> TaskMetadata[DIn, DOut]: return TaskMetadata(TaskId('{mod_id_s}.go'), DIn, DOut)\n"
        "    def run(self, req: DIn, ctx: TaskContext) -> DOut:\n"
        "        m = importlib.import_module('shared_dyn')\n"
        "        time.sleep(0.004)\n"
        "        m2 = importlib.import_module('shared_dyn')\n"
        f"        if not (m.TAG == '{expected_val}' and m2.TAG == '{expected_val}'): raise AssertionError('tag mismatch')\n"
        "        return DOut(val=str(m2.TAG))\n"
        "class IsoMod(YscbModule):\n"
        f"    @property\n    def module_id(self) -> ModuleId: return ModuleId('{mod_id_s}')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (DynT(),)\n"
        "def create_module() -> YscbModule: return IsoMod()\n"
    )


def _verify_concurrent_importlib_and_upgrade_release(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_iso = HostPath(ws8.path / "ws_conc_importlib")
    provision_live_workspace(ws_iso.path)
    for mid, tag_v in (("isom_a", "ONLY_A"), ("isom_b", "ONLY_B")):
        md = ws_iso.path / ".modules" / mid
        md.mkdir(parents=True, exist_ok=True)
        (md / "shared_dyn.py").write_text(f"TAG = '{tag_v}'\n", encoding="utf-8")
        (md / "module_entry.py").write_text(_build_iso_dyn_mod_src(mid, tag_v), encoding="utf-8")
        atomic_write_json(HostPath(md / "routes.json"), {"module_id": mid, "tier1": False, "tasks": [{"task_id": f"{mid}.go"}]})
    disp_iso = build_dispatcher_for_workspace(ws_iso, venv_bin, is_daemon_host=True).dispatcher
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
            futs = [
                pool.submit(
                    disp_iso.invoke,
                    InvokeRequest(TaskId("isom_a.go" if i % 2 == 0 else "isom_b.go"), {"n": i}, ws_iso, ws_iso),
                )
                for i in range(16)
            ]
            for i, f in enumerate(futs):
                r = f.result(timeout=5.0)
                _check(r.ok and r.value == {"val": "ONLY_A" if i % 2 == 0 else "ONLY_B"})
        _check("shared_dyn" not in sys.modules)
    finally:
        disp_iso.shutdown(grace_ms=100)

    lk_file = ws8.join(".cache", "locks", "conc_upg_release.lock")
    holder_other = FileLock(lk_file)
    upg_lk = FileLock(lk_file)
    _check(holder_other.acquire(shared=True, blocking=False))
    _check(upg_lk.acquire(shared=True, blocking=False))
    upg_entered = threading.Event()
    upg_err: list[ErrorCode] = []

    def _run_upg() -> None:
        upg_entered.set()
        try:
            upg_lk.upgrade_to_exclusive(timeout_sec=4.0)
        except YscbError as exc:
            upg_err.append(exc.detail.code)

    th_u = threading.Thread(target=_run_upg, daemon=True)
    th_u.start()
    try:
        _check(upg_entered.wait(timeout=1.0))
        time.sleep(0.04)
        t0 = time.monotonic()
        upg_lk.release()
        _check(not upg_lk.is_acquired)
        holder_other.release()
        excl_probe = FileLock(lk_file)
        _check(excl_probe.acquire(shared=False, blocking=False))
        excl_probe.release()
        th_u.join(timeout=1.0)
        _check(not th_u.is_alive() and (time.monotonic() - t0) < 0.4)
        _check(upg_err == [ErrorCode.TASK_CANCELLED])
    finally:
        holder_other.release()
        upg_lk.release()


def _verify_selective_quiesce_colocated_and_degraded_preserved(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_sq = HostPath(ws8.path / "ws_sel_quiesce_coloc")
    provision_live_workspace(ws_sq.path)
    (ws_sq.path / "sub_dir").mkdir(parents=True, exist_ok=True)
    (ws_sq.path / "sub_dir" / "sample.py").write_text("X = 1\n", encoding="utf-8")
    atomic_write_json(ws_sq.join("config", "gdrive.json"), {"put_sleep_ms": 650})
    disp_sq = build_dispatcher_for_workspace(ws_sq, venv_bin, ttl_sec=25.0).dispatcher
    try:
        disp_sq.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot_sq"))
        st0 = wait_for_daemon_online(ws_sq)
        _check("broken_opt" in st0.get("degraded_modules", []))

        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            f_gd = pool.submit(
                disp_sq.invoke,
                InvokeRequest(TaskId("gdrive.put"), {"local_rel": "./sample.py"}, ws_sq, HostPath(ws_sq.path / "sub_dir"), routing_policy=ClientRoutingPolicy.STRICT_HOT),
                output_type=GdriveOutDto,
            )
            time.sleep(0.12)
            q_kdb = query_daemon_control(
                ws_sq.join(".cache"), ws_sq, FrameKind.CONTROL_QUIESCE, {"modules": ["kdb"], "lease_sec": 6.0, "drain_timeout_sec": 0.35}
            )
            _check(q_kdb is not None and q_kdb.get("ok") is True)
            f_ast = pool.submit(
                disp_sq.invoke_typed, AST_OUTLINE_META, OutlineInDto(rel_file="./sample.py"), caller_cwd=HostPath(ws_sq.path / "sub_dir"), routing_policy=ClientRoutingPolicy.STRICT_HOT
            )
            time.sleep(0.12)
            _check(not f_ast.done())
            echo_hot = disp_sq.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="unblocked_during_kdb_q"), routing_policy=ClientRoutingPolicy.STRICT_HOT)
            _check(echo_hot.ok and echo_hot.executed_hot)
            r_kdb = query_daemon_control(ws_sq.join(".cache"), ws_sq, FrameKind.CONTROL_RESUME, {})
            _check(r_kdb is not None and r_kdb.get("ok") is True)
            _check(f_ast.result(timeout=6.0).ok and f_gd.result(timeout=6.0).ok)

        st1 = query_daemon_control(ws_sq.join(".cache"), ws_sq, FrameKind.CONTROL_STATUS)
        _check(st1 is not None and isinstance(st1.get("status"), Mapping))
        _check("broken_opt" in st1["status"].get("degraded_modules", []))
    finally:
        stop_daemon_cleanly(ws_sq)
        disp_sq.shutdown()


_STRICT_IMM_AND_FILTER_MOD_SRC: Final[str] = (
    "from dataclasses import dataclass\nfrom typing import Optional, Sequence\n"
    "from core.execution.event import EventMetadata, EventOrdering, EventSubscriptionSpec\n"
    "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
    "from core.filesystem.fs import atomic_write_json\n"
    "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
    "@dataclass(frozen=True, slots=True)\nclass FIn:\n    kind: str = 'keep'\n"
    "@dataclass(frozen=True, slots=True)\nclass FOut:\n    ok_tag: str = 'ok'\n"
    "EV_X = EventMetadata(EventId('sif.ev_x'), FIn, EventOrdering.UNORDERED)\n"
    "EV_MAIN = EventMetadata(EventId('sif.ev_main'), FIn, EventOrdering.UNORDERED)\n"
    "EV_IMM_FAIL = EventMetadata(EventId('sif.ev_imm_fail'), FIn, EventOrdering.ORDERED)\n"
    "def _map_f(items: Sequence[FIn]) -> Optional[FIn]: return items[-1] if items else None\n"
    "class TrigFilterT(Task[FIn, FOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]: return TaskMetadata(TaskId('sif.trig_filter'), FIn, FOut)\n"
    "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
    "        ctx.emit(EV_X, FIn(kind='seed'))\n"
    "        ctx.emit(EV_MAIN, FIn(kind='keep'))\n"
    "        return FOut()\n"
    "class SubXDropEmitterT(Task[FIn, FOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]:\n"
    "        return TaskMetadata(TaskId('sif.sub_x'), FIn, FOut, subscriptions=(EventSubscriptionSpec(EV_X, _map_f, payload_filter={'kind': ('seed',)}),))\n"
    "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
    "        ctx.emit(EV_MAIN, FIn(kind='drop'))\n"
    "        return FOut()\n"
    "class SubMainKeepOnlyT(Task[FIn, FOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]:\n"
    "        return TaskMetadata(TaskId('sif.sub_main_keep'), FIn, FOut, subscriptions=(EventSubscriptionSpec(EV_MAIN, _map_f, payload_filter={'kind': ('keep',)}),))\n"
    "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
    "        ctx.emit(EV_X, FIn(kind='after_keep'))\n"
    "        atomic_write_json(ctx.workspace_root.join('.cache', 'sif_keep_ok.json'), {'ok': True})\n"
    "        return FOut()\n"
    "class EmitStrictImmT(Task[FIn, FOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]: return TaskMetadata(TaskId('sif.emit_strict'), FIn, FOut)\n"
    "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
    "        ctx.emit_imm(EV_IMM_FAIL, FIn(kind='boom'), strict=True)\n"
    "        return FOut()\n"
    "class FailingImmSubT(Task[FIn, FOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[FIn, FOut]:\n"
    "        return TaskMetadata(TaskId('sif.fail_sub'), FIn, FOut, subscriptions=(EventSubscriptionSpec(EV_IMM_FAIL, _map_f),))\n"
    "    def run(self, req: FIn, ctx: TaskContext) -> FOut:\n"
    "        raise ValueError('strict_sub_boom')\n"
    "class SifMod(YscbModule):\n"
    "    @property\n    def module_id(self) -> ModuleId: return ModuleId('sif')\n"
    "    def tasks(self) -> Sequence[BoundTask]:\n"
    "        return (TrigFilterT(), SubXDropEmitterT(), SubMainKeepOnlyT(), EmitStrictImmT(), FailingImmSubT())\n"
    "def create_module() -> YscbModule: return SifMod()\n"
)


def _verify_strict_imm_source_task_and_filtered_lineage(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_sf = HostPath(ws8.path / "ws_strict_imm_filter")
    provision_live_workspace(ws_sf.path)
    md = ws_sf.path / ".modules" / "sif"
    md.mkdir(parents=True, exist_ok=True)
    (md / "module_entry.py").write_text(_STRICT_IMM_AND_FILTER_MOD_SRC, encoding="utf-8")
    atomic_write_json(
        HostPath(md / "routes.json"),
        {
            "module_id": "sif",
            "tier1": False,
            "tasks": [
                {"task_id": "sif.trig_filter"},
                {"task_id": "sif.sub_x", "subscriptions": [{"event_id": "sif.ev_x", "payload_filter": {"kind": ["seed"]}}]},
                {"task_id": "sif.sub_main_keep", "subscriptions": [{"event_id": "sif.ev_main", "payload_filter": {"kind": ["keep"]}}]},
                {"task_id": "sif.emit_strict"},
                {"task_id": "sif.fail_sub", "subscriptions": [{"event_id": "sif.ev_imm_fail"}]},
            ],
        },
    )
    disp_sf = build_dispatcher_for_workspace(ws_sf, venv_bin, is_daemon_host=True).dispatcher
    try:
        strict_out = disp_sf.invoke(InvokeRequest(TaskId("sif.emit_strict"), {}, ws_sf, ws_sf))
        _check(not strict_out.ok and strict_out.error is not None)
        _check(strict_out.error.source_task == "sif.fail_sub")

        # Two UNORDERED records (one from SubX with lineage [ev_x, ev_main] & kind='drop', one with [ev_main] & kind='keep'):
        # SubMainKeepOnly filters kind=='keep', so ev_x must NOT pollute its lineage when re-emitting ev_x!
        q = DoubleBufferedEventQueue()
        lin_drop = CausalLineage().advance(EventId("sif.ev_x"), workspace_scope=ws_sf.comparison_key).advance(
            EventId("sif.ev_main"), workspace_scope=ws_sf.comparison_key
        )
        lin_keep = CausalLineage().advance(EventId("sif.ev_main"), workspace_scope=ws_sf.comparison_key)
        q.append_committed(
            (
                RawEventRecord(EventId("sif.ev_main"), TaskId("sif.sub_x"), {"kind": "drop"}, EventOrdering.UNORDERED, lin_drop),
                RawEventRecord(EventId("sif.ev_main"), TaskId("sif.trig_filter"), {"kind": "keep"}, EventOrdering.UNORDERED, lin_keep),
            )
        )
        envelopes = q.freeze_and_swap()
        _check(len(envelopes) == 1)
        f_pays, f_lin = envelopes[0].filter_for_subscription({"kind": ("keep",)})
        _check(len(f_pays) == 1 and EventId("sif.ev_x") not in f_lin.chain)
        scope = TurnScope(turn_id="t_flt", kind=TurnKind.HOT_FOREGROUND, cancel_token=CancellationToken())
        step_res = disp_sf.run_event_step(envelopes[0], scope)
        _check(len(step_res) == 1 and step_res[0].ok and ws_sf.join(".cache", "sif_keep_ok.json").path.is_file())
    finally:
        disp_sf.shutdown(grace_ms=100)

    # FlightCascade batch registration & seed_teardown_diagnostics preservation
    td_seed = ErrorDetail(ErrorCode.TEARDOWN_ERROR, "seed_td", source_task="t.seed")
    td_drain = ErrorDetail(ErrorCode.TEARDOWN_ERROR, "drain_td", source_task="t.drain")
    rec_s = RawEventRecord(EventId("fc.s"), TaskId("m.t"), {}, EventOrdering.UNORDERED)
    casc = FlightCascade(seed_events=(rec_s,), seed_teardown_diagnostics=(td_seed,))
    tok_0 = CancellationToken()
    tok_1 = CancellationToken()
    casc.register_caller_slots(
        (LiveFlightParticipant(0, tok_0, ()), LiveFlightParticipant(1, tok_1, ())),
        ExecutionPriority.FOREGROUND,
    )
    tok_0.cancel(reason="one_aborted")
    _check(not casc.drain_cg.host_token.is_cancelled)
    casc_out = casc.activate_and_await(
        1,
        CausalLineage(),
        tok_1,
        None,
        lambda _c: TurnExecutionReport(turn_id="d", primary_result=StepExecutionResult(ok=True), teardown_diagnostics=(td_drain,)),
    )
    _check(casc_out.teardown_diagnostics == (td_seed, td_drain))


def _verify_lock_transition_prechecks(ws_base: HostPath) -> None:
    lk_file = ws_base.join("lock_transition_prechecks.lock")
    pre_tok = CancellationToken()
    pre_tok.cancel(reason="pre_cancelled_transition")
    lk_pre = FileLock(lk_file)
    _check(lk_pre.acquire(shared=True, blocking=False))
    try:
        try:
            lk_pre.upgrade_to_exclusive(timeout_sec=1.0, cancel_token=pre_tok)
            raise AssertionError("Expected pre-cancelled upgrade to fail")
        except TaskCancelledException:
            pass
        try:
            lk_pre.upgrade_to_exclusive(timeout_sec=-1.0)
            raise AssertionError("Expected negative timeout upgrade to fail")
        except ValueError:
            pass
        _check(lk_pre.is_acquired)
    finally:
        lk_pre.release()

    lk_dn = FileLock(lk_file)
    _check(lk_dn.acquire(shared=False, blocking=False))
    try:
        try:
            lk_dn.downgrade_to_shared(timeout_sec=-1.0)
            raise AssertionError("Expected negative timeout downgrade to fail")
        except ValueError:
            pass
        _check(lk_dn.is_acquired)
    finally:
        lk_dn.release()


def _verify_superseded_preempt_queue_and_monotonic_guard(ws8: HostPath) -> None:
    guard_expired = DeadlineGuard(deadline=time.monotonic() - 0.05)
    try:
        guard_expired.remaining_ms(500)
        raise AssertionError("Expected expired DeadlineGuard to fail")
    except YscbError as exc:
        _check(exc.detail.code == ErrorCode.TASK_TIMEOUT)

    coord = ResourceCoordinator(HostPath(ws8.path / ".cache_pre_sup"))
    (ws8.path / ".cache_pre_sup").mkdir(parents=True, exist_ok=True)
    hold_entered = threading.Event()
    allow_holder_exit = threading.Event()

    def _run_holder(_ph: PriorityHandle, tok: CancellationToken, _fl: object) -> str:
        hold_entered.set()
        while not tok.is_cancelled:
            time.sleep(0.01)
        allow_holder_exit.wait(timeout=1.5)
        tok.raise_if_cancelled()
        return "holder"

    spec_h = ResourceAcquireSpec(
        resource_key="rk_sup_pre",
        mode=ConcurrencyMode.PREEMPT,
        equiv_key="h",
        priority=ExecutionPriority.FOREGROUND,
        turn_id="t_h",
        call_stack=((ws8, TaskId("sup.t")),),
        cancel_token=CancellationToken(),
    )
    spec_p1 = ResourceAcquireSpec(
        resource_key="rk_sup_pre",
        mode=ConcurrencyMode.PREEMPT,
        equiv_key="p1",
        priority=ExecutionPriority.FOREGROUND,
        turn_id="t_p1",
        call_stack=((ws8, TaskId("sup.t")),),
        cancel_token=CancellationToken(),
    )
    spec_p2 = ResourceAcquireSpec(
        resource_key="rk_sup_pre",
        mode=ConcurrencyMode.PREEMPT,
        equiv_key="p2",
        priority=ExecutionPriority.FOREGROUND,
        turn_id="t_p2",
        call_stack=((ws8, TaskId("sup.t")),),
        cancel_token=CancellationToken(),
    )
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
        fh = pool.submit(coord.execute, spec_h, _run_holder)
        _check(hold_entered.wait(timeout=1.5))
        fp1 = pool.submit(coord.execute, spec_p1, lambda _p, _t, _f: "p1")
        time.sleep(0.04)
        fp2 = pool.submit(coord.execute, spec_p2, lambda _p, _t, _f: "p2_win")
        time.sleep(0.04)
        allow_holder_exit.set()
        try:
            _ = fp1.result(timeout=2.0)
            raise AssertionError("Superseded preempt waiter must fail")
        except TaskCancelledException as exc_p1:
            _check(exc_p1.detail.code == ErrorCode.TASK_PREEMPTED)
        try:
            _ = fh.result(timeout=2.0)
        except TaskCancelledException as exc_h:
            _check(exc_h.detail.code == ErrorCode.TASK_PREEMPTED)
        out_p2 = fp2.result(timeout=2.0)
        _check(out_p2.outcome == "p2_win")


def _verify_daemon_gate_monotonic_deadline(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_md = HostPath(ws8.path / "ws_mono_dl")
    provision_live_workspace(ws_md.path)
    mdir = ws_md.path / ".modules" / "mdl"
    mdir.mkdir(parents=True, exist_ok=True)
    atomic_write_json(
        HostPath(mdir / "routes.json"),
        {"module_id": "mdl", "tier1": False, "tasks": [{"task_id": "mdl.slow", "timeout_ms": 300}]},
    )
    (mdir / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport time\nfrom typing import Sequence\n"
        "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.foundation.primitives import ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass MIn:\n    ms: int = 200\n"
        "@dataclass(frozen=True, slots=True)\nclass MOut:\n    ok: bool = True\n"
        "class SlowT(Task[MIn, MOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[MIn, MOut]:\n"
        "        return TaskMetadata(TaskId('mdl.slow'), MIn, MOut, timeout_ms=300)\n"
        "    def run(self, req: MIn, ctx: TaskContext) -> MOut:\n"
        "        for _ in range(max(1, req.ms // 15)):\n"
        "            ctx.cancel_token.raise_if_cancelled()\n"
        "            time.sleep(0.015)\n"
        "        return MOut()\n"
        "class MdlMod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('mdl')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (SlowT(),)\n"
        "def create_module() -> YscbModule: return MdlMod()\n",
        encoding="utf-8",
    )
    disp_md = build_dispatcher_for_workspace(ws_md, venv_bin, ttl_sec=20.0).dispatcher
    try:
        _check(disp_md.invoke(InvokeRequest(TaskId("mdl.slow"), {"ms": 15}, ws_md, ws_md)).ok)
        wait_for_daemon_online(ws_md)
        q_ok = query_daemon_control(ws_md.join(".cache"), ws_md, FrameKind.CONTROL_QUIESCE, {"modules": ["mdl"], "lease_sec": 5.0})
        _check(q_ok is not None and q_ok.get("ok") is True)
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
            t_start = time.monotonic()
            fut = pool.submit(
                disp_md.invoke,
                InvokeRequest(TaskId("mdl.slow"), {"ms": 210}, ws_md, ws_md, routing_policy=ClientRoutingPolicy.STRICT_HOT),
            )
            time.sleep(0.18)
            query_daemon_control(ws_md.join(".cache"), ws_md, FrameKind.CONTROL_RESUME, {})
            res = fut.result(timeout=3.0)
            elapsed = time.monotonic() - t_start
        _check(not res.ok and res.error is not None and res.error.code == ErrorCode.TASK_TIMEOUT)
        _check(elapsed < 0.55)
    finally:
        stop_daemon_cleanly(ws_md)
        disp_md.shutdown()


_DUAL_WS_A_MOD_SRC: Final[str] = (
    "from dataclasses import dataclass\nfrom typing import Optional, Sequence\n"
    "from core.execution.event import EventMetadata, EventOrdering, EventSubscriptionSpec\n"
    "from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule\n"
    "from core.foundation.primitives import EventId, HostPath, ModuleId, TaskId\n"
    "@dataclass(frozen=True, slots=True)\nclass CxaIn:\n    peer_ws: str = ''\n    hold_ms: int = 0\n"
    "@dataclass(frozen=True, slots=True)\nclass CxaOut:\n    tag: str = 'ok'\n"
    "EV_PING = EventMetadata(EventId('cxa.ping'), CxaIn, EventOrdering.UNORDERED)\n"
    "EV_LEAF = EventMetadata(EventId('cxa.leaf'), CxaIn, EventOrdering.ORDERED)\n"
    "def _map_cxa(items: Sequence[CxaIn]) -> Optional[CxaIn]: return items[-1] if items else None\n"
    "class SeedPingT(Task[CxaIn, CxaOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[CxaIn, CxaOut]: return TaskMetadata(TaskId('cxa.seed'), CxaIn, CxaOut)\n"
    "    def run(self, req: CxaIn, ctx: TaskContext) -> CxaOut:\n"
    "        ctx.emit(EV_PING, req)\n"
    "        return CxaOut('seeded')\n"
    "class PingSubBounceT(Task[CxaIn, CxaOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[CxaIn, CxaOut]:\n"
    "        return TaskMetadata(TaskId('cxa.sub_ping'), CxaIn, CxaOut, subscriptions=(EventSubscriptionSpec(EV_PING, _map_cxa),))\n"
    "    def run(self, req: CxaIn, ctx: TaskContext) -> CxaOut:\n"
    "        out = ctx.invoke_task(TaskId('cxb.coal_bounce'), {'peer_ws': str(ctx.workspace_root), 'hold_ms': req.hold_ms}, target_workspace=HostPath(req.peer_ws))\n"
    "        if not out.ok:\n"
    "            raise RuntimeError(out.error.message if out.error else 'bounce_err')\n"
    "        return CxaOut('bounced')\n"
    "class DeferredReemitT(Task[CxaIn, CxaOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[CxaIn, CxaOut]: return TaskMetadata(TaskId('cxa.reemit_def'), CxaIn, CxaOut)\n"
    "    def run(self, req: CxaIn, ctx: TaskContext) -> CxaOut:\n"
    "        ctx.emit(EV_PING, CxaIn(peer_ws=req.peer_ws))\n"
    "        return CxaOut('reemitted')\n"
    "class DoubleImmCoalT(Task[CxaIn, CxaOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[CxaIn, CxaOut]:\n"
    "        return TaskMetadata(TaskId('cxa.double_imm'), CxaIn, CxaOut, resource_key='rk_dimm', concurrency_mode=ConcurrencyMode.COALESCE)\n"
    "    def run(self, req: CxaIn, ctx: TaskContext) -> CxaOut:\n"
    "        ctx.emit_imm(EV_LEAF, req)\n"
    "        ctx.emit_imm(EV_LEAF, req)\n"
    "        return CxaOut('double_ok')\n"
    "class LeafSubT(Task[CxaIn, CxaOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[CxaIn, CxaOut]:\n"
    "        return TaskMetadata(TaskId('cxa.leaf_sub'), CxaIn, CxaOut, subscriptions=(EventSubscriptionSpec(EV_LEAF, _map_cxa),))\n"
    "    def run(self, req: CxaIn, ctx: TaskContext) -> CxaOut: return CxaOut('leaf')\n"
    "class CxaMod(YscbModule):\n"
    "    @property\n    def module_id(self) -> ModuleId: return ModuleId('cxa')\n"
    "    def tasks(self) -> Sequence[BoundTask]:\n"
    "        return (SeedPingT(), PingSubBounceT(), DeferredReemitT(), DoubleImmCoalT(), LeafSubT())\n"
    "def create_module() -> YscbModule: return CxaMod()\n"
)

