def _provision_dual_daemon_coalesce_workspaces(ws_a: HostPath, ws_b: HostPath) -> None:
    provision_live_workspace(ws_a.path)
    provision_live_workspace(ws_b.path)
    mda = ws_a.path / ".modules" / "cxa"
    mda.mkdir(parents=True, exist_ok=True)
    (mda / "module_entry.py").write_text(_DUAL_WS_A_MOD_SRC, encoding="utf-8")
    atomic_write_json(
        HostPath(mda / "routes.json"),
        {
            "module_id": "cxa",
            "tier1": False,
            "tasks": [
                {"task_id": "cxa.seed"},
                {"task_id": "cxa.sub_ping", "subscriptions": [{"event_id": "cxa.ping"}]},
                {"task_id": "cxa.reemit_def"},
                {"task_id": "cxa.double_imm", "resource_key": "rk_dimm", "concurrency_mode": "coalesce"},
                {"task_id": "cxa.leaf_sub", "subscriptions": [{"event_id": "cxa.leaf"}]},
            ],
        },
    )
    mdb = ws_b.path / ".modules" / "cxb"
    mdb.mkdir(parents=True, exist_ok=True)
    (mdb / "module_entry.py").write_text(_DUAL_WS_B_MOD_SRC, encoding="utf-8")
    atomic_write_json(
        HostPath(mdb / "routes.json"),
        {
            "module_id": "cxb",
            "tier1": False,
            "tasks": [{"task_id": "cxb.coal_bounce", "resource_key": "rk_cxb", "concurrency_mode": "coalesce"}],
        },
    )


def _verify_dual_daemon_coalesce_deferred_cycle_and_imm_hops(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_a = HostPath(ws8.path / "ws_dual_cxa")
    ws_b = HostPath(ws8.path / "ws_dual_cxb")
    _provision_dual_daemon_coalesce_workspaces(ws_a, ws_b)
    disp_a = build_dispatcher_for_workspace(ws_a, venv_bin, ttl_sec=25.0).dispatcher
    disp_b = build_dispatcher_for_workspace(ws_b, venv_bin, ttl_sec=25.0).dispatcher
    try:
        disp_a.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot_a"))
        disp_b.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot_b"))
        wait_for_daemon_online(ws_a)
        wait_for_daemon_online(ws_b)

        dimm = disp_a.invoke(InvokeRequest(TaskId("cxa.double_imm"), {}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        _check(dimm.ok)

        cyc_single = disp_a.invoke(
            InvokeRequest(TaskId("cxa.seed"), {"peer_ws": str(ws_b), "hold_ms": 0}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(not cyc_single.ok and cyc_single.error is not None)
        _check(cyc_single.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
        _check(cyc_single.error.source_task == "cxa.reemit_def")

        (ws_b.path / ".cache" / "cxb_entered.json").unlink(missing_ok=True)
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_clean = pool.submit(
                disp_b.invoke,
                InvokeRequest(
                    TaskId("cxb.coal_bounce"),
                    {"peer_ws": str(ws_a), "hold_ms": 180},
                    ws_b,
                    ws_b,
                    routing_policy=ClientRoutingPolicy.STRICT_HOT,
                ),
            )
            _wait_file_marker(ws_b.path / ".cache" / "cxb_entered.json")
            f_cycled = pool.submit(
                disp_a.invoke,
                InvokeRequest(
                    TaskId("cxa.seed"),
                    {"peer_ws": str(ws_b), "hold_ms": 180},
                    ws_a,
                    ws_a,
                    routing_policy=ClientRoutingPolicy.STRICT_HOT,
                ),
            )
            r_clean = f_clean.result(timeout=6.0)
            r_cycled = f_cycled.result(timeout=6.0)
        _check(r_clean.ok)
        _check(not r_cycled.ok and r_cycled.error is not None)
        _check(r_cycled.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
        _check(r_cycled.error.source_task == "cxa.reemit_def")
    finally:
        stop_daemon_cleanly(ws_a)
        stop_daemon_cleanly(ws_b)
        disp_a.shutdown()
        disp_b.shutdown()


_QUIESCE_NESTED_MOD_SRC: Final[str] = (
    "from dataclasses import dataclass\nimport time\nfrom typing import Sequence\n"
    "from core.execution.event import EventMetadata, EventOrdering\n"
    "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
    "from core.filesystem.fs import atomic_write_json\n"
    "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
    "@dataclass(frozen=True, slots=True)\nclass QIn:\n    phase: str = 'fast'\n    ms: int = 0\n"
    "@dataclass(frozen=True, slots=True)\nclass QOut:\n    tag: str = 'ok'\n"
    "EV_Q = EventMetadata(EventId('qouter.ev'), QIn, EventOrdering.UNORDERED)\n"
    "class OuterSpanT(Task[QIn, QOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[QIn, QOut]: return TaskMetadata(TaskId('qouter.span'), QIn, QOut)\n"
    "    def run(self, req: QIn, ctx: TaskContext) -> QOut:\n"
    "        if req.phase == 'emit_ev':\n"
    "            ctx.emit(EV_Q, req)\n"
    "            return QOut('emitted')\n"
    "        if req.phase == 'wait_then_call':\n"
    "            atomic_write_json(ctx.workspace_root.join('.cache', 'qouter_started.json'), {'in': True})\n"
    "            go_f = ctx.workspace_root.join('.cache', 'qouter_go.json').path\n"
    "            while not go_f.is_file(): time.sleep(0.015)\n"
    "            sub = ctx.invoke_task(TaskId('qinner.work'), {'ms': 10})\n"
    "            if not sub.ok: raise RuntimeError(sub.error.message if sub.error else 'inner_err')\n"
    "            return QOut('pre_turn_completed')\n"
    "        sub2 = ctx.invoke_task(TaskId('qinner.work'), {'ms': req.ms})\n"
    "        if not sub2.ok: raise RuntimeError(sub2.error.message if sub2.error else 'busy_err')\n"
    "        return QOut('nested_done')\n"
    "class QOuterMod(YscbModule):\n"
    "    @property\n    def module_id(self) -> ModuleId: return ModuleId('qouter')\n"
    "    def tasks(self) -> Sequence[BoundTask]: return (OuterSpanT(),)\n"
    "def create_module() -> YscbModule: return QOuterMod()\n"
)

_QUIESCE_INNER_MOD_SRC: Final[str] = (
    "from dataclasses import dataclass\nimport time\nfrom typing import Optional, Sequence\n"
    "from core.execution.event import EventMetadata, EventOrdering, EventSubscriptionSpec\n"
    "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
    "from core.filesystem.fs import atomic_write_json\n"
    "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
    "@dataclass(frozen=True, slots=True)\nclass QIIn:\n    phase: str = 'fast'\n    ms: int = 0\n"
    "@dataclass(frozen=True, slots=True)\nclass QIOut:\n    tag: str = 'ok'\n"
    "EV_Q = EventMetadata(EventId('qouter.ev'), QIIn, EventOrdering.UNORDERED)\n"
    "def _map_qi(items: Sequence[QIIn]) -> Optional[QIIn]: return items[-1] if items else None\n"
    "class InnerWorkT(Task[QIIn, QIOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[QIIn, QIOut]:\n"
    "        return TaskMetadata(TaskId('qinner.work'), QIIn, QIOut, subscriptions=(EventSubscriptionSpec(EV_Q, _map_qi),))\n"
    "    def run(self, req: QIIn, ctx: TaskContext) -> QIOut:\n"
    "        if req.ms >= 200:\n"
    "            atomic_write_json(ctx.workspace_root.join('.cache', 'qinner_busy.json'), {'in': True})\n"
    "        if req.ms > 0: time.sleep(req.ms / 1000.0)\n"
    "        return QIOut('inner_ok')\n"
    "class QInnerMod(YscbModule):\n"
    "    @property\n    def module_id(self) -> ModuleId: return ModuleId('qinner')\n"
    "    def tasks(self) -> Sequence[BoundTask]: return (InnerWorkT(),)\n"
    "def create_module() -> YscbModule: return QInnerMod()\n"
)


