def _verify_quiesce_nested_drain_accepted_turn_and_broken_reload(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_qn = HostPath(ws8.path / "ws_quiesce_nested")
    _provision_quiesce_nested_workspace(ws_qn)
    disp_qn = build_dispatcher_for_workspace(ws_qn, venv_bin, ttl_sec=25.0).dispatcher
    try:
        disp_qn.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="boot_qn"))
        wait_for_daemon_online(ws_qn)
        _exercise_quiesce_busy_and_pre_accepted_turn(ws_qn, disp_qn)
        _exercise_deleted_module_resume_and_broken_reload(ws_qn)
    finally:
        stop_daemon_cleanly(ws_qn)
        disp_qn.shutdown()


def _exercise_quiesce_busy_and_pre_accepted_turn(ws_qn: HostPath, disp_qn: RuntimeDispatcher) -> None:
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        f_busy = pool.submit(
            disp_qn.invoke,
            InvokeRequest(TaskId("qouter.span"), {"phase": "nested_hold", "ms": 380}, ws_qn, ws_qn, routing_policy=ClientRoutingPolicy.STRICT_HOT),
        )
        _wait_file_marker(ws_qn.path / ".cache" / "qinner_busy.json")
        q_busy = query_daemon_control(
            ws_qn.join(".cache"), ws_qn, FrameKind.CONTROL_QUIESCE, {"modules": ["qinner"], "lease_sec": 5.0, "drain_timeout_sec": 0.08}
        )
        _check(q_busy is not None and q_busy.get("ok") is False and q_busy.get("error") == "daemon_busy")
        _check(f_busy.result(timeout=4.0).ok)

        f_pre = pool.submit(
            disp_qn.invoke,
            InvokeRequest(TaskId("qouter.span"), {"phase": "wait_then_call"}, ws_qn, ws_qn, routing_policy=ClientRoutingPolicy.STRICT_HOT),
        )
        _wait_file_marker(ws_qn.path / ".cache" / "qouter_started.json")
        q_ok = query_daemon_control(
            ws_qn.join(".cache"), ws_qn, FrameKind.CONTROL_QUIESCE, {"modules": ["qinner"], "lease_sec": 6.0, "drain_timeout_sec": 0.4}
        )
        _check(q_ok is not None and q_ok.get("ok") is True)
        atomic_write_json(ws_qn.join(".cache", "qouter_go.json"), {"go": True})
        time.sleep(0.08)
        _check(not f_pre.done())
        ev_out = disp_qn.invoke(
            InvokeRequest(TaskId("qouter.span"), {"phase": "emit_ev"}, ws_qn, ws_qn, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(ev_out.ok and any(d.code == ErrorCode.DAEMON_UNAVAILABLE for d in ev_out.event_diagnostics))
        query_daemon_control(ws_qn.join(".cache"), ws_qn, FrameKind.CONTROL_RESUME, {})
        _check(f_pre.result(timeout=4.0).ok)


def _exercise_deleted_module_resume_and_broken_reload(ws_qn: HostPath) -> None:
    md_tmp = ws_qn.path / ".modules" / "qtemp"
    q_tmp = query_daemon_control(ws_qn.join(".cache"), ws_qn, FrameKind.CONTROL_QUIESCE, {"modules": ["qtemp"], "lease_sec": 5.0})
    _check(q_tmp is not None and q_tmp.get("ok") is True)
    md_tmp.mkdir(parents=True, exist_ok=True)
    atomic_write_json(HostPath(md_tmp / "routes.json"), {"module_id": "qtemp", "tier1": False, "tasks": []})
    (md_tmp / "routes.json").unlink()
    md_tmp.rmdir()
    r_tmp = query_daemon_control(ws_qn.join(".cache"), ws_qn, FrameKind.CONTROL_RESUME, {})
    _check(r_tmp is not None and r_tmp.get("ok") is True)

    (ws_qn.path / ".modules" / "qinner" / "routes.json").unlink(missing_ok=True)
    (ws_qn.path / ".modules" / "qinner" / "module_entry.py").write_text(
        "from core.execution.runtime import YscbModule\n"
        "def create_module() -> YscbModule:\n"
        "    raise RuntimeError('broken_after_reload')\n",
        encoding="utf-8",
    )
    rel_out = query_daemon_control(ws_qn.join(".cache"), ws_qn, FrameKind.CONTROL_RELOAD, {"modules": ["qinner"]})
    _check(rel_out is not None and rel_out.get("ok") is True)
    st = query_daemon_control(ws_qn.join(".cache"), ws_qn, FrameKind.CONTROL_STATUS)
    _check(st is not None and isinstance(st.get("status"), Mapping))
    _check("qinner" in st["status"].get("degraded_modules", []))


_SCOPED_LOADER_ADV_MOD_SRC: Final[str] = (
    "from dataclasses import dataclass\nimport importlib\nimport threading\nimport time\nfrom typing import Callable, Optional, Sequence\n"
    "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
    "from core.filesystem.fs import atomic_write_json\n"
    "from core.foundation.primitives import HostPath, ModuleId, TaskId\n"
    "@dataclass(frozen=True, slots=True)\nclass SIn:\n    hold_ms: int = 0\n"
    "@dataclass(frozen=True, slots=True)\nclass SOut:\n    vals: str\n"
    "class ScopeAdvT(Task[SIn, SOut]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[SIn, SOut]: return TaskMetadata(TaskId('sadv.op'), SIn, SOut)\n"
    "    def run(self, req: SIn, ctx: TaskContext) -> SOut:\n"
    "        res_box: list[str] = []\n"
    "        def _th() -> None:\n"
    "            m_th = importlib.import_module('sib_thread')\n"
    "            m_rel = importlib.import_module('.sub_leaf', package='subpkg')\n"
    "            res_box.append(f'{m_th.TAG}:{m_rel.LEAF}')\n"
    "        t = threading.Thread(target=_th)\n"
    "        t.start()\n"
    "        t.join(timeout=2.0)\n"
    "        if req.hold_ms > 0:\n"
    "            atomic_write_json(ctx.workspace_root.join('.cache', 'sadv_in.json'), {'in': True})\n"
    "            time.sleep(req.hold_ms / 1000.0)\n"
    "        return SOut(vals=res_box[0] if res_box else 'missing')\n"
    "class SAdvMod(YscbModule):\n"
    "    @property\n    def module_id(self) -> ModuleId: return ModuleId('sadv')\n"
    "    def tasks(self) -> Sequence[BoundTask]: return (ScopeAdvT(),)\n"
    "    def on_init(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:\n"
    "        def _close() -> None:\n"
    "            atomic_write_json(workspace_root.join('.cache', 'sadv_closed.json'), {'tag': importlib.import_module('sib_close').CLOSED})\n"
    "            if workspace_root.join('.cache', 'sadv_fail_stop.json').path.is_file():\n"
    "                raise RuntimeError('retiring_stop_boom')\n"
    "        return _close\n"
    "def create_module() -> YscbModule: return SAdvMod()\n"
)


def _verify_scoped_loader_threads_closers_and_handoff_rpc(ws8: HostPath) -> None:
    ws_sa = HostPath(ws8.path / "ws_scoped_adv")
    provision_live_workspace(ws_sa.path)
    mdir = ws_sa.path / ".modules" / "sadv"
    (mdir / "subpkg").mkdir(parents=True, exist_ok=True)
    (mdir / "sib_thread.py").write_text("TAG = 'TH_OK'\n", encoding="utf-8")
    (mdir / "sib_close.py").write_text("CLOSED = 'CL_OK'\n", encoding="utf-8")
    (mdir / "subpkg" / "sub_leaf.py").write_text("LEAF = 'LF_OK'\n", encoding="utf-8")
    (mdir / "module_entry.py").write_text(_SCOPED_LOADER_ADV_MOD_SRC, encoding="utf-8")
    desc = ModuleDescriptor(
        module_id=ModuleId("sadv"),
        module_dir=HostPath(mdir),
        declared_tasks=(TaskRouteSpec(task_id=TaskId("sadv.op")),),
    )
    disp_sa = RuntimeDispatcher(
        workspace_root=ws_sa,
        cache_dir=ws_sa.join(".cache"),
        module_provider=_SingleProbeProvider(desc),
        options=DispatcherHostOptions(is_daemon_host=True),
    )
    try:
        r0 = disp_sa.invoke(InvokeRequest(TaskId("sadv.op"), {"hold_ms": 0}, ws_sa, ws_sa))
        _check(r0.ok and isinstance(r0.value, Mapping) and r0.value.get("vals") == "TH_OK:LF_OK")
        _check("sib_thread" not in sys.modules and "sib_close" not in sys.modules and "subpkg" not in sys.modules)

        disp_sa.reload_affected_modules(frozenset({ModuleId("sadv")}))
        closed_doc = read_json_dict(ws_sa.join(".cache", "sadv_closed.json"))
        _check(closed_doc is not None and closed_doc.get("tag") == "CL_OK")

        atomic_write_json(ws_sa.join(".cache", "sadv_fail_stop.json"), {"boom": True})
        slot_stack = LifoResourceStack()
        slots = LocalModuleSlotRegistry(ws_sa, slot_stack)
        slots.register_descriptors([desc])
        cbs = StepContextCallbacks(
            on_emit_imm=lambda _e, _p, _l, _s: None,
            on_invoke_task=lambda _t, _i, _c, _r: TaskOutcome(ok=True),
            on_progress=lambda _p: None,
        )
        lspec = LocalStepExecutionSpec(
            task_id=TaskId("sadv.op"),
            raw_input={"hold_ms": 180},
            caller_cwd=ws_sa,
            caller_env={},
            base_lineage=CausalLineage(),
            cancel_token=CancellationToken(),
            priority_getter=lambda: ExecutionPriority.FOREGROUND,
            callbacks=cbs,
        )
        (ws_sa.path / ".cache" / "sadv_in.json").unlink(missing_ok=True)
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
            f_slot = pool.submit(slots.execute_step_locally, lspec)
            _wait_file_marker(ws_sa.path / ".cache" / "sadv_in.json")
            _check(slots.unload_modules(frozenset({ModuleId("sadv")}), drain_in_flight=False) == ())
            rep_slot = f_slot.result(timeout=4.0)
        _check(rep_slot.ok and any(d.code == ErrorCode.TEARDOWN_ERROR for d in rep_slot.teardown_diagnostics))
        slot_stack.close_all_lifo()
    finally:
        disp_sa.shutdown()


class _EchoHandoffHandler(InboundCallHandler):
    def __init__(self, accept: bool) -> None:
        self._accept = accept

    def on_call(
        self,
        _stream_id: int,
        payload: JsonObject,
        ack_accepted: typing.Callable[[], bool],
        _emit_progress: typing.Callable[[JsonObject], None],
        _peer_cancel_token: CancellationToken,
    ) -> tuple[bool, JsonObject]:
        if not self._accept:
            return (False, {"ok": False})
        ack_accepted()
        return (True, {"ok": True, "echo": payload.get("v")})

    def on_control(self, kind: FrameKind, payload: JsonObject) -> JsonObject:
        _ = (kind, payload)
        return {"ok": True}


def _verify_default_handoff_reconnect_and_stalled_handshake(ws8: HostPath) -> None:
    ws_hf = HostPath(ws8.path / "ws_rpc_handoff_def")
    cdir = ws_hf.join(".cache")
    (cdir.path / "daemon").mkdir(parents=True, exist_ok=True)
    l1 = RpcServerListener(ws_hf, _EchoHandoffHandler(accept=False), boot_id="boot_old_1")
    ep1 = l1.start()
    ep_file = cdir.join("daemon", "daemon.json")
    atomic_write_json(ep_file, DataclassCodec.encode_object(ep1))
    atomic_write_json(cdir.join("daemon", "handoff_lease.json"), {"old_boot_id": "boot_old_1", "expires_epoch": time.time() + 5.0})
    _check(read_active_handoff_boot_id(cdir) == "boot_old_1")

    l2 = RpcServerListener(ws_hf, _EchoHandoffHandler(accept=True), boot_id="boot_new_2")
    ep2 = l2.start()
    sess = PersistentRpcSession(cdir, ws_hf)
    try:
        def _swap_endpoint() -> None:
            time.sleep(0.08)
            l1.close_all()
            atomic_write_json(ep_file, DataclassCodec.encode_object(ep2))

        swap_th = threading.Thread(target=_swap_endpoint, daemon=True)
        swap_th.start()
        try:
            out_s = sess.call({"v": 42}, timeout_ms=3000)
            _check(out_s is not None and out_s.was_accepted and out_s.result_payload == {"ok": True, "echo": 42})
            out_e = call_ephemeral_daemon_rpc((cdir, ws_hf), {"v": 99}, timeout_ms=2000)
            _check(out_e is not None and out_e.was_accepted and out_e.result_payload == {"ok": True, "echo": 99})
        finally:
            swap_th.join(timeout=1.0)
    finally:
        sess.close()
        l1.close_all()
        l2.close_all()

    l_stall = RpcServerListener(ws_hf, _EchoHandoffHandler(accept=True), boot_id="boot_stall")
    ep_st = l_stall.start()
    raw_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        raw_sock.connect((ep_st.host, ep_st.port))
        time.sleep(0.04)
        t0 = time.monotonic()
        l_stall.stop_accepting()
        _check((time.monotonic() - t0) < 0.6)
    finally:
        raw_sock.close()
        l_stall.close_all()


def _verify_filelock_phase_and_reentrant_pin(ws8: HostPath) -> None:
    lk_path = ws8.join(".cache", "locks", "phase_race.lock")
    for _ in range(12):
        holder = FileLock(lk_path)
        blocker = FileLock(lk_path)
        _check(holder.acquire(shared=True, blocking=False))
        _check(blocker.acquire(shared=True, blocking=False))
        rel_done = threading.Event()
        err_box: list[BaseException] = []

        def _try_upg(h: FileLock = holder, eb: list[BaseException] = err_box) -> None:
            try:
                h.upgrade_to_exclusive(timeout_sec=0.08)
            except YscbError:
                pass
            except BaseException as exc:
                eb.append(exc)

        t = threading.Thread(target=_try_upg, daemon=True)
        t.start()
        time.sleep(0.015)
        holder.release()
        t.join(timeout=2.0)
        blocker.release()
        rel_done.set()
        _check(rel_done.is_set() and not err_box and not holder.is_acquired)
        probe = FileLock(lk_path)
        _check(probe.acquire(shared=False, blocking=False))
        probe.release()

    # Verify failed upgrade timeout preserves shared OS lock against an exclusive contender
    sh1 = FileLock(lk_path)
    sh2 = FileLock(lk_path)
    ex3 = FileLock(lk_path)
    _check(sh1.acquire(shared=True, blocking=False) and sh2.acquire(shared=True, blocking=False))
    try:
        try:
            sh1.upgrade_to_exclusive(timeout_sec=0.04)
            raise AssertionError("Expected upgrade timeout")
        except YscbError as exc:
            _check(exc.detail.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
        sh2.release()
        _check(sh1.is_acquired and not ex3.acquire(shared=False, blocking=False))
    finally:
        sh1.release()
        ex3.release()


def _provision_callback_t1_mod(ws_d: HostPath) -> None:
    md_t1 = ws_d.path / ".modules" / "cb_t1"
    md_t1.mkdir(parents=True, exist_ok=True)
    atomic_write_json(
        HostPath(md_t1 / "routes.json"),
        {
            "module_id": "cb_t1",
            "tier1": True,
            "venv_group": "cb_grp",
            "eager_warmup": True,
            "tasks": [
                {"task_id": "cb_t1.short_parent", "timeout_ms": 400},
                {"task_id": "cb_t1.dyn_coal", "resource_key": "rk_dyn_dl", "concurrency_mode": "coalesce"},
            ],
        },
    )
    (md_t1 / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport time\nfrom typing import Callable, Optional, Sequence\n"
        "from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.filesystem.fs import atomic_write_json\n"
        "from core.foundation.primitives import HostPath, ModuleId, TaskId\n"
        "def _boom_close() -> None:\n    raise RuntimeError('t1_close_boom')\n"
        "@dataclass(frozen=True, slots=True)\nclass CIn:\n    ms: int = 0\n"
        "@dataclass(frozen=True, slots=True)\nclass COut:\n    ok: bool = True\n"
        "class ShortParent(Task[CIn, COut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[CIn, COut]:\n"
        "        return TaskMetadata(TaskId('cb_t1.short_parent'), CIn, COut, timeout_ms=400)\n"
        "    def run(self, req: CIn, ctx: TaskContext) -> COut:\n"
        "        _ = ctx.invoke_task(TaskId('cb_t0.slow_child'), {'ms': req.ms})\n"
        "        return COut()\n"
        "class DynCoal(Task[CIn, COut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[CIn, COut]:\n"
        "        return TaskMetadata(TaskId('cb_t1.dyn_coal'), CIn, COut, resource_key='rk_dyn_dl', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda _r: 'same_dl')\n"
        "    def run(self, req: CIn, ctx: TaskContext) -> COut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 'dyn_in.json'), {'in': True})\n"
        "        time.sleep(0.45)\n"
        "        sub = ctx.invoke_task(TaskId('cb_t0.slow_child'), {'ms': 40})\n"
        "        return COut(ok=sub.ok)\n"
        "class CbT1Mod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('cb_t1')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (ShortParent(), DynCoal())\n"
        "    def on_init(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:\n"
        "        flag = workspace_root.join('.cache', 'fail_t1_close.flag')\n"
        "        return _boom_close if flag.path.exists() else None\n"
        "def create_module() -> YscbModule: return CbT1Mod()\n",
        encoding="utf-8",
    )


def _provision_deadline_and_callback_mod(ws_d: HostPath) -> None:
    _provision_callback_t1_mod(ws_d)
    md_t0 = ws_d.path / ".modules" / "cb_t0"
    md_t0.mkdir(parents=True, exist_ok=True)
    atomic_write_json(
        HostPath(md_t0 / "routes.json"),
        {
            "module_id": "cb_t0",
            "tier1": False,
            "eager_warmup": False,
            "tasks": [
                {"task_id": "cb_t0.slow_child"},
                {"task_id": "cb_t0.uncapped_hang"},
            ],
        },
    )
    (md_t0 / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport threading\nimport time\nfrom typing import Sequence\n"
        "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.filesystem.fs import atomic_write_json\n"
        "from core.foundation.primitives import ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass SIn:\n    ms: int = 0\n"
        "@dataclass(frozen=True, slots=True)\nclass SOut:\n    cancelled: bool = False\n"
        "class SlowChild(Task[SIn, SOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[SIn, SOut]: return TaskMetadata(TaskId('cb_t0.slow_child'), SIn, SOut)\n"
        "    def run(self, req: SIn, ctx: TaskContext) -> SOut:\n"
        "        dl = time.monotonic() + (req.ms / 1000.0)\n"
        "        while time.monotonic() < dl:\n"
        "            if ctx.cancel_token.is_cancelled:\n"
        "                atomic_write_json(ctx.workspace_root.join('.cache', 'slow_child_cancelled.json'), {'c': True})\n"
        "                ctx.cancel_token.raise_if_cancelled()\n"
        "            time.sleep(0.02)\n"
        "        return SOut(cancelled=False)\n"
        "class UncappedHang(Task[SIn, SOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[SIn, SOut]: return TaskMetadata(TaskId('cb_t0.uncapped_hang'), SIn, SOut)\n"
        "    def run(self, req: SIn, ctx: TaskContext) -> SOut:\n"
        "        atomic_write_json(ctx.workspace_root.join('.cache', 't0_hang_in.json'), {'in': True})\n"
        "        threading.Event().wait(timeout=2.5)\n"
        "        return SOut()\n"
        "class CbT0Mod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('cb_t0')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (SlowChild(), UncappedHang())\n"
        "def create_module() -> YscbModule: return CbT0Mod()\n",
        encoding="utf-8",
    )


def _verify_callback_cancel_dyn_deadline_and_t0_cancel(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_d = HostPath(ws8.path / "ws_case_dl")
    provision_live_workspace(ws_d.path)
    _provision_deadline_and_callback_mod(ws_d)
    disp_hot = build_dispatcher_for_workspace(ws_d, venv_bin, is_daemon_host=True).dispatcher
    try:
        disp_hot.warmup_daemon_container()
        # 1) Tier 1 parent step timeout immediately cancels active Master callback
        t0 = time.monotonic()
        out_to = disp_hot.invoke(InvokeRequest(TaskId("cb_t1.short_parent"), {"ms": 3000}, ws_d, ws_d))
        _check(not out_to.ok and out_to.error is not None and out_to.error.code == ErrorCode.TASK_TIMEOUT)
        _wait_file_marker(ws_d.path / ".cache" / "slow_child_cancelled.json", timeout_sec=1.5)
        _check((time.monotonic() - t0) < 1.8)

        # 2) Dynamic COALESCE deadline: short RPC caller times out while unbounded follower succeeds
        disp_hot.warmup_daemon_container()
        env_short = DataclassCodec.encode_object(
            DaemonRpcInvokeEnvelope(
                task_id=TaskId("cb_t1.dyn_coal"), raw_input={}, workspace_root=ws_d, caller_cwd=ws_d, timeout_ms=300
            )
        )
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_short = pool.submit(disp_hot.invoke_daemon_rpc, env_short, CancellationToken(), lambda _p: None)
            _wait_file_marker(ws_d.path / ".cache" / "dyn_in.json", timeout_sec=3.0)
            f_long = pool.submit(disp_hot.invoke, InvokeRequest(TaskId("cb_t1.dyn_coal"), {}, ws_d, ws_d))
            r_short, r_long = f_short.result(timeout=4.0), f_long.result(timeout=4.0)
        _check(not r_short.ok and r_short.error is not None and r_short.error.code == ErrorCode.TASK_TIMEOUT)
        _check(r_long.ok and r_long.value == {"ok": True})

        # 3) Uncapped non-TTY Tier 0 step returns promptly within grace_sec on cancel_token.cancel()
        tok_u = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
            fu = pool.submit(disp_hot.invoke, InvokeRequest(TaskId("cb_t0.uncapped_hang"), {}, ws_d, ws_d), cancel_token=tok_u)
            _wait_file_marker(ws_d.path / ".cache" / "t0_hang_in.json", timeout_sec=2.0)
            t_cancel = time.monotonic()
            tok_u.cancel(reason="abort_uncapped")
            ru = fu.result(timeout=1.5)
        _check(not ru.ok and ru.error is not None and ru.error.code == ErrorCode.TASK_CANCELLED)
        _check((time.monotonic() - t_cancel) < 0.8)

        # 4) Cold Turn OneShotVenvHost CONTROL_STOP teardown_diagnostics propagation
        (ws_d.path / ".cache" / "fail_t1_close.flag").write_text("1", encoding="utf-8")
        disp_cold = build_dispatcher_for_workspace(ws_d, venv_bin, is_daemon_host=False, sandbox_restricted=True).dispatcher
        try:
            cold_td = disp_cold.invoke(
                InvokeRequest(TaskId("cb_t1.dyn_coal"), {}, ws_d, ws_d, routing_policy=ClientRoutingPolicy.FORCE_COLD)
            )
            _check(cold_td.ok and any(d.code == ErrorCode.TEARDOWN_ERROR for d in cold_td.teardown_diagnostics))
        finally:
            disp_cold.shutdown(grace_ms=100)
    finally:
        disp_hot.shutdown(grace_ms=100)


def _verify_selective_quiesce_deleted_mod_and_child_cascade(ws8: HostPath, venv_bin: HostPath) -> None:
    # 1) Nested ChildCascadeJoin snapshot_emitted_hops() & source_task attribution
    ev_p, ev_c = EventId("cas.ev_parent"), EventId("cas.ev_child")
    child_c = FlightCascade(imm_hops=(EmittedEventHop("ws_s", ev_c, "mod.child_task"),))
    parent_c = FlightCascade(imm_hops=(EmittedEventHop("ws_s", ev_p, "mod.parent_task"),))
    parent_c.add_child_join((EmittedEventHop("ws_s", ev_p, "mod.parent_task"),), child_c)
    snapped = parent_c.snapshot_emitted_hops()
    _check({(h.event_id, h.source_task) for h in snapped} == {(ev_p, "mod.parent_task"), (ev_c, "mod.child_task")})

    # 2) Selective quiesce keeps container READY, skips quiesced warmup without MODULE_DEGRADED, and stops deleted module worker
    ws_q = HostPath(ws8.path / "ws_case_selq")
    provision_live_workspace(ws_q.path)
    rig = build_dispatcher_for_workspace(ws_q, venv_bin, is_daemon_host=True)
    disp_q, prov_q = rig.dispatcher, rig.config_view
    try:
        disp_q.warmup_daemon_container()
        _check(disp_q.invoke(
            InvokeRequest(TaskId("gdrive.put"), {"local_rel": "./sample.py"}, ws_q, HostPath(ws_q.path / "sub_dir"))
        ).ok)
        snaps_before = disp_q.tier1_pool.active_worker_snapshots()
        gd_pids = [s.pid for s in snaps_before if s.group == "mod_gdrive"]
        _check(len(gd_pids) == 1 and is_process_alive(gd_pids[0]))

        disp_q.quiesce_modules(frozenset({ModuleId("gdrive")}))
        _check(disp_q.container_lifecycle.state.value == "quiesced")
        disp_q.warmup_daemon_container(only_modules=frozenset({ModuleId("gdrive")}))
        _check(disp_q.container_lifecycle.get_degraded(ModuleId("gdrive")) is None)
        disp_q.resume_from_quiesce()
        _check(disp_q.container_lifecycle.state.value == "ready")

        # Respawn gdrive worker, then delete gdrive directory from disk and reload_affected_modules({gdrive})
        _check(disp_q.invoke(
            InvokeRequest(TaskId("gdrive.put"), {"local_rel": "./sample.py"}, ws_q, HostPath(ws_q.path / "sub_dir"))
        ).ok)
        gd_pid2 = [s.pid for s in disp_q.tier1_pool.active_worker_snapshots() if s.group == "mod_gdrive"][0]
        for f in sorted((ws_q.path / ".modules" / "gdrive").rglob("*"), reverse=True):
            if f.is_file():
                f.unlink()
            elif f.is_dir():
                f.rmdir()
        (ws_q.path / ".modules" / "gdrive").rmdir()
        prov_q.reload()
        disp_q.reload_affected_modules(frozenset({ModuleId("gdrive")}))
        _check(not is_process_alive(gd_pid2))
    finally:
        disp_q.shutdown(grace_ms=100)


def _provision_cross_reentrant_mod(ws_r: HostPath) -> None:
    mr = ws_r.path / ".modules" / "xre"
    mr.mkdir(parents=True, exist_ok=True)
    atomic_write_json(
        HostPath(mr / "routes.json"),
        {
            "module_id": "xre",
            "tier1": False,
            "eager_warmup": False,
            "tasks": [
                {"task_id": "xre.step1", "resource_key": "rk_xre", "concurrency_mode": "coalesce"},
                {"task_id": "xre.step2", "resource_key": "rk_xre", "concurrency_mode": "coalesce"},
            ],
        },
    )
    (mr / "module_entry.py").write_text(
        "from dataclasses import dataclass\nfrom typing import Sequence\n"
        "from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.foundation.primitives import ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass XIn:\n    k: str = 'a'\n"
        "@dataclass(frozen=True, slots=True)\nclass XOut:\n    k: str = ''\n"
        "class XStep1(Task[XIn, XOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[XIn, XOut]:\n"
        "        return TaskMetadata(TaskId('xre.step1'), XIn, XOut, resource_key='rk_xre', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.k)\n"
        "    def run(self, req: XIn, ctx: TaskContext) -> XOut: return XOut(k=req.k)\n"
        "class XStep2(Task[XIn, XOut]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[XIn, XOut]:\n"
        "        return TaskMetadata(TaskId('xre.step2'), XIn, XOut, resource_key='rk_xre', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.k)\n"
        "    def run(self, req: XIn, ctx: TaskContext) -> XOut: return XOut(k=req.k)\n"
        "class XMod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('xre')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (XStep1(), XStep2())\n"
        "def create_module() -> YscbModule: return XMod()\n",
        encoding="utf-8",
    )


def _verify_cross_proc_reentrant_pin_and_watcher_v2_edit(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_r = HostPath(ws8.path / "ws_case_xreent")
    provision_live_workspace(ws_r.path)
    _provision_cross_reentrant_mod(ws_r)
    disp_a = build_dispatcher_for_workspace(ws_r, venv_bin, is_daemon_host=True).dispatcher
    disp_b = build_dispatcher_for_workspace(ws_r, venv_bin, is_daemon_host=True).dispatcher
    try:
        # Simulate cross-process owner file written by process A for call_tree_id='tree_x1' holding mode='coalesce'
        coord_a = ResourceCoordinator(ws_r.join(".cache", "locks"))
        entered = threading.Event()
        release = threading.Event()

        def _hold_coal() -> str:
            res = coord_a.execute(
                ResourceAcquireSpec(
                    resource_key="rk_xre",
                    mode=ConcurrencyMode.COALESCE,
                    equiv_key="eq_1",
                    priority=ExecutionPriority.FOREGROUND,
                    turn_id="t_outer",
                    call_stack=((ws_r, TaskId("xre.step1")),),
                    cancel_token=CancellationToken(),
                    call_tree_id="tree_x1",
                ),
                leader_fn=lambda _ph, _ec, _fl: (entered.set(), release.wait(timeout=3.0), "done")[2],
            )
            return res.outcome or ""

        th = threading.Thread(target=_hold_coal, daemon=True)
        th.start()
        _check(entered.wait(timeout=2.0))
        try:
            t_start = time.monotonic()
            reent_out = disp_b.invoke(
                InvokeRequest(
                    TaskId("xre.step2"),
                    {"k": "eq_2"},
                    ws_r,
                    ws_r,
                    propagation=CallPropagationContext(call_tree_id="tree_x1", call_stack=((ws_r, TaskId("xre.step1")),)),
                )
            )
            _check((time.monotonic() - t_start) < 0.8)
            _check(not reent_out.ok and reent_out.error is not None)
            _check(reent_out.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
        finally:
            release.set()
            th.join(timeout=2.0)
    finally:
        disp_a.shutdown(grace_ms=100)
        disp_b.shutdown(grace_ms=100)


def _verify_direct_frame_importlib_isolation(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_imp = HostPath(ws8.path / "ws_case_imp")
    provision_live_workspace(ws_imp.path)
    mi = ws_imp.path / ".modules" / "imp_mod"
    (mi / "subpkg").mkdir(parents=True, exist_ok=True)
    (mi / "subpkg" / "leaf.py").write_text("LEAF_TAG = 'leaf_ok'\n", encoding="utf-8")
    (mi / "sib.py").write_text("from .subpkg import leaf\nSIB_TAG = leaf.LEAF_TAG\n", encoding="utf-8")
    atomic_write_json(
        HostPath(mi / "routes.json"),
        {"module_id": "imp_mod", "tier1": False, "eager_warmup": False, "tasks": [{"task_id": "imp_mod.check"}]},
    )
    (mi / "module_entry.py").write_text(
        "from dataclasses import dataclass\nimport importlib\nimport mimetypes\nfrom typing import Sequence\nfrom core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\nfrom core.foundation.primitives import ModuleId, TaskId\n@dataclass(frozen=True, slots=True)\nclass IIn:\n    x: int = 1\n@dataclass(frozen=True, slots=True)\nclass IOut:\n    tag: str = ''\nclass ImpTask(Task[IIn, IOut]):\n    @property\n    def metadata(self) -> TaskMetadata[IIn, IOut]: return TaskMetadata(TaskId('imp_mod.check'), IIn, IOut)\n    def run(self, req: IIn, ctx: TaskContext) -> IOut:\n        _ = mimetypes.guess_type('a.json')\n        m1 = importlib.import_module('.sib', __package__)\n        m2 = importlib.import_module('sib')\n        if not (m1 is m2): raise AssertionError('embedded check failed')\n        return IOut(tag=str(m1.SIB_TAG))\nclass ImpMod(YscbModule):\n    @property\n    def module_id(self) -> ModuleId: return ModuleId('imp_mod')\n    def tasks(self) -> Sequence[BoundTask]: return (ImpTask(),)\ndef create_module() -> YscbModule: return ImpMod()\n",
        encoding="utf-8",
    )
    disp_i = build_dispatcher_for_workspace(ws_imp, venv_bin, is_daemon_host=True).dispatcher
    try:
        out_i = disp_i.invoke(InvokeRequest(TaskId("imp_mod.check"), {}, ws_imp, ws_imp))
        _check(out_i.ok and out_i.value == {"tag": "leaf_ok"})
    finally:
        disp_i.shutdown(grace_ms=100)


def _verify_cross_proc_serialize_reentrant_pin(ws_base: HostPath) -> None:
    ws_imp = HostPath(ws_base.path / "ws_reentrant_pin_unit")
    locks_d = ws_imp.join(".cache", "locks")
    locks_d.path.mkdir(parents=True, exist_ok=True)
    c_parent, c_child, c_other = ResourceCoordinator(locks_d), ResourceCoordinator(locks_d), ResourceCoordinator(locks_d)
    p_in, p_rel, ch_in, ch_rel, cont_in = (threading.Event() for _ in range(5))
    s_parent = ResourceAcquireSpec(
        "rk_pin", ConcurrencyMode.SERIALIZE, "p", ExecutionPriority.FOREGROUND, "tp",
        ((ws_imp, TaskId("imp_mod.check")),), CancellationToken(), call_tree_id="tree_pin",
    )
    s_child = ResourceAcquireSpec(
        "rk_pin", ConcurrencyMode.SERIALIZE, "c", ExecutionPriority.FOREGROUND, "tc",
        ((ws_imp, TaskId("imp_mod.check")), (ws_imp, TaskId("space.echo_tier0"))), CancellationToken(), call_tree_id="tree_pin",
    )
    s_other = ResourceAcquireSpec(
        "rk_pin", ConcurrencyMode.SERIALIZE, "o", ExecutionPriority.FOREGROUND, "to",
        ((ws_imp, TaskId("vsc.sync")),), CancellationToken(), call_tree_id="tree_other",
    )
    tp_th = threading.Thread(
        target=lambda: c_parent.execute(s_parent, leader_fn=lambda _p, _c, _f: (p_in.set(), p_rel.wait(timeout=3.0))[1]),
        daemon=True,
    )
    tc_th = threading.Thread(
        target=lambda: c_child.execute(s_child, leader_fn=lambda _p, _c, _f: (ch_in.set(), ch_rel.wait(timeout=3.0))[1]),
        daemon=True,
    )
    to_th = threading.Thread(
        target=lambda: c_other.execute(s_other, leader_fn=lambda _p, _c, _f: cont_in.set()),
        daemon=True,
    )
    tp_th.start()
    _check(p_in.wait(timeout=2.0))
    tc_th.start()
    _check(ch_in.wait(timeout=2.0))
    p_rel.set()
    tp_th.join(timeout=2.0)
    to_th.start()
    time.sleep(0.08)
    _check(not cont_in.is_set(), "Contender entered while reentrant child still held .reentrant.lock")
    ch_rel.set()
    tc_th.join(timeout=2.0)
    to_th.join(timeout=2.0)
    _check(cont_in.is_set())


def _verify_tier0_preempt_lingering_lock_and_gate_guard(ws_base: HostPath, venv_bin: HostPath) -> None:
    ws_t0 = HostPath(ws_base.path.parent / "ws_case_t0_preempt_guard")
    provision_live_workspace(ws_t0.path)
    code_t0 = """import time
from dataclasses import dataclass
from typing import Sequence
from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule
from core.filesystem.fs import atomic_write_json, read_json_dict
from core.foundation.primitives import ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class LingIn:
    tag: str
    linger_ms: int = 0

@dataclass(frozen=True, slots=True)
class LingOut:
    order: tuple[str, ...]

class PreemptLingTask(Task[LingIn, LingOut]):
    @property
    def metadata(self) -> TaskMetadata[LingIn, LingOut]:
        return TaskMetadata(
            TaskId("ling_mod.work"), LingIn, LingOut,
            resource_key="ling_rk", concurrency_mode=ConcurrencyMode.PREEMPT,
        )
    def run(self, req: LingIn, ctx: TaskContext) -> LingOut:
        f = ctx.workspace_root.join(".cache", "ling_log.json")
        if req.linger_ms > 0:
            atomic_write_json(ctx.workspace_root.join(".cache", "ling_entered.json"), {"tag": req.tag})
            while not ctx.cancel_token.is_cancelled:
                time.sleep(0.01)
            time.sleep(req.linger_ms / 1000.0)
        cur = read_json_dict(f) or {}
        seq = list(cur["seq"]) if isinstance(cur.get("seq"), list) else []
        seq.append(req.tag)
        atomic_write_json(f, {"seq": seq})
        return LingOut(order=tuple(str(x) for x in seq))

class LingMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("ling_mod")
    def tasks(self) -> Sequence[BoundTask]:
        return (PreemptLingTask(),)

def create_module() -> YscbModule:
    return LingMod()
"""
    _write_module(
        ws_t0.path,
        "ling_mod",
        {"tier1": False, "tasks": [{"task_id": "ling_mod.work", "resource_key": "ling_rk", "concurrency_mode": "preempt"}]},
        code_t0,
    )
    disp = build_dispatcher_for_workspace(ws_t0, venv_bin, is_daemon_host=True, sandbox_restricted=True).dispatcher
    try:
        out_a: list[TaskOutcome[JsonValue]] = []
        t_a = threading.Thread(
            target=lambda: out_a.append(disp.invoke(InvokeRequest(TaskId("ling_mod.work"), {"tag": "A_linger", "linger_ms": 300}, ws_t0, ws_t0))),
            daemon=True,
        )
        t_a.start()
        dl = time.monotonic() + 3.0
        while time.monotonic() < dl and read_json_dict(ws_t0.join(".cache", "ling_entered.json")) is None:
            time.sleep(0.01)
        out_b = disp.invoke(InvokeRequest(TaskId("ling_mod.work"), {"tag": "B_winner", "linger_ms": 0}, ws_t0, ws_t0))
        t_a.join(timeout=3.0)
        _check(out_b.ok and isinstance(out_b.value, Mapping))
        _check(list(out_b.value.get("order", ())) == ["A_linger", "B_winner"])
        _check(out_a and not out_a[0].ok and out_a[0].error is not None and out_a[0].error.code == ErrorCode.TASK_PREEMPTED)
    finally:
        disp.shutdown()


_PARALLEL_MUT_MOD_SRC: Final[str] = """import concurrent.futures, time
from dataclasses import dataclass
from typing import Sequence
from core.execution.runtime import (
    BoundTask, ClientRoutingPolicy, DispatchMode, SelfMutationScope, Task, TaskContext, TaskMetadata, YscbModule
)
from core.filesystem.fs import FileLock
from core.foundation.primitives import ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class MutChildIn:
    hold_ms: int = 80

@dataclass(frozen=True, slots=True)
class MutOut:
    ok_flag: bool

class ChildMutTask(Task[MutChildIn, MutOut]):
    @property
    def metadata(self) -> TaskMetadata[MutChildIn, MutOut]:
        return TaskMetadata(
            TaskId("par_mut.child"), MutChildIn, MutOut,
            dispatch_mode=DispatchMode.COLD_ONLY, mutation_scope=SelfMutationScope.MUTATES_MODULES,
        )
    def run(self, req: MutChildIn, ctx: TaskContext) -> MutOut:
        time.sleep(req.hold_ms / 1000.0)
        probe = FileLock(ctx.workspace_root.join(".cache", "locks", "installer.lock"))
        still_excl = not probe.acquire(shared=True, blocking=False)
        if not still_excl:
            probe.release()
        return MutOut(ok_flag=still_excl)

class ParentFanoutTask(Task[MutChildIn, MutOut]):
    @property
    def metadata(self) -> TaskMetadata[MutChildIn, MutOut]:
        return TaskMetadata(TaskId("par_mut.fanout"), MutChildIn, MutOut, dispatch_mode=DispatchMode.COLD_ONLY)
    def run(self, req: MutChildIn, ctx: TaskContext) -> MutOut:
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f1 = pool.submit(lambda: ctx.invoke_task("par_mut.child", MutChildIn(hold_ms=40), routing_policy=ClientRoutingPolicy.FORCE_COLD))
            f2 = pool.submit(lambda: ctx.invoke_task("par_mut.child", MutChildIn(hold_ms=140), routing_policy=ClientRoutingPolicy.FORCE_COLD))
            r1, r2 = f1.result(timeout=5.0), f2.result(timeout=5.0)
        ok_both = (
            r1.ok and r2.ok
            and isinstance(r1.value, dict) and bool(r1.value.get("ok_flag"))
            and isinstance(r2.value, dict) and bool(r2.value.get("ok_flag"))
        )
        return MutOut(ok_flag=ok_both)

class ParMutMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("par_mut")
    def tasks(self) -> Sequence[BoundTask]:
        return (ChildMutTask(), ParentFanoutTask())

def create_module() -> YscbModule:
    return ParMutMod()
"""


def _verify_cross_proc_reentrant_pin_toctou_and_parallel_cold_lease(ws_base: HostPath, venv_bin: HostPath) -> None:
    ws_lk = HostPath(ws_base.path.parent / "ws_case_lock_toctou_and_lease")
    provision_live_workspace(ws_lk.path)
