def _verify_interleaved_lifo_owner_tags_and_reload_diags() -> None:
    s1, s2 = socket.socketpair()
    ch1 = MultiplexedChannel(s1, is_initiator=True)
    ch2 = MultiplexedChannel(s2, is_initiator=False)
    try:
        _check(ch1.wait_until_closed(timeout_sec=0.01) is False)
        ch2.close()
        _check(ch1.wait_until_closed(timeout_sec=1.0) is True)
    finally:
        ch1.close()
        ch2.close()



_ORDERED_LIFO_MOD_TPL: Final[str] = """from dataclasses import dataclass
from typing import Callable, Optional, Sequence
from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule
from core.filesystem.fs import atomic_write_json, read_json_dict
from core.foundation.primitives import HostPath, ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class PingIn:
    pass

@dataclass(frozen=True, slots=True)
class PingOut:
    tag: str

class PingTask(Task[PingIn, PingOut]):
    @property
    def metadata(self) -> TaskMetadata[PingIn, PingOut]:
        return TaskMetadata(TaskId("__MID__.ping"), PingIn, PingOut)
    def run(self, req: PingIn, ctx: TaskContext) -> PingOut:
        _ = (req, ctx)
        return PingOut(tag="__MID__")

class LifoProbeMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("__MID__")
    def on_init(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:
        def _close() -> None:
            f = workspace_root.join(".cache", "ord_lifo_seq.json")
            cur = read_json_dict(f) or {}
            seq = list(cur["seq"]) if isinstance(cur.get("seq"), list) else []
            seq.append("__MID__.on_init")
            atomic_write_json(f, {"seq": seq})
            if "__FAIL__" == "1":
                raise RuntimeError("boom_on_init")
        return _close
    def tasks(self) -> Sequence[BoundTask]:
        return (PingTask(),)

def create_module() -> YscbModule:
    return LifoProbeMod()
"""


def _verify_interleaved_lifo_and_reload_diags_ws(ws_base: HostPath, venv_bin: HostPath) -> None:
    ws_lf = HostPath(ws_base.path.parent / "ws_case_interleaved_lifo")
    provision_live_workspace(ws_lf.path)
    t0_src_tpl = _ORDERED_LIFO_MOD_TPL
    _write_module(
        ws_lf.path,
        "m_early",
        {"tier1": False, "tasks": [{"task_id": "m_early.ping"}]},
        t0_src_tpl.replace("__MID__", "m_early").replace("__FAIL__", "1"),
    )
    _write_module(
        ws_lf.path,
        "m_mid_t1",
        {"tier1": True, "venv_group": "ord_lifo_grp", "tasks": [{"task_id": "m_mid_t1.ping"}]},
        t0_src_tpl.replace("__MID__", "m_mid_t1").replace("__FAIL__", "0"),
    )
    _write_module(
        ws_lf.path,
        "m_late",
        {"tier1": False, "tasks": [{"task_id": "m_late.ping"}]},
        t0_src_tpl.replace("__MID__", "m_late").replace("__FAIL__", "0"),
    )
    disp = build_dispatcher_for_workspace(ws_lf, venv_bin, is_daemon_host=True, sandbox_restricted=True).dispatcher
    _check(disp.invoke(InvokeRequest(TaskId("m_early.ping"), {}, ws_lf, ws_lf)).ok)
    _check(disp.invoke(InvokeRequest(TaskId("m_mid_t1.ping"), {}, ws_lf, ws_lf)).ok)
    _check(disp.invoke(InvokeRequest(TaskId("m_late.ping"), {}, ws_lf, ws_lf)).ok)
    disp.reload_affected_modules(frozenset({ModuleId("m_early")}))
    rel_diags = disp.drain_teardown_diagnostics()
    _check(len(rel_diags) == 1 and rel_diags[0].source_task == "m_early.on_init")
    _write_module(
        ws_lf.path,
        "m_early",
        {"tier1": False, "tasks": [{"task_id": "m_early.ping"}]},
        t0_src_tpl.replace("__MID__", "m_early").replace("__FAIL__", "0"),
    )
    disp.reload_affected_modules(frozenset({ModuleId("m_early")}))
    ws_lf.join(".cache", "ord_lifo_seq.json").path.unlink(missing_ok=True)
    _check(disp.invoke(InvokeRequest(TaskId("m_early.ping"), {}, ws_lf, ws_lf)).ok)
    disp.shutdown()
    seq_doc = read_json_dict(ws_lf.join(".cache", "ord_lifo_seq.json")) or {}
    _check(seq_doc.get("seq") == ["m_early.on_init", "m_late.on_init", "m_mid_t1.on_init"])




_MULTIHOP_AND_EVICT_SRC: Final[str] = """import time
from dataclasses import dataclass
from typing import Sequence
from core.execution.event import EventMetadata, EventOrdering, EventSubscriptionSpec
from core.execution.runtime import (
    BoundTask, ConcurrencyMode, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule
)
from core.filesystem.fs import atomic_write_json
from core.foundation.errors import YscbError
from core.foundation.primitives import EventId, ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class KeyIn:
    key: str = "k"
    mode: str = "reenter"
    hold_ms: int = 0

@dataclass(frozen=True, slots=True)
class ResOut:
    ok_tag: str

EV_X = EventMetadata(EventId("hopm.ev_x"), KeyIn, EventOrdering.ORDERED)
EV_Y = EventMetadata(EventId("hopm.ev_y"), KeyIn, EventOrdering.ORDERED)

class CoalATask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.coal_a"), KeyIn, ResOut,
            resource_key="hop_ca", concurrency_mode=ConcurrencyMode.COALESCE,
            equivalence_fn=lambda r: r.key,
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        out = ctx.invoke_task("hopm.serial_outer", req, output_type=ResOut)
        if not out.ok and out.error is not None:
            raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)
        return ResOut(ok_tag=out.value.ok_tag if out.value else "none")

class SerialOuterTask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.serial_outer"), KeyIn, ResOut,
            resource_key="hop_ser", concurrency_mode=ConcurrencyMode.SERIALIZE,
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        out = ctx.invoke_task("hopm.coal_b", req, output_type=ResOut)
        if not out.ok and out.error is not None:
            raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)
        return ResOut(ok_tag=out.value.ok_tag if out.value else "none")

class CoalBTask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.coal_b"), KeyIn, ResOut,
            resource_key="hop_cb", concurrency_mode=ConcurrencyMode.COALESCE,
            equivalence_fn=lambda r: r.key,
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        if req.hold_ms > 0:
            atomic_write_json(ctx.workspace_root.join(".cache", f"hop_cb_{req.key}.json"), {"in": True})
            time.sleep(req.hold_ms / 1000.0)
        target = "hopm.serial_inner" if req.mode == "reenter" else "hopm.evict_leaf"
        out = ctx.invoke_task(target, req, output_type=ResOut)
        if not out.ok and out.error is not None:
            raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)
        return ResOut(ok_tag=out.value.ok_tag if out.value else "none")

class SerialInnerTask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.serial_inner"), KeyIn, ResOut,
            resource_key="hop_ser", concurrency_mode=ConcurrencyMode.SERIALIZE,
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        return ResOut(ok_tag=f"multihop_ok:{req.key}")

class PreOuterTask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.pre_outer"), KeyIn, ResOut,
            resource_key="hop_evict_rk", concurrency_mode=ConcurrencyMode.PREEMPT,
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        atomic_write_json(ctx.workspace_root.join(".cache", "hop_pre_held.json"), {"held": True})
        out = ctx.invoke_task("hopm.coal_b", KeyIn(key=req.key, mode="evict", hold_ms=140), output_type=ResOut)
        if not out.ok and out.error is not None:
            raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)
        return ResOut(ok_tag="unexpected")

class EvictLeafTask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.evict_leaf"), KeyIn, ResOut,
            resource_key="hop_evict_rk", concurrency_mode=ConcurrencyMode.SERIALIZE,
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        return ResOut(ok_tag=f"innocent_survived:{req.key}")

class DualCycleCoalTask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.dual_cyc_coal"), KeyIn, ResOut,
            resource_key="hop_cyc", concurrency_mode=ConcurrencyMode.COALESCE,
            equivalence_fn=lambda r: r.key,
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        atomic_write_json(ctx.workspace_root.join(".cache", f"hop_dcyc_{req.mode}.json"), {"in": True})
        time.sleep(0.14)
        if req.mode == "imm_strict_chain":
            ctx.emit_imm(EV_X, KeyIn(key=req.key, mode="chain_step"), strict=True)
        else:
            ctx.emit_imm(EV_X, KeyIn(key=req.key, mode="noop"), strict=False)
            ctx.emit(EV_Y, KeyIn(key=req.key, mode="noop"))
        return ResOut(ok_tag="done")

class SubEvXTask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.sub_ev_x"), KeyIn, ResOut,
            exposure=TaskExposure.INTERNAL_TRIGGER,
            subscriptions=(EventSubscriptionSpec(EventId("hopm.ev_x"), lambda items: items[0], payload_type=KeyIn),),
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        if req.mode == "chain_step":
            ctx.emit_imm(EV_Y, KeyIn(key=req.key, mode="leaf"), strict=True)
        return ResOut(ok_tag="sub_x")

class SubEvYTask(Task[KeyIn, ResOut]):
    @property
    def metadata(self) -> TaskMetadata[KeyIn, ResOut]:
        return TaskMetadata(
            TaskId("hopm.sub_ev_y"), KeyIn, ResOut,
            exposure=TaskExposure.INTERNAL_TRIGGER,
            subscriptions=(EventSubscriptionSpec(EventId("hopm.ev_y"), lambda items: items[0], payload_type=KeyIn),),
        )
    def run(self, req: KeyIn, ctx: TaskContext) -> ResOut:
        return ResOut(ok_tag="sub_y")

class HopEvictMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("hopm")
    def tasks(self) -> Sequence[BoundTask]:
        return (
            CoalATask(), SerialOuterTask(), CoalBTask(), SerialInnerTask(),
            PreOuterTask(), EvictLeafTask(), DualCycleCoalTask(), SubEvXTask(), SubEvYTask(),
        )

def create_module() -> YscbModule:
    return HopEvictMod()
"""


def _verify_multihop_evict_and_dual_cycle_attribution(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_m = HostPath(ws8.path / "ws_case_multihop")
    provision_live_workspace(ws_m.path)
    _write_module(
        ws_m.path,
        "hopm",
        {
            "tier1": False,
            "tasks": [
                {"task_id": "hopm.coal_a", "resource_key": "hop_ca", "concurrency_mode": "coalesce"},
                {"task_id": "hopm.serial_outer", "resource_key": "hop_ser", "concurrency_mode": "serialize"},
                {"task_id": "hopm.coal_b", "resource_key": "hop_cb", "concurrency_mode": "coalesce"},
                {"task_id": "hopm.serial_inner", "resource_key": "hop_ser", "concurrency_mode": "serialize"},
                {"task_id": "hopm.pre_outer", "resource_key": "hop_evict_rk", "concurrency_mode": "preempt"},
                {"task_id": "hopm.evict_leaf", "resource_key": "hop_evict_rk", "concurrency_mode": "serialize"},
                {"task_id": "hopm.dual_cyc_coal", "resource_key": "hop_cyc", "concurrency_mode": "coalesce"},
                {"task_id": "hopm.sub_ev_x", "exposure": "internal_trigger", "subscriptions": [{"event_id": "hopm.ev_x"}]},
                {"task_id": "hopm.sub_ev_y", "exposure": "internal_trigger", "subscriptions": [{"event_id": "hopm.ev_y"}]},
            ],
        },
        _MULTIHOP_AND_EVICT_SRC,
    )
    disp = build_dispatcher_for_workspace(ws_m, venv_bin, is_daemon_host=True, sandbox_restricted=True).dispatcher
    try:
        # 1) invariant (S1A): Multi-hop coal_a -> serial_outer -> coal_b -> serial_inner reentrancy!
        out_mh = disp.invoke(InvokeRequest(TaskId("hopm.coal_a"), {"key": "mh1"}, ws_m, ws_m))
        _check(out_mh.ok and isinstance(out_mh.value, dict) and out_mh.value.get("ok_tag") == "multihop_ok:mh1")

        # 2) invariant (S1D): Partial caller illegal lock reentrancy evicts ONLY offending caller while innocent caller succeeds!
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_bad = pool.submit(disp.invoke, InvokeRequest(TaskId("hopm.pre_outer"), {"key": "evk"}, ws_m, ws_m))
            _wait_file_marker(ws_m.path / ".cache" / "hop_cb_evk.json")
            f_good = pool.submit(
                disp.invoke,
                InvokeRequest(TaskId("hopm.coal_b"), {"key": "evk", "mode": "evict", "hold_ms": 140}, ws_m, ws_m),
            )
            r_bad, r_good = f_bad.result(timeout=5.0), f_good.result(timeout=5.0)
        _check(not r_bad.ok and r_bad.error is not None and r_bad.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
        _check(r_good.ok and isinstance(r_good.value, dict) and r_good.value.get("ok_tag") == "innocent_survived:evk")

        # 3) invariant & invariant (S1B & S1E): Per-caller exact event cycle attribution across mixed emit_imm + emit & strict chain!
        for mode_tag, exp_src_y in (("mixed", "hopm.dual_cyc_coal"), ("imm_strict_chain", "hopm.sub_ev_x")):
            lin_x = CausalLineage().advance(EventId("hopm.ev_x"), workspace_scope=ws_m.comparison_key)
            lin_y = CausalLineage().advance(EventId("hopm.ev_y"), workspace_scope=ws_m.comparison_key)
            req_x = InvokeRequest(
                TaskId("hopm.dual_cyc_coal"),
                {"key": f"dc_{mode_tag}", "mode": mode_tag},
                ws_m,
                ws_m,
                propagation=CallPropagationContext(lineage=lin_x, is_internal_trigger=True, in_event_chain=True),
            )
            req_y = InvokeRequest(
                TaskId("hopm.dual_cyc_coal"),
                {"key": f"dc_{mode_tag}", "mode": mode_tag},
                ws_m,
                ws_m,
                propagation=CallPropagationContext(lineage=lin_y, is_internal_trigger=True, in_event_chain=True),
            )
            with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
                fx = pool.submit(disp.invoke, req_x)
                _wait_file_marker(ws_m.path / ".cache" / f"hop_dcyc_{mode_tag}.json")
                fy = pool.submit(disp.invoke, req_y)
                rx, ry = fx.result(timeout=5.0), fy.result(timeout=5.0)
            _check(not rx.ok and rx.error is not None and rx.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
            _check("hopm.ev_x" in rx.error.message and rx.error.source_task == "hopm.dual_cyc_coal")
            _check(not ry.ok and ry.error is not None and ry.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
            _check("hopm.ev_y" in ry.error.message and ry.error.source_task == exp_src_y)
    finally:
        disp.shutdown(grace_ms=200)


_COLOCATED_LIFO_TPL: Final[str] = 'import urllib.request\nfrom dataclasses import dataclass\nfrom typing import Callable, Optional, Sequence\nfrom core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\nfrom core.filesystem.fs import atomic_write_json, read_json_dict\nfrom core.foundation.primitives import HostPath, ModuleId, TaskId\n\n@dataclass(frozen=True, slots=True)\nclass StepIn:\n    next_task: str = ""\n\n@dataclass(frozen=True, slots=True)\nclass StepOut:\n    urllib_ok: bool\n\nclass ChainTask(Task[StepIn, StepOut]):\n    @property\n    def metadata(self) -> TaskMetadata[StepIn, StepOut]:\n        return TaskMetadata(TaskId("__MID__.step"), StepIn, StepOut)\n    def run(self, req: StepIn, ctx: TaskContext) -> StepOut:\n        if req.next_task:\n            sub = ctx.invoke_task(req.next_task, {"next_task": "__NEXT2__"})\n            if not (sub.ok): raise AssertionError(\'embedded check failed\')\n        return StepOut(urllib_ok=callable(urllib.request.urlopen))\n\nclass ModImpl(YscbModule):\n    @property\n    def module_id(self) -> ModuleId:\n        return ModuleId("__MID__")\n    def on_init(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:\n        def _close() -> None:\n            f = workspace_root.join(".cache", "coloc_lifo_seq.json")\n            cur = read_json_dict(f) or {}\n            seq = list(cur.get("seq", [])) if isinstance(cur.get("seq"), list) else []\n            seq.append("__MID__")\n            atomic_write_json(f, {"seq": seq})\n            raise RuntimeError("diag___MID__")\n        return _close\n    def tasks(self) -> Sequence[BoundTask]:\n        return (ChainTask(),)\n\ndef create_module() -> YscbModule:\n    return ModImpl()\n'


def _verify_colocated_lifo_stdlib_and_grace_reload(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_c = HostPath(ws8.path / "ws_case_coloc_lifo")
    provision_live_workspace(ws_c.path)
    for mid, is_t1, nxt2 in (("t1_a", True, "t1_c.step"), ("t0_b", False, ""), ("t1_c", True, "")):
        _write_module(
            ws_c.path,
            mid,
            {"tier1": is_t1, "venv_group": "shg_shared_grp" if is_t1 else None, "tasks": [{"task_id": f"{mid}.step"}]},
            _COLOCATED_LIFO_TPL.replace("__MID__", mid).replace("__NEXT2__", nxt2),
        )
        # invariant: sibling http.py inside .modules/<mid>/ must NEVER shadow stdlib http.client used by urllib.request!
        (ws_c.path / ".modules" / mid / "http.py").write_text("BROKEN_SHADOW = 1\n", encoding="utf-8")

    # Cold Turn LIFO: T1_a(grp) -> T0_b -> T1_c(grp) closes ['t1_c', 't0_b', 't1_a'] with exact LIFO diagnostics!
    disp_cold = build_dispatcher_for_workspace(ws_c, venv_bin, is_daemon_host=False, sandbox_restricted=True).dispatcher
    try:
        cold_out = disp_cold.invoke(
            InvokeRequest(TaskId("t1_a.step"), {"next_task": "t0_b.step"}, ws_c, ws_c, routing_policy=ClientRoutingPolicy.FORCE_COLD)
        )
        _check(cold_out.ok)
        _check([d.source_task for d in cold_out.teardown_diagnostics] == ["t1_c.on_init", "t0_b.on_init", "t1_a.on_init"])
        _check((read_json_dict(ws_c.join(".cache", "coloc_lifo_seq.json")) or {}).get("seq") == ["t1_c", "t0_b", "t1_a"])
    finally:
        disp_cold.shutdown(grace_ms=200)

    # Hot Daemon LIFO + zero cross-Turn diagnostic hijacking!
    ws_c.join(".cache", "coloc_lifo_seq.json").path.unlink(missing_ok=True)
    disp_hot = build_dispatcher_for_workspace(ws_c, venv_bin, is_daemon_host=True, sandbox_restricted=True).dispatcher
    try:
        _check(disp_hot.invoke(InvokeRequest(TaskId("t1_a.step"), {"next_task": "t0_b.step"}, ws_c, ws_c)).ok)
        disp_hot.reload_affected_modules(frozenset({ModuleId("t0_b")}), grace_ms=300)
        unrel = disp_hot.invoke(InvokeRequest(TaskId("t1_c.step"), {}, ws_c, ws_c))
        _check(unrel.ok and unrel.teardown_diagnostics == ())
        host_diags = disp_hot.drain_teardown_diagnostics()
        _check([d.source_task for d in host_diags] == ["t0_b.on_init"])
        ws_c.join(".cache", "coloc_lifo_seq.json").path.unlink(missing_ok=True)
        _check(disp_hot.invoke(InvokeRequest(TaskId("t0_b.step"), {}, ws_c, ws_c)).ok)
        shut_diags = disp_hot.shutdown(grace_ms=500)
        _check([d.source_task for d in shut_diags] == ["t0_b.on_init", "t1_c.on_init", "t1_a.on_init"])
        _check((read_json_dict(ws_c.join(".cache", "coloc_lifo_seq.json")) or {}).get("seq") == ["t0_b", "t1_c", "t1_a"])
    finally:
        disp_hot.shutdown(grace_ms=100)


_SHARED_WORKER_GUARD_SRC: Final[str] = """import time
from dataclasses import dataclass
from typing import Sequence
from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule
from core.filesystem.fs import atomic_write_json, read_json_dict
from core.foundation.primitives import ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class GuardIn:
    tag: str
    uncoop_ms: int = 0

@dataclass(frozen=True, slots=True)
class GuardOut:
    ok_tag: str

class TimedResTask(Task[GuardIn, GuardOut]):
    @property
    def metadata(self) -> TaskMetadata[GuardIn, GuardOut]:
        return TaskMetadata(
            TaskId("shgm.res_op"), GuardIn, GuardOut,
            resource_key="shg_shared_rk", concurrency_mode=ConcurrencyMode.SERIALIZE,
            timeout_ms=130,
        )
    def run(self, req: GuardIn, ctx: TaskContext) -> GuardOut:
        f = ctx.workspace_root.join(".cache", "shg_overlap.json")
        atomic_write_json(f, {"active": True, "overlap": False})
        atomic_write_json(ctx.workspace_root.join(".cache", f"shg_{req.tag}.json"), {"started": True})
        time.sleep(req.uncoop_ms / 1000.0)
        cur = read_json_dict(f) or {}
        atomic_write_json(f, {"active": False, "overlap": bool(cur.get("overlap", False))})
        return GuardOut(ok_tag="late")

class ContendResTask(Task[GuardIn, GuardOut]):
    @property
    def metadata(self) -> TaskMetadata[GuardIn, GuardOut]:
        return TaskMetadata(
            TaskId("shgm.res_contend"), GuardIn, GuardOut,
            resource_key="shg_shared_rk", concurrency_mode=ConcurrencyMode.SERIALIZE,
            timeout_ms=2500,
        )
    def run(self, req: GuardIn, ctx: TaskContext) -> GuardOut:
        f = ctx.workspace_root.join(".cache", "shg_overlap.json")
        cur = read_json_dict(f) or {}
        if cur.get("active"):
            atomic_write_json(f, {"active": True, "overlap": True})
        return GuardOut(ok_tag="contender_clean")

class SiblingHoldTask(Task[GuardIn, GuardOut]):
    @property
    def metadata(self) -> TaskMetadata[GuardIn, GuardOut]:
        return TaskMetadata(TaskId("shgm.sib_hold"), GuardIn, GuardOut)
    def run(self, req: GuardIn, ctx: TaskContext) -> GuardOut:
        atomic_write_json(ctx.workspace_root.join(".cache", f"shg_sib_{req.tag}.json"), {"in": True})
        time.sleep(req.uncoop_ms / 1000.0)
        return GuardOut(ok_tag="sib_done")

class SharedGuardMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("shgm")
    def tasks(self) -> Sequence[BoundTask]:
        return (TimedResTask(), ContendResTask(), SiblingHoldTask())

def create_module() -> YscbModule:
    return SharedGuardMod()
"""


def _verify_shared_worker_timeout_guard_and_cascade_cycle(ws8: HostPath, venv_bin: HostPath) -> None:
    # invariant: Mutual FlightCascade.bind_parent_cascade cycle guard!
    rec_a = RawEventRecord(EventId("fc.a"), TaskId("m.a"), {}, EventOrdering.UNORDERED)
    rec_b = RawEventRecord(EventId("fc.b"), TaskId("m.b"), {}, EventOrdering.UNORDERED)
    fc1 = FlightCascade(seed_events=(rec_a,))
    fc2 = FlightCascade(seed_events=(rec_b,))
    _check(fc1.bind_parent_cascade(fc2) is True)
    _check(fc2.bind_parent_cascade(fc1) is False)
    fc2.mark_own_completed()
    fc1.mark_own_completed()
    _check(fc1.drain_cg.active_count == 0 and fc2.drain_cg.active_count == 0)

    # invariant & invariant: Shared Tier 1 worker timeout holds resource_key until tainted worker exits + grace_ms bound!
    ws_g = HostPath(ws8.path / "ws_case_shared_guard")
    provision_live_workspace(ws_g.path)
    _write_module(
        ws_g.path,
        "shgm",
        {
            "tier1": True,
            "venv_group": "shg_guard_grp",
            "tasks": [
                {"task_id": "shgm.res_op", "resource_key": "shg_shared_rk", "concurrency_mode": "serialize", "timeout_ms": 130},
                {"task_id": "shgm.res_contend", "resource_key": "shg_shared_rk", "concurrency_mode": "serialize", "timeout_ms": 2500},
                {"task_id": "shgm.sib_hold"},
            ],
        },
        _SHARED_WORKER_GUARD_SRC,
    )
    disp = build_dispatcher_for_workspace(ws_g, venv_bin, is_daemon_host=True, sandbox_restricted=True).dispatcher
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            f_sib = pool.submit(disp.invoke, InvokeRequest(TaskId("shgm.sib_hold"), {"tag": "s1", "uncoop_ms": 420}, ws_g, ws_g))
            _wait_file_marker(ws_g.path / ".cache" / "shg_sib_s1.json")
            f_tmo = pool.submit(disp.invoke, InvokeRequest(TaskId("shgm.res_op"), {"tag": "t1", "uncoop_ms": 380}, ws_g, ws_g))
            _wait_file_marker(ws_g.path / ".cache" / "shg_t1.json")
            r_tmo = f_tmo.result(timeout=4.0)
            _check(not r_tmo.ok and r_tmo.error is not None and r_tmo.error.code == ErrorCode.TASK_TIMEOUT)
            f_cont = pool.submit(disp.invoke, InvokeRequest(TaskId("shgm.res_contend"), {"tag": "c2", "uncoop_ms": 0}, ws_g, ws_g))
            r_sib, r_cont = f_sib.result(timeout=5.0), f_cont.result(timeout=5.0)
        _check(r_sib.ok and r_cont.ok)
        ov_doc = read_json_dict(ws_g.join(".cache", "shg_overlap.json")) or {}
        _check(ov_doc.get("overlap") is False)

        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_hang = pool.submit(disp.invoke, InvokeRequest(TaskId("shgm.sib_hold"), {"tag": "s_hang", "uncoop_ms": 4500}, ws_g, ws_g))
            _wait_file_marker(ws_g.path / ".cache" / "shg_sib_s_hang.json")
            t0_rel = time.monotonic()
            disp.reload_affected_modules(frozenset({ModuleId("shgm")}), grace_ms=120)
            rel_elapsed = time.monotonic() - t0_rel
            _ = f_hang.result(timeout=5.0)
        _check(rel_elapsed < 2.8, lambda: f"reload_affected_modules ignored grace_ms=120: took {rel_elapsed:.2f}s")
    finally:
        disp.shutdown(grace_ms=200)


_DAEMON_QUIESCE_MOD_TPL: Final[str] = """import enum, time
from dataclasses import dataclass
from typing import Callable, Literal, Optional, Sequence
from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule
from core.foundation.errors import YscbError
from core.foundation.primitives import HostPath, ModuleId, TaskId

class StageTag(enum.Enum):
    ALPHA = "alpha"

@dataclass(frozen=True, slots=True)
class QIn:
    call_target: str = ""
    stage: Literal[StageTag.ALPHA] = StageTag.ALPHA

@dataclass(frozen=True, slots=True)
class QOut:
    who: str

class QTask(Task[QIn, QOut]):
    @property
    def metadata(self) -> TaskMetadata[QIn, QOut]:
        return TaskMetadata(TaskId("__MID__.ping"), QIn, QOut)
    def run(self, req: QIn, ctx: TaskContext) -> QOut:
        if req.call_target:
            sub = ctx.invoke_task(req.call_target, {})
            if not sub.ok and sub.error is not None:
                    raise YscbError(sub.error.code, sub.error.message, source_task=sub.error.source_task)
        return QOut(who="__MID__")

class QMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("__MID__")
    def on_start(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:
        warm_ms = int("__WARM_MS__")
        if warm_ms > 0:
            time.sleep(warm_ms / 1000.0)
        def _close_start() -> None:
            if "__FAIL_STOP__" == "1":
                raise RuntimeError("stop_diag___MID__")
        return _close_start
    def tasks(self) -> Sequence[BoundTask]:
        return (QTask(),)

def create_module() -> YscbModule:
    return QMod()
"""


def _verify_per_module_quiesce_deadlines_and_stop_diags(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_d = HostPath(ws8.path / "ws_case_daemon_quiesce")
    provision_live_workspace(ws_d.path)
    _write_module(
        ws_d.path,
        "qslow",
        {"tier1": False, "eager_warmup": True, "tasks": [{"task_id": "qslow.ping"}]},
        _DAEMON_QUIESCE_MOD_TPL.replace("__MID__", "qslow").replace("__WARM_MS__", "450").replace("__FAIL_STOP__", "1"),
    )
    _write_module(
        ws_d.path,
        "qfast",
        {"tier1": False, "eager_warmup": True, "tasks": [{"task_id": "qfast.ping"}]},
        _DAEMON_QUIESCE_MOD_TPL.replace("__MID__", "qfast").replace("__WARM_MS__", "0").replace("__FAIL_STOP__", "0"),
    )
    disp_c = build_dispatcher_for_workspace(ws_d, venv_bin, ttl_sec=25.0).dispatcher
    try:
        _check(disp_c.invoke(
            InvokeRequest(TaskId("qfast.ping"), {}, ws_d, ws_d, routing_policy=ClientRoutingPolicy.AUTO_SPAWN)
        ).ok)
        wait_for_daemon_online(ws_d)

        # 1) invariant: Quiesce qslow (lease=4.0s) and qfast (lease=0.22s); qfast expiry MUST NOT resume qslow early!
        _check(query_daemon_control(ws_d.join(".cache"), ws_d, FrameKind.CONTROL_QUIESCE, {"modules": ["qslow"], "lease_sec": 4.0}))
        _check(query_daemon_control(ws_d.join(".cache"), ws_d, FrameKind.CONTROL_QUIESCE, {"modules": ["qfast"], "lease_sec": 0.22}))
        _wait_until(
            lambda: disp_c.invoke(
                InvokeRequest(TaskId("qfast.ping"), {}, ws_d, ws_d, routing_policy=ClientRoutingPolicy.STRICT_HOT)
            ).ok,
            timeout_sec=3.0,
        )
        fast_ok = disp_c.invoke(
            InvokeRequest(TaskId("qfast.ping"), {}, ws_d, ws_d, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(fast_ok.ok and fast_ok.executed_hot)
        # qslow is STILL gated! A nested call qfast.ping -> qslow.ping (invariant) waits on leased gate until qslow resumes!
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_nested = pool.submit(
                disp_c.invoke,
                InvokeRequest(
                    TaskId("qfast.ping"),
                    {"call_target": "qslow.ping"},
                    ws_d,
                    ws_d,
                    routing_policy=ClientRoutingPolicy.STRICT_HOT,
                ),
            )
            time.sleep(0.12)
            _check(not f_nested.done(), "qslow was prematurely resumed by qfast's short lease!")
            # 2) invariant: Resume qslow (360ms warmup) in background while verifying qfast stays non-blocking!
            f_res = pool.submit(query_daemon_control, ws_d.join(".cache"), ws_d, FrameKind.CONTROL_RESUME, {})
            time.sleep(0.05)
            t0_fast = time.monotonic()
            fast_during_res = disp_c.invoke(
                InvokeRequest(TaskId("qfast.ping"), {}, ws_d, ws_d, routing_policy=ClientRoutingPolicy.STRICT_HOT)
            )
            fast_lat = time.monotonic() - t0_fast
            r_nested = f_nested.result(timeout=5.0)
            _ = f_res.result(timeout=5.0)
        _check(fast_during_res.ok and fast_lat < 0.34, lambda: f"Healthy module blocked during selective resume: {fast_lat:.2f}s")
        _check(r_nested.ok and r_nested.executed_hot)

        # 3) invariant: CONTROL_STOP returns container teardown_diagnostics!
        stop_rep = query_daemon_control(ws_d.join(".cache"), ws_d, FrameKind.CONTROL_STOP, {"force": False})
        _check(isinstance(stop_rep, dict) and stop_rep.get("ok") is True)
        td_raw = stop_rep.get("teardown_diagnostics")
        _check(isinstance(td_raw, list) and any(
            isinstance(item, dict) and item.get("source_task") == "qslow.on_start" for item in td_raw
        ))
    finally:
        stop_daemon_cleanly(ws_d)
        disp_c.shutdown(grace_ms=100)


_SELECTIVE_EAGER_MOD_TPL: Final[str] = """from dataclasses import dataclass
from typing import Callable, Optional, Sequence
from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule
from core.filesystem.fs import atomic_write_json
from core.foundation.primitives import HostPath, ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class E8In:
    tag: str = "ok"

@dataclass(frozen=True, slots=True)
class E8Out:
    started: bool

class E8Task(Task[E8In, E8Out]):
    @property
    def metadata(self) -> TaskMetadata[E8In, E8Out]:
        return TaskMetadata(TaskId("__MID__.ping"), E8In, E8Out)
    def run(self, req: E8In, ctx: TaskContext) -> E8Out:
        return E8Out(started=ctx.workspace_root.join(".cache", "warm___MID__.json").path.is_file())

class E8ProbeTask(Task[E8In, E8Out]):
    @property
    def metadata(self) -> TaskMetadata[E8In, E8Out]:
        return TaskMetadata(TaskId("__MID__.probe"), E8In, E8Out, timeout_ms=110)
    def run(self, req: E8In, ctx: TaskContext) -> E8Out:
        return E8Out(started=ctx.workspace_root.join(".cache", "warm___MID__.json").path.is_file())

class E8Mod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("__MID__")
    def on_start(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:
        f = workspace_root.join(".cache", "warm___MID__.json")
        atomic_write_json(f, {"started": True})
        return lambda: f.path.unlink(missing_ok=True)
    def tasks(self) -> Sequence[BoundTask]:
        return (E8Task(), E8ProbeTask())

def create_module() -> YscbModule:
    return E8Mod()
"""


def _verify_global_selective_quiesce_and_monotonic_leases(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_q = HostPath(ws8.path / "ws_case_quiesce_matrix")
    provision_live_workspace(ws_q.path)
    for mid, grp in (("m8a", "g8_shared"), ("m8b", "g8_shared"), ("m8c", "")):
        _write_module(
            ws_q.path,
            mid,
            {"tier1": bool(grp), "venv_group": grp, "eager_warmup": True, "tasks": [{"task_id": f"{mid}.ping"}, {"task_id": f"{mid}.probe", "timeout_ms": 110}]},
            _SELECTIVE_EAGER_MOD_TPL.replace("__MID__", mid),
        )
    disp = build_dispatcher_for_workspace(ws_q, venv_bin, ttl_sec=25.0).dispatcher
    try:
        _check(disp.invoke(InvokeRequest(TaskId("m8c.ping"), {}, ws_q, ws_q, routing_policy=ClientRoutingPolicy.AUTO_SPAWN)).ok)
        wait_for_daemon_online(ws_q)
        # Scenario A: Global quiesce -> selective resume m8c -> m8c.on_start runs, m8a stays quiesced -> resume m8a -> READY!
        _check(query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_QUIESCE, {"modules": [], "lease_sec": 8.0}))
        _check(query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_RESUME, {"modules": ["m8c"]}))
        r_c = disp.invoke(InvokeRequest(TaskId("m8c.ping"), {}, ws_q, ws_q, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        _check(r_c.ok and r_c.executed_hot and isinstance(r_c.value, Mapping) and r_c.value.get("started") is True)
        r_a_tmo = disp.invoke(
            InvokeRequest(TaskId("m8a.probe"), {}, ws_q, ws_q, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(not r_a_tmo.ok and r_a_tmo.error is not None and r_a_tmo.error.code == ErrorCode.TASK_TIMEOUT)
        all_other = [d.name for d in (ws_q.path / ".modules").iterdir() if d.is_dir() and d.name not in ("core", "m8c")]
        res_rest = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_RESUME, {"modules": all_other})
        _check(isinstance(res_rest, Mapping) and res_rest.get("state") == "ready")

        # Scenario B & C: Short module lease + long global lease, and co-located long lease + short lease monotonic max!
        _check(query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_QUIESCE, {"modules": ["m8c"], "lease_sec": 0.22}))
        _check(query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_QUIESCE, {"modules": [], "lease_sec": 6.0}))
        time.sleep(0.35)
        st_b = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_STATUS)
        _check(isinstance(st_b, Mapping) and isinstance(st_b.get("status"), Mapping) and st_b["status"].get("state") == "quiesced")
        _check(query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_RESUME, {}))

        _check(query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_QUIESCE, {"modules": ["m8a"], "lease_sec": 6.0}))
        _check(query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_QUIESCE, {"modules": ["m8b"], "lease_sec": 0.22}))
        time.sleep(0.35)
        st_c = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_STATUS)
        _check(isinstance(st_c, Mapping) and isinstance(st_c.get("status"), Mapping) and st_c["status"].get("state") == "quiesced")
        _check(query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_RESUME, {}))
    finally:
        stop_daemon_cleanly(ws_q)
        disp.shutdown(grace_ms=100)


def _verify_deferred_selective_resume_and_stop_latch(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_s = HostPath(ws8.path / "ws_case_stop_and_def_res")
    provision_live_workspace(ws_s.path)
    for mid in ("d8a", "d8b"):
        _write_module(
            ws_s.path,
            mid,
            {"tier1": False, "eager_warmup": True, "tasks": [{"task_id": f"{mid}.ping"}, {"task_id": f"{mid}.probe", "timeout_ms": 110}]},
            _SELECTIVE_EAGER_MOD_TPL.replace("__MID__", mid),
        )
    disp = build_dispatcher_for_workspace(ws_s, venv_bin, ttl_sec=25.0).dispatcher
    inst_lk = FileLock(ws_s.join(".cache", "locks", "installer.lock"))
    try:
        _check(disp.invoke(InvokeRequest(TaskId("d8a.ping"), {}, ws_s, ws_s, routing_policy=ClientRoutingPolicy.AUTO_SPAWN)).ok)
        wait_for_daemon_online(ws_s)
        # Consecutive per-module quiesce while installer B holds installer.lock must NOT swallow d8a CONTROL_RESUME!
        _check(query_daemon_control(ws_s.join(".cache"), ws_s, FrameKind.CONTROL_QUIESCE, {"modules": ["d8a"], "lease_sec": 12.0}))
        inst_lk.acquire(shared=False, blocking=True, timeout_sec=2.0)
        try:
            _check(query_daemon_control(ws_s.join(".cache"), ws_s, FrameKind.CONTROL_RESUME, {"modules": ["d8a"]}))
            _check(query_daemon_control(ws_s.join(".cache"), ws_s, FrameKind.CONTROL_QUIESCE, {"modules": ["d8b"], "lease_sec": 12.0}))
        finally:
            inst_lk.release()
        r_d8a = disp.invoke(
            InvokeRequest(TaskId("d8a.ping"), {}, ws_s, ws_s, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(r_d8a.ok and r_d8a.executed_hot)
        r_d8b_tmo = disp.invoke(
            InvokeRequest(TaskId("d8b.probe"), {}, ws_s, ws_s, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(not r_d8b_tmo.ok and r_d8b_tmo.error is not None and r_d8b_tmo.error.code == ErrorCode.TASK_TIMEOUT)
        _check(query_daemon_control(ws_s.join(".cache"), ws_s, FrameKind.CONTROL_RESUME, {}))

        # Explicit CONTROL_STOP racing with core mutation CONTROL_RELOAD must latch stop and spawn 0 successor daemons!
        core_dir = ws_s.path / ".modules" / "core"
        core_dir.mkdir(parents=True, exist_ok=True)
        for idx in range(24):
            atomic_write_bytes(HostPath(core_dir / f"blob_{idx}.bin"), b"x" * 65536)
        spawns_before = _jint(read_json_dict(ws_s.join(".cache", "daemon_spawn_count.json")), "spawns", 0)
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_stop = pool.submit(query_daemon_control, ws_s.join(".cache"), ws_s, FrameKind.CONTROL_STOP, {"force": False})
            f_rel = pool.submit(query_daemon_control, ws_s.join(".cache"), ws_s, FrameKind.CONTROL_RELOAD, {"modules": []})
            _ = f_stop.result(timeout=5.0), f_rel.result(timeout=5.0)
        stop_daemon_cleanly(ws_s)
        _wait_until(
            lambda: read_active_handoff_boot_id(ws_s.join(".cache")) is None
            and probe_daemon_endpoint(ws_s.join(".cache"), ws_s) is None,
            timeout_sec=3.0,
        )
        _check(_jint(read_json_dict(ws_s.join(".cache", "daemon_spawn_count.json")), "spawns", 0) == spawns_before)
    finally:
        inst_lk.release()
        stop_daemon_cleanly(ws_s)
        disp.shutdown(grace_ms=100)


def _verify_stopped_hot_gate_generic_evict_and_strict_force_cold(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_h = HostPath(ws8.path / "ws_case_hot_stopped_and_strict")
    provision_live_workspace(ws_h.path)
    # 1) Generic dataclass GenBox[int] in dynamically loaded module evicted cleanly on cleanup_package!
    _write_module(
        ws_h.path,
        "sgen",
        {"tier1": False, "tasks": [{"task_id": "sgen.box"}]},
        (
            "from dataclasses import dataclass\nfrom typing import Generic, Sequence, TypeVar\n"
            "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
            "from core.foundation.primitives import ModuleId, TaskId\n"
            "T = TypeVar('T')\n"
            "@dataclass(frozen=True, slots=True)\nclass GenBox(Generic[T]):\n    item: T\n"
            "class BoxTask(Task[GenBox[int], GenBox[int]]):\n"
            "    @property\n    def metadata(self) -> TaskMetadata[GenBox[int], GenBox[int]]:\n"
            "        return TaskMetadata(TaskId('sgen.box'), GenBox[int], GenBox[int])\n"
            "    def run(self, req: GenBox[int], ctx: TaskContext) -> GenBox[int]: return GenBox(req.item + 1)\n"
            "class BoxMod(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId('sgen')\n"
            "    def tasks(self) -> Sequence[BoundTask]: return (BoxTask(),)\n"
            "def create_module() -> YscbModule: return BoxMod()\n"
        ),
    )
    disp_hot = build_dispatcher_for_workspace(ws_h, venv_bin, is_daemon_host=True, sandbox_restricted=True).dispatcher
    gen_res = disp_hot.invoke(InvokeRequest(TaskId("sgen.box"), {"item": 41}, ws_h, ws_h))
    _check(gen_res.ok and gen_res.value == {"item": 42})
    _check(any(_type_mentions_scoped_pkg(fk, "_yscb_v2_mod_sgen_") for fk in _codec_live_form_plan_types()))
    _check(disp_hot.try_quiesce_modules(frozenset({ModuleId("core")})))
    _check(disp_hot.reload_gate.is_globally_quiesced())
    disp_hot.resume_from_quiesce()
    _check(not disp_hot.reload_gate.is_globally_quiesced())
    disp_hot.shutdown(grace_ms=100)
    post_stop = disp_hot.invoke(InvokeRequest(TaskId("space.echo_tier0"), {"tag": "after_stop"}, ws_h, ws_h))
    _check(not post_stop.ok and post_stop.error is not None and post_stop.error.code == ErrorCode.DAEMON_UNAVAILABLE)
    _check(disp_hot.container_lifecycle.resource_stack.close_all_lifo() == ())
    _check(not any(k.startswith("_yscb_v2_mod_space_") for k in sys.modules))
    _check(all(not _type_mentions_scoped_pkg(fk, "_yscb_v2_mod_sgen_") for fk in _codec_live_form_plan_types()))

    strict_opts = DispatcherHostOptions(
        config_view=FileConfigView(ws_h),
        daemon_spawner=None,
        connection_config=DaemonConnectionConfig(enabled=True, auto_spawn=False, strict_hot_dispatch=True),
        is_daemon_host=False,
    )
    disp_strict = RuntimeDispatcher(
        workspace_root=ws_h,
        cache_dir=ws_h.join(".cache"),
        module_provider=ManifestModuleProvider(ws_h, venv_bin, dedicated_venv_python=venv_bin),
        options=strict_opts,
    )
    try:
        off_res = disp_strict.invoke(InvokeRequest(TaskId("space.echo_tier0"), {"tag": "off"}, ws_h, ws_h))
        _check(not off_res.ok and off_res.error is not None and off_res.error.code == ErrorCode.DAEMON_UNAVAILABLE)
        fc_res = disp_strict.invoke(
            InvokeRequest(TaskId("space.echo_tier0"), {"tag": "fc"}, ws_h, ws_h, routing_policy=ClientRoutingPolicy.FORCE_COLD)
        )
        _check(fc_res.ok and fc_res.executed_hot is False)
    finally:
        disp_strict.shutdown(grace_ms=100)


def _type_mentions_scoped_pkg(tp: object, prefix: str) -> bool:
    orig = typing.get_origin(tp)
    if isinstance(tp, type) and tp.__module__.startswith(prefix):
        return True
    if isinstance(orig, type) and orig.__module__.startswith(prefix):
        return True
    return any(_type_mentions_scoped_pkg(a, prefix) for a in typing.get_args(tp))


class _DummyHandshakeRpcHandler(InboundCallHandler):
    def on_call(
        self,
        stream_id: int,
        payload: JsonObject,
        ack_accepted: typing.Callable[[], bool],
        emit_progress: typing.Callable[[JsonObject], None],
        peer_cancel_token: CancellationToken,
    ) -> tuple[bool, JsonObject]:
        _ = (stream_id, payload, emit_progress, peer_cancel_token)
        ack_accepted()
        return (True, {"ok": True})

    def on_control(self, kind: FrameKind, payload: JsonObject) -> JsonObject:
        _ = (kind, payload)
        return {"ok": True}


def _hammer_single_rpc_handshake(ep: RpcEndpointInfo) -> None:
    ch = connect_and_handshake(ep, connect_timeout_sec=0.3)
    if ch is not None:
        ch.close()


def _verify_rpc_handshake_stop_race_and_mismatched_retire(ws8: HostPath, venv_bin: HostPath) -> None:
    # 1) Hammer 20 rounds x 8 concurrent handshakes racing against stop_accepting() + flush + close_all()!
    t0 = time.monotonic()
    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
        for idx in range(20):
            listener = RpcServerListener(ws8, _DummyHandshakeRpcHandler())
            ep = listener.start(pid=os.getpid() + idx)
            futs = [pool.submit(_hammer_single_rpc_handshake, ep) for _ in range(8)]
            time.sleep(0.002)
            listener.stop_accepting()
            listener.flush_inbound_controls(timeout_sec=0.5)
            listener.close_all()
            for f in futs:
                f.result(timeout=2.0)
    _check((time.monotonic() - t0) < 4.0)

    # 2) Tier 1 mismatched_live retirement preserves teardown diagnostics & blocks non-eager overlap!
    ws_m = HostPath(ws8.path / "ws_case_mismatched_fp")
    provision_live_workspace(ws_m.path)
    _write_module(
        ws_m.path,
        "m9fp",
        {"tier1": True, "venv_group": "g9_fp", "eager_warmup": False, "tasks": [{"task_id": "m9fp.op"}]},
        (
            "from dataclasses import dataclass\nimport time\nfrom typing import Callable, Optional, Sequence\n"
            "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
            "from core.foundation.primitives import HostPath, ModuleId, TaskId\n"
            "@dataclass(frozen=True, slots=True)\nclass MIn:\n    ms: int = 0\n"
            "@dataclass(frozen=True, slots=True)\nclass MOut:\n    rev: int = 1\n"
            "class MTask(Task[MIn, MOut]):\n"
            "    @property\n    def metadata(self) -> TaskMetadata[MIn, MOut]: return TaskMetadata(TaskId('m9fp.op'), MIn, MOut)\n"
            "    def run(self, req: MIn, ctx: TaskContext) -> MOut:\n"
            "        if req.ms > 0: time.sleep(req.ms / 1000.0)\n"
            "        return MOut(rev=1)\n"
            "class MMod(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId('m9fp')\n"
            "    def on_init(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:\n"
            "        def _bad_close() -> None:\n            raise RuntimeError('m9_close_err')\n"
            "        return _bad_close\n"
            "    def tasks(self) -> Sequence[BoundTask]: return (MTask(),)\n"
            "def create_module() -> YscbModule: return MMod()\n"
        ),
    )
    rig = build_dispatcher_for_workspace(ws_m, venv_bin, is_daemon_host=True, sandbox_restricted=True)
    disp, prov = rig.dispatcher, rig.provider
    try:
        _check(disp.invoke(InvokeRequest(TaskId("m9fp.op"), {"ms": 0}, ws_m, ws_m)).ok)
        # Mutate manifest venv_group/eager_warmup via routes.json + reload provider only to trigger mismatched_live!
        atomic_write_json(
            ws_m.join(".modules", "m9fp", "routes.json"),
            {"module_id": "m9fp", "tier1": True, "venv_group": "g9_fp", "eager_warmup": True, "tasks": [{"task_id": "m9fp.op"}]},
        )
        prov.reload()
        _check(disp.invoke(InvokeRequest(TaskId("m9fp.op"), {"ms": 0}, ws_m, ws_m)).ok)
        diags = disp.drain_teardown_diagnostics()
        _check(any(d.code == ErrorCode.TEARDOWN_ERROR and "m9_close_err" in d.message for d in diags))
    finally:
        disp.shutdown(grace_ms=150)


