def _hammer_concurrent_rpc_caller(
    cli_disp: RuntimeDispatcher,
    ws_q: HostPath,
    stop_ev: threading.Event,
    worker_idx: int,
) -> int:
    count = 0
    while not stop_ev.is_set():
        prop = CallPropagationContext(turn_id=f"hammer_turn_{worker_idx}_{count}") if (count % 2 == 0) else CallPropagationContext()
        req = InvokeRequest(
            TaskId("hamma.ping"),
            {"seq": count},
            ws_q,
            ws_q,
            routing_policy=ClientRoutingPolicy.STRICT_HOT,
            propagation=prop,
        )
        out = cli_disp.invoke(req)
        _check(out.ok and out.executed_hot is True, lambda: f"RPC hammer failed: {out}")
        count += 1
    return count


def _run_quiesce_and_worker_stop_cycles(ws_q: HostPath, cli_disp: RuntimeDispatcher) -> None:
    stop_ev = threading.Event()
    t0 = time.monotonic()
    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
        futs = [pool.submit(_hammer_concurrent_rpc_caller, cli_disp, ws_q, stop_ev, idx) for idx in range(8)]
        try:
            for _ in range(25):
                q1 = query_daemon_control(
                    ws_q.join(".cache"),
                    ws_q,
                    FrameKind.CONTROL_QUIESCE,
                    {"modules": ["hamma"], "lease_sec": 3.0, "drain_timeout_sec": 0.35},
                )
                _check(q1 is not None and q1.get("ok") is True, lambda: f"Selective quiesce deadlocked/failed: {q1}")
                q2 = query_daemon_control(
                    ws_q.join(".cache"),
                    ws_q,
                    FrameKind.CONTROL_QUIESCE,
                    {"modules": ["hamma"], "lease_sec": 4.0, "drain_timeout_sec": 0.35},
                )
                _check(q2 is not None and q2.get("ok") is True)
                r1 = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_RESUME, {"modules": ["hamma"]})
                _check(r1 is not None and r1.get("ok") is True)
        finally:
            stop_ev.set()
        totals = [f.result(timeout=5.0) for f in futs]
    _check(sum(totals) >= 40 and (time.monotonic() - t0) < 6.0)

    for idx in range(5):
        t_out = cli_disp.invoke(
            InvokeRequest(TaskId("hammt1.op"), {"v": idx}, ws_q, ws_q, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(t_out.ok)
        rel = query_daemon_control(ws_q.join(".cache"), ws_q, FrameKind.CONTROL_RELOAD, {"modules": ["hammt1"]})
        _check(rel is not None and rel.get("ok") is True)
        diags = _jlist(rel, "teardown_diagnostics")
        _check(any(isinstance(d, Mapping) and "hammer_td_err" in str(d.get("message", "")) for d in diags))


class _RejectOverflowRpcHandler(InboundCallHandler):
    def on_call(
        self,
        stream_id: int,
        payload: JsonObject,
        ack_accepted: typing.Callable[[], bool],
        emit_progress: typing.Callable[[JsonObject], None],
        peer_cancel_token: CancellationToken,
    ) -> tuple[bool, JsonObject]:
        _ = (stream_id, ack_accepted, emit_progress, peer_cancel_token)
        if payload.get("mode") == "nan":
            return (False, {"bad": float("nan")})
        return (False, {"blob": "X" * 4096})

    def on_control(self, kind: FrameKind, payload: JsonObject) -> JsonObject:
        _ = (kind, payload)
        return {"ok": True}


def _verify_rpc_unaccepted_overflow_and_posix_upgrade(ws8: HostPath) -> None:
    s1, s2 = socket.socketpair()
    srv_ch = MultiplexedChannel(s1, is_initiator=False, handler=_RejectOverflowRpcHandler(), max_frame_bytes=2048)
    cli_ch = MultiplexedChannel(s2, is_initiator=True, max_frame_bytes=2048)
    try:
        o_big = cli_ch.call({"mode": "big"}, timeout_ms=2000)
        o_nan = cli_ch.call({"mode": "nan"}, timeout_ms=2000)
        _check(o_big.error_code == ErrorCode.PAYLOAD_TOO_LARGE and not o_big.was_accepted and o_big.rejected_before_accept)
        _check(o_nan.error_code == ErrorCode.CODEC_VALIDATION_FAILED and not o_nan.was_accepted and o_nan.rejected_before_accept)
    finally:
        cli_ch.close()
        srv_ch.close()

    # Aborted handoff lease fast-exits wait_for_handoff_daemon_endpoint (< 0.35s instead of 8.0s)!
    ws_hf = HostPath(ws8.path / "ws_case_handoff_fast")
    ws_hf.join(".cache", "daemon").path.mkdir(parents=True, exist_ok=True)
    atomic_write_json(ws_hf.join(".cache", "daemon", "handoff_lease.json"), {"old_boot_id": "b_old", "expires_epoch": time.time() + 10.0})
    with _scoped_timer(0.05, lambda: ws_hf.join(".cache", "daemon", "handoff_lease.json").path.unlink(missing_ok=True)):
        t_h0 = time.monotonic()
        _check(wait_for_handoff_daemon_endpoint(ws_hf.join(".cache"), ws_hf, max_wait_sec=5.0) is None)
    _check((time.monotonic() - t_h0) < 0.45)

    # Concurrent dual-reader upgrade_to_exclusive NEVER drops LOCK_SH to a 3rd exclusive writer!
    lk_path = ws_hf.join(".cache", "cf_up.lock")
    lk_a, lk_b = FileLock(lk_path), FileLock(lk_path)
    _check(lk_a.acquire(shared=True, blocking=False) and lk_b.acquire(shared=True, blocking=False))
    stop_w = threading.Event()
    stolen_excl: list[bool] = []

    def _writer_probe() -> None:
        while not stop_w.is_set():
            w = FileLock(lk_path)
            if w.acquire(shared=False, blocking=False):
                stolen_excl.append(True)
                w.release()
            time.sleep(0.001)

    w_th = threading.Thread(target=_writer_probe, daemon=True)
    w_th.start()
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            fa = pool.submit(_expect_yscb_code, lambda: lk_a.upgrade_to_exclusive(timeout_sec=0.18), ErrorCode.ILLEGAL_LOCK_REENTRANCY)
            fb = pool.submit(_expect_yscb_code, lambda: lk_b.upgrade_to_exclusive(timeout_sec=0.18), ErrorCode.ILLEGAL_LOCK_REENTRANCY)
            fa.result(timeout=3.0)
            fb.result(timeout=3.0)
        _check(not stolen_excl and lk_a.is_acquired and lk_b.is_acquired)
    finally:
        stop_w.set()
        w_th.join(timeout=2.0)
        lk_a.release()
        lk_b.release()


def _provision_quiesce_and_coalesce_ws(ws_r: HostPath) -> None:
    provision_live_workspace(ws_r.path)
    _write_module(
        ws_r.path,
        "cfmodb",
        {
            "tier1": False,
            "tasks": [
                {"task_id": "cfmodb.ping"},
                {"task_id": "cfmodb.child_coal", "resource_key": "rk_cf_ch", "concurrency_mode": "coalesce"},
                {"task_id": "cfmodb.parent_coal", "resource_key": "rk_cf_par", "concurrency_mode": "coalesce"},
                {"task_id": "cfmodb.sub_ev", "exposure": "internal_trigger", "subscriptions": [{"event_id": "cfmodb.ev"}]},
            ],
        },
        (
            "from dataclasses import dataclass\nimport time\nfrom typing import Callable, Optional, Sequence\nfrom core.execution.event import EventMetadata, EventSubscriptionSpec\nfrom core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\nfrom core.filesystem.fs import atomic_write_json, read_json_dict\nfrom core.foundation.primitives import EventId, HostPath, ModuleId, TaskId\n@dataclass(frozen=True, slots=True)\nclass BIn:\n    tag: str = ''\n    fail: bool = False\n@dataclass(frozen=True, slots=True)\nclass BOut:\n    tag: str = 'ok'\nEV_COAL_FAIL = EventMetadata(EventId('cfmodb.ev'), BIn)\nclass PingT(Task[BIn, BOut]):\n    @property\n    def metadata(self) -> TaskMetadata[BIn, BOut]: return TaskMetadata(TaskId('cfmodb.ping'), BIn, BOut)\n    def run(self, req: BIn, ctx: TaskContext) -> BOut: return BOut(tag='b_v1')\nclass ChildCoalT(Task[BIn, BOut]):\n    @property\n    def metadata(self) -> TaskMetadata[BIn, BOut]:\n        return TaskMetadata(TaskId('cfmodb.child_coal'), BIn, BOut, resource_key='rk_cf_ch', concurrency_mode=ConcurrencyMode.COALESCE)\n    def run(self, req: BIn, ctx: TaskContext) -> BOut:\n        atomic_write_json(ctx.workspace_root.join('.cache', 'cf_ch_in.json'), {'ok': True})\n        dl = time.monotonic() + 3.0\n        while not ctx.workspace_root.join('.cache', 'cf_ch_go.json').path.is_file() and time.monotonic() < dl:\n            time.sleep(0.01)\n        ctx.emit(EV_COAL_FAIL, BIn(tag=req.tag))\n        return BOut(tag='ch_ok')\nclass ParentCoalT(Task[BIn, BOut]):\n    @property\n    def metadata(self) -> TaskMetadata[BIn, BOut]:\n        return TaskMetadata(TaskId('cfmodb.parent_coal'), BIn, BOut, resource_key='rk_cf_par', concurrency_mode=ConcurrencyMode.COALESCE)\n    def run(self, req: BIn, ctx: TaskContext) -> BOut:\n        if not (ctx.invoke_task(TaskId('cfmodb.child_coal'), {'tag': req.tag}).ok): raise AssertionError('embedded check failed')\n        if req.fail: raise RuntimeError('cf_parent_biz_err')\n        return BOut(tag='par_ok')\nclass SubEvT(Task[BIn, BOut]):\n    @property\n    def metadata(self) -> TaskMetadata[BIn, BOut]:\n        return TaskMetadata(TaskId('cfmodb.sub_ev'), BIn, BOut, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('cfmodb.ev'), lambda xs: xs[-1] if xs else None),))\n    def run(self, req: BIn, ctx: TaskContext) -> BOut:\n        p = ctx.workspace_root.join('.cache', 'cf_sub_cnt.json')\n        c = int((read_json_dict(p) or {}).get('cnt', 0)) + 1\n        atomic_write_json(p, {'cnt': c})\n        return BOut(tag=str(c))\nclass BMod(YscbModule):\n    @property\n    def module_id(self) -> ModuleId: return ModuleId('cfmodb')\n    def on_init(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:\n        def _cls() -> None:\n            raise RuntimeError('cf_watcher_td_err')\n        return _cls\n    def tasks(self) -> Sequence[BoundTask]: return (PingT(), ChildCoalT(), ParentCoalT(), SubEvT())\ndef create_module() -> YscbModule: return BMod()\n"
        ),
    )


