            "        return TaskMetadata(TaskId('a0fail.sub'), DWrap, DWrap, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('deepmod.deep_ev'), lambda xs: xs[-1] if xs else None),))\n"
            "    def run(self, req: DWrap, ctx: TaskContext) -> DWrap:\n"
            "        raise RuntimeError('de_a0_sub_boom')\n"
            "class A0Mod(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId('a0fail')\n"
            "    def on_init(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:\n"
            "        def _cls() -> None:\n            raise RuntimeError('de_a0_td_boom')\n"
            "        return _cls\n"
            "    def tasks(self) -> Sequence[BoundTask]: return (FailSub(),)\n"
