        deep125 = _make_nested_dict_depth(125)
        c_out = cli_disp.invoke(
            InvokeRequest(TaskId("zt0deep.emit_main"), {"data": deep125}, ws_r, ws_r, routing_policy=ClientRoutingPolicy.FORCE_COLD)
        )
