def _verify_filelock_upgrade_no_starvation(ws8: HostPath) -> None:
    lk_path = ws8.join("locks_atomic_xchg", "contended.lock")
    lk_path.path.parent.mkdir(parents=True, exist_ok=True)
    worker_code = """
import sys, time
sys.path.insert(0, sys.argv[1])
from core.filesystem.fs import FileLock
from core.foundation.primitives import HostPath
p = HostPath(sys.argv[2])
mode = sys.argv[3]
stop_at = time.monotonic() + 1.1
while time.monotonic() < stop_at:
    lk = FileLock(p)
    try:
        if lk.acquire(shared=(mode == "r"), blocking=True, timeout_sec=0.4):
            time.sleep(0.003)
            lk.release()
    except Exception:
        pass
    time.sleep(0.001)
"""
    src_root = str(Path(__file__).resolve().parent / "source" / "core")
    procs = [
        subprocess.Popen(
            [sys.executable, "-B", "-c", worker_code, src_root, str(lk_path), "r" if i < 3 else "w"],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        for i in range(4)
    ]
    try:
        time.sleep(0.05)
        for _ in range(4):
            up_lk = FileLock(lk_path)
            _check(up_lk.acquire(shared=True, blocking=True, timeout_sec=3.0))
            try:
                up_lk.upgrade_to_exclusive(timeout_sec=3.0)
                up_lk.downgrade_to_shared(timeout_sec=3.0)
            finally:
                up_lk.release()
    finally:
        for pr in procs:
            try:
                pr.wait(timeout=5.0)
            except subprocess.TimeoutExpired:
                _reap_popen_quietly(pr)
        for pr in procs:
            _reap_popen_quietly(pr)


def _verify_nested_session_forest_reaping(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_f = HostPath(ws8.path / "ws_nested_forest")
    provision_live_workspace(ws_f.path)
    _write_module(
        ws_f.path,
        "forest_mod",
        {"tier1": True, "venv_group": "forest_grp", "eager_warmup": True, "tasks": [{"task_id": "forest_mod.hang", "timeout_ms": 450}]},
        (
            "from __future__ import annotations\n"
            "from dataclasses import dataclass\n"
            "import subprocess, sys, time\n"
            "from typing import Sequence\n"
            "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
            "from core.foundation.primitives import ModuleId, TaskId\n"
            "from core.foundation.proc import ManagedProcessTree\n"
            "@dataclass(frozen=True, slots=True)\nclass FDto:\n    v: int = 0\n"
            "class HangTask(Task[FDto, FDto]):\n"
            "    @property\n    def metadata(self) -> TaskMetadata[FDto, FDto]:\n"
            "        return TaskMetadata(TaskId('forest_mod.hang'), FDto, FDto, timeout_ms=450)\n"
            "    def run(self, req: FDto, ctx: TaskContext) -> FDto:\n"
            "        out_f = ctx.workspace_root.join('.cache', 'forest_pids.json')\n"
            "        code = (\n"
            "            'import json, os, subprocess, sys, time; from pathlib import Path; '\n"
            "            'gc = subprocess.Popen([sys.executable, \"-B\", \"-c\", \"import time; time.sleep(30)\"], start_new_session=True); '\n"
            "            f'Path({str(out_f)!r}).write_text(json.dumps({{\"child\": os.getpid(), \"grandchild\": gc.pid, \"worker\": os.getppid()}})); '\n"
            "            'time.sleep(30)'\n"
            "        )\n"
            "        _ = ManagedProcessTree([sys.executable, '-B', '-c', code], cwd=ctx.workspace_root, inherit_tty=False)\n"
            "        for _ in range(80):\n"
            "            if out_f.path.is_file(): break\n"
            "            time.sleep(0.01)\n"
            "        time.sleep(10.0)\n"
            "        return req\n"
            "class FMod(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId('forest_mod')\n"
            "    def tasks(self) -> Sequence[BoundTask]: return (HangTask(),)\n"
            "def create_module() -> YscbModule: return FMod()\n"
        ),
    )
    disp_f = build_dispatcher_for_workspace(ws_f, venv_bin, is_daemon_host=True).dispatcher
    try:
        disp_f.warmup_daemon_container()
        out = disp_f.invoke(InvokeRequest(TaskId("forest_mod.hang"), {}, ws_f, ws_f))
        _check(not out.ok and out.error is not None and out.error.code == ErrorCode.TASK_TIMEOUT)
        pid_doc = read_json_dict(ws_f.join(".cache", "forest_pids.json"))
        _check(pid_doc is not None)
        pids = [int(pid_doc["worker"]), int(pid_doc["child"]), int(pid_doc["grandchild"])]
        deadline = time.monotonic() + 3.0
        while time.monotonic() < deadline and any(is_process_alive(pid) for pid in pids):
            time.sleep(0.03)
        alive_left = [pid for pid in pids if is_process_alive(pid)]
        for lp in alive_left:
            try:
                os.kill(lp, signal.SIGKILL)
            except OSError:
                pass
        _check(not alive_left, lambda: f"Orphan nested session processes leaked: {alive_left}")
    finally:
        disp_f.shutdown(grace_ms=200)


def _verify_deferred_boot_selective_lease_and_space_watch(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_db = HostPath(ws8.path / "ws_defboot_sel_lease")
