        _check(dmn_disp.reload_gate.is_module_quiesced(ModuleId("ast")) is False)
        ast_hot = cli_disp.invoke(InvokeRequest(TaskId("space.echo_tier0"), {"tag": "hot_ok"}, ws_db, ws_db, routing_policy=ClientRoutingPolicy.STRICT_HOT))
        _check(ast_hot.ok and ast_hot.executed_hot)
