            "    def run(self, req: SDto, ctx: TaskContext) -> SDto:\n"
            "        if req.wait_f2:\n"
            "            for _ in range(80):\n"
            "                if ctx.workspace_root.join('.cache', f'f2_in_{req.key}.json').path.is_file(): break\n"
            "                time.sleep(0.005)\n"
