            "    def run(self, req: SDto, ctx: TaskContext) -> SDto: return SDto(key=f'ok:{req.key}')\n"
            "class QCoal(Task[SDto, SDto]):\n"
            "    @property\n    def metadata(self) -> TaskMetadata[SDto, SDto]:\n"
            "        return TaskMetadata(TaskId('sym_fl.q_coal'), SDto, SDto, resource_key='rk_sym_qc', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.key)\n"
            "    def run(self, req: SDto, ctx: TaskContext) -> SDto:\n"
            "        atomic_write_json(ctx.workspace_root.join('.cache', f'qc_in_{req.key}.json'), {'ok': True})\n"
            "        time.sleep(0.07)\n"
