def _provision_sym_nested_flight_modules(ws_sn: Path) -> None:
    _write_module(
        ws_sn,
        "sym_fl",
        {
            "tier1": False,
            "tasks": [
                {"task_id": "sym_fl.outer_pre", "resource_key": "rk_sym_pre", "concurrency_mode": "preempt"},
                {"task_id": "sym_fl.flight_one", "resource_key": "rk_sym_f1", "concurrency_mode": "coalesce"},
                {"task_id": "sym_fl.flight_two", "resource_key": "rk_sym_f2", "concurrency_mode": "coalesce"},
                {"task_id": "sym_fl.leaf_ser", "resource_key": "rk_sym_pre", "concurrency_mode": "serialize"},
                {"task_id": "sym_fl.q_coal", "resource_key": "rk_sym_qc", "concurrency_mode": "coalesce"},
            ],
        },
        _SYM_FL_MOD_SRC,
    )
    _write_module(
        ws_sn,
        "q_leaf",
        {"tier1": False, "tasks": [{"task_id": "q_leaf.ping"}]},
        (
            "from __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Sequence\n"
            "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
            "from core.foundation.primitives import ModuleId, TaskId\n"
            "@dataclass(frozen=True, slots=True)\nclass SDto:\n    key: str = 'k'\n    wait_f2: bool = False\n"
            "class PingT(Task[SDto, SDto]):\n"
            "    @property\n    def metadata(self) -> TaskMetadata[SDto, SDto]: return TaskMetadata(TaskId('q_leaf.ping'), SDto, SDto)\n"
            "    def run(self, req: SDto, ctx: TaskContext) -> SDto: return SDto(key=f'pong:{req.key}')\n"
            "class QLMod(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId('q_leaf')\n"
            "    def tasks(self) -> Sequence[BoundTask]: return (PingT(),)\n"
            "def create_module() -> YscbModule: return QLMod()\n"
        ),
    )


def _verify_symmetric_nested_flight_and_leased_quiesce(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_sn = HostPath(ws8.path / "ws_sym_nested")
    provision_live_workspace(ws_sn.path)
    _provision_sym_nested_flight_modules(ws_sn.path)
    disp = build_dispatcher_for_workspace(ws_sn, venv_bin, is_daemon_host=True).dispatcher
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            # Order A: Flight_1 enters Flight_2 first, innocent Caller_I joins Flight_2 second!
            fa_bad = pool.submit(disp.invoke, InvokeRequest(TaskId("sym_fl.outer_pre"), {"key": "ord_a", "wait_f2": False}, ws_sn, ws_sn))
            _wait_file_marker(ws_sn.path / ".cache" / "f2_in_ord_a.json", timeout_sec=3.0)
            fa_ok = pool.submit(disp.invoke, InvokeRequest(TaskId("sym_fl.flight_two"), {"key": "ord_a"}, ws_sn, ws_sn))
            ra_bad, ra_ok = fa_bad.result(timeout=4.0), fa_ok.result(timeout=4.0)
            _check(not ra_bad.ok and ra_bad.error is not None and ra_bad.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
            _check(ra_ok.ok and isinstance(ra_ok.value, Mapping) and ra_ok.value.get("key") == "ok:ord_a")

            # Order B: Innocent Caller_I enters Flight_2 first, Flight_1 joins Flight_2 second!
            fb_ok = pool.submit(disp.invoke, InvokeRequest(TaskId("sym_fl.flight_two"), {"key": "ord_b"}, ws_sn, ws_sn))
            fb_bad = pool.submit(disp.invoke, InvokeRequest(TaskId("sym_fl.outer_pre"), {"key": "ord_b", "wait_f2": True}, ws_sn, ws_sn))
            rb_bad, rb_ok = fb_bad.result(timeout=4.0), fb_ok.result(timeout=4.0)
            _check(not rb_bad.ok and rb_bad.error is not None and rb_bad.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
            _check(rb_ok.ok and isinstance(rb_ok.value, Mapping) and rb_ok.value.get("key") == "ok:ord_b")

            # Leased quiesce symmetry: event-chain caller arrives BEFORE foreground caller -> waits on leased q_leaf and succeeds!
            _check(disp.try_quiesce_modules(frozenset({ModuleId("q_leaf")}), leased=True) is not None)
            ev_req = InvokeRequest(
                TaskId("sym_fl.q_coal"), {"key": "lq1"}, ws_sn, ws_sn,
                propagation=CallPropagationContext(is_internal_trigger=True, in_event_chain=True),
            )
            fg_req = InvokeRequest(TaskId("sym_fl.q_coal"), {"key": "lq1"}, ws_sn, ws_sn)
            f_ev = pool.submit(disp.invoke, ev_req)
            _wait_file_marker(ws_sn.path / ".cache" / "qc_in_lq1.json", timeout_sec=3.0)
            f_fg = pool.submit(disp.invoke, fg_req)
            with _scoped_timer(0.11, lambda: disp.resume_from_quiesce(modules=frozenset({ModuleId("q_leaf")}))):
                r_ev, r_fg = f_ev.result(timeout=4.0), f_fg.result(timeout=4.0)
            _check(r_fg.ok and isinstance(r_fg.value, Mapping) and r_fg.value.get("key") == "pong:lq1")
            _check(r_ev.ok)
    finally:
        disp.shutdown(grace_ms=100)


def _verify_deferred_route_index_and_dup_turn_isolation(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_di = HostPath(ws8.path / "ws_def_idx")
    provision_live_workspace(ws_di.path)
    inst_lk = FileLock(ws_di.join(".cache", "locks", "installer.lock"))
    _check(inst_lk.acquire(shared=False, blocking=True, timeout_sec=3.0))
    disp_d = build_dispatcher_for_workspace(ws_di, venv_bin, is_daemon_host=True).dispatcher
    try:
        m_nm = ws_di.path / ".modules" / "nomf_mod"
        m_nm.mkdir(parents=True, exist_ok=True)
        (m_nm / "module_entry.py").write_text(
            "from __future__ import annotations\nfrom dataclasses import dataclass\nimport time\nfrom typing import Sequence\n"
            "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
            "from core.foundation.primitives import ModuleId, TaskId\n"
            "@dataclass(frozen=True, slots=True)\nclass NDto:\n    v: int = 0\n"
            "class SlowEcho(Task[NDto, NDto]):\n"
            "    @property\n    def metadata(self) -> TaskMetadata[NDto, NDto]: return TaskMetadata(TaskId('nomf_mod.echo'), NDto, NDto)\n"
            "    def run(self, req: NDto, ctx: TaskContext) -> NDto:\n        time.sleep(0.04); return NDto(v=req.v + 1)\n"
            "class NMod(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId('nomf_mod')\n"
            "    def tasks(self) -> Sequence[BoundTask]: return (SlowEcho(),)\n"
            "def create_module() -> YscbModule: return NMod()\n",
            encoding="utf-8",
        )
        _check(not any(s.task_id == TaskId("nomf_mod.echo") for s in disp_d.list_route_specs()))
        inst_lk.release()
        _check(any(s.task_id == TaskId("nomf_mod.echo") for s in disp_d.list_route_specs()))
        dup_prop = CallPropagationContext(turn_id="dup_top_tid")
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f1 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("nomf_mod.echo"), {"v": 10}, ws_di, ws_di, propagation=dup_prop))
            f2 = pool.submit(disp_d.invoke, InvokeRequest(TaskId("nomf_mod.echo"), {"v": 20}, ws_di, ws_di, propagation=dup_prop))
            r1, r2 = f1.result(timeout=4.0), f2.result(timeout=4.0)
        _check(r1.ok and r1.value == {"v": 11} and r2.ok and r2.value == {"v": 21})
        _check(disp_d.active_turn_count == 0)
    finally:
        if inst_lk.is_acquired:
            inst_lk.release()
        disp_d.shutdown(grace_ms=100)



_SEAL_AND_EV_CYCLE_MOD_SRC: Final[str] = (
    "from __future__ import annotations\nfrom dataclasses import dataclass\nimport time\nfrom typing import Sequence\nfrom core.execution.event import EventMetadata, EventSubscriptionSpec\nfrom core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\nfrom core.filesystem.fs import atomic_write_json\nfrom core.foundation.primitives import EventId, ModuleId, TaskId\n@dataclass(frozen=True, slots=True)\nclass RDto:\n    k: str = 'a'\nEV_LP = EventMetadata(EventId('sealm.loop'), RDto)\nclass SealFlightTask(Task[RDto, RDto]):\n    @property\n    def metadata(self) -> TaskMetadata[RDto, RDto]:\n        return TaskMetadata(TaskId('sealm.seal_fl'), RDto, RDto, resource_key='rk_seal_sf', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.k)\n    def run(self, req: RDto, ctx: TaskContext) -> RDto:\n        try:\n            _ = ctx.invoke_task(TaskId('sealm.seal_caller'), req, output_type=RDto)\n            return RDto(k=f'clean:{req.k}')\n        finally:\n            if not ctx.workspace_root.join('.cache', f'sf_fin_{req.k}.json').path.is_file():\n                atomic_write_json(ctx.workspace_root.join('.cache', f'sf_fin_{req.k}.json'), {'fin': True})\n                time.sleep(0.09)\nclass SealCallerTask(Task[RDto, RDto]):\n    @property\n    def metadata(self) -> TaskMetadata[RDto, RDto]: return TaskMetadata(TaskId('sealm.seal_caller'), RDto, RDto)\n    def run(self, req: RDto, ctx: TaskContext) -> RDto:\n        if req.k == 'init_cyc':\n            out = ctx.invoke_task(TaskId('sealm.seal_fl'), RDto(k='cyc1'), output_type=RDto)\n            if not (out.ok): raise AssertionError('embedded check failed')\n        return RDto(k='leaf')\nclass TrigLoopTask(Task[RDto, RDto]):\n    @property\n    def metadata(self) -> TaskMetadata[RDto, RDto]: return TaskMetadata(TaskId('sealm.trig_loop'), RDto, RDto)\n    def run(self, req: RDto, ctx: TaskContext) -> RDto:\n        ctx.emit(EV_LP, req); return req\nclass SubPreLoopTask(Task[RDto, RDto]):\n    @property\n    def metadata(self) -> TaskMetadata[RDto, RDto]:\n        return TaskMetadata(TaskId('sealm.sub_pre'), RDto, RDto, exposure=TaskExposure.INTERNAL_TRIGGER, resource_key='rk_seal_sub', concurrency_mode=ConcurrencyMode.PREEMPT, subscriptions=(EventSubscriptionSpec(EventId('sealm.loop'), lambda xs: xs[0]),))\n    def run(self, req: RDto, ctx: TaskContext) -> RDto:\n        if req.k == 'start':\n            out = ctx.invoke_task(TaskId('sealm.imm_coal'), RDto(k='shared'), output_type=RDto)\n            if not (out.ok): raise AssertionError('embedded check failed')\n        return req\nclass ImmCoalTask(Task[RDto, RDto]):\n    @property\n    def metadata(self) -> TaskMetadata[RDto, RDto]:\n        return TaskMetadata(TaskId('sealm.imm_coal'), RDto, RDto, resource_key='rk_seal_ic', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.k)\n    def run(self, req: RDto, ctx: TaskContext) -> RDto:\n        atomic_write_json(ctx.workspace_root.join('.cache', 'seal_ic_in.json'), {'in': True})\n        time.sleep(0.08)\n        ctx.emit_imm(EV_LP, RDto(k='reemit'), strict=False)\n        return RDto(k='ic_done')\nclass SealEvMod(YscbModule):\n    @property\n    def module_id(self) -> ModuleId: return ModuleId('sealm')\n    def tasks(self) -> Sequence[BoundTask]: return (SealFlightTask(), SealCallerTask(), TrigLoopTask(), SubPreLoopTask(), ImmCoalTask())\ndef create_module() -> YscbModule: return SealEvMod()\n"
)


def _verify_seal_ev_cycle_degrade_and_reload(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_x = HostPath(ws8.path / "ws_case_adv")
    provision_live_workspace(ws_x.path)
    _write_module(
        ws_x.path,
        "sealm",
        {
            "tier1": False,
            "tasks": [
                {"task_id": "sealm.seal_fl", "resource_key": "rk_seal_sf", "concurrency_mode": "coalesce"},
                {"task_id": "sealm.seal_caller"},
                {"task_id": "sealm.trig_loop"},
                {"task_id": "sealm.sub_pre", "exposure": "internal_trigger", "resource_key": "rk_seal_sub", "concurrency_mode": "preempt", "subscriptions": [{"event_id": "sealm.loop"}]},
                {"task_id": "sealm.imm_coal", "resource_key": "rk_seal_ic", "concurrency_mode": "coalesce"},
            ],
        },
        _SEAL_AND_EV_CYCLE_MOD_SRC,
    )
    m_brk = ws_x.path / ".modules" / "brk_t0"
    m_brk.mkdir(parents=True, exist_ok=True)
    atomic_write_json(HostPath(m_brk / "routes.json"), {"module_id": "brk_t0", "tier1": False, "tasks": [{"task_id": "brk_t0.op"}]})
    (m_brk / "module_entry.py").write_text("raise RuntimeError('import_crash_seal')\n", encoding="utf-8")

    disp_x = build_dispatcher_for_workspace(ws_x, venv_bin, is_daemon_host=True).dispatcher
    try:
        # 1) Module load failure via get_task_uninitialized MUST report MODULE_DEGRADED and record degraded_modules!
        brk_out = disp_x.invoke(InvokeRequest(TaskId("brk_t0.op"), {}, ws_x, ws_x))
        _check(not brk_out.ok and brk_out.error is not None and brk_out.error.code == ErrorCode.MODULE_DEGRADED)
        _check(ModuleId("brk_t0") in disp_x.container_lifecycle.degraded_modules)

        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            # 2) Follower arriving during fatal StepFlight finally cleanup MUST NOT join doomed flight!
            f_cyc = pool.submit(disp_x.invoke, InvokeRequest(TaskId("sealm.seal_caller"), {"k": "init_cyc"}, ws_x, ws_x))
            _wait_file_marker(ws_x.path / ".cache" / "sf_fin_cyc1.json", timeout_sec=3.0)
            f_late = pool.submit(disp_x.invoke, InvokeRequest(TaskId("sealm.seal_fl"), {"k": "cyc1"}, ws_x, ws_x))
            r_cyc, r_late = f_cyc.result(timeout=4.0), f_late.result(timeout=4.0)
            _check(not r_cyc.ok and r_cyc.error is not None and r_cyc.error.code == ErrorCode.CALL_CYCLE_DETECTED)
            _check(r_late.ok and r_late.value == {"k": "clean:cyc1"})

            # 3) PREEMPT event subscriber coalesced with clean peer on emit_imm cycle MUST get EVENT_CYCLE_DETECTED!
            f_ev = pool.submit(disp_x.invoke, InvokeRequest(TaskId("sealm.trig_loop"), {"k": "start"}, ws_x, ws_x))
            _wait_file_marker(ws_x.path / ".cache" / "seal_ic_in.json", timeout_sec=3.0)
            f_peer = pool.submit(disp_x.invoke, InvokeRequest(TaskId("sealm.imm_coal"), {"k": "shared"}, ws_x, ws_x))
            r_ev, r_peer = f_ev.result(timeout=4.0), f_peer.result(timeout=4.0)
            _check(r_peer.ok and r_peer.value == {"k": "ic_done"})
            _check(not r_ev.ok and r_ev.error is not None and r_ev.error.code == ErrorCode.EVENT_CYCLE_DETECTED)
    finally:
        disp_x.shutdown(grace_ms=100)



