    "    def run(self, req: WDto, ctx: TaskContext) -> WDto:\n"
    "        atomic_write_json(ctx.workspace_root.join('.cache', f'we_osh_{req.k}.json'), {'held': True})\n"
    "        time.sleep(0.06)\n"
    "        out = ctx.invoke_task(TaskId('we_mod.mid_coal'), WDto(k=req.k), output_type=WDto)\n"
    "        if not out.ok and out.error is not None: raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)\n"
    "        return out.value or req\n"
    "class MidCoal(Task[WDto, WDto]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[WDto, WDto]:\n"
    "        return TaskMetadata(TaskId('we_mod.mid_coal'), WDto, WDto, resource_key='rk_we_mid', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.k)\n"
    "    def run(self, req: WDto, ctx: TaskContext) -> WDto:\n"
    "        out = ctx.invoke_task(TaskId('we_mod.inner_ser'), req, output_type=WDto)\n"
    "        if not out.ok and out.error is not None: raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)\n"
    "        return out.value or req\n"
    "class InnerSer(Task[WDto, WDto]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[WDto, WDto]:\n"
    "        return TaskMetadata(TaskId('we_mod.inner_ser'), WDto, WDto, resource_key='rk_we_tgt', concurrency_mode=ConcurrencyMode.SERIALIZE)\n"
    "    def run(self, req: WDto, ctx: TaskContext) -> WDto: return WDto(k=f'done:{req.k}')\n"
    "class EmitQCoal(Task[WDto, WDto]):\n"
    "    @property\n    def metadata(self) -> TaskMetadata[WDto, WDto]:\n"
    "        return TaskMetadata(TaskId('we_mod.emit_q'), WDto, WDto, resource_key='rk_we_eq', concurrency_mode=ConcurrencyMode.COALESCE, equivalence_fn=lambda r: r.k, timeout_ms=500)\n"
    "    def run(self, req: WDto, ctx: TaskContext) -> WDto:\n"
    "        atomic_write_json(ctx.workspace_root.join('.cache', f'we_eq_{req.k}.json'), {'in': True})\n"
    "        time.sleep(0.06)\n"
    "        if req.k.startswith('cyc'): ctx.emit(EV_C, req)\n"
