def _provision_wait_edge_workspace(ws8: HostPath) -> HostPath:
    ws_w = HostPath(ws8.path / "ws_wait_edge_q")
    provision_live_workspace(ws_w.path)
    _write_module(
        ws_w.path,
        "we_mod",
        {
            "tier1": False,
            "tasks": [
                {"task_id": "we_mod.outer_coal", "resource_key": "rk_we_tgt", "concurrency_mode": "coalesce"},
                {"task_id": "we_mod.outer_ser", "resource_key": "rk_we_tgt", "concurrency_mode": "serialize"},
                {"task_id": "we_mod.mid_coal", "resource_key": "rk_we_mid", "concurrency_mode": "coalesce"},
                {"task_id": "we_mod.inner_ser", "resource_key": "rk_we_tgt", "concurrency_mode": "serialize"},
                {"task_id": "we_mod.emit_q", "resource_key": "rk_we_eq", "concurrency_mode": "coalesce", "timeout_ms": 500},
                {"task_id": "we_mod.sub_cyc", "exposure": "internal_trigger", "subscriptions": [{"event_id": "we_mod.ev_cyc"}]},
            ],
        },
        _WAIT_EDGE_CASCADE_MOD_SRC,
    )
    _write_module(
        ws_w.path,
        "we_qsub",
        {"tier1": False, "tasks": [{"task_id": "we_qsub.on_q", "exposure": "internal_trigger", "subscriptions": [{"event_id": "we_mod.ev_q"}]}]},
        (
            "from __future__ import annotations\nfrom dataclasses import dataclass\nfrom typing import Sequence\n"
            "from core.execution.event import EventSubscriptionSpec\n"
            "from core.execution.runtime import BoundTask, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\n"
            "from core.foundation.primitives import EventId, ModuleId, TaskId\n"
            "@dataclass(frozen=True, slots=True)\nclass WDto:\n    k: str = 'a'\n    hold_ms: int = 0\n"
            "class OnQT(Task[WDto, WDto]):\n"
            "    @property\n    def metadata(self) -> TaskMetadata[WDto, WDto]:\n"
            "        return TaskMetadata(TaskId('we_qsub.on_q'), WDto, WDto, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('we_mod.ev_q'), lambda xs: xs[0]),))\n"
            "    def run(self, req: WDto, ctx: TaskContext) -> WDto: return req\n"
            "class QSubM(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId('we_qsub')\n"
            "    def tasks(self) -> Sequence[BoundTask]: return (OnQT(),)\n"
            "def create_module() -> YscbModule: return QSubM()\n"
        ),
    )
    return ws_w


def _verify_late_holder_wait_edges_and_cascade_quiesce(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_w = _provision_wait_edge_workspace(ws8)
    disp_w = build_dispatcher_for_workspace(ws_w, venv_bin, is_daemon_host=True).dispatcher
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            # 1) Late-joining COALESCE holder into already-waiting StepFlight -> ILLEGAL_LOCK_REENTRANCY without deadlocking innocent peer!
            f_bad = pool.submit(disp_w.invoke, InvokeRequest(TaskId("we_mod.outer_coal"), {"k": "late_c"}, ws_w, ws_w))
            _wait_file_marker(ws_w.path / ".cache" / "we_och_late_c.json", timeout_sec=3.0)
            f_good = pool.submit(disp_w.invoke, InvokeRequest(TaskId("we_mod.mid_coal"), {"k": "late_c"}, ws_w, ws_w))
            r_bad, r_good = f_bad.result(timeout=4.0), f_good.result(timeout=4.0)
            _check(not r_bad.ok and r_bad.error is not None and r_bad.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
            _check(r_good.ok and r_good.value == {"k": "done:late_c", "hold_ms": 0})

            # 2) Late-joining SERIALIZE holder into already-waiting StepFlight -> legal reentrant grant, BOTH succeed!
            f_ser = pool.submit(disp_w.invoke, InvokeRequest(TaskId("we_mod.outer_ser"), {"k": "late_s"}, ws_w, ws_w))
            _wait_file_marker(ws_w.path / ".cache" / "we_osh_late_s.json", timeout_sec=3.0)
            f_peer = pool.submit(disp_w.invoke, InvokeRequest(TaskId("we_mod.mid_coal"), {"k": "late_s"}, ws_w, ws_w))
            r_ser, r_peer = f_ser.result(timeout=4.0), f_peer.result(timeout=4.0)
            _check(r_ser.ok and r_peer.ok and r_peer.value == {"k": "done:late_s", "hold_ms": 0})

            # 3) 2-caller FlightCascade emitting event to leased-QUIESCED module fast-fails subscriber into event_diagnostics!
            disp_w.reload_gate.record_quiesce_lease(False, frozenset({ModuleId("we_qsub")}), lease_sec=10.0)
            try:
                fq1 = pool.submit(disp_w.invoke, InvokeRequest(TaskId("we_mod.emit_q"), {"k": "qcas"}, ws_w, ws_w))
                _wait_file_marker(ws_w.path / ".cache" / "we_eq_qcas.json", timeout_sec=3.0)
                fq2 = pool.submit(disp_w.invoke, InvokeRequest(TaskId("we_mod.emit_q"), {"k": "qcas"}, ws_w, ws_w))
                rq1, rq2 = fq1.result(timeout=3.0), fq2.result(timeout=3.0)
                _check(rq1.ok and rq2.ok)
                _check(any(d.code == ErrorCode.DAEMON_UNAVAILABLE for d in rq1.event_diagnostics))
                _check(any(d.code == ErrorCode.DAEMON_UNAVAILABLE for d in rq2.event_diagnostics))
            finally:
                disp_w.resume_from_quiesce(modules=frozenset({ModuleId("we_qsub")}))

            # 4) Direct TurnEngine.execute_turn with FlightCascade event cycle MUST surface fatal_event_error!
            te_direct = TurnEngine(disp_w)
            fc1 = pool.submit(te_direct.execute_turn, InvokeRequest(TaskId("we_mod.emit_q"), {"k": "cyc_ab"}, ws_w, ws_w), TurnKind.HOT_FOREGROUND)
            _wait_file_marker(ws_w.path / ".cache" / "we_eq_cyc_ab.json", timeout_sec=3.0)
            fc2 = pool.submit(te_direct.execute_turn, InvokeRequest(TaskId("we_mod.emit_q"), {"k": "cyc_ab"}, ws_w, ws_w), TurnKind.HOT_FOREGROUND)
            rc1, rc2 = fc1.result(timeout=3.0), fc2.result(timeout=3.0)
            _check(rc1.fatal_event_error is not None and rc1.fatal_event_error.code == ErrorCode.EVENT_CYCLE_DETECTED)
            _check(rc2.fatal_event_error is not None and rc2.fatal_event_error.code == ErrorCode.EVENT_CYCLE_DETECTED)
    finally:
        disp_w.shutdown(grace_ms=200)



