def _verify_signal_wakeup_guard_no_deadlock() -> None:
    if os.name == "nt":
        return
    non_reentrant = threading.Lock()
    fired = threading.Event()
    sig_num = int(signal.SIGUSR1)
    with SignalWakeupGuard((sig_num,), lambda: (non_reentrant.acquire(), (fired.set(), non_reentrant.release()))[1][0]):
        with non_reentrant:
            os.kill(os.getpid(), sig_num)
            time.sleep(0.01)
        _check(fired.wait(timeout=1.5), "SignalWakeupGuard failed to fire callback after lock release")


def _verify_xws_symmetric_flight_eviction(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_a = HostPath(ws8.path / "ws_sym_xa")
    ws_b = HostPath(ws8.path / "ws_sym_xb")
    provision_live_workspace(ws_a.path)
    provision_live_workspace(ws_b.path)
    _write_module(
        ws_a.path,
        "ma",
        {
            "tier1": False,
            "tasks": [
                {"task_id": "ma.hold_and_call_b", "resource_key": "rk_ma", "concurrency_mode": "serialize"},
                {"task_id": "ma.reenter_preempt", "resource_key": "rk_ma", "concurrency_mode": "preempt"},
            ],
        },
        _XWS_SYM_A_SRC,
    )
    _write_module(
        ws_b.path,
        "mb",
        {"tier1": False, "tasks": [{"task_id": "mb.coal_step", "resource_key": "rk_mb", "concurrency_mode": "coalesce"}]},
        _XWS_SYM_B_SRC,
    )
    disp_a = build_dispatcher_for_workspace(ws_a, venv_bin, ttl_sec=25.0).dispatcher
    disp_b = build_dispatcher_for_workspace(ws_b, venv_bin, ttl_sec=25.0).dispatcher
    try:
        disp_a.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="xa_boot"))
        disp_b.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="xb_boot"))
        wait_for_daemon_online(ws_a)
        wait_for_daemon_online(ws_b)
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            f_c2 = pool.submit(disp_b.invoke, InvokeRequest(TaskId("mb.coal_step"), {"k": "ord1", "peer_ws": str(ws_a)}, ws_b, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
            _wait_file_marker(ws_b.path / ".cache" / "mb_in_ord1.json", timeout_sec=3.0)
            f_c1 = pool.submit(disp_a.invoke, InvokeRequest(TaskId("ma.hold_and_call_b"), {"k": "ord1", "peer_ws": str(ws_b)}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
            r_c1, r_c2 = f_c1.result(timeout=4.0), f_c2.result(timeout=4.0)
            _check(not r_c1.ok and r_c1.error is not None and r_c1.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
            _check(r_c2.ok and r_c2.value == {"k": "pre_ok:ord1", "peer_ws": ""})

            f2_c1 = pool.submit(disp_a.invoke, InvokeRequest(TaskId("ma.hold_and_call_b"), {"k": "ord2", "peer_ws": str(ws_b)}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
            _wait_file_marker(ws_b.path / ".cache" / "mb_in_ord2.json", timeout_sec=3.0)
            f2_c2 = pool.submit(disp_b.invoke, InvokeRequest(TaskId("mb.coal_step"), {"k": "ord2", "peer_ws": str(ws_a)}, ws_b, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT))
            sc_c1, sc_c2 = f2_c1.result(timeout=4.0), f2_c2.result(timeout=4.0)
            _check(not sc_c1.ok and sc_c1.error is not None and sc_c1.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
            _check(sc_c2.ok and sc_c2.coalesced is True and sc_c2.value == {"k": "pre_ok:ord2", "peer_ws": ""})
    finally:
        stop_daemon_cleanly(ws_a)
        stop_daemon_cleanly(ws_b)
        disp_a.shutdown(grace_ms=200)
        disp_b.shutdown(grace_ms=200)


def _verify_debounce_resync_preserves_config_changes(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_db = HostPath(ws8.path / "ws_cfg_debounce")
    _provision_cfg_ser_probe_ws(ws_db)
    cfg_dir = ws_db.join("config")
    cfg_dir.path.mkdir(parents=True, exist_ok=True)
    app_f = cfg_dir.join("app.json")
    first_f = cfg_dir.join("first.json")
    second_f = cfg_dir.join("second.json")
    atomic_write_json(app_f, {"v": 0})
    rig = build_dispatcher_for_workspace(ws_db, venv_bin, is_daemon_host=True, ttl_sec=30.0)
    disp, cfg_view = rig.dispatcher, rig.config_view
    dmn = WorkspaceDaemon(
        workspace_root=ws_db,
        cache_dir=ws_db.join(".cache"),
        dispatcher=disp,
        config_view=cfg_view,
        watch_config=DaemonWatcherConfig(
            config_watch_roots=(cfg_dir,),
            on_config_changed_task=TaskId("cs_probe.on_cfg"),
            watcher_debounce_sec=0.35,
        ),
    )
    th = threading.Thread(target=dmn.run_forever, daemon=True)
    th.start()
    try:
        wait_for_daemon_online(ws_db)
        atomic_write_json(app_f, {"v": 1})
        time.sleep(0.06)
        ack = query_daemon_control(ws_db.join(".cache"), ws_db, FrameKind.CONTROL_RELOAD, {"modules": ["cs_probe"]})
        _check(ack is not None and ack.get("ok") is True)
        hits_f = ws_db.path / ".cache" / "cfg_hits.json"
        _wait_file_marker(hits_f, timeout_sec=3.0)
        doc1 = read_json_dict(HostPath(hits_f))
        _check(doc1 is not None and str(app_f) in _jlist(doc1, "paths"))
        hits_f.unlink(missing_ok=True)

        inst_lk = FileLock(ws_db.join(".cache", "locks", "installer.lock"))
        _check(inst_lk.acquire(shared=False, blocking=True, timeout_sec=3.0))
        try:
            atomic_write_json(first_f, {"v": 1})
            time.sleep(0.42)
            atomic_write_json(second_f, {"v": 1})
            time.sleep(0.05)
        finally:
            inst_lk.release()
        _wait_file_marker(hits_f, timeout_sec=3.0)
        doc2 = read_json_dict(HostPath(hits_f))
        _check(doc2 is not None)
        seen_paths = set(_jlist(doc2, "paths"))
        _check(str(first_f) in seen_paths and str(second_f) in seen_paths)
    finally:
        dmn.request_shutdown()
        th.join(timeout=4.0)
        disp.shutdown(grace_ms=100)




_T0_BORROWED_GUARD_MOD_SRC: Final[str] = """import time
from dataclasses import dataclass
from typing import Sequence
from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule
from core.filesystem.fs import atomic_write_json
from core.foundation.errors import YscbError
from core.foundation.primitives import ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class BgIn:
    sleep_ms: int = 0

@dataclass(frozen=True, slots=True)
class BgOut:
    ok_tag: str

class HolderTask(Task[BgIn, BgOut]):
    @property
    def metadata(self) -> TaskMetadata[BgIn, BgOut]:
        return TaskMetadata(
            TaskId("t0bg.holder"), BgIn, BgOut,
            resource_key="rk_ser", concurrency_mode=ConcurrencyMode.SERIALIZE,
        )
    def run(self, req: BgIn, ctx: TaskContext) -> BgOut:
        out = ctx.invoke_task("t0bg.coal", {"sleep_ms": req.sleep_ms})
        if not out.ok and out.error is not None:
            raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)
        return BgOut(ok_tag="holder_done")

class CoalTask(Task[BgIn, BgOut]):
    @property
    def metadata(self) -> TaskMetadata[BgIn, BgOut]:
        return TaskMetadata(
            TaskId("t0bg.coal"), BgIn, BgOut,
            resource_key="rk_coal", concurrency_mode=ConcurrencyMode.COALESCE,
        )
    def run(self, req: BgIn, ctx: TaskContext) -> BgOut:
        out = ctx.invoke_task("t0bg.borrowed", {"sleep_ms": req.sleep_ms})
        if not out.ok and out.error is not None:
            raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)
        return BgOut(ok_tag="coal_done")

from core.foundation.observability import ProgressEvent

class BorrowedTask(Task[BgIn, BgOut]):
    @property
    def metadata(self) -> TaskMetadata[BgIn, BgOut]:
        return TaskMetadata(
            TaskId("t0bg.borrowed"), BgIn, BgOut,
            resource_key="rk_ser", concurrency_mode=ConcurrencyMode.SERIALIZE,
        )
    def run(self, req: BgIn, ctx: TaskContext) -> BgOut:
        if req.sleep_ms > 0:
            atomic_write_json(ctx.workspace_root.join(".cache", "t0bg_entered.json"), {"in": True})
            time.sleep(req.sleep_ms / 1000.0)
        ctx.report_progress(ProgressEvent("borrowed", 1, 1, "done"))
        return BgOut(ok_tag="borrowed_done")

class T0BgMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("t0bg")
    def tasks(self) -> Sequence[BoundTask]:
        return (HolderTask(), CoalTask(), BorrowedTask())

def create_module() -> YscbModule:
    return T0BgMod()
"""


def _verify_t0_borrowed_guard_no_self_deadlock(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_bg = HostPath(ws8.path / "ws_t0_borrowed_guard")
    provision_live_workspace(ws_bg.path)
    _write_module(
        ws_bg.path,
        "t0bg",
        {
            "tier1": False,
            "tasks": [
                {"task_id": "t0bg.holder", "resource_key": "rk_ser", "concurrency_mode": "serialize"},
                {"task_id": "t0bg.coal", "resource_key": "rk_coal", "concurrency_mode": "coalesce"},
                {"task_id": "t0bg.borrowed", "resource_key": "rk_ser", "concurrency_mode": "serialize"},
            ],
        },
        _T0_BORROWED_GUARD_MOD_SRC,
    )
    disp = build_dispatcher_for_workspace(ws_bg, venv_bin, is_daemon_host=True, sandbox_restricted=True).dispatcher
    try:
        src_c1 = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_c1 = pool.submit(
                disp.invoke, InvokeRequest(TaskId("t0bg.holder"), {"sleep_ms": 420}, ws_bg, ws_bg), cancel_token=src_c1
            )
            _wait_file_marker(ws_bg.path / ".cache" / "t0bg_entered.json")
            f_c2 = pool.submit(disp.invoke, InvokeRequest(TaskId("t0bg.coal"), {"sleep_ms": 420}, ws_bg, ws_bg))
            time.sleep(0.05)
            src_c1.cancel(reason="cancel_lending_holder")
            r_c1 = f_c1.result(timeout=3.0)
            r_c2 = f_c2.result(timeout=3.0)
        _check(not r_c1.ok and r_c1.error is not None and r_c1.error.code == ErrorCode.TASK_CANCELLED)
        _check(r_c2.ok)
        (ws_bg.path / ".cache" / "t0bg_entered.json").unlink(missing_ok=True)
        src_sole = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
            f_sole = pool.submit(
                disp.invoke, InvokeRequest(TaskId("t0bg.holder"), {"sleep_ms": 420}, ws_bg, ws_bg), cancel_token=src_sole
            )
            _wait_file_marker(ws_bg.path / ".cache" / "t0bg_entered.json")
            src_sole.cancel(reason="cancel_sole_lending_holder")
            r_sole = f_sole.result(timeout=3.0)
        _check(not r_sole.ok and r_sole.error is not None and r_sole.error.code == ErrorCode.TASK_CANCELLED)
        _check(disp.invoke(InvokeRequest(TaskId("t0bg.borrowed"), {"sleep_ms": 0}, ws_bg, ws_bg)).ok)
        _check(disp.try_quiesce_modules(frozenset({ModuleId("t0bg")}), drain_deadline=time.monotonic() + 1.0, leased=True))
        disp.resume_from_quiesce(modules=frozenset({ModuleId("t0bg")}))
    finally:
        disp.shutdown(grace_ms=200)


class _MalformedDaemonReplyHandler(InboundCallHandler):
    def on_call(
        self,
        stream_id: int,
        payload: JsonObject,
        ack_accepted: typing.Callable[[], bool],
        emit_progress: typing.Callable[[JsonObject], None],
        peer_cancel_token: CancellationToken,
    ) -> tuple[bool, JsonObject]:
        _ = (stream_id, payload, emit_progress, peer_cancel_token)
        ack_accepted()
        return (True, {"schema_version": 1, "ok": "not_a_bool"})

    def on_control(self, kind: FrameKind, payload: JsonObject) -> JsonObject:
        _ = (kind, payload)
        return {"ok": True, "conflict": True, "error": {"bad_error_shape": 1}}


class _MalformedMasterCallbackHandler(InboundCallHandler):
    def on_call(
        self,
        stream_id: int,
        payload: JsonObject,
        ack_accepted: typing.Callable[[], bool],
        emit_progress: typing.Callable[[JsonObject], None],
        peer_cancel_token: CancellationToken,
    ) -> tuple[bool, JsonObject]:
        _ = (stream_id, payload, emit_progress, peer_cancel_token)
        ack_accepted()
        return (True, {"schema_version": 1, "ok": "corrupt_bool"})

    def on_control(self, kind: FrameKind, payload: JsonObject) -> JsonObject:
        _ = (kind, payload)
        return {"ok": True}


