def _verify_malformed_join_conflict_detaches_progress(
    disp_j: RuntimeDispatcher,
    ws_join: HostPath,
    ws_mw: HostPath,
) -> None:
    progress_hits: list[JsonObject] = []
    prop_anc = CallPropagationContext(
        coalesce_callers=(
            core.execution.runtime.CoalesceCallerView(
                turn_id="t_anc",
                call_tree_id="tree_anc",
                call_stack=((ws_mw, TaskId("mw.ping")),),
                flight_ids=("fid_mw",),
            ),
        ),
        hot_workspaces=frozenset({ws_mw}),
    )
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        f_lead = pool.submit(disp_j.invoke, InvokeRequest(TaskId("t0bg.coal"), {"sleep_ms": 300}, ws_join, ws_join))
        _wait_file_marker(ws_join.path / ".cache" / "t0bg_entered.json")
        r_join = disp_j.invoke(
            InvokeRequest(TaskId("t0bg.coal"), {"sleep_ms": 300}, ws_join, ws_join, propagation=prop_anc),
            on_progress=progress_hits.append,
        )
        r_lead = f_lead.result(timeout=3.0)
    _check(r_lead.ok)
    _check(not r_join.ok and r_join.error is not None and r_join.error.code == ErrorCode.CODEC_VALIDATION_FAILED)
    _check(not progress_hits)


