def _verify_cold_bootstrap_lifo_and_warmup_cancel_grace(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_cb = HostPath(ws8.path / "ws_cold_boot_and_warm_grace")
    provision_live_workspace(ws_cb.path)
    _write_module(
        ws_cb.path,
        "sw",
        {"tier1": True, "venv_group": "sw_grp", "eager_warmup": True, "tasks": [{"task_id": "sw.ping"}]},
        _SLOW_WARMUP_MOD_SRC,
    )
    disp_hot = build_dispatcher_for_workspace(ws_cb, venv_bin, is_daemon_host=True, sandbox_restricted=True).dispatcher
    try:
        src_cancel = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
            fut = pool.submit(
                disp_hot.invoke,
                InvokeRequest(TaskId("sw.ping"), {}, ws_cb, ws_cb),
                cancel_token=src_cancel,
            )
            _wait_file_marker(ws_cb.path / ".cache" / "sw_warming.json")
            t0 = time.monotonic()
            src_cancel.cancel(reason="abort_slow_warmup")
            out_w = fut.result(timeout=3.0)
            elapsed = time.monotonic() - t0
        _check(not out_w.ok and out_w.error is not None and out_w.error.code == ErrorCode.TASK_CANCELLED)
        _check(elapsed < 1.5, lambda: f"Warmup cancel took {elapsed:.2f}s instead of ~0.2s cancel_grace_ms!")
    finally:
        disp_hot.shutdown(grace_ms=200)

class _FailingReloadConfigView(ConfigViewPort):
    def __init__(self) -> None:
        self.fail_reload = False

    def get_module_value(self, module_id: ModuleId, key: str, default: JsonValue = None) -> JsonValue:
        _ = (module_id, key)
        return default

    def fingerprint(self) -> str:
        return "fp_fail" if self.fail_reload else "fp_ok"

    def reload(self) -> None:
        if self.fail_reload:
            raise YscbError(ErrorCode.CODEC_VALIDATION_FAILED, "Simulated corrupt workspace config")


def _verify_cold_bootstrap_failure_lifo_release(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_cb = HostPath(ws8.path / "ws_cold_boot_fail_lifo")
    provision_live_workspace(ws_cb.path)
    bad_cfg = _FailingReloadConfigView()
    prov = ManifestModuleProvider(ws_cb, venv_bin)
    opts = DispatcherHostOptions(
        config_view=bad_cfg,
        connection_config=DaemonConnectionConfig(enabled=False, auto_spawn=False),
    )
    disp_cold = RuntimeDispatcher(workspace_root=ws_cb, cache_dir=ws_cb.join(".cache"), module_provider=prov, options=opts)
    try:
        bad_cfg.fail_reload = True
        ref_out = disp_cold.invoke(
            InvokeRequest(TaskId("missing.task"), {}, ws_cb, ws_cb, routing_policy=ClientRoutingPolicy.FORCE_COLD)
        )
        _check(not ref_out.ok and ref_out.error is not None and ref_out.error.code == ErrorCode.CODEC_VALIDATION_FAILED)
        rep = disp_cold.emit_background_event(EventId("ev.corrupt"), {})
        _check(not rep.primary_result.ok and rep.primary_result.error is not None and rep.primary_result.error.code == ErrorCode.CODEC_VALIDATION_FAILED)
        inst_lk = FileLock(ws_cb.join(".cache", "locks", "installer.lock"))
        _check(inst_lk.acquire(shared=False, blocking=False))
        inst_lk.release()
    finally:
        disp_cold.shutdown(grace_ms=100)





