_XWS_UNKEYED_REENTRANT_B_SRC: Final[str] = """import time
from dataclasses import dataclass
from typing import Sequence
from core.execution.rpc import FrameKind, connect_and_handshake, probe_daemon_endpoint
from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule
from core.filesystem.fs import atomic_write_json
from core.foundation.errors import YscbError
from core.foundation.primitives import HostPath, ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class XbIn:
    peer_ws: str
    boot_only: bool = False

@dataclass(frozen=True, slots=True)
class XbOut:
    ok_tag: str

def _flood_remote_flight_joins(ws_a: HostPath, origin_str: str) -> None:
    ep = probe_daemon_endpoint(ws_a.join(".cache"), ws_a)
    if ep is None:
        return
    ch = connect_and_handshake(ep, connect_timeout_sec=1.0)
    if ch is None:
        return
    try:
        for idx in range(300):
            ch.send_control(
                FrameKind.CONTROL_REQUEST,
                {
                    "action": "flight_join",
                    "flight_id": f"flood_fid_{idx}",
                    "origin_ws": origin_str,
                    "callers": [
                        {
                            "turn_id": f"ft_{idx}",
                            "call_tree_id": f"fc_{idx}",
                            "call_stack": [[str(ws_a), "xa.inner_unkeyed"]],
                            "caller_hops": [],
                            "flight_ids": [f"flood_fid_{idx}"],
                            "in_event_chain": False,
                        }
                    ],
                },
            )
    finally:
        ch.close()

class CoalBorrowATask(Task[XbIn, XbOut]):
    @property
    def metadata(self) -> TaskMetadata[XbIn, XbOut]:
        return TaskMetadata(
            TaskId("xb.coal_and_borrow_a"), XbIn, XbOut,
            resource_key="rk_xb", concurrency_mode=ConcurrencyMode.COALESCE,
        )
    def run(self, req: XbIn, ctx: TaskContext) -> XbOut:
        if req.boot_only:
            return XbOut(ok_tag="booted")
        ws_a = HostPath(req.peer_ws)
        atomic_write_json(ctx.workspace_root.join(".cache", "xb_flight_in.json"), {"in": True})
        time.sleep(0.16)
        _flood_remote_flight_joins(ws_a, str(ctx.workspace_root))
        out = ctx.invoke_task("xa.inner_unkeyed", {}, target_workspace=ws_a)
        if not out.ok and out.error is not None:
            raise YscbError(out.error.code, out.error.message, source_task=out.error.source_task)
        return XbOut(ok_tag="fb_done")

class XbMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("xb")
    def tasks(self) -> Sequence[BoundTask]:
        return (CoalBorrowATask(),)

def create_module() -> YscbModule:
    return XbMod()
"""


def _verify_xws_pinned_flight_flood_and_done_cleanup(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_a = HostPath(ws8.path / "ws_xws_flood_a")
    ws_b = HostPath(ws8.path / "ws_xws_flood_b")
    provision_live_workspace(ws_a.path)
    provision_live_workspace(ws_b.path)
    _write_module(
        ws_a.path,
        "xa",
        {
            "tier1": False,
            "tasks": [
                {"task_id": "xa.hold_and_join_b", "resource_key": "rk_xa", "concurrency_mode": "serialize"},
                {"task_id": "xa.inner_unkeyed"},
                {"task_id": "xa.leaf_serial", "resource_key": "rk_xa", "concurrency_mode": "serialize"},
            ],
        },
        _XWS_UNKEYED_REENTRANT_A_SRC,
    )
    _write_module(
        ws_b.path,
        "xb",
        {"tier1": False, "tasks": [{"task_id": "xb.coal_and_borrow_a", "resource_key": "rk_xb", "concurrency_mode": "coalesce"}]},
        _XWS_UNKEYED_REENTRANT_B_SRC,
    )
    disp_a = build_dispatcher_for_workspace(ws_a, venv_bin, ttl_sec=20.0).dispatcher
    disp_b = build_dispatcher_for_workspace(ws_b, venv_bin, ttl_sec=20.0).dispatcher
    try:
        _check(disp_a.invoke(InvokeRequest(TaskId("xa.leaf_serial"), {}, ws_a, ws_a)).ok)
        _check(disp_b.invoke(InvokeRequest(TaskId("xb.coal_and_borrow_a"), {"peer_ws": str(ws_a), "boot_only": True}, ws_b, ws_b)).ok)
        wait_for_daemon_online(ws_a)
        wait_for_daemon_online(ws_b)
        (ws_b.path / ".cache" / "xb_flight_in.json").unlink(missing_ok=True)
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_c2 = pool.submit(
                disp_b.invoke,
                InvokeRequest(TaskId("xb.coal_and_borrow_a"), {"peer_ws": str(ws_a)}, ws_b, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT),
            )
            _wait_file_marker(ws_b.path / ".cache" / "xb_flight_in.json")
            f_c1 = pool.submit(
                disp_a.invoke,
                InvokeRequest(TaskId("xa.hold_and_join_b"), {"peer_ws": str(ws_b)}, ws_a, ws_a, routing_policy=ClientRoutingPolicy.STRICT_HOT),
            )
            r_c1 = f_c1.result(timeout=6.0)
            r_c2 = f_c2.result(timeout=6.0)
        _check(r_c1.ok and r_c2.ok, lambda: f"r_c1={r_c1}, r_c2={r_c2}")
        bad_ctrl = query_daemon_control(ws_a.join(".cache"), ws_a, FrameKind.CONTROL_QUIESCE, {"lease_ms": 200})
        _check(bad_ctrl is not None and bad_ctrl.get("ok") is False and bad_ctrl.get("error") == ErrorCode.CODEC_VALIDATION_FAILED.value)
    finally:
        stop_daemon_cleanly(ws_a)
        stop_daemon_cleanly(ws_b)
        disp_a.shutdown(grace_ms=100)
        disp_b.shutdown(grace_ms=100)


