def _verify_raw_malformed_frames_rejected_without_state_desync(ep_info: RpcEndpointInfo, ws_s: HostPath) -> None:
    for bad_raw in (
        b'{"kind":"control_quiesce","stream_id":0,"payload":{"_req_id":"\\ud800","lease_sec":10.0}}',
        b'{"kind":"control_quiesce","stream_id":0,"payload":{"_req_id":"r1","lease_sec":1e400}}',
        b'{"kind":"control_quiesce","stream_id":0,"payload":{"lease_sec":10.0},"meta":{"req_id":"\\ud800"}}',
    ):
        with socket.create_connection((ep_info.host, ep_info.port), timeout=2.0) as raw_s:
            hello_body = json.dumps(
                {
                    "kind": "hello",
                    "stream_id": 0,
                    "payload": {
                        "protocol": 2,
                        "auth_token": ep_info.auth_token,
                        "boot_id": ep_info.boot_id,
                        "workspace_root": str(ws_s),
                    },
                }
            ).encode("utf-8")
            raw_s.sendall(struct.pack(">I", len(hello_body)) + hello_body)
            ack_hdr = raw_s.recv(4)
            (ack_len,) = struct.unpack(">I", ack_hdr)
            ack_json = json.loads(raw_s.recv(ack_len).decode("utf-8"))
            _check(ack_json["payload"]["ok"] is True)
            raw_s.sendall(struct.pack(">I", len(bad_raw)) + bad_raw)
            eof = raw_s.recv(16)
            _check(eof == b"")
    st = query_daemon_control(ws_s.join(".cache"), ws_s, FrameKind.CONTROL_STATUS)
    _check(isinstance(st, Mapping) and isinstance(st.get("status"), Mapping) and st["status"].get("state") == "ready")




