def _verify_signal_guard_escalation_and_send_control_kind_isolation() -> None:
    prev_r, prev_w = socket.socketpair()
    prev_w.setblocking(False)
    prev_r.settimeout(1.5)
    sig_num = int(signal.SIGINT) if os.name == "nt" else int(signal.SIGUSR1)
    old_fd = signal.set_wakeup_fd(prev_w.fileno(), warn_on_full_buffer=False)
    first_hits: list[int] = []
    second_hits: list[int] = []
    done_second = threading.Event()
    try:
        with SignalWakeupGuard(
            (sig_num,),
            lambda: first_hits.append(1),
            on_second_signal=lambda: (second_hits.append(1), done_second.set())[1],
        ):
            signal.raise_signal(sig_num)
            time.sleep(0.05)
            signal.raise_signal(sig_num)
            _check(done_second.wait(timeout=1.5))
        fwd_bytes = prev_r.recv(16)
        _check(len(first_hits) == 1 and len(second_hits) == 1 and sig_num in fwd_bytes)
    finally:
        signal.set_wakeup_fd(old_fd)
        prev_r.close()
        prev_w.close()

    # MultiplexedChannel.send_control with non-control FrameKind MUST return None locally without killing active stream
    gate_ev = threading.Event()
    srv_s, cli_s = socket.socketpair()

    class _SlowAcceptHandler(InboundCallHandler):
        def on_call(
            self,
            _sid: int,
            _pay: JsonObject,
            ack_accepted: typing.Callable[[], bool],
            _prog: typing.Callable[[JsonObject], None],
            _cancel: CancellationToken,
        ) -> tuple[bool, JsonObject]:
            ack_accepted()
            gate_ev.wait(timeout=2.0)
            return (True, {"ok": True})

        def on_control(self, _k: FrameKind, _p: JsonObject) -> JsonObject:
            return {"ok": True}

    srv_ch = MultiplexedChannel(srv_s, is_initiator=False, handler=_SlowAcceptHandler())
    cli_ch = MultiplexedChannel(cli_s, is_initiator=True)
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
            fut = pool.submit(cli_ch.call, {"op": "hold"}, timeout_ms=3000)
            time.sleep(0.05)
            _check(cli_ch.send_control(FrameKind.CALL_START, {}) is None)
            gate_ev.set()
            call_out = fut.result(timeout=3.0)
        _check(call_out.was_accepted and not call_out.transport_lost and call_out.result_payload == {"ok": True})
    finally:
        gate_ev.set()
        cli_ch.close()
        srv_ch.close()

    # Tier 1 mapper crash with transport_lost=True + TRANSPORT_LOST must map to ErrorCode.WORKER_CRASHED
    m_crash = core.execution.runtime.step_host.decode_tier1_mapper_outcome(
        rpc_pkg.RemoteCallOutcome(was_accepted=True, transport_lost=True, error_code=ErrorCode.TRANSPORT_LOST),
        CancellationToken(),
        TaskId("kdb.on_files"),
    )
    _check(not m_crash.ok and m_crash.error is not None and m_crash.error.code == ErrorCode.WORKER_CRASHED)


def _verify_selective_quiesce_config_and_warming_reload(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_cfg = HostPath(ws8.path / "ws_sel_quiesce_cfg")
    provision_live_workspace(ws_cfg.path)
    disp_c = build_dispatcher_for_workspace(ws_cfg, venv_bin, ttl_sec=20.0).dispatcher
    try:
        _check(disp_c.invoke_typed(ECHO_TIER0_META, EchoInDto(tag="up")).ok)
        _ = wait_for_daemon_online(ws_cfg)
        q_ack = query_daemon_control(
            ws_cfg.join(".cache"), ws_cfg, FrameKind.CONTROL_QUIESCE, {"modules": ["space"], "lease_sec": 15.0}
        )
        _check(isinstance(q_ack, Mapping) and q_ack.get("ok") is True)
        ep_val = q_ack["epoch"]
        marker_p = ws_cfg.path / ".cache" / "config_reloaded_marker.json"
        marker_p.unlink(missing_ok=True)
        atomic_write_json(ws_cfg.join("yscb.config.json"), {"theme": "after_sel_quiesce"})
        time.sleep(0.28)
        _check(not marker_p.is_file())
        r_ack = query_daemon_control(
            ws_cfg.join(".cache"), ws_cfg, FrameKind.CONTROL_RESUME, {"expected_epoch": ep_val, "modules": ["space"]}
        )
        _check(isinstance(r_ack, Mapping) and r_ack.get("ok") is True)
        _wait_file_marker(marker_p, timeout_sec=4.0)
        bad_req = query_daemon_control(
            ws_cfg.join(".cache"), ws_cfg, FrameKind.CONTROL_REQUEST, {"action": "flight_done", "flight_id": ""}
        )
        _check(
            isinstance(bad_req, Mapping)
            and bad_req.get("ok") is False
            and bad_req.get("error") == ErrorCode.CODEC_VALIDATION_FAILED.value
            and isinstance(bad_req.get("message"), str)
        )
    finally:
        stop_daemon_cleanly(ws_cfg)
        disp_c.shutdown(grace_ms=100)


def _verify_warming_control_reload_and_core_handoff(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_w = HostPath(ws8.path / "ws_warm_reload")
    provision_live_workspace(ws_w.path)
    _write_module(ws_w.path, "dynm", {"tier1": False, "eager_warmup": True}, _WARM_RELOAD_DYN_TPL.replace("__VER__", "v1"))
    (ws_w.path / ".cache").mkdir(parents=True, exist_ok=True)
    disp_w = build_dispatcher_for_workspace(ws_w, venv_bin, ttl_sec=20.0).dispatcher
    try:
        SingleFlightDaemonSpawner(
            ws_w.join(".cache"),
            lambda root: [
                sys.executable, "-W", "error::ResourceWarning", str(Path(__file__).resolve()),
                "--daemon-entry", str(root), str(venv_bin), "20.0",
            ],
        ).try_spawn_background(ws_w)
        _wait_file_marker(ws_w.path / ".cache" / "warm_entered.json", timeout_sec=5.0)
        _write_module(ws_w.path, "dynm", {"tier1": False, "eager_warmup": True}, _WARM_RELOAD_DYN_TPL.replace("__VER__", "v2"))
        rel_w = query_daemon_control(ws_w.join(".cache"), ws_w, FrameKind.CONTROL_RELOAD, {"modules": ["dynm"]})
        _check(isinstance(rel_w, Mapping) and rel_w.get("ok") is True and rel_w.get("deferred") is True)
        (ws_w.path / ".cache" / "warm_go.json").write_text("1", encoding="utf-8")
        st_ready = wait_for_daemon_online(ws_w)
        boot1 = str(st_ready["boot_id"])
        ver_out = disp_w.invoke(
            InvokeRequest(TaskId("dynm.ver"), {}, ws_w, ws_w, routing_policy=ClientRoutingPolicy.STRICT_HOT)
        )
        _check(ver_out.ok and ver_out.value == {"ver": "v2"} and bool(boot1))
    finally:
        (ws_w.path / ".cache" / "warm_go.json").write_text("1", encoding="utf-8")
        stop_daemon_cleanly(ws_w)
        disp_w.shutdown(grace_ms=100)


def _verify_warming_core_control_reload_handoff(ws8: HostPath, venv_bin: HostPath) -> None:
    ws_wc = HostPath(ws8.path / "ws_warm_core_handoff")
    provision_live_workspace(ws_wc.path)
    _write_module(ws_wc.path, "dynm", {"tier1": False, "eager_warmup": True}, _WARM_RELOAD_DYN_TPL.replace("__VER__", "v1"))
    (ws_wc.path / ".cache").mkdir(parents=True, exist_ok=True)
    try:
        SingleFlightDaemonSpawner(
            ws_wc.join(".cache"),
            lambda root: [
                sys.executable, "-W", "error::ResourceWarning", str(Path(__file__).resolve()),
                "--daemon-entry", str(root), str(venv_bin), "20.0",
            ],
        ).try_spawn_background(ws_wc)
        _wait_file_marker(ws_wc.path / ".cache" / "warm_entered.json", timeout_sec=5.0)
        ep_warm = probe_daemon_endpoint(ws_wc.join(".cache"), ws_wc)
        _check(ep_warm is not None)
        warm_boot_id = ep_warm.boot_id if ep_warm is not None else ""
        rel_c = query_daemon_control(ws_wc.join(".cache"), ws_wc, FrameKind.CONTROL_RELOAD, {"modules": ["core"]})
        _check(isinstance(rel_c, Mapping) and rel_c.get("ok") is True and rel_c.get("deferred") is True)
        (ws_wc.path / ".cache" / "warm_go.json").write_text("1", encoding="utf-8")
        dl = time.monotonic() + 8.0
        rotated = False
        while time.monotonic() < dl:
            st_cur = query_daemon_control(ws_wc.join(".cache"), ws_wc, FrameKind.CONTROL_STATUS)
            st_map = st_cur.get("status") if isinstance(st_cur, Mapping) else None
            if isinstance(st_map, Mapping) and st_map.get("state") == "ready" and st_map.get("boot_id") != warm_boot_id:
                    rotated = True
                    break
            time.sleep(0.05)
        _check(rotated, "Expected WARMING CONTROL_RELOAD(core) to rotate boot_id via handoff")
    finally:
        (ws_wc.path / ".cache" / "warm_go.json").write_text("1", encoding="utf-8")
        stop_daemon_cleanly(ws_wc)




_HUGE_TMO_MOD_SRC: Final[str] = """from dataclasses import dataclass
import time
from typing import Callable, Optional, Sequence
from core.execution.runtime import BoundTask, ConcurrencyMode, Task, TaskContext, TaskMetadata, YscbModule
from core.filesystem.fs import atomic_write_json, read_json_dict
from core.foundation.primitives import HostPath, ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class HugeIn:
    sleep_ms: int = 0

@dataclass(frozen=True, slots=True)
class HugeOut:
    ok: bool = True

class HugeSerTask(Task[HugeIn, HugeOut]):
    @property
    def metadata(self) -> TaskMetadata[HugeIn, HugeOut]:
        return TaskMetadata(
            TaskId("huget0.ser"), HugeIn, HugeOut,
            resource_key="rk_huge_ser", concurrency_mode=ConcurrencyMode.SERIALIZE,
            timeout_ms=10_000_000_000_000,
        )
    def run(self, req: HugeIn, ctx: TaskContext) -> HugeOut:
        f = ctx.workspace_root.join(".cache", "huge_cs.json")
        cur = read_json_dict(f) or {}
        act = (int(cur["act"]) if isinstance(cur.get("act"), int) else 0) + 1
        mx = max(act, int(cur["max_cs"]) if isinstance(cur.get("max_cs"), int) else 0)
        atomic_write_json(f, {"act": act, "max_cs": mx})
        if req.sleep_ms > 0:
            time.sleep(req.sleep_ms / 1000.0)
        cur2 = read_json_dict(f) or {}
        mx2 = max(act, int(cur2["max_cs"]) if isinstance(cur2.get("max_cs"), int) else 0)
        atomic_write_json(f, {"act": max(0, int(cur2.get("act", 1)) - 1), "max_cs": mx2})
        return HugeOut(ok=True)

class HugeMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("huget0")
    def on_init(self, workspace_root: HostPath) -> Optional[Callable[[], None]]:
        f = workspace_root.join(".cache", "huge_lifecycle.json")
        c = read_json_dict(f) or {}
        atomic_write_json(f, {"init": int(c.get("init", 0)) + 1, "close": int(c.get("close", 0))})
        def _on_close() -> None:
            c2 = read_json_dict(f) or {}
            atomic_write_json(f, {"init": int(c2.get("init", 0)), "close": int(c2.get("close", 0)) + 1})
        return _on_close
    def tasks(self) -> Sequence[BoundTask]:
        return (HugeSerTask(),)

def create_module() -> YscbModule:
    return HugeMod()
"""


def _verify_signal_close_zero_sleep_and_forwardref_evict() -> None:
    sig_num = int(signal.SIGINT) if os.name == "nt" else int(signal.SIGUSR1)
    for _ in range(25):
        pr, pw = socket.socketpair()
        pw.setblocking(False)
        pr.settimeout(1.0)
        old_fd = signal.set_wakeup_fd(pw.fileno(), warn_on_full_buffer=False)
        hits: list[int] = []
        try:
            with SignalWakeupGuard((sig_num,), lambda h=hits: h.append(1)):
                signal.raise_signal(sig_num)
            fwd = pr.recv(16)
            _check(len(hits) == 1 and sig_num in fwd)
        finally:
            signal.set_wakeup_fd(old_fd)
            pr.close()
            pw.close()

    pkg_nm = "_yscb_v2_mod_fref_test"
    mod_v1 = types.ModuleType(pkg_nm)

    @dataclass(frozen=True, slots=True)
    class ItemV1:
        a: int

    ItemV1.__module__ = pkg_nm
    object.__setattr__(mod_v1, "Item", ItemV1)
    sys.modules[pkg_nm] = mod_v1
    try:
        f_form = list[typing.ForwardRef("Item", module=pkg_nm)]
        d_v1 = DataclassCodec.decode(f_form, [{"a": 7}])
        _check(isinstance(d_v1, list) and len(d_v1) == 1 and type(d_v1[0]) is ItemV1)
        DataclassCodec.evict_module_prefix(pkg_nm)

        @dataclass(frozen=True, slots=True)
        class ItemV2:
            a: int
            b: str = "ok"

        ItemV2.__module__ = pkg_nm
        object.__setattr__(mod_v1, "Item", ItemV2)
        d_v2 = DataclassCodec.decode(list[typing.ForwardRef("Item", module=pkg_nm)], [{"a": 9, "b": "v2"}])
        _check(isinstance(d_v2, list) and len(d_v2) == 1 and type(d_v2[0]) is ItemV2 and d_v2[0].b == "v2")
    finally:
        DataclassCodec.evict_module_prefix(pkg_nm)
        sys.modules.pop(pkg_nm, None)


