def _verify_owner_write_rollback_and_listener_stop_race(tmp_ws: HostPath) -> None:
    ws_ro = HostPath(tmp_ws.path / "ws_owner_rollback")
    provision_live_workspace(ws_ro.path)
    (ws_ro.path / ".cache" / "locks" / "installer.owner.json").mkdir(parents=True, exist_ok=True)
    disp_ro = build_dispatcher_for_workspace(ws_ro, HostPath(Path(sys.executable))).dispatcher
    try:
        out_ro = disp_ro.invoke(
            InvokeRequest(
                TaskId("space.remove_and_install"),
                {"target_module": "vsc"},
                ws_ro,
                ws_ro,
                routing_policy=ClientRoutingPolicy.FORCE_COLD,
                approval_scope=frozenset({TaskId("space.remove_and_install")}),
            )
        )
        _check(not out_ro.ok)
        probe_i = FileLock(ws_ro.join(".cache", "locks", "installer.lock"))
        _check(probe_i.acquire(shared=True, blocking=False))
        probe_i.release()
    finally:
        disp_ro.shutdown(grace_ms=100)

    ws_rc = HostPath(tmp_ws.path / "ws_coord_rollback")
    provision_live_workspace(ws_rc.path)
    lks_c = ws_rc.join(".cache", "locks")
    lks_c.path.mkdir(parents=True, exist_ok=True)
    stem = f"res_installer_{hashlib.sha256(b'installer').hexdigest()[:12]}"
    (lks_c.path / f"{stem}.owner.json").mkdir(parents=True, exist_ok=True)
    disp_rc = build_dispatcher_for_workspace(ws_rc, HostPath(Path(sys.executable))).dispatcher
    try:
        out_rc = disp_rc.invoke(
            InvokeRequest(TaskId("space.reload"), {}, ws_rc, ws_rc, routing_policy=ClientRoutingPolicy.FORCE_COLD)
        )
        _check(not out_rc.ok)
        probe_r = FileLock(lks_c.join(f"{stem}.lock"))
        _check(probe_r.acquire(shared=False, blocking=False))
        probe_r.release()
    finally:
        disp_rc.shutdown(grace_ms=100)



def _assert_raises_val_error(fn: typing.Callable[[], object]) -> None:
    caught = False
    try:
        _ = fn()
    except ValueError:
        caught = True
    _check(caught)


def _verify_signal_self_close_and_worker_expect_channel(tmp_ws: HostPath) -> None:
    for bad_sig in (0, -1, 99999, True):
        _assert_raises_val_error(lambda s=bad_sig: SignalWakeupGuard((s,), lambda: None))
    sig_usr1_enum = signal.Signals.__members__.get("SIGUSR1")
    if os.name != "nt" and sig_usr1_enum is not None:
        sig_u1 = int(sig_usr1_enum)
        closed_evt = threading.Event()
        holder_g: list[SignalWakeupGuard] = []
        g_self = SignalWakeupGuard((sig_u1,), lambda: (holder_g[0].close(), closed_evt.set())[1])
        holder_g.append(g_self)
        with g_self:
            os.kill(os.getpid(), sig_u1)
            _check(closed_evt.wait(timeout=2.0))

    ws_wc = HostPath(tmp_ws.path / "ws_worker_expect_ch")
    mdir = ws_wc.path / ".modules" / "wexp"
    mdir.mkdir(parents=True, exist_ok=True)
    (mdir / "module_entry.py").write_text(
        "from typing import Sequence\nfrom core.execution.runtime import BoundTask, YscbModule\n"
        "from core.foundation.primitives import ModuleId\n"
        "class WMod(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('wexp')\n"
        "    def tasks(self) -> Sequence[BoundTask]: return ()\n"
        "def create_module() -> YscbModule: return WMod()\n",
        encoding="utf-8",
    )
    desc_w = ModuleDescriptor(module_id=ModuleId("wexp"), module_dir=HostPath(mdir), eager_warmup=True)
    got_init: list[str] = []

    class _MasterCtrlSink(InboundCallHandler):
        def on_call(
            self,
            _sid: int,
            _pl: JsonObject,
            ack: typing.Callable[[], bool],
            _pr: typing.Callable[[JsonObject], None],
            _ct: CancellationToken,
        ) -> tuple[bool, JsonObject]:
            ack()
            return (True, {"ok": True})

        def on_control(self, _k: FrameKind, pl: JsonObject) -> JsonObject:
            if pl.get("action") == "module_initialized":
                got_init.append(str(pl.get("module_id", "")))
            return {"ok": True}

    s1, s2 = socket.socketpair()
    ch_master = MultiplexedChannel(s1, is_initiator=True, handler=_MasterCtrlSink())
    wh_exp = worker_entry_pkg.WorkerSubprocessHandler(ws_wc, (desc_w,), is_hot_container=True, expect_channel=True)
    ch_worker = MultiplexedChannel(s2, is_initiator=False, handler=wh_exp)
    try:
        with _scoped_timer(0.04, lambda: wh_exp.bind_channel(ch_worker)):
            cmd_wu = DataclassCodec.encode_envelope(
                worker_entry_pkg.WorkerCommandEnvelope(action=worker_entry_pkg.WorkerCommandKind.WARMUP)
            )
            out_wu = ch_master.call(cmd_wu, timeout_ms=3000)
        _check(out_wu.was_accepted and got_init == ["wexp"])
    finally:
        wh_exp.close()
        ch_worker.close()
        ch_master.close()


def _verify_event_and_rpc_frame_contracts(tmp_ws: HostPath) -> None:
    _assert_raises_val_error(lambda: strict_parse_json_object('{"dup": 1, "dup": 2}'))
    _check(normalize_payload_filter({"k": ["a", 1]}) == {"k": ("a", 1)})
    _assert_raises_val_error(lambda: normalize_payload_filter({"k": "not_seq"}))
    _assert_raises_val_error(lambda: normalize_payload_filter({"k": (float("nan"),)}))
    _assert_raises_val_error(lambda: SubscriptionRouteSpec(EventId("ev.x"), payload_filter={"k": "bad"}))

    ev_meta = EventMetadata(EventId("ev.flt"), EchoInDto)
    sub_f = EventSubscriptionSpec(
        ev_meta,
        lambda items: items[0] if items else None,
        payload_filter={"tag": ("allow",)},
    )
    _check(sub_f.decode_and_map(({"tag": "deny"},)) is None)
    matched_dto = sub_f.decode_and_map(({"tag": "deny"}, {"tag": "allow"}))
    _check(matched_dto == EchoInDto(tag="allow"))

    _assert_raises_val_error(lambda: ProgressEvent(phase="ok", completed=True, total=1))
    _assert_raises_val_error(lambda: ProgressEvent(phase="bad\ud800", completed=0, total=1))
    _assert_raises_val_error(lambda: CausalLineage(chain=(EventId("ev.a"),), scopes=("ok", "extra")))
    _assert_raises_val_error(lambda: CausalLineage().advance(EventId("ev.a"), workspace_scope="bad\ud800"))
    _assert_raises_val_error(
        lambda: RawEventRecord(EventId("ev.a"), TaskId("m.t"), {"x": float("nan")}, EventOrdering.UNORDERED)
    )
    _assert_raises_val_error(lambda: TaskLocalOutbox(TaskId("m.t"), CausalLineage(), workspace_scope="bad\ud800"))
    _assert_raises_val_error(lambda: clamp_wait_sec(1.0, min_sec=-0.1))
    _assert_raises_val_error(lambda: ms_to_safe_sec(100, min_sec=float("nan")))
    _assert_raises_val_error(lambda: atomic_write_bytes(tmp_ws.join("bad_mode.bin"), b"x", file_mode=True))
    _assert_raises_val_error(lambda: RpcEndpointInfo(pid=True, host="127.0.0.1", port=80, boot_id="b", auth_token="t", workspace_root=tmp_ws))
    _assert_raises_val_error(lambda: RpcFrame(kind=FrameKind.PING, stream_id=-1))

    l_bad = RpcServerListener(tmp_ws, _EchoHandoffHandler(accept=True), boot_id="b_pid")
    _assert_raises_val_error(lambda: l_bad.start(pid=True))
    _assert_raises_val_error(lambda: l_bad.start(pid=0))

    p1, p2 = socket.socketpair()
    c_init = MultiplexedChannel(p1, is_initiator=True, handler=_EchoHandoffHandler(accept=True))
    c_resp = MultiplexedChannel(p2, is_initiator=False, handler=_EchoHandoffHandler(accept=True))
    try:
        _check(c_init.send_control(FrameKind.CONTROL_STATUS, {}, timeout_ms=0) is None)
        _check(c_init.ping(timeout_ms=0) is False)
        _assert_raises_val_error(lambda: c_init.ping(timeout_ms=True))
        _check(c_init.ping(timeout_ms=1000) is True)
        # Verify PONG frame cannot satisfy a pending CONTROL_ACK waiter
        ev_w = threading.Event()
        h_w: dict[str, JsonObject] = {}
        with c_init._cond:
            c_init._pending_controls["spoof_id"] = rpc_pkg.channel._PendingControlWait(FrameKind.CONTROL_ACK, ev_w, h_w)
        c_init._on_frame_control_ack(RpcFrame(FrameKind.PONG, 0, {"ok": True}, meta={"req_id": "spoof_id"}))
        _check(not ev_w.is_set() and "spoof_id" in c_init._pending_controls)
        c_init._on_frame_control_ack(RpcFrame(FrameKind.CONTROL_ACK, 0, {"ok": True}, meta={"req_id": "spoof_id"}))
        _check(ev_w.is_set() and h_w.get("response") == {"ok": True})
    finally:
        c_init.close()
        c_resp.close()


def _verify_duplex_ping_stall_and_frame_symmetry(tmp_ws: HostPath) -> None:
    _ = (clone_strict_json_object({"a": [1]}), validate_wire_json_object({"a": 1}))
    # 1) Full-duplex large frames + interleaved PING/PONG without deadlock + outbound symmetry isolation
    class _SlowAndEchoHandler(InboundCallHandler):
        def on_call(
            self,
            _sid: int,
            pl: JsonObject,
            ack: typing.Callable[[], bool],
            _pr: typing.Callable[[JsonObject], None],
            _ct: CancellationToken,
        ) -> tuple[bool, JsonObject]:
            ack()
            slp = pl.get("sleep_ms", 0)
            if isinstance(slp, int) and slp > 0:
                time.sleep(slp / 1000.0)
            blob = pl.get("blob", "")
            return (True, {"ok": True, "n": len(blob) if isinstance(blob, str) else 0})

        def on_control(self, _k: FrameKind, _pl: JsonObject) -> JsonObject:
            return {"ok": True}

    a1, a2 = socket.socketpair()
    ch_a = MultiplexedChannel(a1, is_initiator=True, handler=_SlowAndEchoHandler())
    ch_b = MultiplexedChannel(a2, is_initiator=False, handler=_SlowAndEchoHandler())
    try:
        big_str = "x" * (2 * 1024 * 1024)
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            fa = pool.submit(ch_a.call, {"blob": big_str}, timeout_ms=8000)
            fb = pool.submit(ch_b.call, {"blob": big_str}, timeout_ms=8000)
            fp1 = pool.submit(ch_a.ping, timeout_ms=4000)
            fp2 = pool.submit(ch_b.ping, timeout_ms=4000)
            ra, rb = fa.result(timeout=10.0), fb.result(timeout=10.0)
            _check(ra.was_accepted and rb.was_accepted and fp1.result(timeout=5.0) and fp2.result(timeout=5.0))

        # Shared channel survival when sibling sends >300-digit int, >134 depth, cyclic dict, or non-str key
        deep_d: dict[str, object] = {"leaf": 1}
        for _ in range(140):
            deep_d = {"w": deep_d}
        cyc_d: dict[str, object] = {}
        cyc_d["self"] = cyc_d
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_slow = pool.submit(ch_a.call, {"sleep_ms": 140, "blob": "ok"}, timeout_ms=3000)
            time.sleep(0.03)
            for bad_pl in ({"big": 10**305}, deep_d, cyc_d, {1: "a", "1": "b"}):
                r_bad = ch_a.call(bad_pl, timeout_ms=1000)
                _check(not r_bad.was_accepted and r_bad.error_code == ErrorCode.CODEC_VALIDATION_FAILED)
            r_ok_sib = f_slow.result(timeout=3.0)
        _check(not ch_a.is_closed and r_ok_sib.was_accepted and r_ok_sib.result_payload == {"ok": True, "n": 2})
    finally:
        ch_a.close()
        ch_b.close()

    # 2) Unresponsive/jammed peer socket send buffer does not block caller timeout_ms or sibling CANCEL
    j1, j2 = socket.socketpair()
    try:
        j1.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 16384)
        j2.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 16384)
    except OSError:
        pass
    ch_jam = MultiplexedChannel(j1, is_initiator=True)
    try:
        t0_jam = time.monotonic()
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f_small = pool.submit(ch_jam.call, {"s": 1}, timeout_ms=200)
            f_huge = pool.submit(ch_jam.call, {"blob": "z" * (4 * 1024 * 1024)}, timeout_ms=200)
            rs_j, rh_j = f_small.result(timeout=2.0), f_huge.result(timeout=2.0)
        _check((time.monotonic() - t0_jam) < 1.0)
        _check(rs_j.error_code == ErrorCode.TASK_TIMEOUT and rh_j.error_code == ErrorCode.TASK_TIMEOUT)
    finally:
        ch_jam.close()
        j2.close()
    _ = tmp_ws


def _assert_nonblocking_sock_empty(sp_r: socket.socket) -> None:
    try:
        _ = sp_r.recv(16)
    except BlockingIOError:
        return
    raise AssertionError("Unexpected stray signal byte on newly opened socketpair")


def _verify_signal_bg_close_fd_reuse_guard() -> None:
    sig_usr1 = signal.Signals.__members__.get("SIGUSR1")
    if os.name == "nt" or sig_usr1 is None:
        return
    su = int(sig_usr1)
    prev_u1 = signal.signal(su, lambda _s, _f: None)
    try:
        bg_done = threading.Event()
        g_box: list[SignalWakeupGuard] = []
        g_fd = SignalWakeupGuard((su,), lambda: (g_box[0].close(), bg_done.set())[1])
        g_box.append(g_fd)
        with g_fd:
            os.kill(os.getpid(), su)
            _check(bg_done.wait(timeout=2.0))
            sp_r, sp_w = socket.socketpair()
            sp_r.setblocking(False)
            try:
                os.kill(os.getpid(), su)
                _assert_nonblocking_sock_empty(sp_r)
            finally:
                sp_r.close()
                sp_w.close()
    finally:
        signal.signal(su, prev_u1)


def _verify_fd_reuse_outbox_alias_and_codec_gc(tmp_ws: HostPath) -> None:
    # 1) SignalWakeupGuard non-main-thread close() prevents OS FD reuse & signal byte injection

    # 2) Outbox deep-clone isolation, Enum rejection, and atomic_write_json symmetry
    nested_arr: list[JsonValue] = [1, 2]
    ob = TaskLocalOutbox(TaskId("m.emit"), CausalLineage())
    rec = ob.stage(EventId("ev.deep"), {"arr": nested_arr})
    nested_arr.append(float("nan"))
    _check(rec.raw_payload == {"arr": [1, 2]})

    class _BadIntEnum(int, Enum):
        ONE = 1

    _assert_raises_val_error(lambda: ob.stage(EventId("ev.enum"), {"e": _BadIntEnum.ONE}))
    _assert_raises_val_error(lambda: normalize_payload_filter({"e": (_BadIntEnum.ONE,)}))

    valid_json_p = tmp_ws.join("sym_state.json")
    atomic_write_json(valid_json_p, {"ok": 1})
    caught_aw = False
    try:
        atomic_write_json(valid_json_p, {"bad": 10**305})
    except (TypeError, ValueError):
        caught_aw = True
    _check(caught_aw and read_json_dict(valid_json_p) == {"ok": 1})

    # 3) DataclassCodec ClassVar exclusion & recursive/composite dynamic type GC collection
    ref_opt, ref_self, ref_ma, ref_mb = _build_recursive_and_classvar_codec_probes()
    gc.collect()
    _check(ref_opt() is None and ref_self() is None and ref_ma() is None and ref_mb() is None)

    # 4) Public dataclass write-back, int64 bounds, iterable-str rejection, Watcher HostPath check
    qc_huge = DaemonQuiesceControl(lease_sec=10**100, drain_timeout_sec=10**100)
    _check(isinstance(qc_huge.lease_sec, float) and DataclassCodec.encode_object(qc_huge)["lease_sec"] == qc_huge.lease_sec)
    _assert_raises_val_error(lambda: WorkerProcessSnapshot("g", True, True))
    _assert_raises_val_error(lambda: WorkerProcessSnapshot("bad\ud800", 1, True))
    _assert_raises_val_error(lambda: CliBindingSpec("ab", "summary"))
    _assert_raises_val_error(lambda: TaskRouteSpec(TaskId("m.t"), subscriptions="ab"))
    _assert_raises_val_error(lambda: PollingDirectoryWatcher("abc", lambda _p: None))
    _assert_raises_val_error(lambda: PersistentRpcSession(tmp_ws.join(".c"), tmp_ws, connect_timeout_sec=-1.0))


def _build_recursive_and_classvar_codec_probes() -> tuple[weakref.ReferenceType[type[object]], ...]:
    dyn_mod_nm = "_yscb_v2_ephem_mut_probe"
    dyn_mod = types.ModuleType(dyn_mod_nm)
    sys.modules[dyn_mod_nm] = dyn_mod
    try:
        @dataclass(frozen=True, slots=True)
        class WithClassVar:
            HIDDEN: typing.ClassVar[bytes | str] = b"ok"
            val: int = 5

        @dataclass(frozen=True, slots=True)
        class DynSelfNode:
            v: int
            nxt: DynSelfNode | None = None

        @dataclass(frozen=True, slots=True)
        class MutA:
            x: int
            b: MutB | None = None

        @dataclass(frozen=True, slots=True)
        class MutB:
            y: int
            a: MutA | None = None

        object.__setattr__(dyn_mod, "typing", typing)
        for c in (DynSelfNode, MutA, MutB):
            c.__module__ = dyn_mod_nm
            c.__qualname__ = c.__name__
            object.__setattr__(dyn_mod, c.__name__, c)

        _check(DataclassCodec.decode(WithClassVar, DataclassCodec.encode_object(WithClassVar(val=9))).val == 9)
        _check(DataclassCodec.decode(WithClassVar | None, {"val": 3}) == WithClassVar(val=3))
        s_dec = DataclassCodec.decode(DynSelfNode, {"v": 1, "nxt": {"v": 2, "nxt": None}})
        _check(s_dec.nxt == DynSelfNode(v=2))
        m_dec = DataclassCodec.decode(MutA, {"x": 1, "b": {"y": 2, "a": None}})
        _check(m_dec.b == MutB(y=2))
        return (weakref.ref(WithClassVar), weakref.ref(DynSelfNode), weakref.ref(MutA), weakref.ref(MutB))
    finally:
        sys.modules.pop(dyn_mod_nm, None)


def _verify_ack_barrier_under_sigkill() -> None:
    if os.name == "nt":
        return
    srv_code = (
        "import os, signal, socket\n"
        "from core.execution.rpc.channel import InboundCallHandler, MultiplexedChannel\n"
        "class _KillOnAccept(InboundCallHandler):\n"
        "    def on_call(self, sid, payload, ack_accept, send_prog, tok):\n"
        "        ok = ack_accept()\n"
        "        if ok:\n"
        "            os.kill(os.getpid(), signal.SIGKILL)\n"
        "        return (ok, {'ok': True})\n"
        "    def on_control(self, kind, payload): return {'ok': True}\n"
        "s = socket.socket(fileno=int(os.environ['YSCB_SRV_FD']))\n"
        "ch = MultiplexedChannel(s, is_initiator=False, handler=_KillOnAccept())\n"
        "ch.wait_until_closed(timeout_sec=5.0)\n"
    )
    for _ in range(8):
        s_cli, s_srv = socket.socketpair()
        env = dict(os.environ, PYTHONPATH="source/core", YSCB_SRV_FD=str(s_srv.fileno()))
        proc = subprocess.Popen(
            [sys.executable, "-B", "-c", srv_code],
            cwd=str(Path(__file__).resolve().parent),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            env=env,
            pass_fds=(s_srv.fileno(),),
        )
        s_srv.close()
        ch_cli = MultiplexedChannel(s_cli, is_initiator=True)
        try:
            out = ch_cli.call({"ping": 1}, timeout_ms=3000)
            _check(out.was_accepted and out.transport_lost and out.error_code == ErrorCode.TRANSPORT_LOST)
        finally:
            ch_cli.close()
            proc.wait(timeout=3.0)


def _verify_ack_barrier_sig_gc_and_tty_grandchild(tmp_ws: HostPath) -> None:
    # 1) SignalWakeupGuard non-main-thread close() + GC produces 0 ResourceWarning & isolates callback exceptions
    sig_usr1 = signal.Signals.__members__.get("SIGUSR1")
    if os.name != "nt" and sig_usr1 is not None:
        su = int(sig_usr1)
        second_hit = threading.Event()
        with SignalWakeupGuard((su,), lambda: (_ for _ in ()).throw(RuntimeError("boom_cb")), on_second_signal=second_hit.set):
            os.kill(os.getpid(), su)
            time.sleep(0.02)
            os.kill(os.getpid(), su)
            _check(second_hit.wait(timeout=2.0))

        def _make_and_bg_close_guard() -> None:
            g_tmp = SignalWakeupGuard((su,), lambda: None)
            g_tmp.install()
            t_bg = threading.Thread(target=g_tmp.close, daemon=True)
            t_bg.start()
            t_bg.join(timeout=2.0)

        _make_and_bg_close_guard()
        gc.collect()
        # Drain retired socket cleanly on main thread
        with SignalWakeupGuard((su,), lambda: None):
            pass

    # 2) ManagedProcessTree(inherit_tty=True) reaps orphaned grandchild when root child crashes via os._exit(1)
    if os.name != "nt":
        pid_file = tmp_ws.join("tty_grandchild_pid.txt").path
        crash_script = (
            "import os, subprocess, sys, time\n"
            f"gp = subprocess.Popen([sys.executable, '-B', '-c', 'import time; time.sleep(30)'])\n"
            f"open({str(pid_file)!r}, 'w', encoding='utf-8').write(str(gp.pid))\n"
            "os._exit(1)\n"
        )
        tree = ManagedProcessTree([sys.executable, "-B", "-c", crash_script], cwd=tmp_ws, inherit_tty=True)
        dl = time.monotonic() + 3.0
        while time.monotonic() < dl and not pid_file.is_file():
            time.sleep(0.02)
        time.sleep(0.05)
        g_pid = int(pid_file.read_text(encoding="utf-8").strip())
