def _verify_symlink_escape_loopback_and_utf8_hello(tmp_ws: HostPath) -> None:
    if os.name != "nt":
        ext_dir = tmp_ws.path / "ext_outside" / "nested"
        ws_in = tmp_ws.path / "ws_inside"
        ext_dir.mkdir(parents=True, exist_ok=True)
