    atomic_write_json(
        dmn_json,
        {"pid": os.getpid(), "host": "198.51.100.99", "port": 9000, "boot_id": [1], "auth_token": None, "workspace_root": str(tmp_ws)},
    )
    _check(read_daemon_endpoint_file(tmp_ws.join(".cache"), tmp_ws) is None)

    # Non-ASCII UTF-8 auth_token / boot_id mutual handshake & nested MappingProxyType serialization
    nested_ro = normalize_payload_filter({"op": ["create", "update"]})
    ro_file = tmp_ws.join("nested_ro.json")
    atomic_write_json(ro_file, {"flt": nested_ro or {}})
    _check(read_json_dict(ro_file) == {"flt": {"op": ["create", "update"]}})

    class _EchoCtrl(InboundCallHandler):
        def on_call(self, sid: int, pl: JsonObject, ack: typing.Callable[[], bool], prog: typing.Callable[[JsonObject], None], tok: CancellationToken) -> tuple[bool, JsonObject]:
            _ = (sid, prog, tok)
            return (ack(), {"echo": pl})

        def on_control(self, kind: FrameKind, pl: JsonObject) -> JsonObject:
            _ = kind
            return {"ok": True, "pl": pl}

    srv_u = RpcServerListener(tmp_ws, _EchoCtrl(), boot_id="啟動_α", auth_token="密鑰_β")
    ep_u = srv_u.start()
