def _verify_baseexc_lifo_and_nonutf8_proc_comm(tmp_ws: HostPath) -> None:
    # 1) LifoResourceStack drains ALL lower entries even when an upper closer raises KeyboardInterrupt
    stk = LifoResourceStack()
    tree = ManagedProcessTree([sys.executable, "-B", "-c", "import time; time.sleep(30)"], cwd=tmp_ws)
    stk.push_closeable("worker_proc", lambda: (tree.terminate_tree(grace_sec=0.1), ())[1])
    stk.push_closeable("top_sigint", lambda: (_ for _ in ()).throw(KeyboardInterrupt("simulated_sigint")))
    caught_kb = False
    try:
        stk.close_all_lifo()
    except KeyboardInterrupt:
        caught_kb = True
    _check(caught_kb and not is_process_alive(tree.pid))

    # 2) is_process_alive tolerates arbitrary non-UTF-8 comm bytes in /proc/<pid>/stat
    if sys.platform.startswith("linux"):
        comm_rdy = tmp_ws.join("bad_comm.rdy").path
        comm_code = (
            "import ctypes, pathlib, time\n"
            "libc = ctypes.CDLL(None)\n"
            "libc.prctl(15, ctypes.c_char_p(b'wrk_\\xff\\xfe_bad'), 0, 0, 0)\n"
            f"pathlib.Path({str(comm_rdy)!r}).write_text('1', encoding='utf-8')\n"
            "time.sleep(20)\n"
        )
        t_comm = ManagedProcessTree([sys.executable, "-B", "-c", comm_code], cwd=tmp_ws)
        try:
            _wait_file_marker(comm_rdy, timeout_sec=3.0)
            _check(is_process_alive(t_comm.pid) is True)
        finally:
            t_comm.terminate_tree(grace_sec=0.1)


def _verify_preauth_handshake_cap_and_slow_trickle(tmp_ws: HostPath) -> None:
    ws_hs = HostPath(tmp_ws.path / "ws_hs_cap")
    ws_hs.path.mkdir(parents=True, exist_ok=True)
    cache_hs = ws_hs.join(".cache")
    cache_hs.join("daemon").path.mkdir(parents=True, exist_ok=True)
    srv = RpcServerListener(ws_hs, _NoopInboundRpcHandler())
    ep = srv.start()
    tracemalloc.start()
    try:
        base_cur, _ = tracemalloc.get_traced_memory()
        tracemalloc.reset_peak()
        hdr_64m = struct.pack(">I", 64 * 1024 * 1024)
        socks: list[socket.socket] = []
        for _ in range(4):
            s = socket.create_connection((ep.host, ep.port), timeout=1.0)
            s.sendall(hdr_64m)
            socks.append(s)
        time.sleep(0.08)
        _, peak_after = tracemalloc.get_traced_memory()
        for s in socks:
            s.close()
        _check((peak_after - base_cur) < 8 * 1024 * 1024)
    finally:
        tracemalloc.stop()
        srv.close_all()

    # Slow-trickle server must never stretch probe_daemon_endpoint past cumulative deadline
    trickle_srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    trickle_srv.bind(("127.0.0.1", 0))
    trickle_srv.listen(2)
    t_port = int(trickle_srv.getsockname()[1])
    stop_tr = threading.Event()

    def _trickle_peer() -> None:
        try:
            conn, _ = trickle_srv.accept()
        except OSError:
            return
        with conn:
            for _ in range(25):
                if stop_tr.wait(0.03):
                    break
                try:
                    conn.sendall(b"\x00")
                except OSError:
                    break

    th_tr = threading.Thread(target=_trickle_peer, daemon=True)
    th_tr.start()
    try:
        atomic_write_json(
            cache_hs.join("daemon", "daemon.json"),
            {
                "pid": os.getpid(),
                "host": "127.0.0.1",
                "port": t_port,
                "boot_id": "b_tr",
                "auth_token": "tok_tr",
                "workspace_root": str(ws_hs),
            },
        )
        t0 = time.monotonic()
        res_pr = probe_daemon_endpoint(cache_hs, ws_hs, timeout_sec=0.08)
        _check(res_pr is None and (time.monotonic() - t0) < 0.35)
    finally:
        stop_tr.set()
        trickle_srv.close()
        th_tr.join(timeout=1.0)


