def _verify_signal_event_rpc_and_quiesce_contracts(tmp_ws: HostPath) -> None:

    gate_q = LifecycleReloadGate(tmp_ws)
    for bad_now in (True, float("nan"), float("inf"), float("-inf")):
        _assert_raises_val_error(lambda v=bad_now: gate_q.due_quiesce_resume(v))
        _assert_raises_val_error(lambda v=bad_now: gate_q.next_quiesce_wakeup(v))
