            "    @property\n    def metadata(self) -> TaskMetadata[CfgIn, CfgIn]:\n"
            "        return TaskMetadata(TaskId('cfg_unav.on_cfg'), CfgIn, CfgIn, exposure=TaskExposure.INTERNAL_TRIGGER, subscriptions=(EventSubscriptionSpec(EventId('core.config_changed'), lambda _xs: CfgIn(1)),))\n"
            "    def run(self, req: CfgIn, ctx: TaskContext) -> CfgIn:\n"
            "        p = ctx.workspace_root.join('.cache', 'cfg_unav_hits.json')\n"
            "        c = int((read_json_dict(p) or {}).get('hits', 0)) + 1\n"
            "        atomic_write_json(p, {'hits': c})\n"
            "        raise YscbError(ErrorCode.DAEMON_UNAVAILABLE, 'remote peer offline')\n"
            "class CMod(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId('cfg_unav')\n"
            "    def tasks(self) -> Sequence[BoundTask]: return (OnCfgT(),)\n"
