class _CollidingTargetEnum(Enum):
    CORE = "core"
    SPACE = "space"


class _CollidingBytesEnum(bytes, Enum):
    MAGIC = b"ABCD"


@dataclass(frozen=True, slots=True)
class _AmbiguousEnumVoDto:
    target: typing.Union[_CollidingTargetEnum, ModuleId]


@dataclass(frozen=True, slots=True)
class _AmbiguousBytesEnumDto:
    blob: typing.Union[_CollidingBytesEnum, bytes]


@dataclass(frozen=True, slots=True)
class _AmbiguousBytesLiteralDto:
    blob: typing.Union[typing.Literal[b"XYZ"], bytes]


_TLayer = typing.TypeVar("_TLayer")


@dataclass(frozen=True, slots=True)
class _DeepLayerDto(typing.Generic[_TLayer]):
    tag: str
    inner: _TLayer


def _verify_codec_union_enum_vo_and_linear_depth() -> None:
    for bad_cls, sample in (
        (_AmbiguousEnumVoDto, _AmbiguousEnumVoDto(target=ModuleId("core"))),
        (_AmbiguousBytesEnumDto, _AmbiguousBytesEnumDto(blob=b"ABCD")),
        (_AmbiguousBytesLiteralDto, _AmbiguousBytesLiteralDto(blob=b"XYZ")),
    ):
        caught_enc = False
        try:
            DataclassCodec.encode(sample)
        except YscbError as exc:
            caught_enc = exc.detail.code == ErrorCode.CODEC_VALIDATION_FAILED
        _check(caught_enc, lambda: f"Expected union collision rejection on encode for {bad_cls}")
        caught_dec = False
        try:
            DataclassCodec.decode(bad_cls, {"target": "core", "blob": "QUJDRA=="})
        except YscbError as exc:
            caught_dec = exc.detail.code == ErrorCode.CODEC_VALIDATION_FAILED
        _check(caught_dec, lambda: f"Expected union collision rejection on decode for {bad_cls}")

    nested = _DeepLayerDto(
        "d1",
        _DeepLayerDto("d2", _DeepLayerDto("d3", _DeepLayerDto("d4", _DeepLayerDto("d5", 42)))),
    )
    tp_nested = _DeepLayerDto[_DeepLayerDto[_DeepLayerDto[_DeepLayerDto[_DeepLayerDto[int]]]]]
    enc_nested = DataclassCodec.encode_typed(tp_nested, nested)
    dec_nested = DataclassCodec.decode(tp_nested, enc_nested)
    _check(dec_nested == nested)


def _verify_stdout_discard_post_control_and_reload_semantics() -> None:
    saved_out = sys.stdout
    try:
        sys.stdout = None
        with core.foundation.observability.guard_standard_streams() as cap_out:
            proxy_ref = sys.stdout
            _check(proxy_ref is not None and not proxy_ref.closed)
            written_holder = [0]

            def _bg_untracked_writer() -> None:
                if sys.stdout is not None:
                    written_holder[0] = sys.stdout.write("untracked_discard_payload" * 8)
                    sys.stdout.writelines(["line_a\n", "line_b\n"])
                    sys.stdout.flush()

            bg_t = threading.Thread(target=_bg_untracked_writer, daemon=True)
            bg_t.start()
            bg_t.join(timeout=2.0)
            _check(written_holder[0] == len("untracked_discard_payload" * 8))
            sys.stdout.write("captured_only")
            _check(cap_out.getvalue() == "captured_only")
    finally:
        sys.stdout = saved_out

    wlc_sem = WorkerContainerLifecycle()
    err_deg = ErrorDetail(ErrorCode.MODULE_DEGRADED, "keep_me")
    wlc_sem.record_degraded(ModuleId("alpha"), err_deg)
    wlc_sem.reload_modules(frozenset())
    _check(wlc_sem.get_degraded(ModuleId("alpha")) == err_deg)
    wlc_sem.reload_modules(None)
    _check(wlc_sem.get_degraded(ModuleId("alpha")) is None)

    received_ctrl: list[JsonObject] = []
    ctrl_ev = threading.Event()

    class _PostCtrlHandler:
        def on_call(
            self,
            _sid: int,
            _pay: JsonObject,
            _ack: typing.Callable[[], bool],
            _prog: typing.Callable[[JsonObject], None],
            _tok: CancellationToken,
        ) -> tuple[bool, JsonObject]:
            return (True, {"ok": True})

        def on_control(self, kind: FrameKind, payload: JsonObject) -> JsonObject:
            if kind == FrameKind.CONTROL_REQUEST:
                received_ctrl.append(dict(payload))
                ctrl_ev.set()
            return {"ok": True}

    sp_a, sp_b = socket.socketpair()
    ch_recv = MultiplexedChannel(sp_a, is_initiator=False, handler=_PostCtrlHandler())
    ch_send = MultiplexedChannel(sp_b, is_initiator=True)
    try:
        _check(ch_send.post_control(FrameKind.CONTROL_REQUEST, {"action": "elevate_step", "step_run_id": "s1"}) is True)
        _check(ctrl_ev.wait(timeout=2.0) and len(received_ctrl) == 1 and received_ctrl[0].get("step_run_id") == "s1")
        _check(ch_send.post_control(FrameKind.CALL_START, {}) is False)
    finally:
        ch_send.close()
        ch_recv.close()


