def _verify_bounded_pin_and_borrowed_guard_release(ws8: HostPath) -> None:
    pin_dir = ws8.join(".cache", "pin_grace_probe")
    pin_dir.path.mkdir(parents=True, exist_ok=True)
    paths = core.filesystem.fs.CrossProcessLockPaths.for_stem(pin_dir, "bounded_res")
    _check(paths.lock_file.acquire(shared=False, blocking=False))
    core.filesystem.fs.write_cross_proc_owner_json(paths.owner_path, {"pid": os.getpid(), "call_tree_id": "ct_pin"})

    hold_script = (
        "import sys, time\n"
        "from pathlib import Path\n"
        "from core.foundation.primitives import HostPath\n"
        "from core.filesystem.fs import FileLock\n"
        "lk = FileLock(HostPath(Path(sys.argv[1])))\n"
        "lk.acquire(shared=True, blocking=True, timeout_sec=5.0)\n"
        "Path(sys.argv[2]).write_text('pinned', encoding='utf-8')\n"
        "while not Path(sys.argv[3]).exists():\n"
        "    time.sleep(0.02)\n"
        "lk.release()\n"
    )
    rdy_f = pin_dir.path / "child_pinned.flag"
    rel_f = pin_dir.path / "release_pin.flag"
    env_sub = {**os.environ, "PYTHONPATH": str(CORE_SRC_ROOT)}
    proc = subprocess.Popen(
        [sys.executable, "-B", "-c", hold_script, str(paths.pin_path), str(rdy_f), str(rel_f)],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        env=env_sub,
    )
    try:
        dl_rdy = time.monotonic() + 4.0
        while not rdy_f.exists() and time.monotonic() < dl_rdy:
            time.sleep(0.02)
        _check(rdy_f.exists())
        t0 = time.monotonic()
        core.filesystem.fs.unlink_owner_under_pin(
            paths.owner_path,
            paths.pin_path,
            paths.lock_file.release,
            grace_timeout_sec=0.12,
        )
        elapsed = time.monotonic() - t0
        _check(elapsed < 0.8, lambda: f"unlink_owner_under_pin hung for {elapsed:.2f}s")
        _check(not paths.lock_file.is_acquired)
        _check(paths.owner_path.path.is_file())
        rel_f.write_text("go", encoding="utf-8")
        proc.wait(timeout=4.0)
        dl_reap = time.monotonic() + 3.0
        while paths.owner_path.path.exists() and time.monotonic() < dl_reap:
            time.sleep(0.03)
        _check(not paths.owner_path.path.exists())
    finally:
        rel_f.write_text("go", encoding="utf-8")
        if proc.poll() is None:
            proc.kill()
        proc.wait(timeout=3.0)


