def _verify_peer_cache_resolver_and_pooled_child(ws8: HostPath) -> None:
    ws_p1 = HostPath(ws8.path / "ws_peer_res_1")
    ws_p2 = HostPath(ws8.path / "ws_peer_res_2")
    provision_live_workspace(ws_p1.path)
    provision_live_workspace(ws_p2.path)
    factory_calls = [0]
    resolver_calls = [0]
    pooled_p2 = RuntimeDispatcher(
        workspace_root=ws_p2,
        cache_dir=ws_p2.join(".cache"),
        module_provider=ManifestModuleProvider(ws_p2, None),
        options=DispatcherHostOptions(connection_config=DaemonConnectionConfig(enabled=False)),
    )

    def _pooled_factory(target_ws: HostPath) -> RuntimeDispatcher:
        factory_calls[0] += 1
        _check(target_ws == ws_p2)
        return pooled_p2

    def _fast_cache_resolver(target_ws: HostPath) -> HostPath:
        resolver_calls[0] += 1
        return target_ws.join(".cache")

    disp_p1 = RuntimeDispatcher(
        workspace_root=ws_p1,
        cache_dir=ws_p1.join(".cache"),
        module_provider=ManifestModuleProvider(ws_p1, None),
        options=DispatcherHostOptions(
            connection_config=DaemonConnectionConfig(enabled=False),
            child_dispatcher_factory=_pooled_factory,
            peer_cache_dir_resolver=_fast_cache_resolver,
            owns_child_dispatchers=False,
        ),
    )
    try:
        _check(disp_p1.coordinator._lookup_workspace_cache_dir(ws_p2) == ws_p2.join(".cache"))
        _check(factory_calls[0] == 0 and resolver_calls[0] == 1)
        r1 = disp_p1.invoke(InvokeRequest(TaskId("space.echo_tier0"), {"tag": "c1"}, ws_p2, ws_p2))
        r2 = disp_p1.invoke(InvokeRequest(TaskId("space.echo_tier0"), {"tag": "c2"}, ws_p2, ws_p2))
        _check(r1.ok and r2.ok and factory_calls[0] == 2)
        _check(pooled_p2.container_lifecycle.state == ContainerState.UNINITIALIZED)
    finally:
        disp_p1.shutdown(grace_ms=50)
        pooled_p2.shutdown(grace_ms=50)


