def _verify_codec_schema_strictness_and_fwd_unions() -> None:
    for bad_schema in (123, "not_a_type", object(), set, set[int], typing.Union[bytes, object], typing.Union[list[bytes], list[object]]):
        _expect_yscb_code(
            lambda s_bad=bad_schema: DataclassCodec.encode_typed(s_bad, "x"),
            ErrorCode.CODEC_VALIDATION_FAILED,
        )
    ambig_fwd = typing.Union[typing.ForwardRef("_FwdDupAlpha"), typing.ForwardRef("_FwdDupBeta")]
    lns_dup: dict[str, object] = {"_FwdDupAlpha": _FwdDupAlpha, "_FwdDupBeta": _FwdDupBeta}
    _expect_yscb_code(
        lambda: DataclassCodec.decode(ambig_fwd, {"k": 1}, localns=lns_dup),
        ErrorCode.CODEC_VALIDATION_FAILED,
    )
    rank_fwd = typing.Union[str, typing.ForwardRef("_LateSpecMode")]
    dec_mode = DataclassCodec.decode(rank_fwd, "fast", localns={"_LateSpecMode": _LateSpecMode})
