def _verify_subpkg_evict_extra_siblings_and_periodic_first_tick(ws_base: HostPath) -> None:
    ws_conf = HostPath(ws_base.path / "ws_extra_sibling_deg_ssot")
    provision_live_workspace(ws_conf.path)
    py_a = HostPath(Path(sys.executable))
    py_b = ws_conf.join("fake_other_venv_python")
    state_descs: list[list[ModuleDescriptor]] = [
        [
            ModuleDescriptor(ModuleId("ma"), ws_conf.join(".modules", "ma"), venv_group="g1", venv_python=py_a, declared_tasks=(TaskRouteSpec(TaskId("ma.t")),)),
            ModuleDescriptor(ModuleId("mb"), ws_conf.join(".modules", "mb"), venv_group="g2", venv_python=py_b, declared_tasks=(TaskRouteSpec(TaskId("mb.t")),)),
        ]
    ]

    class _SwitchGroupProvider:
        def list_modules(self) -> Sequence[ModuleDescriptor]:
            return tuple(state_descs[0])

        def get_module(self, module_id: ModuleId) -> Optional[ModuleDescriptor]:
            return next((d for d in state_descs[0] if d.module_id == module_id), None)

        def reload(self) -> None:
            return None

    disp_cf = RuntimeDispatcher(
        workspace_root=ws_conf,
        cache_dir=ws_conf.join(".cache"),
        module_provider=_SwitchGroupProvider(),
        options=DispatcherHostOptions(is_daemon_host=True),
    )
    try:
        state_descs[0] = [
            ModuleDescriptor(ModuleId("ma"), ws_conf.join(".modules", "ma"), venv_group="g2", venv_python=py_a, declared_tasks=(TaskRouteSpec(TaskId("ma.t")),)),
            ModuleDescriptor(ModuleId("mb"), ws_conf.join(".modules", "mb"), venv_group="g2", venv_python=py_b, declared_tasks=(TaskRouteSpec(TaskId("mb.t")),)),
        ]
        disp_cf.reload_affected_modules(frozenset({ModuleId("ma")}), grace_ms=100)
        out_mb = disp_cf.invoke(InvokeRequest(TaskId("mb.t"), {}, ws_conf, ws_conf))
        _check(not out_mb.ok and out_mb.error is not None and out_mb.error.code == ErrorCode.MODULE_DEGRADED)

        p_spec = TaskRouteSpec(TaskId("mp.tick"), periodic=PeriodicScheduleSpec(default_interval_sec=3600.0))
        state_descs[0] = [ModuleDescriptor(ModuleId("mp"), ws_conf.join(".modules", "mp"), declared_tasks=(p_spec,))]
        disp_cf.reload_affected_modules(frozenset(), grace_ms=100)
        fired = threading.Event()
        gate_flag = [False]
        pl = PeriodicTriggerLoop(
            dispatcher=disp_cf,
            config_view=None,
            can_run_background=lambda: gate_flag[0],
            execute_periodic_task=lambda _tid: fired.set(),
        )
        try:
            pl.start()
            pl.refresh_schedules()
            pl.refresh_schedules()
            gate_flag[0] = True
            pl.wake()
            _check(fired.wait(timeout=2.0), "PeriodicTriggerLoop delayed first tick after pre-run refresh_schedules!")
        finally:
            pl.stop(drain_timeout_sec=1.0)
    finally:
        disp_cf.shutdown(grace_ms=100)

