def _verify_periodic_disable_race_and_deferred_dirty_space(ws_base: HostPath) -> None:
    ws_pr = HostPath(ws_base.path / "ws_per_race_and_dirty")
    provision_live_workspace(ws_pr.path)
    cfg_enabled = [True]

    class _MutCfgView:
        def get_module_value(self, _m: ModuleId, key: str, default: JsonValue = None) -> JsonValue:
            return cfg_enabled[0] if key == "en" else default

    p_spec = TaskRouteSpec(TaskId("mp.r"), periodic=PeriodicScheduleSpec(default_interval_sec=0.05, enabled_config_key="en"))

    class _OnePeriodicProvider:
        def list_modules(self) -> Sequence[ModuleDescriptor]:
            return (ModuleDescriptor(ModuleId("mp"), ws_pr.join(".modules", "mp"), declared_tasks=(p_spec,)),)
        def get_module(self, module_id: ModuleId) -> Optional[ModuleDescriptor]:
            return self.list_modules()[0] if module_id == ModuleId("mp") else None
        def reload(self) -> None:
            return None

    disp_p = RuntimeDispatcher(workspace_root=ws_pr, cache_dir=ws_pr.join(".cache"), module_provider=_OnePeriodicProvider(), options=DispatcherHostOptions(is_daemon_host=True))
    in_exec = threading.Event()
    unblock = threading.Event()
    runs = [0]

    def _exec_p(_tid: TaskId) -> None:
        runs[0] += 1
        in_exec.set()
        unblock.wait(timeout=2.0)

    pl = PeriodicTriggerLoop(dispatcher=disp_p, config_view=_MutCfgView(), can_run_background=lambda: True, execute_periodic_task=_exec_p)
    try:
        pl.start()
        _check(in_exec.wait(timeout=2.0))
        cfg_enabled[0] = False
        pl.refresh_schedules()
        unblock.set()
        time.sleep(0.16)
        _check(runs[0] == 1, f"Disabled periodic task resurrected: runs={runs[0]}")
    finally:
        unblock.set()
        pl.stop(drain_timeout_sec=1.0)
        disp_p.shutdown(grace_ms=100)


def _provision_two_mod_bg_diag_ws(ws_dd: HostPath) -> ModuleProviderPort:
    provision_live_workspace(ws_dd.path)
    for m_name, fail_flag in (("m1", True), ("m2", False)):
        m_dir = ws_dd.path / ".modules" / m_name
        m_dir.mkdir(parents=True, exist_ok=True)
        (m_dir / "module_entry.py").write_text(
            "from dataclasses import dataclass\nfrom typing import Callable, Optional, Sequence\n"
            "from core.execution.runtime import BoundTask, Task, TaskContext, TaskExposure, TaskMetadata, YscbModule\n"
            "from core.foundation.primitives import HostPath, ModuleId, TaskId\n"
            f"FAIL_CLOSE = {fail_flag!r}\nMID = {m_name!r}\n"
            "@dataclass(frozen=True, slots=True)\nclass _SpIn:\n    changed_paths: tuple[str, ...] = ()\n    startup_catchup: bool = False\n"
            "@dataclass(frozen=True, slots=True)\nclass _SpOut:\n    ok: bool = True\n"
            "class _SpTask(Task[_SpIn, _SpOut]):\n"
            "    @property\n    def metadata(self) -> TaskMetadata[_SpIn, _SpOut]:\n"
            "        return TaskMetadata(TaskId('m2.on_space'), _SpIn, _SpOut, exposure=TaskExposure.INTERNAL_TRIGGER)\n"
            "    def run(self, req: _SpIn, ctx: TaskContext) -> _SpOut:\n"
            "        with (ctx.workspace_root.path / 'space_runs.txt').open('a', encoding='utf-8') as fh:\n"
            "            fh.write(('catchup' if req.startup_catchup else 'change') + '\\n')\n"
            "        return _SpOut()\n"
            "class _M(YscbModule):\n"
            "    @property\n    def module_id(self) -> ModuleId: return ModuleId(MID)\n"
            "    def on_init(self, _ws: HostPath) -> Optional[Callable[[], None]]:\n"
            "        return (lambda: (_ for _ in ()).throw(RuntimeError('bg_close_' + MID))) if FAIL_CLOSE else None\n"
            "    def tasks(self) -> Sequence[BoundTask]:\n"
            "        return (_SpTask(),) if MID == 'm2' else ()\n"
            "def create_module() -> YscbModule: return _M()\n",
            encoding="utf-8",
        )

    class _TwoModProvider:
        def list_modules(self) -> Sequence[ModuleDescriptor]:
            return (
                ModuleDescriptor(ModuleId("m1"), ws_dd.join(".modules", "m1"), eager_warmup=True),
                ModuleDescriptor(ModuleId("m2"), ws_dd.join(".modules", "m2"), declared_tasks=(TaskRouteSpec(TaskId("m2.on_space"), exposure=TaskExposure.INTERNAL_TRIGGER),)),
            )
        def get_module(self, module_id: ModuleId) -> Optional[ModuleDescriptor]:
            return next((d for d in self.list_modules() if d.module_id == module_id), None)
        def reload(self) -> None:
            return None

    return _TwoModProvider()


def _verify_deferred_dirty_space_and_scoped_bg_diags(ws_base: HostPath) -> None:
    ws_dd = HostPath(ws_base.path / "ws_deferred_dirty_and_diags")
    cache_dd = ws_dd.join(".cache")
    disp_d = RuntimeDispatcher(workspace_root=ws_dd, cache_dir=cache_dd, module_provider=_provision_two_mod_bg_diag_ws(ws_dd), options=DispatcherHostOptions(is_daemon_host=True))
    sp_dir, cfg_dir = ws_dd.join("space_docs"), ws_dd.join("cfg_docs")
    sp_dir.path.mkdir(parents=True, exist_ok=True)
    cfg_dir.path.mkdir(parents=True, exist_ok=True)
    dm = WorkspaceDaemon(
        workspace_root=ws_dd,
        cache_dir=cache_dd,
        dispatcher=disp_d,
        watch_config=DaemonWatcherConfig(
            space_watch_roots=(sp_dir,),
            config_watch_roots=(cfg_dir,),
            on_space_changed_task=TaskId("m2.on_space"),
            watcher_debounce_sec=0.05,
        ),
    )
    ready_ev = threading.Event()
    dm_th = threading.Thread(target=lambda: dm.run_forever(ttl_override_sec=15.0, ready_callback=ready_ev.set), daemon=True)
    dm_th.start()
    try:
        _check(ready_ev.wait(timeout=5.0))
        runs_file = ws_dd.path / "space_runs.txt"
        t_end = time.monotonic() + 2.0
        while not runs_file.is_file() and time.monotonic() < t_end:
            time.sleep(0.02)
        _check(runs_file.read_text(encoding="utf-8").splitlines() == ["catchup"])
        excl_lk = FileLock(cache_dd.join("locks", "installer.lock"))
        _check(excl_lk.acquire(blocking=True, timeout_sec=2.0, shared=False))
        try:
            _check(dm.quiesce(frozenset({ModuleId("m2")}), lease_sec=5.0, drain_timeout_sec=1.0))
            (cfg_dir.path / "c.json").write_text("{}", encoding="utf-8")
            (sp_dir.path / "doc.txt").write_text("hello", encoding="utf-8")
            time.sleep(0.18)
            _check(runs_file.read_text(encoding="utf-8").splitlines() == ["catchup"])
        finally:
            excl_lk.release()
        dm.resume_from_quiesce(modules=frozenset({ModuleId("m2")}))
        t_sp = time.monotonic() + 3.0
        while len(runs_file.read_text(encoding="utf-8").splitlines()) < 2 and time.monotonic() < t_sp:
            time.sleep(0.03)
        _check(len(runs_file.read_text(encoding="utf-8").splitlines()) == 2)
        (ws_dd.path / ".modules" / "m1" / "touch.py").write_text("X = 1\n", encoding="utf-8")
        _wait_until(lambda: bool(dm._bg_teardown_diags), timeout_sec=3.5)
        rel_m2 = query_daemon_control(cache_dd, ws_dd, FrameKind.CONTROL_RELOAD, {"modules": ["m2"]})
        _check(isinstance(rel_m2, dict) and rel_m2.get("teardown_diagnostics") == [], f"Leaked m1 diag: {rel_m2}")
        stop_rep = query_daemon_control(cache_dd, ws_dd, FrameKind.CONTROL_STOP, {})
        _check(isinstance(stop_rep, dict) and any("bg_close_m1" in str(d) for d in stop_rep.get("teardown_diagnostics", [])))
    finally:
        dm.request_shutdown(force=True)
        dm_th.join(timeout=5.0)


def _verify_watcher_scan_lock_strict_imm_and_linear_frames(ws_base: HostPath) -> None:
    # 1) WorkerContainerLifecycle UNINITIALIZED -> quiesce() -> resume() stays UNINITIALIZED
    lc_u = WorkerContainerLifecycle()
    lc_u.quiesce()
    _check(lc_u.state == ContainerState.QUIESCED)
    lc_u.resume()
    _check(lc_u.state == ContainerState.UNINITIALIZED)

    # 2) ErrorDetail.raise_as_exception() preserves TaskCancelledException (including preempted) for Tier 0 & Tier 1
    caught_preempt = False
    try:
        ErrorDetail(ErrorCode.TASK_PREEMPTED, "preempted_sub", source_task="m.sub").raise_as_exception()
    except TaskCancelledException as exc:
        caught_preempt = exc.detail.code == ErrorCode.TASK_PREEMPTED and exc.detail.source_task == "m.sub"
    _check(caught_preempt)

    # 3) O(1) TurnSessionRegistry frame & hop accumulation (< 150 ms for 1,500 steps)
    class _BenchProv:
        def list_modules(self) -> Sequence[ModuleDescriptor]: return ()
        def get_module(self, _m: ModuleId) -> Optional[ModuleDescriptor]: return None
        def reload(self) -> None: return None

    disp_b = RuntimeDispatcher(workspace_root=ws_base, cache_dir=ws_base.join(".cache"), module_provider=_BenchProv())
    ts_scope = TurnScope("turn_lin_bench", TurnKind.COLD, CancellationToken())
    sess_b = disp_b._sessions.get_or_bind_turn_session(ts_scope)
    prop_b = CallPropagationContext(turn_id="turn_lin_bench")
    t0 = time.perf_counter()
    for idx in range(1500):
        disp_b._sessions.record_transitive_invoked_tasks(prop_b, ((ws_base, TaskId(f"m.t{idx}")),))
        disp_b._sessions.record_transitive_emitted_hops(prop_b, (EmittedEventHop(ws_base.comparison_key, EventId(f"m.e{idx}"), f"m.t{idx}"),))
    snap_inv, snap_eh = disp_b._sessions.snapshot_session_lineage(sess_b)
    _check(len(snap_inv) == 1500 and len(snap_eh) == 1500 and (time.perf_counter() - t0) < 0.15)
    disp_b.shutdown(grace_ms=50)

    # 4) PollingDirectoryWatcher concurrent resync_paths() + _poll_once() + echo suppression never rolls back or leaks
    w_dir = HostPath(ws_base.path / "ws_wat_race")
    w_dir.path.mkdir(parents=True, exist_ok=True)
    suppressed_stamps: set[tuple[int, int]] = set()
    spurious: list[frozenset[HostPath]] = []
    wat = PollingDirectoryWatcher(
        (w_dir,),
        spurious.append,
        debounce_sec=0.02,
        poll_interval_sec=0.02,
        is_suppressed=lambda _hp, mt, sz, _ino: (mt, sz) in suppressed_stamps,
    )
    wat.start()
    try:
        f_p = w_dir.path / "cfg.json"
        for i in range(12):
            payload = f'{{"v": {i}}}' + (" " * i)
            f_p.write_text(payload, encoding="utf-8")
            st = f_p.stat()
            suppressed_stamps.add((st.st_mtime_ns, st.st_size))
            flushed = wat.resync_paths((w_dir,))
            _check(not flushed, f"Suppressed self-write leaked from resync_paths: {flushed}")
        time.sleep(0.08)
        _check(not spurious, f"Spurious post-resync callback fired: {spurious}")
    finally:
        wat.stop()


@dataclass(frozen=True, slots=True)
class _GenTaskIdBox(typing.Generic[_TLayer]):
    item: _TLayer


def _verify_rpc_cancel_order_and_generic_vo_equiv() -> None:
    # 1) Generic dataclass with runtime-erased TypeVar holding TaskId encodes, hashes, and computes COALESCE equiv
    box = _GenTaskIdBox(TaskId("m.alpha"))
    _check(DataclassCodec.encode_object(box) == {"item": "m.alpha"})
    _check(len(DataclassCodec.canonical_hash(box)) == 64)

    class _GenBoxTask(Task[_GenTaskIdBox[TaskId], SimpleOutDto]):
        @property
        def metadata(self) -> TaskMetadata[_GenTaskIdBox[TaskId], SimpleOutDto]:
            return TaskMetadata(TaskId("m.gen_box"), _GenTaskIdBox[TaskId], SimpleOutDto, concurrency_mode=ConcurrencyMode.COALESCE, resource_key="rk_gen_box")
        def run(self, _req: _GenTaskIdBox[TaskId], _ctx: TaskContext) -> SimpleOutDto:
            return SimpleOutDto(ok_msg="ok")

    _check(_GenBoxTask().compute_normalized_equivalence({"item": "m.alpha"}).startswith("m.gen_box:norm:"))

    # 2) Cross-module Outer -> dynamic InnerB cache eviction frees InnerB on GC (while Outer stays alive!)
    dyn_nm = "_yscb_v2_mod_dyn_inner_gc"
    out_nm = "_yscb_v2_static_outer_host"
    dyn_m = types.ModuleType(dyn_nm)
    out_m = types.ModuleType(out_nm)
    sys.modules[dyn_nm] = dyn_m
    sys.modules[out_nm] = out_m
    try:
        @dataclass(frozen=True, slots=True)
        class _DynInner:
            v: int = 1
        _DynInner.__module__ = dyn_nm
        _DynInner.__qualname__ = "_DynInner"
        object.__setattr__(dyn_m, "_DynInner", _DynInner)

        @dataclass(frozen=True, slots=True)
        class _StaticOuter:
            inner: _DynInner
        _StaticOuter.__module__ = out_nm
        _StaticOuter.__qualname__ = "_StaticOuter"
        object.__setattr__(out_m, "_StaticOuter", _StaticOuter)
        object.__setattr__(out_m, "_DynInner", _DynInner)
        _check(DataclassCodec.decode(_StaticOuter, {"inner": {"v": 7}}).inner.v == 7)
        ref_in = weakref.ref(_DynInner)
        del _DynInner
        object.__delattr__(out_m, "_DynInner")
        sys.modules.pop(dyn_nm, None)
        del dyn_m
        DataclassCodec.evict_module_prefix(dyn_nm)
        gc.collect()
        _check(ref_in() is None)
    finally:
        sys.modules.pop(dyn_nm, None)
        sys.modules.pop(out_nm, None)

    # 3) ErrorDetail.raise_as_exception preserves custom remediation & Redirect stdout interleave detaches proxy
    try:
        ErrorDetail(ErrorCode.TASK_CANCELLED, "c", remediation="retry_later", source_task="m.t").raise_as_exception()
    except TaskCancelledException as exc:
        _check(exc.detail.remediation == "retry_later" and exc.detail.source_task == "m.t")
    real_out = sys.stdout
    ext_buf = io.StringIO()
    with guard_standard_streams():
        cm = contextlib.redirect_stdout(ext_buf)
        cm.__enter__()
    cm.__exit__(None, None, None)
    _ = sys.stdout.write("")
    _check(sys.stdout is real_out)


def _verify_rpc_unsent_cancel_and_worker_drain_order(ws_base: HostPath) -> None:
    # 1) RPC CANCEL while CALL_START is queued behind large frame must NOT execute cancelled call on peer!
    s_cli, s_srv = socket.socketpair()
    s_cli.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 4096)
    s_srv.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 4096)
    ran_tags: list[str] = []

    class _SrvH(InboundCallHandler):
        def on_call(self, _sid: int, pl: JsonObject, ack: Callable[[], bool], _pr: Callable[[JsonObject], None], tok: CancellationToken) -> tuple[bool, JsonObject]:
            ack()
            if not tok.is_cancelled:
                ran_tags.append(str(pl.get("tag", "")))
            return (True, {"ok": True})
        def on_control(self, _k: FrameKind, _pl: JsonObject) -> JsonObject:
            return {"ok": True}

    ch_cli = MultiplexedChannel(s_cli, is_initiator=True)
    ch_srv: Optional[MultiplexedChannel] = None
    try:
        big_str = "x" * (2 * 1024 * 1024)
        tok2 = CancellationToken()
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            f1 = pool.submit(ch_cli.call, {"tag": "first", "blob": big_str})
            dl1 = time.monotonic() + 2.0
            while len(ch_cli._pending_calls) < 1 and time.monotonic() < dl1:
                time.sleep(0.002)
            f2 = pool.submit(ch_cli.call, {"tag": "second"}, cancel_token=tok2, cancel_grace_ms=80)
            dl2 = time.monotonic() + 2.0
            while len(ch_cli._data_out_queue) < 1 and time.monotonic() < dl2:
                time.sleep(0.002)
            tok2.cancel(reason="abort_queued")
            out2 = f2.result(timeout=2.0)
            ch_srv = MultiplexedChannel(s_srv, is_initiator=False, handler=_SrvH())
            out1 = f1.result(timeout=5.0)
        _check(out1.error_code is None and out2.error_code == ErrorCode.TASK_CANCELLED and not out2.was_accepted)
        _check(ran_tags == ["first"], f"Unexpected tags executed: {ran_tags}")
    finally:
        ch_cli.close()
        if ch_srv is not None:
            ch_srv.close()
        else:
            s_srv.close()

    # 2) WorkerSubprocessHandler.close() drains in-flight step BEFORE running module on_init closer!
    ws_w = HostPath(ws_base.path / "ws_worker_drain_order")
    (ws_w.path / ".modules" / "wm").mkdir(parents=True, exist_ok=True)
    (ws_w.path / ".modules" / "wm" / "module_entry.py").write_text(
        "import time\nfrom dataclasses import dataclass\nfrom typing import Callable, Optional, Sequence\n"
        "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.foundation.primitives import HostPath, ModuleId, TaskId\n"
        "CLOSED = [False]\n@dataclass(frozen=True, slots=True)\nclass _In:\n    pass\n@dataclass(frozen=True, slots=True)\nclass _Out:\n    closed_during_run: bool\n"
        "class _T(Task[_In, _Out]):\n    @property\n    def metadata(self) -> TaskMetadata[_In, _Out]: return TaskMetadata(TaskId('wm.run'), _In, _Out)\n"
        "    def run(self, _r: _In, _c: TaskContext) -> _Out:\n        time.sleep(0.08)\n        return _Out(closed_during_run=CLOSED[0])\n"
        "class _WM(YscbModule):\n    @property\n    def module_id(self) -> ModuleId: return ModuleId('wm')\n"
        "    def on_init(self, _ws: HostPath) -> Optional[Callable[[], None]]: return lambda: CLOSED.__setitem__(0, True)\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (_T(),)\n"
        "def create_module() -> YscbModule: return _WM()\n",
        encoding="utf-8",
    )
    wh = WorkerSubprocessHandler(ws_w, (ModuleDescriptor(ModuleId("wm"), ws_w.join(".modules", "wm")),))
    w_cmd = WorkerCommandEnvelope(action=WorkerCommandKind.WARMUP, modules=(ModuleId("wm"),))
    _ = wh.on_call(1, DataclassCodec.encode_envelope(w_cmd), lambda: True, lambda _p: None, CancellationToken())
    cb_ctx = WorkerCallbackContext(propagation=CallPropagationContext(), caller_cwd=ws_w, caller_env={})
    cmd = WorkerCommandEnvelope(action=WorkerCommandKind.RUN_STEP, task_id=TaskId("wm.run"), caller_cwd=ws_w, callback_context=cb_ctx)
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        f_step = pool.submit(wh.on_call, 1, DataclassCodec.encode_envelope(cmd), lambda: True, lambda _p: None, CancellationToken())
        time.sleep(0.02)
        f_close = pool.submit(wh.close, grace_ms=500)
        ok_s, rep_s = f_step.result(timeout=3.0)
        _ = f_close.result(timeout=3.0)
    dec_rep = DataclassCodec.decode_envelope(WorkerStepReply, rep_s)
    _check(ok_s and dec_rep.ok and isinstance(dec_rep.raw_output, Mapping) and dec_rep.raw_output.get("closed_during_run") is False)


def _verify_stream_proxy_cross_thread_and_progress_ack() -> None:
    orig_out = sys.stdout
    t1_entered = threading.Event()
    t1_release = threading.Event()

    def _hold_t1_guard() -> None:
        with guard_standard_streams() as cap1:
            t1_entered.set()
            t1_release.wait(timeout=3.0)
            _ = sys.stdout.write("isolated_t1")
            _check(cap1.getvalue() == "isolated_t1")

    th1 = threading.Thread(target=_hold_t1_guard, daemon=True)
    th1.start()
    _check(t1_entered.wait(timeout=2.0))
    temp_io = io.StringIO()
    with contextlib.redirect_stdout(temp_io):
        with guard_standard_streams() as cap2:
            _ = sys.stdout.write("isolated_t2")
            _check(cap2.getvalue() == "isolated_t2")
    temp_io.close()
    t1_release.set()
    th1.join(timeout=2.0)
    _check(sys.stdout is orig_out and not sys.stdout.closed)

    alt_buf = io.StringIO()
    with guard_standard_streams():
        cm_alt = contextlib.redirect_stdout(alt_buf)
        cm_alt.__enter__()
    cm_alt.__exit__(None, None, None)
    _ = sys.stdout.encoding
    _check(sys.stdout is orig_out)

    s_c, s_s = socket.socketpair()
    prog_seen: list[JsonObject] = []

    class _EarlyProgH(InboundCallHandler):
        def on_call(self, _sid: int, _pl: JsonObject, _ack: Callable[[], bool], prog: Callable[[JsonObject], None], _tok: CancellationToken) -> tuple[bool, JsonObject]:
            prog({"pct": 50})
            raise RuntimeError("boom_after_progress")
        def on_control(self, _k: FrameKind, _pl: JsonObject) -> JsonObject:
            return {"ok": True}

    ch_s = MultiplexedChannel(s_s, is_initiator=False, handler=_EarlyProgH())
    ch_c = MultiplexedChannel(s_c, is_initiator=True)
    try:
        out_p = ch_c.call({"q": 1}, on_progress=prog_seen.append, timeout_ms=2000)
        _check(out_p.was_accepted and not out_p.rejected_before_accept and prog_seen == [{"pct": 50}])
    finally:
        ch_c.close()
        ch_s.close()


def _verify_nonsymlink_dotdot_and_closed_turn_cascade(ws_base: HostPath) -> None:
    ws_ns = ws_base.path / "ws_nonsym_dotdot"
    ext_d = ws_base.path / "ext_outside"
    (ws_ns / "sub").mkdir(parents=True, exist_ok=True)
    ext_d.mkdir(parents=True, exist_ok=True)
    real_f = ws_ns / "real_file.txt"
    real_f.write_bytes(b"safe_bytes")
    if os.name != "nt":
        os.symlink(ws_ns / "sub", ws_ns / "sym_dir")
        os.symlink(ext_d, ws_ns / "sym_ext")
        trav1 = f"{ws_ns}/sym_dir/../real_file.txt"
        trav2 = f"{ws_ns}/sym_ext/../{ws_ns.name}/real_file.txt"
        _check(has_symlink_raw_path(trav1) and has_symlink_raw_path(trav2))
        _check(read_nofollow_regular_bytes(trav1) is None)
        _check(not is_contained_nonsymlink_path(ws_ns, trav1))
        _expect_yscb_code(lambda: assert_no_symlink_raw_path(f"{ws_ns}/sym_dir/../new.txt"), ErrorCode.SECURITY_GATED)
        prev_cwd = os.path.realpath(".")
        try:
            os.chdir(ws_ns)
            _check(not has_symlink_raw_path("real_file.txt"))
            _check(read_nofollow_regular_bytes("real_file.txt") == b"safe_bytes")
            _check(bool(hash_nofollow_regular_sha256("real_file.txt")))
            _check(has_symlink_raw_path("sym_dir/../real_file.txt"))
        finally:
            os.chdir(prev_cwd)

    # Closed turn session attach_resolved_cascade detaches slot cleanly without raising
    ws_hp = HostPath(ws_ns)
    disp = build_dispatcher_for_workspace(ws_hp, HostPath(Path(sys.executable))).dispatcher
    try:
        t_scope = TurnScope(turn_id="closed_turn_probe", kind=TurnKind.HOT_FOREGROUND, cancel_token=CancellationToken())
        sess = disp._sessions.get_or_bind_turn_session(t_scope)
        _ = disp._sessions.close_managed_session(sess)
        seed = RawEventRecord(EventId("m.e"), TaskId("m.t"), {}, EventOrdering.UNORDERED, CausalLineage())
        casc = FlightCascade(seed_events=(seed,))
        detached: list[str] = []
        casc.add_cleanup(lambda: detached.append("detached"))
        casc.register_caller_slots([LiveFlightParticipant(slot_id=0, turn_cancel=CancellationToken())], ExecutionPriority.FOREGROUND)
        disp._sessions.attach_resolved_cascade(t_scope, (), CausalLineage(), casc, 0, "m.t")
        _check(detached == ["detached"])
        lk_path = ws_hp.join(".cache", "locks", "installer.lock")
        stale_lk = FileLock(lk_path)
        ev_res = disp._cold_locks.run_upgraded_nested(
            "evicted_tree", TaskId("m.t"), CancellationToken(), lambda: StepExecutionResult(ok=True, value=1)
        )
        _check(not ev_res.ok and ev_res.error is not None and ev_res.error.code == ErrorCode.ILLEGAL_LOCK_REENTRANCY)
        _check(not stale_lk.is_acquired)
    finally:
        disp.shutdown(grace_ms=200)


def _verify_worker_stop_grace_and_teardown_diags(ws_base: HostPath, venv_bin: HostPath) -> None:
    ws_st = HostPath(ws_base.path.parent / "ws_worker_stop_grace_td")
    (ws_st.path / ".modules" / "stmod").mkdir(parents=True, exist_ok=True)
    (ws_st.path / ".cache").mkdir(parents=True, exist_ok=True)
    (ws_st.path / ".modules" / "stmod" / "module_entry.py").write_text(
        "import time\nfrom dataclasses import dataclass\nfrom typing import Callable, Optional, Sequence\n"
        "from core.execution.runtime import BoundTask, Task, TaskContext, TaskMetadata, YscbModule\n"
        "from core.filesystem.fs import atomic_write_json\n"
        "from core.foundation.primitives import HostPath, ModuleId, TaskId\n"
        "@dataclass(frozen=True, slots=True)\nclass _In:\n    sleep_s: float = 1.4\n"
        "@dataclass(frozen=True, slots=True)\nclass _Out:\n    ok: bool = True\n"
        "class _SlowT(Task[_In, _Out]):\n"
        "    @property\n    def metadata(self) -> TaskMetadata[_In, _Out]: return TaskMetadata(TaskId('stmod.slow'), _In, _Out)\n"
        "    def run(self, r: _In, c: TaskContext) -> _Out:\n"
        "        atomic_write_json(c.workspace_root.join('.cache', 'in_step.json'), {'in': True})\n"
        "        time.sleep(r.sleep_s)\n        return _Out(True)\n"
        "class _StM(YscbModule):\n"
        "    @property\n    def module_id(self) -> ModuleId: return ModuleId('stmod')\n"
        "    def on_init(self, _ws: HostPath) -> Optional[Callable[[], None]]:\n"
        "        def _cls() -> None:\n            raise RuntimeError('tier1_stop_closer_boom')\n"
        "        return _cls\n"
        "    def tasks(self) -> Sequence[BoundTask]: return (_SlowT(),)\n"
        "def create_module() -> YscbModule: return _StM()\n",
        encoding="utf-8",
    )
    desc = ModuleDescriptor(ModuleId("stmod"), ws_st.join(".modules", "stmod"), venv_group="stg", venv_python=venv_bin, eager_warmup=True)
    class _StProv(ModuleProviderPort):
        def list_modules(self) -> Sequence[ModuleDescriptor]:
            return (desc,)

    disp = RuntimeDispatcher(
        workspace_root=ws_st,
        cache_dir=ws_st.join(".cache"),
        module_provider=_StProv(),
        options=DispatcherHostOptions(is_daemon_host=True),
    )
    disp._tier1_pool.warmup_group((desc,))
    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:
        fut = pool.submit(disp.invoke, InvokeRequest(TaskId("stmod.slow"), {"sleep_s": 1.5}, ws_st, ws_st))
        dl = time.monotonic() + 4.0
        while not (ws_st.path / ".cache" / "in_step.json").exists() and time.monotonic() < dl:
            time.sleep(0.02)
        disp.cancel_all_active_turns("stop_now")
        td = disp.shutdown(grace_ms=250)
        _ = fut.result(timeout=5.0)
    _check(any(d.code == ErrorCode.TEARDOWN_ERROR and "tier1_stop_closer_boom" in d.message for d in td), f"Missing teardown diag: {td}")


@dataclass(frozen=True, slots=True)
class _ScalarVoUnionHolder:
    tid_or_mid: TaskId | ModuleId
    mid_or_map: ModuleId | dict[str, int]
    seq_u: list[ModuleId] | list[HostPath]


def _scalar_seq_sub_mapper(items: Sequence[ModuleId]) -> int:
    return len(items)


def _verify_scalar_vo_unions_and_offline_ctrl_kind(ws_base: HostPath) -> None:
    hp = HostPath(ws_base.path)
    h1 = _ScalarVoUnionHolder(TaskId("m.t"), ModuleId("m"), [ModuleId("m1"), ModuleId("m2")])
    h2 = _ScalarVoUnionHolder(ModuleId("m"), {"k": 7}, [hp])
    enc1 = DataclassCodec.encode(h1)
    enc2 = DataclassCodec.encode(h2)
    _check(DataclassCodec.decode(_ScalarVoUnionHolder, enc1) == h1)
    _check(DataclassCodec.decode(_ScalarVoUnionHolder, enc2) == h2)

    sub = EventSubscriptionSpec(EventId("m.raw_ev"), lambda rows: len(rows))
    _check(sub.payload_type is None)
    sub_vo = EventSubscriptionSpec(EventId("m.vo_ev"), _scalar_seq_sub_mapper)
    _check(sub_vo.payload_type is None)

    _check(query_daemon_control(ws_base.join(".cache_none"), ws_base, FrameKind.CALL_START) is None)

    # Deferred CONTROL_RESUME under held installer.lock must NOT steal stashed bg teardown diagnostics!
    ws_d = HostPath(ws_base.path / "ws_resume_no_theft")
    provision_live_workspace(ws_d.path)
    disp_d = build_dispatcher_for_workspace(ws_d, HostPath(Path(sys.executable)), is_daemon_host=True).dispatcher
    daemon = WorkspaceDaemon(workspace_root=ws_d, cache_dir=ws_d.join(".cache"), dispatcher=disp_d)
    try:
        daemon._phase = ContainerState.READY
        _ = daemon.quiesce(frozenset({ModuleId("space")}), lease_sec=30.0, drain_timeout_sec=2.0)
        daemon._record_scoped_bg_diags(
            (ErrorDetail(ErrorCode.TEARDOWN_ERROR, "space_td_held", source_task="space.on_init"),),
            frozenset({ModuleId("space")}),
        )
        inst_lk = FileLock(ws_d.join(".cache", "locks", "installer.lock"))
        _check(inst_lk.acquire(shared=False, blocking=False))
        try:
            rep_def = daemon.on_control(FrameKind.CONTROL_RESUME, {"modules": ["space"]})
            _check(rep_def.get("ok") is True and rep_def.get("teardown_diagnostics") == [])
        finally:
            inst_lk.release()
        rep_sync = daemon.on_control(FrameKind.CONTROL_RESUME, {"modules": ["space"]})
        td_list = rep_sync.get("teardown_diagnostics")
        _check(isinstance(td_list, list) and len(td_list) == 1)
    finally:
        disp_d.shutdown(grace_ms=200)


def _build_auto_gc_codec_probe_refs() -> tuple[weakref.ReferenceType[object], ...]:
    mod = types.ModuleType("_auto_gc_probe_mod")
    sys.modules["_auto_gc_probe_mod"] = mod
    code = (
        "import collections.abc as cabc\nfrom dataclasses import dataclass\nfrom enum import Enum\n"
        "class St(Enum):\n    OK = \x27ok\x27\n    ERR = \x27err\x27\n"
        "@dataclass(frozen=True, slots=True)\nclass Ch:\n    n: int\n    st: St\n"
        "@dataclass(frozen=True, slots=True)\nclass Par:\n"
        "    c: Ch\n    oc: Ch | None\n    xs: list[Ch]\n    mp: dict[St, Ch]\n    u: Ch | int\n"
        "def map_p(rows: cabc.Sequence[Par]) -> int:\n    return len(rows)\n"
    )
    ns: dict[str, object] = {"__name__": "_auto_gc_probe_mod"}
    builtins.exec(code, ns)
    for k, v_obj in ns.items():
        if not k.startswith("__"):
            object.__setattr__(mod, k, v_obj)
    par_cls = ns["Par"]
    ch_cls = ns["Ch"]
    st_cls = ns["St"]
    map_fn = ns["map_p"]
    ns["_mod_self"] = mod
    ok_m = st_cls["OK"]
    err_m = st_cls["ERR"]
    inst = par_cls(ch_cls(1, ok_m), ch_cls(2, err_m), [ch_cls(3, ok_m)], {ok_m: ch_cls(4, ok_m)}, ch_cls(5, err_m))
    enc = DataclassCodec.encode(inst)
    _check(DataclassCodec.decode(par_cls, enc) == inst)
    _check(DataclassCodec.decode(list[par_cls], [enc]) == [inst])
    _check(DataclassCodec.decode(par_cls | None, enc) == inst)
    sub = EventSubscriptionSpec(EventId("m.e"), map_fn)
    _check(sub.decode_and_map([enc]) == 1)
    refs = (weakref.ref(mod), weakref.ref(par_cls), weakref.ref(ch_cls), weakref.ref(st_cls), weakref.ref(map_fn))
    sys.modules.pop("_auto_gc_probe_mod", None)
    return refs


def _verify_importlib_binding_3thread_stdout_and_auto_gc(ws_base: HostPath) -> None:
    # 1) Zero-evict automatic GC of dynamic dataclasses, Enum, generics, and batch_mapper
    refs = _build_auto_gc_codec_probe_refs()
    gc.collect()
    gc.collect()
    _check(all(r() is None for r in refs))

    # 2) Captured importlib.import_module binding remains valid after last managed package unloads
    ws_im = HostPath(ws_base.path / "ws_imp_bind_after_unload")
    (ws_im.path / ".modules" / "ib").mkdir(parents=True, exist_ok=True)
    (ws_im.path / ".modules" / "ib" / "module_entry.py").write_text(
        "from importlib import import_module as BOUND_IMP\nfrom typing import Sequence\n_ = BOUND_IMP\n"
        "from core.execution.runtime import BoundTask, YscbModule\nfrom core.foundation.primitives import ModuleId\n"
        "class _M(YscbModule):\n    @property\n    def module_id(self) -> ModuleId: return ModuleId(\x27ib\x27)\n"
        "    def tasks(self) -> Sequence[BoundTask]: return ()\n"
        "def create_module() -> YscbModule: return _M()\n",
        encoding="utf-8",
    )
    art = ProtectedModuleLoader(ws_im).load_module_artifact(ModuleDescriptor(ModuleId("ib"), ws_im.join(".modules", "ib")))
    bound_imp = dict(inspect.getmembers_static(sys.modules[art.package_key]))["BOUND_IMP"]
    ProtectedModuleLoader.cleanup_package(art.package_key)
    _check(bound_imp("json") is json)

    # 3) 3-thread guard_standard_streams + redirect_stdout interleaving never drops active T3 capture
    real_buf = io.StringIO()
    prev_out = sys.stdout
    sys.stdout = real_buf
    try:
        t1_in, t1_exit, t3_in, t3_write, t3_done = (threading.Event() for _ in range(5))
        t3_captured: list[str] = []

        def _t1() -> None:
            with guard_standard_streams():
                t1_in.set()
                t1_exit.wait(timeout=3.0)

        def _t3() -> None:
            with guard_standard_streams() as cap3:
                t3_in.set()
                t3_write.wait(timeout=3.0)
                _ = sys.stdout.write("secret_t3_out")
                t3_captured.append(cap3.getvalue())
            t3_done.set()

        th1 = threading.Thread(target=_t1, daemon=True)
        th3 = threading.Thread(target=_t3, daemon=True)
        th1.start()
        _check(t1_in.wait(timeout=2.0))
        ext_buf = io.StringIO()
        with contextlib.redirect_stdout(ext_buf):
            th3.start()
            _check(t3_in.wait(timeout=2.0))
        t1_exit.set()
        th1.join(timeout=2.0)
        t3_write.set()
        _check(t3_done.wait(timeout=2.0))
        th3.join(timeout=2.0)
        _check(t3_captured == ["secret_t3_out"] and real_buf.getvalue() == "" and sys.stdout is real_buf)
    finally:
        sys.stdout = prev_out

    # 4) Task.map_subscription_batch rejects raw bytes/HostPath in dict mapper output
    class _MapStrTask(Task[dict[str, str], SimpleOutDto]):
        @property
        def metadata(self) -> TaskMetadata[dict[str, str], SimpleOutDto]:
            return TaskMetadata(
                TaskId("m.map_s"),
                dict[str, str],
                SimpleOutDto,
                subscriptions=(EventSubscriptionSpec(EventId("m.ev_b"), lambda _rows: {"k": b"raw"}),),
            )
        def run(self, _r: dict[str, str], _c: TaskContext) -> SimpleOutDto:
            return SimpleOutDto("ok")

    _expect_yscb_code(lambda: _MapStrTask().map_subscription_batch(EventId("m.ev_b"), [{}]), ErrorCode.CODEC_VALIDATION_FAILED)




class _RetiringRaceServerHandler(InboundCallHandler):
    def __init__(self, a_entered: threading.Event, release_a: threading.Event) -> None:
        self._a_entered = a_entered
        self._release_a = release_a
        self._calls = 0
        self._lock = threading.Lock()

    def on_call(
        self,
        stream_id: int,
        payload: JsonObject,
        ack_accepted: Callable[[], bool],
        emit_progress: Callable[[JsonObject], None],
        cancel_token: CancellationToken,
    ) -> tuple[bool, JsonObject]:
        _ = (stream_id, emit_progress, cancel_token)
        mode = payload.get("mode")
        if mode == "hold_accepted":
            _check(ack_accepted())
            self._a_entered.set()
            self._release_a.wait(timeout=4.0)
            return (True, {"ok": True, "tag": "stream_a_survived"})
        with self._lock:
            self._calls += 1
            idx = self._calls
        if mode == "reject_once" and idx == 1:
            return (False, {"ok": False})
        _check(ack_accepted())
        return (True, {"ok": True, "tag": f"done_{mode}_{idx}"})


def _verify_retiring_rpc_channel_preserves_accepted_stream(ws_base: HostPath) -> None:
    ws_r = HostPath(ws_base.path / "ws_retire_rpc_race")
    cache_r = ws_r.join(".cache")
    (cache_r.path / "daemon").mkdir(parents=True, exist_ok=True)
    a_entered = threading.Event()
    release_a = threading.Event()
    handler = _RetiringRaceServerHandler(a_entered, release_a)
    listener = RpcServerListener(ws_r, handler)
    ep = listener.start()
    atomic_write_json(cache_r.join("daemon", "daemon.json"), DataclassCodec.encode_object(ep))
    sess = PersistentRpcSession(cache_r, ws_r)
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
            fut_a = pool.submit(sess.call, {"mode": "hold_accepted"}, timeout_ms=4000)
            _check(a_entered.wait(timeout=3.0))
            ch_ref = require_non_none(sess._ensure_channel())
            out_b = sess.call({"mode": "reject_once"}, timeout_ms=3000)
            _check(out_b.was_accepted and not out_b.transport_lost)
            direct_c = ch_ref.call({"mode": "after_retire"}, timeout_ms=2000)
            _check(
                not direct_c.was_accepted
                and not direct_c.transport_lost
                and direct_c.rejected_before_accept
                and direct_c.error_code == ErrorCode.DAEMON_UNAVAILABLE
            )
            sess._discard_channel(ch_ref, force_close=True)
            _check(not ch_ref.is_closed, "Detached retiring channel must not be hard-closed while stream A is active!")
            out_c = sess.call({"mode": "fresh_channel"}, timeout_ms=3000)
            _check(out_c.was_accepted and not out_c.transport_lost)
            release_a.set()
            out_a = fut_a.result(timeout=4.0)
            _check(
                out_a.was_accepted
                and not out_a.transport_lost
                and isinstance(out_a.result_payload, Mapping)
                and out_a.result_payload.get("tag") == "stream_a_survived"
            )
            _wait_until(lambda: ch_ref.is_closed, timeout_sec=2.0)
    finally:
        release_a.set()
        sess.close()
        listener.close_all()


_T1_MANIFEST_STRICT_SRC: Final[str] = """from dataclasses import dataclass
import time
from typing import Sequence
from core.execution.runtime import BoundTask, SecurityTier, Task, TaskContext, TaskMetadata, YscbModule
from core.foundation.primitives import ModuleId, TaskId

@dataclass(frozen=True, slots=True)
class MIn:
    ms: int = 0

@dataclass(frozen=True, slots=True)
class MOut:
    ok: bool = True

class StrictTask(Task[MIn, MOut]):
    @property
    def metadata(self) -> TaskMetadata[MIn, MOut]:
        return TaskMetadata(
            TaskId("t1mf.op"), MIn, MOut,
            security_tier=SecurityTier.__SEC__,
            timeout_ms=220,
        )
    def run(self, req: MIn, ctx: TaskContext) -> MOut:
        _ = ctx
        if req.ms > 0:
            time.sleep(req.ms / 1000.0)
        return MOut(ok=True)

class MMod(YscbModule):
    @property
    def module_id(self) -> ModuleId:
        return ModuleId("t1mf")
    def tasks(self) -> Sequence[BoundTask]:
        return (StrictTask(),)

def create_module() -> YscbModule:
    return MMod()
"""


def _verify_retiring_channel_tier1_manifest_and_coord_cache(ws8: HostPath, venv_bin: HostPath) -> None:
    _verify_retiring_rpc_channel_preserves_accepted_stream(ws8)

    # ResourceCoordinator(cache_dir=...) resolves workspace cache_dir without touching symlinked locks subdir
    ws_rc = HostPath(ws8.path / "ws_coord_cache_direct")
    cache_rc = ws_rc.join(".cache")
    cache_rc.path.mkdir(parents=True, exist_ok=True)
    outside_dir = ws8.path / "outside_locks_target"
    outside_dir.mkdir(parents=True, exist_ok=True)
    (cache_rc.path / "locks").symlink_to(outside_dir)
    coord_direct = ResourceCoordinator(cache_dir=cache_rc, workspace_root=ws_rc)
    _check(coord_direct._lookup_workspace_cache_dir(ws_rc) == cache_rc)
    _expect_yscb_code(coord_direct._effective_locks_dir, ErrorCode.SECURITY_GATED)

    # Tier 1 cold & hot declared_tasks manifest verification + timeout_ms SSOT + fingerprint reload
    ws_m = HostPath(ws8.path / "ws_t1_manifest_ssot")
    provision_live_workspace(ws_m.path)
    _write_module(
        ws_m.path,
        "t1mf",
        {"tier1": True, "venv_group": "mf_grp", "tasks": [{"task_id": "t1mf.op"}]},
        _T1_MANIFEST_STRICT_SRC.replace("__SEC__", "GATED"),
    )
    disp_cold = build_dispatcher_for_workspace(ws_m, venv_bin, is_daemon_host=False).dispatcher
    disp_hot = build_dispatcher_for_workspace(ws_m, venv_bin, is_daemon_host=True).dispatcher
    try:
        c_deg = disp_cold.invoke(InvokeRequest(TaskId("t1mf.op"), {}, ws_m, ws_m, routing_policy=ClientRoutingPolicy.FORCE_COLD))
        h_deg = disp_hot.invoke(InvokeRequest(TaskId("t1mf.op"), {}, ws_m, ws_m))
        _check(not c_deg.ok and c_deg.error is not None and c_deg.error.code == ErrorCode.MODULE_DEGRADED)
        _check(not h_deg.ok and h_deg.error is not None and h_deg.error.code == ErrorCode.MODULE_DEGRADED)

        # Fix security_tier to SAFE, still omitting timeout_ms=80 -> still MODULE_DEGRADED until timeout_ms matches!
        _write_module(
            ws_m.path,
            "t1mf",
            {"tier1": True, "venv_group": "mf_grp", "tasks": [{"task_id": "t1mf.op"}]},
            _T1_MANIFEST_STRICT_SRC.replace("__SEC__", "SAFE"),
        )
        disp_hot.reload_affected_modules(frozenset({ModuleId("t1mf")}))
        tmo_deg = disp_hot.invoke(InvokeRequest(TaskId("t1mf.op"), {}, ws_m, ws_m))
        _check(not tmo_deg.ok and tmo_deg.error is not None and tmo_deg.error.code == ErrorCode.MODULE_DEGRADED)

        # Update ONLY routes.json with matching timeout_ms=80 -> group fingerprint updates and Tier 1 enforces 80ms timeout!
        atomic_write_json(
            ws_m.join(".modules", "t1mf", "routes.json"),
            {"module_id": "t1mf", "tier1": True, "venv_group": "mf_grp", "eager_warmup": True, "tasks": [{"task_id": "t1mf.op", "timeout_ms": 220}]},
        )
        disp_hot.reload_affected_modules(frozenset({ModuleId("t1mf")}))
        ok_fast = disp_hot.invoke(InvokeRequest(TaskId("t1mf.op"), {"ms": 0}, ws_m, ws_m))
        tmo_hit = disp_hot.invoke(InvokeRequest(TaskId("t1mf.op"), {"ms": 480}, ws_m, ws_m))
        _check(ok_fast.ok and not tmo_hit.ok and tmo_hit.error is not None and tmo_hit.error.code == ErrorCode.TASK_TIMEOUT, lambda: f"ok_fast={ok_fast} tmo_hit={tmo_hit}")
    finally:
        disp_cold.shutdown(grace_ms=100)
        disp_hot.shutdown(grace_ms=100)


